    class PresentationComboBox(QComboBox):
        """Combo box whose visible label can differ from its stable stored value."""

        def setCurrentText(self, text: str) -> None:
            index = self.findText(str(text))
            if index < 0:
                index = self.findData(str(text))
            if index >= 0:
                self.setCurrentIndex(index)
                return
            super().setCurrentText(str(text))

    class ModelView(QGraphicsView):
        def __init__(self, scene: QGraphicsScene, owner: Any) -> None:
            super().__init__(scene)
            self.owner = owner
            self._middle_panning = False
            self._middle_pan_pos = None
            self._selection_press_handled = False
            self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
            self.setContextMenuPolicy(Qt.ContextMenuPolicy.DefaultContextMenu)
            self.setDragMode(QGraphicsView.DragMode.ScrollHandDrag)
            self.setTransformationAnchor(QGraphicsView.ViewportAnchor.AnchorUnderMouse)
            self.setResizeAnchor(QGraphicsView.ViewportAnchor.AnchorViewCenter)

        def wheelEvent(self, event: Any) -> None:
            factor = 1.18 if event.angleDelta().y() > 0 else 1.0 / 1.18
            self.scale(factor, factor)

        def reset_to_scene(self) -> None:
            self.resetTransform()
            rect = self.scene().itemsBoundingRect().adjusted(-30.0, -30.0, 30.0, 30.0)
            if rect.isValid():
                self.fitInView(rect, Qt.AspectRatioMode.KeepAspectRatio)

        def _event_pos(self, event: Any) -> Any:
            try:
                return event.position().toPoint()
            except Exception:
                return event.pos()

        def mousePressEvent(self, event: Any) -> None:
            owner = self.owner
            pos = self._event_pos(event)
            if event.button() == Qt.MouseButton.MiddleButton:
                self._middle_panning = True
                self._middle_pan_pos = pos
                self.viewport().setCursor(Qt.CursorShape.ClosedHandCursor)
                event.accept()
                return
            if event.button() == Qt.MouseButton.RightButton and getattr(owner, "draw_mode", "select") in owner._cad_drawing_modes():
                if getattr(owner, "draw_mode", "select") in {"line", "helper"} and getattr(owner, "draw_start", None) is not None:
                    owner.handle_model_click(self.mapToScene(pos))
                else:
                    owner.finish_cad_drawing()
                event.accept()
                return
            if event.button() == Qt.MouseButton.RightButton:
                event.accept()
                return
            if event.button() == Qt.MouseButton.LeftButton:
                if getattr(owner, "draw_mode", "select") in owner._cad_drawing_modes():
                    owner.handle_model_click(self.mapToScene(pos))
                    event.accept()
                    return
                if getattr(owner, "selection_mode", "normal") == "lasso" and getattr(owner, "draw_mode", "select") == "select":
                    owner.begin_lasso_selection(self.mapToScene(pos))
                    event.accept()
                    return
                item = self.itemAt(pos)
                data = item.data(0) if item is not None else None
                if isinstance(data, dict) and data.get("kind") == "geometry_endpoint":
                    if not (event.modifiers() & Qt.KeyboardModifier.ControlModifier):
                        self.scene().clearSelection()
                    item.setSelected(True)
                    owner.begin_endpoint_drag(data)
                    event.accept()
                    return
                if isinstance(data, dict) and data.get("kind") in {"curve_control_point", "dimension_endpoint", "cad_draw_control_point"}:
                    if item is not None:
                        if not (event.modifiers() & Qt.KeyboardModifier.ControlModifier):
                            self.scene().clearSelection()
                        item.setSelected(True)
                    owner.begin_cad_handle_drag(data)
                    event.accept()
                    return
                if isinstance(data, dict) and data.get("kind") in {"mesh_control_point", "mesh_refinement", "mesh_size_map", "mesh_split_line"}:
                    if item is not None:
                        if not (event.modifiers() & Qt.KeyboardModifier.ControlModifier):
                            self.scene().clearSelection()
                        item.setSelected(True)
                    owner.begin_mesh_control_drag(data)
                    event.accept()
                    return
                current_panel = owner._panel_key_from_tree_key(str(getattr(owner, "current_panel_key", "")))
                if (
                    current_panel == "mesh"
                    and getattr(owner, "draw_mode", "select") == "select"
                    and getattr(owner, "selection_mode", "normal") == "normal"
                ):
                    node_item = None
                    node_data = None
                    for candidate in [item, *self.items(pos)]:
                        candidate_data = candidate.data(0) if candidate is not None else None
                        if isinstance(candidate_data, dict) and candidate_data.get("kind") == "node":
                            node_item = candidate
                            node_data = candidate_data
                            break
                    if node_item is not None and isinstance(node_data, dict):
                        if not (event.modifiers() & Qt.KeyboardModifier.ControlModifier):
                            self.scene().clearSelection()
                        node_item.setSelected(True)
                        owner.begin_mesh_node_drag(node_data)
                        event.accept()
                        return
                if (
                    getattr(owner, "draw_mode", "select") == "select"
                    and getattr(owner, "selection_mode", "normal") == "normal"
                ):
                    endpoint_data = owner.nearest_geometry_endpoint_at_scene_point(self.mapToScene(pos))
                    if endpoint_data is not None:
                        if not (event.modifiers() & Qt.KeyboardModifier.ControlModifier):
                            self.scene().clearSelection()
                        owner.select_geometry_endpoint_items(endpoint_data, additive=True)
                        owner.begin_endpoint_drag(endpoint_data)
                        event.accept()
                        return
                if (
                    getattr(owner, "draw_mode", "select") == "select"
                    and getattr(owner, "selection_mode", "normal") == "normal"
                    and owner.select_model_item_at_scene_point(
                        self.mapToScene(pos),
                        item=item,
                        items=self.items(pos),
                        additive=bool(event.modifiers() & Qt.KeyboardModifier.ControlModifier),
                    )
                ):
                    self._selection_press_handled = True
                    event.accept()
                    return
            super().mousePressEvent(event)

        def mouseMoveEvent(self, event: Any) -> None:
            owner = self.owner
            pos = self._event_pos(event)
            if self._middle_panning and self._middle_pan_pos is not None:
                delta = pos - self._middle_pan_pos
                self._middle_pan_pos = pos
                self.horizontalScrollBar().setValue(self.horizontalScrollBar().value() - delta.x())
                self.verticalScrollBar().setValue(self.verticalScrollBar().value() - delta.y())
                event.accept()
                return
            if getattr(owner, "selection_mode", "normal") == "lasso" and getattr(owner, "lasso_points", None):
                owner.extend_lasso_selection(self.mapToScene(pos))
                event.accept()
                return
            if getattr(owner, "endpoint_drag", None) is not None:
                owner.update_endpoint_drag(self.mapToScene(pos), final=False)
                return
            if getattr(owner, "cad_handle_drag", None) is not None:
                owner.update_cad_handle_drag(self.mapToScene(pos), final=False)
                return
            if getattr(owner, "mesh_control_drag", None) is not None:
                owner.update_mesh_control_drag(self.mapToScene(pos), final=False)
                return
            if getattr(owner, "mesh_node_drag", None) is not None:
                owner.update_mesh_node_drag(self.mapToScene(pos), final=False)
                return
            if getattr(owner, "draw_mode", "select") in owner._cad_drawing_modes():
                owner.update_cad_lightweight_preview(self.mapToScene(pos))
                event.accept()
                return
            super().mouseMoveEvent(event)

        def mouseReleaseEvent(self, event: Any) -> None:
            owner = self.owner
            pos = self._event_pos(event)
            if event.button() == Qt.MouseButton.MiddleButton and self._middle_panning:
                self._middle_panning = False
                self._middle_pan_pos = None
                owner._apply_selection_drag_mode()
                event.accept()
                return
            if event.button() == Qt.MouseButton.RightButton:
                event.accept()
                return
            if event.button() == Qt.MouseButton.LeftButton and self._selection_press_handled:
                self._selection_press_handled = False
                event.accept()
                return
            if (
                event.button() == Qt.MouseButton.LeftButton
                and getattr(owner, "selection_mode", "normal") == "lasso"
                and getattr(owner, "lasso_points", None)
            ):
                owner.finish_lasso_selection(self.mapToScene(pos))
                event.accept()
                return
            if getattr(owner, "endpoint_drag", None) is not None:
                owner.update_endpoint_drag(self.mapToScene(pos), final=True)
                return
            if getattr(owner, "cad_handle_drag", None) is not None:
                owner.update_cad_handle_drag(self.mapToScene(pos), final=True)
                return
            if getattr(owner, "mesh_control_drag", None) is not None:
                owner.update_mesh_control_drag(self.mapToScene(pos), final=True)
                return
            if getattr(owner, "mesh_node_drag", None) is not None:
                owner.update_mesh_node_drag(self.mapToScene(pos), final=True)
                return
            super().mouseReleaseEvent(event)

        def contextMenuEvent(self, event: Any) -> None:
            owner = self.owner
            pos = self._event_pos(event)
            scene_point = self.mapToScene(pos)
            items = self.items(pos)
            clicked_selection = False
            item = self.itemAt(pos)
            for candidate in [item, *items]:
                try:
                    if candidate is not None and candidate.isSelected():
                        clicked_selection = True
                        break
                except Exception:
                    pass
            if not clicked_selection:
                owner.select_model_item_at_scene_point(
                    scene_point,
                    item=item,
                    items=items,
                    additive=False,
                )
            global_pos = event.globalPos() if hasattr(event, "globalPos") else self.viewport().mapToGlobal(pos)
            owner._show_command_context_menu(global_pos, "view")
            event.accept()

        def keyPressEvent(self, event: Any) -> None:
            owner = self.owner
            if getattr(owner, "draw_mode", "select") in owner._cad_drawing_modes():
                if event.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter):
                    owner.finish_cad_drawing()
                    event.accept()
                    return
                if event.key() == Qt.Key.Key_Escape:
                    owner.cancel_cad_drawing()
                    event.accept()
                    return
                if event.key() == Qt.Key.Key_Backspace:
                    owner.undo_last_cad_drawing_point()
                    event.accept()
                    return
                if event.key() == Qt.Key.Key_Tab:
                    owner.cycle_cad_snap_candidate()
                    event.accept()
                    return
            super().keyPressEvent(event)

    class ResultTablePageModel(QAbstractTableModel):
        def __init__(self) -> None:
            super().__init__()
            self._rows: list[dict[str, str]] = []
            self._headers: list[str] = []
            self._compat_items: dict[tuple[int, int], QTableWidgetItem] = {}
            self._error_tooltips: dict[tuple[int, int], str] = {}

        def set_page(self, rows: list[dict[str, str]], headers: list[str]) -> None:
            self.beginResetModel()
            self._rows = [dict(row) for row in rows]
            self._headers = list(headers)
            self._compat_items = {}
            self._error_tooltips = {}
            self.endResetModel()

        def set_dimensions(self, row_count: int | None = None, column_count: int | None = None) -> None:
            rows = [dict(row) for row in self._rows]
            headers = list(self._headers)
            if column_count is not None:
                safe_cols = max(0, int(column_count))
                if safe_cols < len(headers):
                    headers = headers[:safe_cols]
                else:
                    headers.extend(f"column_{index + 1}" for index in range(len(headers), safe_cols))
            if row_count is not None:
                safe_rows = max(0, int(row_count))
                if safe_rows < len(rows):
                    rows = rows[:safe_rows]
                else:
                    rows.extend({header: "" for header in headers} for _index in range(len(rows), safe_rows))
            for row in rows:
                for header in headers:
                    row.setdefault(header, "")
            self.set_page(rows, headers)

        def set_headers(self, headers: list[str]) -> None:
            rows = [dict(row) for row in self._rows]
            for row in rows:
                for header in headers:
                    row.setdefault(header, "")
            self.set_page(rows, headers)

        def rowCount(self, parent: Any = None) -> int:
            if parent is not None and hasattr(parent, "isValid") and parent.isValid():
                return 0
            return len(self._rows)

        def columnCount(self, parent: Any = None) -> int:
            if parent is not None and hasattr(parent, "isValid") and parent.isValid():
                return 0
            return len(self._headers)

        def data(self, index: Any, role: int = Qt.ItemDataRole.DisplayRole) -> Any:
            if not index.isValid():
                return None
            row = index.row()
            col = index.column()
            key = (row, col)
            item = self._compat_items.get(key)
            if role in (Qt.ItemDataRole.DisplayRole, Qt.ItemDataRole.EditRole):
                if item is not None:
                    return item.text()
                if row < 0 or row >= len(self._rows) or col < 0 or col >= len(self._headers):
                    return ""
                return str(self._rows[row].get(self._headers[col], ""))
            if role == Qt.ItemDataRole.ToolTipRole:
                if key in self._error_tooltips:
                    return self._error_tooltips[key]
                return item.toolTip() if item is not None else None
            if role == Qt.ItemDataRole.BackgroundRole:
                if key in self._error_tooltips:
                    return QColor("#f8d7da")
                return item.background() if item is not None else None
            return None

        def headerData(self, section: int, orientation: Qt.Orientation, role: int = Qt.ItemDataRole.DisplayRole) -> Any:
            if role != Qt.ItemDataRole.DisplayRole:
                return None
            if orientation == Qt.Orientation.Horizontal:
                if 0 <= section < len(self._headers):
                    return self._headers[section]
                return ""
            return str(section + 1)

        def item(self, row: int, col: int) -> QTableWidgetItem | None:
            return self._compat_items.get((row, col))

        def set_item(self, row: int, col: int, item: QTableWidgetItem) -> None:
            if row < 0 or col < 0:
                return
            if row >= len(self._rows) or col >= len(self._headers):
                self.set_dimensions(max(row + 1, len(self._rows)), max(col + 1, len(self._headers)))
            self._compat_items[(row, col)] = item
            self._emit_cell_changed(row, col)

        def set_cell_error(self, row: int, col: int, tooltip: str) -> None:
            if row < 0 or col < 0:
                return
            if row >= len(self._rows) or col >= len(self._headers):
                self.set_dimensions(max(row + 1, len(self._rows)), max(col + 1, len(self._headers)))
            self._error_tooltips[(row, col)] = tooltip
            self._emit_cell_changed(row, col)

        def _emit_cell_changed(self, row: int, col: int) -> None:
            model_index = self.index(row, col)
            self.dataChanged.emit(
                model_index,
                model_index,
                [Qt.ItemDataRole.DisplayRole, Qt.ItemDataRole.ToolTipRole, Qt.ItemDataRole.BackgroundRole],
            )

    class ResultTableView(QTableView):
        def __init__(self) -> None:
            super().__init__()
            self._result_model = ResultTablePageModel()
            self.setModel(self._result_model)
            self.setSelectionBehavior(QTableView.SelectionBehavior.SelectItems)
            self.setSelectionMode(QTableView.SelectionMode.ExtendedSelection)
            self.setAlternatingRowColors(True)
            self.setSortingEnabled(False)
            self.horizontalHeader().setSectionResizeMode(QHeaderView.ResizeMode.Stretch)

        def set_result_page(self, rows: list[dict[str, str]], headers: list[str]) -> None:
            self.setUpdatesEnabled(False)
            try:
                self._result_model.set_page(rows, headers)
                self.horizontalHeader().setSectionResizeMode(QHeaderView.ResizeMode.Stretch)
            finally:
                self.setUpdatesEnabled(True)

        def clearContents(self) -> None:
            self._result_model.set_page([], list(self._result_model._headers))

        def rowCount(self) -> int:
            return self._result_model.rowCount()

        def columnCount(self) -> int:
            return self._result_model.columnCount()

        def setRowCount(self, count: int) -> None:
            self._result_model.set_dimensions(row_count=count)

        def setColumnCount(self, count: int) -> None:
            self._result_model.set_dimensions(column_count=count)

        def setHorizontalHeaderLabels(self, labels: list[str]) -> None:
            self._result_model.set_headers([str(label) for label in labels])

        def item(self, row: int, col: int) -> QTableWidgetItem | None:
            return self._result_model.item(row, col)

        def setItem(self, row: int, col: int, item: QTableWidgetItem) -> None:
            self._result_model.set_item(row, col, item)

        def set_cell_error(self, row: int, col: int, tooltip: str) -> None:
            self._result_model.set_cell_error(row, col, tooltip)

        def setCurrentCell(self, row: int, col: int) -> None:
            index = self._result_model.index(row, col)
            if index.isValid():
                self.setCurrentIndex(index)

        def currentRow(self) -> int:
            return self.currentIndex().row()

        def currentColumn(self) -> int:
            return self.currentIndex().column()

        def scrollToItem(self, item: Any) -> None:
            for key, value in self._result_model._compat_items.items():
                if value is item:
                    self.scrollTo(self._result_model.index(key[0], key[1]))
                    return

