        def _desktop_layout_profile(self) -> DesktopLayoutProfile:
            app = QApplication.instance()
            screen = app.primaryScreen() if app is not None else None
            if screen is None:
                return resolve_desktop_layout_profile(1440, 860)
            geometry = screen.availableGeometry()
            return resolve_desktop_layout_profile(geometry.width(), geometry.height())

        def _apply_button_icon(self, button: QPushButton, icon_role: str) -> None:
            apply_button_icon(button, icon_role, self.style(), QStyle)

        def _surface_text_qt(self) -> dict[str, Any]:
            return {
                "QAbstractButton": QAbstractButton,
                "QGroupBox": QGroupBox,
                "QLabel": QLabel,
                "QTabWidget": QTabWidget,
                "QComboBox": QComboBox,
                "QLineEdit": QLineEdit,
                "QTableWidget": QTableWidget,
                "QTableView": QTableView,
                "QAction": QAction,
                "QMenu": QMenu,
                "QTreeWidget": QTreeWidget,
            }

        def _apply_surface_text_catalog(self) -> None:
            self.surface_text_application = apply_gui_surface_texts(self, locale=self.gui_locale, qt=self._surface_text_qt())
            self._sync_workspace_focus_mode_controls()

        def ui_message(self, key: str, **values: Any) -> str:
            return gui_surface_message(key, locale=self.gui_locale, **values)

        def resizeEvent(self, event: Any) -> None:
            super().resizeEvent(event)
            if hasattr(self, "workflow_ribbon"):
                compact = self.workspace_focus_mode_active() or self._is_compact_gui()
                previous_compact = getattr(self, "workflow_ribbon_compact", None)
                set_workflow_ribbon_compact(self, compact)
                if previous_compact is not None and previous_compact != compact:
                    self.refresh_workflow_guidance()
            if hasattr(self, "right_panel_stack"):
                self._apply_context_visibility(getattr(self, "current_panel_key", "workflow"))

        def _is_compact_gui(self) -> bool:
            return self.width() < 1500 or self.height() < 850

        def _configure_primary_tab_order(self) -> None:
            ordered = [
                getattr(self, "gui_operation_mode_combo", None),
                getattr(self, "command_search", None),
                getattr(self, "tree", None),
                getattr(self, "workflow_ribbon_overview_button", None),
                getattr(self, "workflow_ribbon_focus_button", None),
                getattr(self, "workflow_ribbon_back_button", None),
                getattr(self, "workflow_ribbon_jump_button", None),
                getattr(self, "primary_run_button", None),
                getattr(self, "primary_reset_results_button", None),
                getattr(self, "primary_stop_button", None),
                getattr(self, "primary_save_button", None),
                getattr(self, "global_log_toggle_button", None),
            ]
            widgets = [widget for widget in ordered if isinstance(widget, QWidget)]
            for current, following in zip(widgets, widgets[1:]):
                self.setTabOrder(current, following)

        def _toggle_global_log(self, checked: bool = False) -> None:
            self._set_log_drawer_expanded(bool(checked))

        def workspace_focus_mode_active(self) -> bool:
            return bool(getattr(self, "_workspace_focus_mode_active", False))

        def _workspace_focus_panel_supported(self, panel_key: str | None = None) -> bool:
            panel = self._panel_key_from_tree_key(
                str(panel_key or getattr(self, "current_panel_key", "analysis") or "analysis")
            )
            return panel in self._model_display_panel_keys() or panel in {"results", "report"}

        def _sync_workspace_focus_mode_controls(self) -> None:
            active = self.workspace_focus_mode_active()
            solver_busy = bool(getattr(self, "_solver_navigation_suppressed", False)) or self._solver_process_running()
            available = self._workspace_focus_panel_supported() and not solver_busy
            button = getattr(self, "workflow_ribbon_focus_button", None)
            action = getattr(self, "view_focus_action", None)
            if self.gui_locale == "en":
                text = "Restore Layout" if active else "Expand View"
                tooltip = (
                    "Restore the navigation, inspector, workflow steps, and run log."
                    if active
                    else "Expand the model or result view across the workspace."
                )
                unavailable = "Open a model or result view to use focus mode."
                accessible = "Restore workspace layout" if active else "Expand model or result view"
            else:
                text = "通常表示" if active else "表示を広げる"
                tooltip = (
                    "ナビゲーション、インスペクタ、工程一覧、実行ログを元の表示へ戻します。"
                    if active
                    else "モデル・結果表示を中央いっぱいに広げます。"
                )
                unavailable = "モデル表示または結果表示で利用できます。"
                accessible = "通常の画面配置へ戻す" if active else "モデル・結果表示を広げる"
            if button is not None:
                button.blockSignals(True)
                button.setChecked(active)
                button.setText(text)
                button.setToolTip(tooltip if available or active else unavailable)
                button.setAccessibleName(accessible)
                button.setEnabled(active or available)
                pixmap = (
                    QStyle.StandardPixmap.SP_TitleBarNormalButton
                    if active
                    else QStyle.StandardPixmap.SP_TitleBarMaxButton
                )
                button.setIcon(self.style().standardIcon(pixmap))
                button.setIconSize(QSize(16, 16))
                button.blockSignals(False)
            if action is not None:
                action.blockSignals(True)
                action.setChecked(active)
                action.setText(text)
                action.setStatusTip(tooltip if available or active else unavailable)
                action.setEnabled(active or available)
                action.blockSignals(False)

        def _enforce_workspace_focus_visibility(self) -> None:
            if not self.workspace_focus_mode_active():
                return
            for widget in (
                getattr(self, "left_navigation_panel", None),
                getattr(self, "right_panel_stack", None),
                getattr(self, "bottom_panel", None),
            ):
                if widget is not None:
                    widget.setVisible(False)
            set_workflow_ribbon_compact(self, True)

        def set_workspace_focus_mode(self, active: bool) -> None:
            active = bool(active)
            current = self.workspace_focus_mode_active()
            if active == current:
                self._sync_workspace_focus_mode_controls()
                return
            if active and (not self._workspace_focus_panel_supported() or self._solver_process_running()):
                self._sync_workspace_focus_mode_controls()
                self.statusBar().showMessage(
                    "Focus mode is available in model and result views."
                    if self.gui_locale == "en"
                    else "フォーカスモードはモデル表示と結果表示で利用できます。"
                )
                return

            self._workspace_focus_applying = True
            try:
                if active:
                    self._remember_workspace_splitter_state()
                    self._workspace_focus_restore_state = {
                        "left_visible": not self.left_navigation_panel.isHidden(),
                        "right_visible": not self.right_panel_stack.isHidden(),
                        "bottom_visible": not self.bottom_panel.isHidden(),
                        "log_expanded": bool(getattr(self, "_log_drawer_expanded", False)),
                        "ribbon_compact": bool(getattr(self, "workflow_ribbon_compact", False)),
                        "workspace_sizes": list(self.workspace_splitter.sizes()),
                        "main_sizes": list(self.main_splitter.sizes()),
                    }
                    self._workspace_focus_mode_active = True
                    self.set_left_navigation_visible(False)
                    self.set_right_inspector_visible(False)
                    self._set_log_drawer_expanded(False)
                    self._enforce_workspace_focus_visibility()
                    message = (
                        "Focus mode: model/result view expanded. Press F11 to restore the layout."
                        if self.gui_locale == "en"
                        else "フォーカスモード: モデル・結果表示を拡大しました。F11で通常表示へ戻せます。"
                    )
                else:
                    state = dict(getattr(self, "_workspace_focus_restore_state", {}))
                    self._workspace_focus_mode_active = False
                    self._apply_context_visibility(getattr(self, "current_panel_key", "analysis"))
                    self.set_left_navigation_visible(bool(state.get("left_visible", True)))
                    self.set_right_inspector_visible(bool(state.get("right_visible", True)))
                    self._set_log_drawer_expanded(bool(state.get("log_expanded", False)))
                    if not bool(state.get("bottom_visible", True)):
                        self.bottom_panel.setVisible(False)
                    set_workflow_ribbon_compact(
                        self,
                        bool(state.get("ribbon_compact", self._is_compact_gui())),
                    )
                    workspace_sizes = state.get("workspace_sizes")
                    if isinstance(workspace_sizes, list) and len(workspace_sizes) == 3:
                        self.workspace_splitter.setSizes([int(value) for value in workspace_sizes])
                    main_sizes = state.get("main_sizes")
                    if isinstance(main_sizes, list) and len(main_sizes) == 2:
                        self.main_splitter.setSizes([int(value) for value in main_sizes])
                    self._workspace_focus_restore_state = {}
                    message = "Workspace layout restored." if self.gui_locale == "en" else "通常の画面配置へ戻しました。"
            finally:
                self._workspace_focus_applying = False
                self._sync_workspace_focus_mode_controls()
            self.statusBar().showMessage(message)

        def _set_log_drawer_expanded(self, expanded: bool) -> None:
            expanded = bool(expanded)
            self._log_drawer_expanded = expanded
            self.log.setVisible(expanded)
            button = getattr(self, "global_log_toggle_button", None)
            if button is not None:
                button.blockSignals(True)
                button.setChecked(expanded)
                if self.gui_locale == "en":
                    button.setText("Hide" if expanded else "Show")
                else:
                    button.setText("隠す" if expanded else "表示")
                button.blockSignals(False)
            action = getattr(self, "view_log_action", None)
            if action is not None and action.isChecked() != expanded:
                action.blockSignals(True)
                action.setChecked(expanded)
                action.blockSignals(False)
            panel = getattr(self, "bottom_panel", None)
            detail_visible = bool(getattr(self, "detail_action_group", None) is not None and self.detail_action_group.isVisible())
            collapsed_height = 118 if detail_visible else 42
            if panel is not None:
                panel.setMinimumHeight(collapsed_height if not expanded else 42)
                panel.setMaximumHeight(16777215 if expanded else collapsed_height)
            if self.gui_locale == "en":
                self.global_log_label.setText("Application log")
            splitter = getattr(self, "main_splitter", None)
            if splitter is not None and splitter.count() >= 2:
                total = sum(max(0, int(value)) for value in splitter.sizes()) or max(720, self.height())
                bottom = min(max(210, int(total * 0.25)), 320) if expanded else collapsed_height
                splitter.setSizes([max(1, total - bottom), bottom])

        def _apply_bottom_panel_context(self, panel_key: str, *, detail_mode: bool) -> None:
            panel = getattr(self, "bottom_panel", None)
            if panel is None:
                return
            solver_active = panel_key == "solver"
            panel.setVisible(not solver_active)
            header = getattr(self, "global_log_header", None)
            if header is not None:
                header.setVisible(not solver_active)
            if solver_active:
                return
            splitter = getattr(self, "main_splitter", None)
            if splitter is None or splitter.count() < 2 or self.log.isVisible():
                return
            total = sum(splitter.sizes()) or max(1, self.height())
            bottom = 118 if detail_mode else 42
            panel.setMinimumHeight(bottom)
            panel.setMaximumHeight(bottom)
            splitter.setSizes([max(1, total - bottom), bottom])

        def _apply_panel_button_policy(self, key: str, page: QWidget) -> None:
            page.setProperty("panelKey", key)
            for button in page.findChildren(QPushButton):
                apply_panel_button_icon(button, key, self.style(), QStyle)
                self._prepare_panel_action_button(button)
            self._apply_text_fit_policy(page)

        def _apply_text_fit_policy(self, root: QWidget) -> None:
            for checkbox in root.findChildren(QCheckBox):
                text = str(checkbox.text() or "").replace("&", "").strip()
                if text:
                    width = min(220, checkbox.fontMetrics().horizontalAdvance(text) + 38)
                    checkbox.setMinimumWidth(max(checkbox.minimumWidth(), width))
            for label in root.findChildren(QLabel):
                text = str(label.text() or "").replace("&", "").strip()
                if len(text) >= 32:
                    label.setWordWrap(True)
                    label.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Preferred)
                    required_height = max(32, min(72, label.sizeHint().height()))
                    label.setMinimumHeight(max(label.minimumHeight(), required_height))
            for editor in root.findChildren(QPlainTextEdit):
                if editor.maximumHeight() <= 120 or editor.property("informationRole") == "detail":
                    editor.setMinimumHeight(max(editor.minimumHeight(), 56))

        def _prepare_panel_action_button(self, button: QPushButton) -> None:
            if button.property("cadTool"):
                return
            text = str(button.text() or "").replace("&", "").strip()
            if text and not button.toolTip():
                button.setToolTip(text)
            text_width = button.fontMetrics().horizontalAdvance(text) if text else 72
            uniform_width = button.property("uniformPanelButtonWidth")
            try:
                uniform_width_int = int(uniform_width) if uniform_width is not None else 0
            except (TypeError, ValueError):
                uniform_width_int = 0
            button.setMinimumWidth(uniform_width_int if uniform_width_int > 0 else max(96, min(180, text_width + 34)))
            button.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)

        def _planned_cad_tool(self, name: str) -> Callable[..., None]:
            return lambda *_args, label=name: self.statusBar().showMessage(f"{label}はCAD風作図パレットの次フェーズで実装します。")

        @staticmethod
        def _cad_drawing_modes() -> set[str]:
            return {"line", "helper", "region", "polyline", "rectangle", "circle", "arc", "curve", "point"}

        def activate_cad_selection_tool(self, *, part: bool = False) -> None:
            self.set_selection_mode("normal")
            self.view.setDragMode(QGraphicsView.DragMode.NoDrag)
            self.view.viewport().setCursor(Qt.CursorShape.ArrowCursor)
            message = "部分選択: 端点や制御点をクリックして座標編集できます。" if part else "選択: 作図線や領域をクリックして選択できます。"
            self.statusBar().showMessage(message)
            self._refresh_cad_tool_button_state()
            self._refresh_auxiliary_selection_context()

        def _toggle_grid_lines(self, *_args: Any) -> None:
            if getattr(self, "show_grid_lines", None) is not None:
                self.show_grid_lines.setChecked(not self.show_grid_lines.isChecked())
            self.update_preview(reset_view=False)

        def _install_work_context_menu(self, widget: QWidget, context: str) -> None:
            widget.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
            widget.customContextMenuRequested.connect(
                lambda pos, w=widget, ctx=context: self._show_command_context_menu(w.mapToGlobal(pos), ctx)
            )
            widget.setProperty("workContextMenu", context)

