        def _cad_palette_buttons(self) -> list[QPushButton]:
            buttons: list[QPushButton] = []
            mode_labels = {
                "選択": "select",
                "部分選択": "select",
                "直線": "line",
                "折れ線": "polyline",
                "矩形": "rectangle",
                "多角形": "region",
                "円": "circle",
                "円弧": "arc",
                "曲線": "curve",
                "点": "point",
                "補助線": "helper",
            }
            for label, role, callback, tooltip in self._cad_palette_specs():
                button = QPushButton("")
                button.setToolTip(tooltip)
                self._prepare_cad_tool_button(button, label, role)
                button.setProperty("chipRule", self._cad_tool_rule(label))
                draw_mode = mode_labels.get(label, "")
                if draw_mode:
                    button.setCheckable(True)
                    button.setProperty("cadDrawMode", draw_mode)
                button.clicked.connect(lambda _checked=False, cb=callback: cb())
                self._install_work_context_menu(button, "cad_palette")
                buttons.append(button)
                self.cad_tool_buttons.append(button)
            self._refresh_cad_tool_button_state()
            return buttons

