                (join_btn, self.join_selected_geometry_endpoint_to_nearest),
                (closure_btn, self.add_closure_segment_from_selected_endpoint),
                (helper_btn, lambda _checked=False: self.set_selected_geometry_lines_purpose("helper")),
                (model_btn, lambda _checked=False: self.set_selected_geometry_lines_purpose("model")),
                (region_btn, self.register_closed_lines_as_region),
                (grid_condition_btn, self.apply_selected_geometry_grid_settings),
                (command_btn, lambda _checked=False: self.apply_cad_command_input()),
                (cad_undo_btn, lambda _checked=False: self.undo_edit()),
