                (closure_btn, "geometry.line.close"),
                (helper_btn, "geometry.line.helper"),
                (model_btn, "geometry.line.model"),
                (region_btn, "draw.region"),
                (grid_condition_btn, "grid"),
                (command_btn, "selection.expression.run"),
