        def add_selected_boundary_condition_from_context(self, kind: str | None = None, *, scope: str | None = "global") -> None:
            selected_nodes = self._selected_nodes_for_stage_action()
            kind_combo = getattr(self, "boundary_batch_kind", None)
            if kind and kind_combo is not None:
                index = kind_combo.findData(kind)
                if index >= 0:
                    kind_combo.setCurrentIndex(index)
            scope_combo = getattr(self, "boundary_batch_scope", None)
            if scope and scope_combo is not None:
                index = scope_combo.findData(scope)
                if index >= 0:
                    scope_combo.setCurrentIndex(index)
            self.add_selected_boundary_condition(scope=scope)
            if selected_nodes:
                self._select_preview_payload({"nodes": selected_nodes})

        def apply_active_boundary_condition_to_selected(self) -> None:
            kind = str(getattr(self, "_active_boundary_condition_kind", "") or "")
            if not kind:
                kind_combo = getattr(self, "boundary_batch_kind", None)
                kind = str(kind_combo.currentData() or kind_combo.currentText() or "fixed") if kind_combo is not None else "fixed"
            selected_nodes = self._selected_nodes_for_stage_action()
            if kind == "hydro":
                self.add_selected_hydro_boundary_condition()
            elif kind == "mpc":
                self.add_selected_mpc_constraints()
            elif kind in {"fixed", "roller_y", "roller_x", "pin", "prescribed"}:
                self.add_selected_boundary_condition_from_context(kind, scope=None)
            else:
                self.add_selected_boundary_condition_from_context(None, scope=None)
            if selected_nodes:
                self._select_preview_payload({"nodes": selected_nodes})

        def remove_boundary_conditions_from_selected_nodes(self, kind: str | None = None) -> None:
            selected_nodes = set(self._selected_nodes_for_stage_action())
            if not selected_nodes:
                QMessageBox.information(self, "GeoFEM", "モデルビューで解除する節点、辺、または要素を選択してください。")
                return
            kind_filter = str(kind or getattr(self, "_active_boundary_condition_kind", "") or "").strip()
            if kind_filter == "boundary":
                kind_filter = ""

            try:
                from geofem_app.fem2d import mesh_from_config

                mesh = mesh_from_config(self.cfg)
            except Exception:
                mesh = None

            changed = False
            removed_count = 0

            def matches(raw: Mapping[str, Any], *, hydro_key: str = "") -> bool:
                if not kind_filter:
                    return True
                return self._boundary_condition_kind_from_spec(raw, hydro_key=hydro_key) == kind_filter

            def remove_targets(raw: Mapping[str, Any], *, include_edges: bool = False) -> tuple[dict[str, Any] | None, bool, int]:
                spec = copy.deepcopy(dict(raw))
                nodes, edges = self._boundary_condition_nodes_and_edges(spec, mesh=mesh)
                node_hits = sorted(set(nodes) & selected_nodes, key=self._natural_sort_key)
                edge_hits = [
                    (str(a), str(b))
                    for a, b in edges
                    if {str(a), str(b)}.issubset(selected_nodes)
                ]
                if not node_hits and not (include_edges and edge_hits):
                    return spec, False, 0
                removed = len(node_hits) + (len(edge_hits) if include_edges else 0)
                target_changed = False

                if "node" in spec and str(spec.get("node")) in selected_nodes:
                    spec.pop("node", None)
                    target_changed = True

                if "nodes" in spec:
                    raw_nodes = spec.get("nodes")
                    if isinstance(raw_nodes, str):
                        remaining = [node for node in nodes if node not in selected_nodes]
                        if len(remaining) != len(nodes):
                            spec["nodes"] = remaining
                            target_changed = True
                    else:
                        raw_list = self._ensure_list(raw_nodes)
                        remaining_raw = [value for value in raw_list if str(value) not in selected_nodes]
                        if len(remaining_raw) != len(raw_list):
                            spec["nodes"] = remaining_raw
                            target_changed = True

                if include_edges and ("edge" in spec or "edges" in spec):
                    remaining_edges = [
                        [str(a), str(b)]
                        for a, b in edges
                        if not {str(a), str(b)}.issubset(selected_nodes)
                    ]
                    if len(remaining_edges) != len(edges):
                        spec.pop("edge", None)
                        spec["edges"] = remaining_edges
                        target_changed = True

                if not target_changed and ("set" in spec or bool(spec.get("all", False))):
                    remaining = [node for node in nodes if node not in selected_nodes]
                    if len(remaining) != len(nodes):
                        spec.pop("set", None)
                        spec.pop("all", None)
                        spec["nodes"] = remaining
                        target_changed = True

                if not target_changed:
                    return spec, False, 0

                empty_nodes = "nodes" in spec and not self._ensure_list(spec.get("nodes", []))
                empty_edges = "edges" in spec and not self._ensure_list(spec.get("edges", []))
                has_node_target = (
                    ("node" in spec and spec.get("node") is not None)
                    or ("nodes" in spec and not empty_nodes)
                    or "set" in spec
                    or bool(spec.get("all", False))
                )
                has_edge_target = ("edge" in spec and spec.get("edge") is not None) or ("edges" in spec and not empty_edges)
                if not has_node_target and not has_edge_target:
                    return None, True, removed
                if empty_nodes:
                    spec.pop("nodes", None)
                if empty_edges:
                    spec.pop("edges", None)
                return spec, True, removed

            def filter_condition_list(raw_items: Any, *, hydro_key: str = "", include_edges: bool = False) -> tuple[list[Any], bool, int]:
                local_changed = False
                local_removed = 0
                filtered: list[Any] = []
                for raw in self._ensure_list(raw_items):
                    if not isinstance(raw, Mapping) or not matches(raw, hydro_key=hydro_key):
                        filtered.append(raw)
                        continue
                    updated, item_changed, item_removed = remove_targets(raw, include_edges=include_edges)
                    local_changed = local_changed or item_changed
                    local_removed += item_removed
                    if updated is not None:
                        filtered.append(updated)
                return filtered, local_changed, local_removed

            if kind_filter not in {"hydro", "mpc"}:
                source_key = "boundary_conditions" if "boundary_conditions" in self.cfg or "bc" not in self.cfg else "bc"
                filtered, list_changed, count = filter_condition_list(self.cfg.get(source_key, []))
                if list_changed:
                    self.cfg[source_key] = filtered
                    changed = True
                    removed_count += count
            if kind_filter in {"", "mpc"}:
                mpc_key = "mpc_constraints" if "mpc_constraints" in self.cfg or "mpc" not in self.cfg else "mpc"
                kept_mpcs: list[Any] = []
                global_mpc_changed = False
                for raw in self._ensure_list(self.cfg.get(mpc_key, [])):
                    if not isinstance(raw, Mapping):
                        kept_mpcs.append(raw)
                        continue
                    endpoints = {
                        str(raw.get("master", raw.get("master_node", ""))).strip(),
                        str(raw.get("slave", raw.get("slave_node", ""))).strip(),
                    }
                    if endpoints & selected_nodes:
                        global_mpc_changed = True
                        removed_count += 1
                    else:
                        kept_mpcs.append(raw)
                if global_mpc_changed:
                    self.cfg[mpc_key] = kept_mpcs
                    changed = True

            stages = self._stages()
            for stage in stages:
                if kind_filter not in {"hydro", "mpc"}:
                    stage_key = "boundary_conditions" if "boundary_conditions" in stage or "bc" not in stage else "bc"
                    filtered, list_changed, count = filter_condition_list(stage.get(stage_key, []))
                    if list_changed:
                        stage[stage_key] = filtered
                        changed = True
                        removed_count += count
                if kind_filter in {"", "hydro"}:
                    hydro = stage.get("hydro", stage.get("consolidation", {}))
                    if isinstance(hydro, Mapping):
                        hydro_dict = dict(hydro)
                        for hydro_key in ("pressure_bcs", "pore_pressure_bcs", "pore_flux_bcs", "pore_robin_bcs"):
                            filtered, list_changed, count = filter_condition_list(
                                hydro_dict.get(hydro_key, []), hydro_key=hydro_key, include_edges=True
                            )
                            if list_changed:
                                if filtered:
                                    hydro_dict[hydro_key] = filtered
                                else:
                                    hydro_dict.pop(hydro_key, None)
                                changed = True
                                removed_count += count
                        if hydro_dict != hydro:
                            stage["hydro"] = hydro_dict
                if kind_filter in {"", "mpc"}:
                    mpc_key = "mpc_constraints" if "mpc_constraints" in stage or "mpc" not in stage else "mpc"
                    kept_mpcs: list[Any] = []
                    stage_mpc_changed = False
                    for raw in self._ensure_list(stage.get(mpc_key, [])):
                        if not isinstance(raw, Mapping):
                            kept_mpcs.append(raw)
                            continue
                        endpoints = {
                            str(raw.get("master", raw.get("master_node", ""))).strip(),
                            str(raw.get("slave", raw.get("slave_node", ""))).strip(),
                        }
                        if endpoints & selected_nodes:
                            stage_mpc_changed = True
                            removed_count += 1
                        else:
                            kept_mpcs.append(raw)
                    if stage_mpc_changed:
                        stage[mpc_key] = kept_mpcs
                        changed = True
            self.cfg["stages"] = stages

            if not changed:
                QMessageBox.information(self, "GeoFEM", "選択節点に解除対象の境界条件はありません。")
                return
            self._after_form_change(f"選択節点の境界条件を解除しました ({removed_count}件)")
            self._select_preview_payload({"nodes": sorted(selected_nodes, key=self._natural_sort_key)})

        def _mesh_palette_specs(self) -> list[tuple[str, str, Callable[..., Any], str]]:
            return [
                ("選択", "select", lambda *_args: self.activate_mesh_selection_tool(), "メッシュ制御とメッシュ要素を選択します。"),
                ("Undo", "undo", lambda *_args: self.undo_edit(), "直前のメッシュ編集または形状編集を戻します。"),
                ("Redo", "redo", lambda *_args: self.redo_edit(), "Undoで戻した編集をやり直します。"),
                ("制御点", "point", self.add_mesh_control_point_from_selection, "選択点または形状中心へメッシュ制御点を追加します。"),
                ("局所細分", "circle", self.add_mesh_refinement_from_selection, "選択点または形状中心へ局所細分範囲を追加します。"),
                ("分割線", "split", self.add_mesh_split_line_from_selection, "選択した2点/辺、または形状中心線をメッシュ分割線にします。"),
                ("サイズ", "grid", self.add_mesh_size_map_from_selection, "選択点まわりへ局所メッシュサイズを設定します。"),
                ("ブロック分割", "rectangle", self.split_selected_mesh_block, "選択要素範囲にブロック分割ヒントを追加します。"),
                ("品質抽出", "part_select", self.populate_mesh_quality_violation_table_async, "メッシュ品質違反を抽出して表示します。"),
                ("違反選択", "select", self.select_mesh_quality_violations, "品質違反要素をモデルビューで選択します。"),
                ("違反修復", "join", self.repair_selected_mesh_quality_violations, "選択した品質違反要素へ局所細分と点群再配置用の制御点を追加します。"),
                ("削除", "eraser", self.delete_selected_mesh_edit_items, "選択中のメッシュ制御を削除します。要素選択時はその形状のメッシュだけを削除します。"),
                ("メッシュ削除", "trim", self.reset_mesh_for_rebuild, "現在のメッシュ結果を削除し、再構成待ちにします。"),
                ("再構成", "extend", self.rebuild_mesh_from_shape, "形状とメッシュ制御からメッシュを作り直します。"),
                ("制御反映", "join", self.apply_mesh_controls_panel, "右パネルのメッシュ制御表を設定へ反映します。"),
                ("全体表示", "fit", lambda *_args: self.view.reset_to_scene(), "現在の形状とメッシュ範囲を表示します。"),
                ("モデルチェック", "model_check", self.run_model_check_async, "入力とモデルを事前チェックします。"),
                *self._common_selection_palette_specs(),
            ]

        def _mesh_palette_buttons(self) -> list[QPushButton]:
            buttons: list[QPushButton] = []
            for label, role, callback, tooltip in self._mesh_palette_specs():
                button = QPushButton("")
                button.setToolTip(tooltip)
                self._prepare_cad_tool_button(button, label, role)
                button.setProperty("chipRule", self._mesh_tool_rule(label))
                button.setProperty("meshTool", True)
                button.setProperty("meshToolLabel", label)
                if label == "選択":
                    button.setCheckable(True)
                    button.setProperty("meshToolMode", "select")
                button.clicked.connect(lambda _checked=False, cb=callback: cb())
                self._install_work_context_menu(button, "mesh_palette")
                buttons.append(button)
                self.mesh_tool_buttons.append(button)
            self._refresh_mesh_tool_button_state()
            return buttons

