        def _prepare_cad_tool_button(self, button: QPushButton, label: str, icon_role: str = "") -> None:
            icon = self._custom_cad_tool_icon(icon_role)
            if not icon.isNull():
                button.setIcon(icon)
            else:
                icon_map = {
                    "select": "SP_ArrowUp",
                    "part_select": "SP_FileDialogDetailedView",
                    "pan": "SP_ArrowRight",
                    "line": "SP_FileDialogNewFolder",
                    "polyline": "SP_FileDialogListView",
                    "rectangle": "SP_DirIcon",
                    "polygon": "SP_DirHomeIcon",
                    "circle": "SP_DialogYesButton",
                    "arc": "SP_BrowserReload",
                    "curve": "SP_FileDialogContentsView",
                    "point": "SP_DialogApplyButton",
                    "eraser": "SP_TrashIcon",
                    "move": "SP_ArrowRight",
                    "trim": "SP_DialogDiscardButton",
                    "extend": "SP_ArrowForward",
                    "split": "SP_FileDialogDetailedView",
                    "join": "SP_DialogApplyButton",
                    "grid": "SP_ComputerIcon",
                    "fit": "SP_BrowserReload",
                    "undo": "SP_ArrowBack",
                    "redo": "SP_ArrowForward",
                }
                pixmap_name = icon_map.get(icon_role, "SP_FileIcon")
                pixmap = getattr(QStyle.StandardPixmap, pixmap_name, None)
                if pixmap is not None:
                    button.setIcon(self.style().standardIcon(pixmap))
            button.setText("")
            button.setAccessibleName(label)
            description = str(button.toolTip() or "").strip()
            tooltip = f"<b>{html.escape(label)}</b>"
            if description:
                tooltip += f"<br>{html.escape(description)}"
            button.setToolTip(tooltip)
            button.setStatusTip(f"{label}: {description}" if description else label)
            button.setWhatsThis(f"{label}\n{description}" if description else label)
            button.setToolTipDuration(10000)
            button.setProperty("cadTool", True)
            button.setProperty("cadToolLabel", label)
            button.setProperty("cadToolRole", icon_role)
            button.setProperty("customCadIcon", not icon.isNull())
            button.setMinimumSize(32, 32)
            button.setMaximumSize(36, 36)
            button.setIconSize(QSize(18, 18))
            button.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Fixed)

        def _refresh_cad_tool_button_state(self) -> None:
            mode = str(getattr(self, "draw_mode", "select"))
            for button in list(getattr(self, "cad_tool_buttons", [])):
                draw_mode = str(button.property("cadDrawMode") or "")
                enabled, reason = self._chip_rule_state(str(button.property("chipRule") or ""))
                active = bool(draw_mode and draw_mode == mode)
                if draw_mode:
                    button.setChecked(draw_mode == mode)
                    button.setProperty("activeCadTool", active)
                self._set_chip_tool_state(button, enabled=enabled, active=active, reason=reason)
            label = getattr(self, "model_cad_mode_label", None)
            if label is not None:
                mode_labels = {
                    "select": "選択",
                    "line": "直線作図",
                    "helper": "補助線作図",
                    "region": "多角形作図",
                    "polyline": "折れ線作図",
                    "rectangle": "矩形作図",
                    "circle": "円作図",
                    "arc": "円弧作図",
                    "curve": "曲線作図",
                    "point": "点作図",
                }
                label.setText(f"現在: {mode_labels.get(mode, mode)}")

        def _refresh_mesh_tool_button_state(self) -> None:
            mesh_active = self._panel_key_from_tree_key(str(getattr(self, "current_panel_key", ""))) == "mesh"
            for button in list(getattr(self, "mesh_tool_buttons", [])):
                is_select = str(button.property("meshToolMode") or "") == "select"
                enabled, reason = self._chip_rule_state(str(button.property("chipRule") or ""))
                active = False
                if is_select:
                    active = mesh_active and str(getattr(self, "draw_mode", "select")) == "select"
                    button.setChecked(active)
                    button.setProperty("activeMeshTool", active)
                self._set_chip_tool_state(button, enabled=enabled, active=active, reason=reason)

        def _selected_operation_counts(self) -> dict[str, int]:
            try:
                entities = self._selected_preview_entities()
            except Exception:
                entities = {"nodes": set(), "edges": [], "elements": set()}
            try:
                action_nodes = self._selected_nodes_for_stage_action(include_elements=False)
            except Exception:
                action_nodes = []
            try:
                action_edges = self._selected_edges_for_stage_action()
            except Exception:
                action_edges = []
            try:
                regions = self._selected_mesh_region_keys()
            except Exception:
                regions = []
            return {
                "nodes": len(entities.get("nodes", set())),
                "edges": len(entities.get("edges", [])),
                "elements": len(entities.get("elements", set())),
                "action_nodes": len(action_nodes),
                "action_edges": len(action_edges),
                "regions": len(regions),
            }

        def _selected_chip_scene_data(self) -> list[Mapping[str, Any]]:
            data_items: list[Mapping[str, Any]] = []
            scene = getattr(self, "scene", None)
            if scene is None:
                return data_items
            for item in scene.selectedItems():
                data = item.data(0)
                if isinstance(data, Mapping) and data.get("kind") != "selection_highlight":
                    data_items.append(data)
            return data_items

        def _has_chip_selection(self) -> bool:
            return bool(self._selected_chip_scene_data())

        def _has_named_selection_pair(self) -> bool:
            return len(self._mapping(self.cfg.get("named_selections", {}))) >= 2

        def _cad_tool_rule(self, label: str) -> str:
            return {
                "Undo": "undo_history",
                "Redo": "redo_history",
                "領域を閉じる": "cad_region_points",
                "消しゴム": "geometry_selection",
                "トリム": "geometry_line",
                "延長": "geometry_line",
                "端点結合": "geometry_endpoint",
                "閉合線": "geometry_endpoint",
                "領域化": "geometry_line",
                "格子条件": "geometry_region",
                "補助線化": "geometry_line",
                "分割線化": "geometry_line",
                "選択解除": "selection",
                "履歴記録": "selection",
                "名前保存": "selection",
                "選択比較": "named_selection_pair",
                "選択set登録": "node_or_element_selection",
            }.get(str(label), "")

        def _mesh_tool_rule(self, label: str) -> str:
            return {
                "Undo": "undo_history",
                "Redo": "redo_history",
                "ブロック分割": "element_selection",
                "違反選択": "mesh_quality_rows",
                "違反修復": "mesh_quality_selection",
                "削除": "mesh_control_or_element_selection",
                "選択解除": "selection",
                "履歴記録": "selection",
                "名前保存": "selection",
                "選択比較": "named_selection_pair",
                "選択set登録": "node_or_element_selection",
            }.get(str(label), "")

        def _chip_rule_state(self, rule: str) -> tuple[bool, str]:
            rule = str(rule or "")
            if not rule:
                return True, ""
            data_items = self._selected_chip_scene_data()
            kinds = {str(data.get("kind", "")) for data in data_items}
            if rule == "undo_history":
                return (True, "") if getattr(self, "edit_undo_stack", []) else (False, "Undoできる履歴がありません。")
            if rule == "redo_history":
                return (True, "") if getattr(self, "edit_redo_stack", []) else (False, "Redoできる履歴がありません。")
            if rule == "cad_region_points":
                ready = str(getattr(self, "draw_mode", "select")) == "region" and len(getattr(self, "region_points", [])) >= 3
                return (True, "") if ready else (False, "領域作図で3点以上入力すると有効です。")
            if rule == "selection":
                return (True, "") if data_items else (False, "選択対象がありません。")
            if rule == "geometry_selection":
                geometry_kinds = {"geometry_line", "geometry_endpoint", "geometry_region", "geometry_tunnel", "geometry_point"}
                return (True, "") if kinds.intersection(geometry_kinds) else (False, "形状を選択してください。")
            if rule == "geometry_line":
                return (True, "") if kinds.intersection({"geometry_line", "geometry_endpoint"}) else (False, "線分または端点を選択してください。")
            if rule == "geometry_endpoint":
                return (True, "") if "geometry_endpoint" in kinds else (False, "端点を選択してください。")
            if rule == "geometry_region":
                return (True, "") if "geometry_region" in kinds else (False, "形状領域を選択してください。")
            if rule == "node_or_element_selection":
                return (True, "") if kinds.intersection({"node", "element"}) else (False, "節点または要素を選択してください。")
            if rule == "element_selection":
                return (True, "") if "element" in kinds else (False, "要素を選択してください。")
            if rule == "mesh_control_or_element_selection":
                mesh_kinds = {"mesh_control_point", "mesh_refinement", "mesh_size_map", "mesh_split_line", "mesh_quality_violation", "element"}
                return (True, "") if kinds.intersection(mesh_kinds) else (False, "メッシュ制御または要素を選択してください。")
            if rule == "mesh_quality_rows":
                table = getattr(self, "mesh_quality_violation_table", None)
                row_count = int(table.rowCount()) if table is not None else 0
                return (True, "") if row_count > 0 else (False, "品質違反を抽出してください。")
            if rule == "mesh_quality_selection":
                return (True, "") if kinds.intersection({"mesh_quality_violation", "element"}) else (False, "品質違反要素を選択してください。")
            if rule == "named_selection_pair":
                return (True, "") if self._has_named_selection_pair() else (False, "比較する名前付き選択が2件以上必要です。")
            return True, ""

        def _set_chip_tool_state(self, button: QAbstractButton, *, enabled: bool, active: bool = False, reason: str = "") -> None:
            if self._input_mutation_locked() and not self._analysis_reference_tool_allowed(button):
                enabled = False
                active = False
                reason = self._input_mutation_lock_message("入力変更")
            base = button.property("chipBaseTooltip")
            if base is None:
                base = str(button.toolTip() or button.accessibleName() or "")
                button.setProperty("chipBaseTooltip", base)
            button.setEnabled(enabled)
            button.setProperty("chipDisabled", not enabled)
            button.setProperty("chipDisabledReason", reason if not enabled else "")
            display_base = translate_surface_tooltip(str(base), locale=self.gui_locale)
            if enabled or not reason:
                button.setToolTip(display_base)
            else:
                disabled_label = translate_surface_text("無効", locale=self.gui_locale)
                display_reason = translate_surface_text(str(reason), locale=self.gui_locale)
                button.setToolTip(f"{display_base}\n{disabled_label}: {display_reason}" if display_base else f"{disabled_label}: {display_reason}")
            if not enabled:
                button.setStyleSheet("background:#f1f5f9; border:1px solid #cbd5e1; color:#94a3b8;")
            elif active:
                button.setStyleSheet("background:#dbeafe; border:2px solid #2563eb;")
            else:
                button.setStyleSheet("")

        def _selected_load_body_material_name(self) -> str:
            combo = getattr(self, "load_body_material", None)
            if combo is None:
                return ""
            data = combo.currentData()
            if data is not None and str(data) != "__selected__":
                return str(data).strip()
            text = str(combo.currentText() or "").strip()
            return "" if text in {"", "選択要素の材料"} else text

        def _operation_rule_state(self, rule: str) -> tuple[bool, str]:
            rule = str(rule or "")
            if not rule:
                return True, ""
            if self._input_mutation_locked():
                return False, self._input_mutation_lock_message("入力変更")
            panel = self._panel_key_from_tree_key(str(getattr(self, "current_panel_key", "")))
            counts = self._selected_operation_counts()
            if rule.startswith("material_") and panel != "materials":
                return False, "材料工程で有効です。"
            if rule.startswith("boundary_") and panel != "boundary_conditions":
                return False, "境界条件工程で有効です。"
            if rule.startswith("load_") and panel != "loads":
                return False, "荷重工程で有効です。"
            if rule.startswith("stage_") and panel != "stages":
                return False, "ステージ工程で有効です。"
            if rule == "material_assign":
                if counts["regions"] <= 0:
                    return False, "形状または要素を選択してください。"
                if not self._material_names():
                    return False, "材料を先に定義してください。"
                return True, ""
            if rule == "material_clear":
                return (True, "") if counts["regions"] > 0 else (False, "形状または要素を選択してください。")
            if rule == "boundary_nodes_edges":
                return (True, "") if counts["action_nodes"] > 0 else (False, "節点または辺を選択してください。")
            if rule == "boundary_mpc":
                return (True, "") if counts["action_nodes"] >= 2 else (False, "MPCには節点を2つ以上選択してください。")
            if rule == "boundary_hydro":
                kind = str(getattr(getattr(self, "boundary_hydro_kind", None), "currentData", lambda: "")() or "")
                if kind == "node_pressure":
                    return (True, "") if counts["action_nodes"] > 0 else (False, "水圧を設定する節点を選択してください。")
                return (True, "") if counts["action_edges"] > 0 else (False, "水理境界を設定する辺または要素境界を選択してください。")
            if rule == "load_nodes":
                return (True, "") if counts["nodes"] > 0 else (False, "節点荷重を設定する節点を選択してください。")
            if rule == "load_body":
                if counts["elements"] > 0 or self._selected_load_body_material_name():
                    return True, ""
                return False, "体積力は要素を選択するか、材料名を指定してください。"
            if rule == "load_edges_or_elements":
                return (True, "") if counts["action_edges"] > 0 else (False, "面荷重を設定する辺または要素境界を選択してください。")
            if rule == "stage_elements":
                return (True, "") if counts["elements"] > 0 else (False, "ステージ対象の要素を選択してください。")
            if rule == "stage_nodes_edges":
                return (True, "") if counts["action_nodes"] > 0 else (False, "境界条件を設定する節点または辺を選択してください。")
            if rule == "stage_edges":
                return (True, "") if counts["action_edges"] > 0 else (False, "荷重を設定する辺または要素境界を選択してください。")
            if rule == "stage_hydro":
                return (True, "") if counts["action_nodes"] > 0 or counts["action_edges"] > 0 else (False, "水理条件を設定する節点または辺を選択してください。")
            return True, ""

        def _set_operation_button_state(self, button: QAbstractButton, enabled: bool, reason: str = "") -> None:
            base = button.property("operationBaseTooltip")
            if base is None:
                base = str(button.toolTip() or button.text() or "")
                button.setProperty("operationBaseTooltip", base)
            button.setEnabled(enabled)
            display_base = translate_surface_text(str(base), locale=self.gui_locale)
            if enabled or not reason:
                button.setToolTip(display_base)
            else:
                disabled_label = translate_surface_text("無効", locale=self.gui_locale)
                display_reason = translate_surface_text(str(reason), locale=self.gui_locale)
                button.setToolTip(f"{display_base}\n{disabled_label}: {display_reason}" if display_base else f"{disabled_label}: {display_reason}")

        def _refresh_operation_button_enabled_states(self, panel_key: str | None = None) -> None:
            _panel = self._panel_key_from_tree_key(str(panel_key or getattr(self, "current_panel_key", "")))
            containers = list(getattr(self, "panel_pages", {}).values())
            auxiliary_panel = getattr(self, "auxiliary_panel", None)
            if auxiliary_panel is not None:
                containers.append(auxiliary_panel)
            seen: set[int] = set()
            for page in containers:
                for button in page.findChildren(QAbstractButton):
                    button_id = id(button)
                    if button_id in seen:
                        continue
                    seen.add(button_id)
                    rule = str(button.property("operationRule") or "")
                    if not rule:
                        continue
                    enabled, reason = self._operation_rule_state(rule)
                    self._set_operation_button_state(button, enabled, reason)

        def _custom_cad_tool_icon(self, icon_role: str) -> QIcon:
            if icon_role not in {
                "select",
                "part_select",
                "line",
                "polyline",
                "rectangle",
                "polygon",
                "circle",
                "arc",
                "curve",
                "point",
                "eraser",
                "move",
                "trim",
                "extend",
                "split",
                "join",
                "grid",
                "fit",
                "model_check",
                "finish_region",
                "selection_rectangle",
                "lasso",
                "filter",
                "clear",
                "invert",
                "history",
                "named",
                "compare",
                "help",
                "save_set",
                "undo",
                "redo",
            }:
                return QIcon()
            pixmap = QPixmap(18, 18)
            pixmap.fill(Qt.GlobalColor.transparent)
            painter = QPainter(pixmap)
            painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
            pen = QPen(QColor("#2f4858"))
            pen.setWidth(2)
            accent = QPen(QColor("#0d6efd"))
            accent.setWidth(2)
            painter.setPen(pen)
            painter.setBrush(Qt.BrushStyle.NoBrush)
            if icon_role == "select":
                painter.drawLine(5, 3, 12, 15)
                painter.drawLine(5, 3, 4, 10)
                painter.drawLine(5, 3, 11, 6)
            elif icon_role == "part_select":
                painter.drawRect(4, 4, 10, 10)
                painter.setPen(accent)
                painter.drawEllipse(7, 7, 4, 4)
            elif icon_role == "line":
                painter.drawLine(3, 14, 15, 4)
                painter.setPen(accent)
                painter.drawEllipse(2, 13, 3, 3)
                painter.drawEllipse(13, 3, 3, 3)
            elif icon_role == "polyline":
                painter.drawPolyline(QPolygonF([QPointF(3, 13), QPointF(7, 5), QPointF(12, 10), QPointF(15, 4)]))
            elif icon_role == "rectangle":
                painter.drawRect(4, 5, 10, 8)
            elif icon_role == "polygon":
                painter.drawPolygon(QPolygonF([QPointF(9, 3), QPointF(15, 8), QPointF(12, 15), QPointF(4, 13), QPointF(3, 6)]))
            elif icon_role == "circle":
                painter.drawEllipse(4, 4, 10, 10)
            elif icon_role == "arc":
                painter.drawArc(3, 3, 12, 12, 25 * 16, 240 * 16)
            elif icon_role == "curve":
                painter.drawPolyline(QPolygonF([QPointF(3, 13), QPointF(6, 4), QPointF(11, 14), QPointF(15, 5)]))
            elif icon_role == "point":
                painter.setBrush(QColor("#0d6efd"))
                painter.drawEllipse(7, 7, 4, 4)
            elif icon_role == "eraser":
                painter.drawRect(5, 8, 8, 5)
                painter.drawLine(4, 14, 14, 14)
            elif icon_role == "move":
                painter.drawLine(9, 3, 9, 15)
                painter.drawLine(3, 9, 15, 9)
                painter.drawLine(9, 3, 6, 6)
                painter.drawLine(9, 3, 12, 6)
                painter.drawLine(15, 9, 12, 6)
                painter.drawLine(15, 9, 12, 12)
            elif icon_role == "trim":
                painter.drawLine(3, 13, 15, 5)
                painter.setPen(accent)
                painter.drawLine(7, 3, 11, 15)
            elif icon_role == "extend":
                painter.drawLine(3, 13, 10, 7)
                painter.setPen(accent)
                painter.drawLine(10, 7, 15, 3)
                painter.drawLine(15, 3, 12, 4)
                painter.drawLine(15, 3, 14, 6)
            elif icon_role == "split":
                painter.drawLine(3, 13, 15, 5)
                painter.setPen(accent)
                painter.drawEllipse(8, 8, 3, 3)
            elif icon_role == "join":
                painter.drawLine(3, 4, 9, 9)
                painter.drawLine(3, 14, 9, 9)
                painter.setPen(accent)
                painter.drawLine(9, 9, 15, 9)
            elif icon_role == "grid":
                for value in (5, 9, 13):
                    painter.drawLine(value, 3, value, 15)
                    painter.drawLine(3, value, 15, value)
            elif icon_role == "fit":
                painter.drawRect(4, 4, 10, 10)
                painter.drawLine(4, 7, 4, 4)
                painter.drawLine(4, 4, 7, 4)
                painter.drawLine(14, 11, 14, 14)
                painter.drawLine(14, 14, 11, 14)
            elif icon_role == "model_check":
                painter.drawEllipse(4, 4, 10, 10)
                painter.setPen(accent)
                painter.drawLine(7, 9, 9, 11)
                painter.drawLine(9, 11, 13, 6)
            elif icon_role == "finish_region":
                painter.drawPolygon(QPolygonF([QPointF(5, 4), QPointF(14, 7), QPointF(12, 14), QPointF(4, 12)]))
                painter.setPen(accent)
                painter.drawLine(6, 9, 8, 11)
                painter.drawLine(8, 11, 13, 5)
            elif icon_role == "selection_rectangle":
                painter.drawRect(4, 5, 10, 8)
                painter.setPen(accent)
                painter.drawRect(2, 3, 14, 12)
            elif icon_role == "lasso":
                painter.drawEllipse(3, 5, 12, 8)
                painter.setPen(accent)
                painter.drawLine(10, 12, 15, 15)
            elif icon_role == "filter":
                painter.drawLine(4, 4, 14, 4)
                painter.drawLine(14, 4, 10, 9)
                painter.drawLine(10, 9, 10, 14)
                painter.drawLine(10, 14, 8, 15)
            elif icon_role == "clear":
                painter.drawLine(4, 4, 14, 14)
                painter.drawLine(14, 4, 4, 14)
            elif icon_role == "invert":
                painter.drawArc(4, 4, 10, 10, 45 * 16, 270 * 16)
                painter.setPen(accent)
                painter.drawLine(12, 4, 15, 4)
                painter.drawLine(15, 4, 15, 7)
            elif icon_role == "history":
                painter.drawEllipse(4, 4, 10, 10)
                painter.drawLine(9, 9, 9, 5)
                painter.drawLine(9, 9, 12, 11)
            elif icon_role == "named":
                painter.drawRect(4, 4, 10, 10)
                painter.setPen(accent)
                painter.drawLine(6, 7, 12, 7)
                painter.drawLine(6, 10, 10, 10)
            elif icon_role == "compare":
                painter.drawRect(3, 5, 5, 8)
                painter.drawRect(10, 5, 5, 8)
                painter.setPen(accent)
                painter.drawLine(8, 9, 10, 9)
            elif icon_role == "help":
                painter.drawEllipse(4, 4, 10, 10)
                painter.drawText(7, 13, "?")
            elif icon_role == "save_set":
                painter.drawRect(4, 4, 10, 10)
                painter.setPen(accent)
                painter.drawLine(6, 11, 12, 11)
                painter.drawLine(9, 8, 9, 14)
            elif icon_role == "undo":
                painter.drawArc(4, 5, 10, 9, 20 * 16, 250 * 16)
                painter.drawLine(5, 6, 3, 10)
                painter.drawLine(5, 6, 9, 6)
            elif icon_role == "redo":
                painter.drawArc(4, 5, 10, 9, -90 * 16, 250 * 16)
                painter.drawLine(13, 6, 15, 10)
                painter.drawLine(13, 6, 9, 6)
            painter.end()
            return QIcon(pixmap)

        def _add_cad_tool_button_grid(self, parent_layout: QVBoxLayout, buttons: list[QPushButton], *, columns: int = 12) -> None:
            grid = QGridLayout()
            grid.setHorizontalSpacing(4)
            grid.setVerticalSpacing(4)
            column_count = max(1, columns)
            for index, button in enumerate(buttons):
                grid.addWidget(button, index // column_count, index % column_count)
            grid.setColumnStretch(column_count, 1)
            parent_layout.addLayout(grid)

        def _set_cad_advanced_visible(self, visible: bool) -> None:
            widget = getattr(self, "model_cad_advanced_widget", None)
            if widget is not None:
                widget.setVisible(bool(visible) and getattr(self, "current_panel_key", "") == "geometry")
            button = getattr(self, "model_cad_more_button", None)
            if button is not None:
                button.setText("-" if visible else "...")
                if self.gui_locale == "en":
                    button.setToolTip("Close advanced tools." if visible else "Open less frequently used drawing, repair, and selection tools.")
                else:
                    button.setToolTip("詳細ツールを閉じます。" if visible else "使用頻度の低い作図・修復・選択ツールを開きます。")

        def _add_panel_button_rows(self, parent_layout: QVBoxLayout, buttons: list[QPushButton], *, columns: int = 2) -> None:
            for start in range(0, len(buttons), max(1, columns)):
                row = QHBoxLayout()
                for button in buttons[start : start + max(1, columns)]:
                    self._prepare_panel_action_button(button)
                    row.addWidget(button)
                row.addStretch(1)
                parent_layout.addLayout(row)

        def _add_uniform_panel_button_grid(self, parent_layout: QVBoxLayout, buttons: list[QPushButton], *, columns: int = 2, min_width: int = 196) -> None:
            grid = QGridLayout()
            grid.setHorizontalSpacing(8)
            grid.setVerticalSpacing(6)
            column_count = max(1, columns)
            for col in range(column_count):
                grid.setColumnStretch(col, 1)
            for index, button in enumerate(buttons):
                row = index // column_count
                column = index % column_count
                button.setProperty("uniformPanelButtonWidth", int(min_width))
                button.setProperty("uniformPanelButtonColumns", int(column_count))
                button.setProperty("uniformPanelButtonRow", int(row))
                button.setProperty("uniformPanelButtonColumn", int(column))
                self._prepare_panel_action_button(button)
                grid.addWidget(button, row, column)
            parent_layout.addLayout(grid)

        def _add_uniform_panel_button_pair_grid(self, parent_layout: QVBoxLayout, rows: list[list[QPushButton]], *, columns: int = 2, min_width: int = 196) -> None:
            grid = QGridLayout()
            grid.setHorizontalSpacing(8)
            grid.setVerticalSpacing(6)
            column_count = max(1, columns)
            for col in range(column_count):
                grid.setColumnStretch(col, 1)
            for row_index, row_buttons in enumerate(rows):
                if not row_buttons:
                    continue
                span_single = len(row_buttons) == 1 and column_count > 1
                for column_index, button in enumerate(row_buttons[:column_count]):
                    button.setProperty("uniformPanelButtonWidth", int(min_width))
                    button.setProperty("uniformPanelButtonColumns", int(column_count))
                    button.setProperty("uniformPanelButtonRow", int(row_index))
                    button.setProperty("uniformPanelButtonColumn", int(column_index))
                    button.setProperty("uniformPanelButtonSpan", int(column_count if span_single else 1))
                    self._prepare_panel_action_button(button)
                    if span_single:
                        grid.addWidget(button, row_index, 0, 1, column_count)
                    else:
                        grid.addWidget(button, row_index, column_index)
            parent_layout.addLayout(grid)

