        def _configure_workspace_tabs(self) -> None:
            self.tabs.setDocumentMode(True)
            self.tabs.setMovable(False)
            self.tabs.setUsesScrollButtons(True)
            self.tabs.setElideMode(Qt.TextElideMode.ElideRight)
            self.tabs.tabBar().hide()
            self._apply_workspace_tab_locale()

        def _apply_workspace_tab_locale(self) -> None:
            tabs = getattr(self, "tabs", None)
            if tabs is None:
                return
            rows = self._workspace_tab_locale_rows()
            for key, widget in getattr(self, "workspace_tab_widgets", {}).items():
                index = tabs.indexOf(widget)
                if index < 0:
                    continue
                label, tooltip = rows.get(key, (key, ""))
                tabs.setTabText(index, label)
                tabs.setTabToolTip(index, tooltip)
            caption = getattr(self, "workspace_tabs_caption", None)
            if caption is not None:
                caption.setText(
                    "Workspace View: switch between model, checks, input, and results."
                    if self.gui_locale == "en"
                    else "作業ビュー: モデル表示・検証・入力・結果を切り替えます。"
                )
                caption.setToolTip(
                    "Advanced data, recovery, and audit tabs are shown in Advanced/Maintenance mode."
                    if self.gui_locale == "en"
                    else "詳細データ、復旧候補、監査ログは詳細/保守モードで表示します。"
                )
                caption.setMaximumHeight(0)
                caption.setVisible(False)
            self._update_workspace_heading(getattr(self, "current_panel_key", "workflow"))

        def _update_workspace_heading(self, panel_key: str) -> None:
            caption = getattr(self, "workspace_tabs_caption", None)
            if caption is None:
                return
            caption.setMaximumHeight(0)
            caption.setVisible(False)
            guidance = getattr(self, "workflow_guidance", None)
            if not isinstance(guidance, Mapping):
                guidance = build_workflow_guidance(self.cfg, result_dir=self._active_result_dir(), locale=self.gui_locale)
            panel_key = self._panel_key_from_tree_key(panel_key)
            steps = [step for step in guidance.get("steps", []) if isinstance(step, Mapping)]
            step = next((row for row in steps if str(row.get("panel", "")) == panel_key or str(row.get("id", "")) == panel_key), None)
            if step is None:
                label = self._auxiliary_panel_texts().get(panel_key, (panel_key, ""))[0]
                status = "Current" if self.gui_locale == "en" else "選択中"
                next_action = ""
                step_id = panel_key
            else:
                label = str(step.get("label", panel_key))
                step_id = str(step.get("id", panel_key))
                has_issue = self.workflow_step_has_input_issue(step_id, str(step.get("panel", panel_key)))
                if has_issue:
                    status = "Input Issue" if self.gui_locale == "en" else "入力課題"
                else:
                    status = str(step.get("status_label", step.get("status", "")))
                next_action = str(step.get("next_action", ""))
            prefix = "Workspace View" if self.gui_locale == "en" else "作業ビュー"
            status_label = "Status" if self.gui_locale == "en" else "状態"
            next_label = "Next" if self.gui_locale == "en" else "次"
            text = f"{prefix}: {label} | {status_label}: {status}"
            if next_action:
                text += f" | {next_label}: {next_action}"
            caption.setText(text)
            caption.setProperty("currentPanel", panel_key)
            caption.setProperty("workflowStepId", step_id)
            caption.setProperty("workflowStatus", status)

        @staticmethod
        def _model_display_panel_keys() -> set[str]:
            return {"geometry", "mesh", "materials", "boundary_conditions", "loads", "stages"}

        def _apply_fixed_workspace_target(self, panel_key: str) -> None:
            tabs = getattr(self, "tabs", None)
            if tabs is None:
                return
            panel = self._panel_key_from_tree_key(str(panel_key or ""))
            if panel in {"workflow", "analysis", "model_check", "solver"}:
                page = self.panel_pages.get(panel)
                if page is not None:
                    self.panel_stack.setCurrentWidget(page)
                tabs.setCurrentWidget(self.panel_stack)
            elif panel in self._model_display_panel_keys():
                model_page = getattr(self, "model_workspace_page", None)
                if model_page is not None:
                    tabs.setCurrentWidget(model_page)

        def _apply_workspace_tab_visibility(self, panel_key: str, *, detail_mode: bool) -> None:
            tabs = getattr(self, "tabs", None)
            if tabs is None:
                return
            panel_key = self._panel_key_from_tree_key(str(panel_key or ""))
            mode = self._current_gui_operation_mode()
            inline_detail = panel_key in getattr(self, "inline_detail_panel_keys", set())
            fixed_workspace = panel_key in {"workflow", "analysis"} or panel_key in self._model_display_panel_keys()
            if panel_key in {"workflow", "analysis"}:
                visible_keys = {"detail"}
            elif panel_key in self._model_display_panel_keys():
                visible_keys = {"model"}
            else:
                visible_keys = {"model", "check", "assist", "form", "result", "table"}
                if detail_mode:
                    visible_keys.update({"yaml", "selection_history", "named_selection", "selection_compare", "cell_errors", "detail"})
                if mode == "maintenance":
                    visible_keys.update({"recovery", "audit"})
                if panel_key == "model_check":
                    visible_keys.update({"detail", "check", "cell_errors"})
                if panel_key == "solver":
                    visible_keys.add("detail")
                if inline_detail:
                    visible_keys.add("model")
                    visible_keys.discard("detail")
            current_widget = tabs.currentWidget()
            if fixed_workspace or (inline_detail and current_widget is getattr(self, "panel_stack", None)):
                current_widget = None
            for key, widget in getattr(self, "workspace_tab_widgets", {}).items():
                index = tabs.indexOf(widget)
                if index < 0:
                    continue
                visible = key in visible_keys or widget is current_widget
                if hasattr(tabs, "setTabVisible"):
                    tabs.setTabVisible(index, visible)
                else:
                    tabs.setTabEnabled(index, visible)
            tabs.tabBar().hide()

        def _focused_table(self) -> Any | None:
            widget = QApplication.focusWidget()
            while widget is not None:
                if isinstance(widget, (QTableWidget, QTableView)):
                    return widget
                widget = widget.parentWidget() if hasattr(widget, "parentWidget") else None
            return None

        def _copy_model_table_selection(self, table: QTableView) -> str:
            indexes = sorted(table.selectedIndexes(), key=lambda item: (item.row(), item.column()))
            model = table.model()
            if not indexes:
                current = table.currentIndex()
                if model is None or not current.isValid():
                    return ""
                value = model.data(current, Qt.ItemDataRole.DisplayRole)
                return "" if value is None else str(value)
            rows = sorted({index.row() for index in indexes})
            cols = sorted({index.column() for index in indexes})
            selected = {(index.row(), index.column()): index for index in indexes}
            lines = []
            for row in rows:
                values = []
                for col in cols:
                    index = selected.get((row, col))
                    if model is None or index is None:
                        values.append("")
                    else:
                        value = model.data(index, Qt.ItemDataRole.DisplayRole)
                        values.append("" if value is None else str(value))
                lines.append("\t".join(values))
            return "\n".join(lines)

        def _copy_table_selection(self, table: Any) -> str:
            if isinstance(table, QTableView) and not isinstance(table, QTableWidget):
                return self._copy_model_table_selection(table)
            ranges = table.selectedRanges()
            if not ranges:
                row = table.currentRow()
                col = table.currentColumn()
                if row < 0 or col < 0:
                    return ""
                item = table.item(row, col)
                return "" if item is None else item.text()
            selected = ranges[0]
            lines = []
            for row in range(selected.topRow(), selected.bottomRow() + 1):
                values = []
                for col in range(selected.leftColumn(), selected.rightColumn() + 1):
                    item = table.item(row, col)
                    values.append("" if item is None else item.text())
                lines.append("\t".join(values))
            return "\n".join(lines)

        def copy_current_selection(self) -> None:
            widget = QApplication.focusWidget()
            table = self._focused_table()
            if table is not None:
                QApplication.clipboard().setText(self._copy_table_selection(table))
                self.statusBar().showMessage("選択セルをコピーしました。")
                return
            if widget is not None and hasattr(widget, "copy"):
                widget.copy()
                return
            self.statusBar().showMessage("コピー対象がありません。")

        def cut_current_selection(self) -> None:
            if self._guard_input_mutation("切り取り"):
                return
            widget = QApplication.focusWidget()
            table = self._focused_table()
            if table is not None:
                QApplication.clipboard().setText(self._copy_table_selection(table))
                if isinstance(table, QTableWidget):
                    for item in table.selectedItems():
                        item.setText("")
                self.statusBar().showMessage("選択セルを切り取りました。")
                return
            if widget is not None and hasattr(widget, "cut"):
                widget.cut()
                return
            self.statusBar().showMessage("切り取り対象がありません。")

        def paste_current_selection(self) -> None:
            if self._guard_input_mutation("貼り付け"):
                return
            widget = QApplication.focusWidget()
            table = self._focused_table()
            text = QApplication.clipboard().text()
            if table is not None and text and isinstance(table, QTableWidget):
                start_row = max(0, table.currentRow())
                start_col = max(0, table.currentColumn())
                for r_offset, line in enumerate(text.splitlines() or [text]):
                    row = start_row + r_offset
                    if row >= table.rowCount():
                        table.insertRow(row)
                    for c_offset, value in enumerate(line.split("\t")):
                        col = start_col + c_offset
                        if col >= table.columnCount():
                            continue
                        item = table.item(row, col)
                        if item is None:
                            item = QTableWidgetItem("")
                            table.setItem(row, col, item)
                        item.setText(value)
                self.statusBar().showMessage("クリップボードを表へ貼り付けました。")
                return
            if widget is not None and hasattr(widget, "paste"):
                widget.paste()
                return
            self.statusBar().showMessage("貼り付け先がありません。")

        def delete_current_selection(self) -> None:
            if self._guard_input_mutation("削除"):
                return
            table = self._focused_table()
            if table is not None and isinstance(table, QTableWidget):
                for item in table.selectedItems():
                    item.setText("")
                self.statusBar().showMessage("選択セルを削除しました。")
                return
            if getattr(self, "current_panel_key", "") == "mesh":
                self.delete_selected_mesh_edit_items()
                return
            if getattr(self, "current_panel_key", "") in {"workflow", "geometry"}:
                self.delete_selected_geometry()
                return
            self.clear_preview_selection()

        def edit_selected_coordinates(self) -> None:
            if self._guard_input_mutation("座標編集"):
                return
            if getattr(self, "current_panel_key", "") not in {"workflow", "geometry", "mesh"}:
                self._activate_panel("geometry")
            self.edit_selected_geometry_line()

        def activate_pan_view(self) -> None:
            self.draw_mode = "select"
            self.selection_mode = "normal"
            self._apply_selection_drag_mode()
            self.statusBar().showMessage("表示パンを有効にしました。")

        def toggle_grid_visibility(self) -> None:
            if getattr(self, "show_grid_lines", None) is not None:
                self.show_grid_lines.toggle()
            self.update_preview(reset_view=False)

        def toggle_snap_enabled(self) -> None:
            if getattr(self, "snap_enabled", None) is not None:
                self.snap_enabled.toggle()
            state = "有効" if getattr(self, "snap_enabled", None) is not None and self.snap_enabled.isChecked() else "無効"
            self.statusBar().showMessage(f"スナップ: {state}")

        def cycle_display_quality_mode(self) -> None:
            combo = getattr(self, "display_quality_mode", None)
            if combo is None or combo.count() == 0:
                return
            combo.setCurrentIndex((combo.currentIndex() + 1) % combo.count())
            self.update_preview(reset_view=False)

        def focus_result_display_controls(self) -> None:
            self._activate_panel("results")
            summary = self._current_summary_path()
            if summary is None:
                self.notify_user(
                    "No analysis results are available." if self.gui_locale == "en" else "解析結果がまだありません。"
                )
                return
            if getattr(self, "aux_result_control_group", None) is not None:
                self.aux_result_control_group.setVisible(True)
            self.statusBar().showMessage("結果表示調整を右ペインに表示しました。")

        def _refresh_result_action_states(self) -> None:
            try:
                summary_path = self._current_summary_path() or getattr(self, "_loaded_result_summary_path", None)
                available = summary_path is not None and Path(summary_path).exists()
            except Exception:
                available = False
                summary_path = None
            reason = "Analysis results are not available." if self.gui_locale == "en" else "解析結果がまだありません。"
            for button in getattr(self, "result_data_buttons", []) or []:
                if button.property("resultBaseTooltip") is None:
                    button.setProperty("resultBaseTooltip", str(button.toolTip() or button.text() or ""))
                button.setEnabled(available)
                button.setToolTip(str(button.property("resultBaseTooltip") or "") if available else reason)
            detail_mode = self._show_internal_representation()
            for attr in ("result_primary_actions_widget", "result_more_button"):
                widget = getattr(self, attr, None)
                if widget is not None:
                    widget.setVisible(available)
            stage_controls = getattr(self, "result_stage_controls_widget", None)
            if stage_controls is not None:
                stage_controls.setVisible(available and detail_mode)
            detail_widget = getattr(self, "result_detail_actions_widget", None)
            more_button = getattr(self, "result_more_button", None)
            if detail_widget is not None:
                detail_widget.setVisible(available and more_button is not None and more_button.isChecked())
            self.refresh_result_judgment_summary(summary_path=Path(summary_path) if summary_path is not None else None)
            tabs = getattr(self, "results_tabs", None)
            if tabs is not None:
                if not available:
                    tabs.setCurrentIndex(0)
                if 1 < tabs.count():
                    tabs.setTabEnabled(1, available)
                    tabs.setTabVisible(1, available)
                if 2 < tabs.count():
                    is_srm = str(getattr(self, "result_judgment_model", {}).get("kind", "")) == "srm"
                    tabs.setTabEnabled(2, available and is_srm)
                    tabs.setTabVisible(2, available and is_srm)
                if 3 < tabs.count():
                    tabs.setTabEnabled(3, available)
                    tabs.setTabVisible(3, available)
            controls = getattr(self, "aux_result_control_group", None)
            if controls is not None:
                controls.setEnabled(available)
                controls.setVisible(available and getattr(self, "current_panel_key", "") == "results")

        def set_left_navigation_visible(self, visible: bool) -> None:
            panel = getattr(self, "left_navigation_panel", None)
            if panel is None:
                return
            if not visible:
                self._remember_workspace_splitter_state()
            panel.setVisible(bool(visible))
            action = getattr(self, "view_navigation_action", None)
            if action is not None and action.isChecked() != bool(visible):
                action.blockSignals(True)
                action.setChecked(bool(visible))
                action.blockSignals(False)
            if visible:
                self._workspace_splitter_force_restore = True
                self._apply_context_visibility(getattr(self, "current_panel_key", "analysis"))

        def set_right_inspector_visible(self, visible: bool) -> None:
            panel = getattr(self, "right_panel_stack", None)
            if panel is None:
                return
            if not visible:
                self._remember_workspace_splitter_state()
            panel.setVisible(bool(visible))
            action = getattr(self, "view_inspector_action", None)
            if action is not None and action.isChecked() != bool(visible):
                action.blockSignals(True)
                action.setChecked(bool(visible))
                action.blockSignals(False)
            if visible:
                self._workspace_splitter_force_restore = True
                self._apply_context_visibility(getattr(self, "current_panel_key", "analysis"))

