        def _context_menu_action_rule(self, panel: str, label: str, callback: Callable[..., Any] | None) -> str:
            if callback is None:
                return ""
            name = str(getattr(callback, "__name__", ""))
            if panel == "materials":
                if str(label).startswith("材料:") or str(label).startswith("譚先侭:"):
                    return "material_assign"
                if "材料割当解除" in str(label) or "譚先侭蜑ｲ蠖楢ｧ｣髯､" in str(label):
                    return "material_clear"
                return ""
            if panel == "boundary_conditions":
                if name in {"activate_boundary_selection_tool", "apply_boundary_conditions_panel", "reset_to_scene"}:
                    return ""
                if name == "add_selected_hydro_boundary_condition":
                    return "boundary_hydro"
                if name == "add_selected_mpc_constraints":
                    return "boundary_mpc"
                if name == "register_selected_nodes_as_set":
                    return "boundary_nodes_edges"
                return "boundary_nodes_edges"
            if panel == "loads":
                if name in {"activate_load_selection_tool", "apply_loads_panel", "reset_to_scene"}:
                    return ""
                if name == "add_selected_nodal_load_condition":
                    return "load_nodes"
                if name == "add_selected_body_load_condition":
                    return "load_body"
                if name == "add_selected_distributed_load_condition":
                    return "load_edges_or_elements"
                if name == "<lambda>":
                    text = str(label)
                    if "面荷重" in text or "擇闕ｷ驥" in text:
                        return "load_edges_or_elements"
                return ""
            if panel == "stages":
                if name in {"activate_stage_selection_tool", "add_pseudo_static_earthquake_load", "show_stage_difference"}:
                    return ""
                if name in {"apply_selected_elements_to_stage_set", "add_selected_elements_to_stage_death", "add_selected_elements_to_stage_birth", "add_selected_elements_to_stage_material_change"}:
                    return "stage_elements"
                if name == "add_selected_prescribed_displacement":
                    return "stage_nodes_edges"
                if name == "add_selected_edge_load":
                    return "stage_edges"
                if name == "add_selected_hydro_coupling":
                    return "stage_hydro"
                return ""
            return ""

        def _reference_context_action_allowed(self, label: str, callback: Callable[..., Any] | None) -> bool:
            if callback is None:
                return True
            name = str(getattr(callback, "__name__", ""))
            if name in {
                "activate_cad_selection_tool",
                "activate_mesh_selection_tool",
                "activate_material_assignment_selection",
                "activate_boundary_selection_tool",
                "activate_load_selection_tool",
                "activate_stage_selection_tool",
                "toggle_grid_visibility",
                "reset_to_scene",
                "populate_mesh_quality_violation_table_async",
                "select_mesh_quality_violations",
                "show_stage_difference",
            }:
                return True
            return str(label) in {
                "選択",
                "部分選択",
                "グリッド表示",
                "全体表示",
                "品質抽出",
                "違反選択",
                "ステージ差分確認",
                "モデルで表示",
            }

        def _show_command_context_menu(self, global_pos: Any, context: str) -> None:
            self._refresh_auxiliary_selection_context()
            if context == "tree" and self._show_tree_context_menu(global_pos):
                return
            action_specs = self._context_menu_action_specs(context)
            if action_specs:
                menu = QMenu(self)
                panel = self._panel_key_from_tree_key(str(getattr(self, "current_panel_key", "")))
                for label, callback, tooltip in action_specs:
                    if label == "-":
                        menu.addSeparator()
                        continue
                    action = QAction(label, self)
                    rule = self._context_menu_action_rule(panel, label, callback)
                    enabled, reason = self._operation_rule_state(rule)
                    if self._input_mutation_locked() and not self._reference_context_action_allowed(label, callback):
                        enabled = False
                        reason = self._input_mutation_lock_message("入力変更")
                    action.setEnabled(enabled)
                    if tooltip:
                        full_tooltip = f"{tooltip}\n無効: {reason}" if (not enabled and reason) else tooltip
                        action.setToolTip(full_tooltip)
                        action.setStatusTip(full_tooltip)
                    if callback is not None:
                        action.triggered.connect(lambda _checked=False, cb=callback: cb())
                    menu.addAction(action)
                if not menu.isEmpty():
                    menu.exec(global_pos)
                return
            command_ids = list(self.command_hierarchy.get("contexts", {}).get(context, []))
            if not command_ids:
                return
            menu = QMenu(self)
            last_role = ""
            for command_id in command_ids:
                spec = self.command_spec_by_id.get(str(command_id), {})
                action = self.command_actions.get(str(command_id))
                if action is None:
                    continue
                role = str(spec.get("role", ""))
                if last_role and role != last_role:
                    menu.addSeparator()
                menu.addAction(action)
                last_role = role
            if not menu.isEmpty():
                menu.exec(global_pos)

        def _show_tree_context_menu(self, global_pos: Any) -> bool:
            tree = getattr(self, "tree", None)
            if tree is None:
                return False
            pos = tree.viewport().mapFromGlobal(global_pos)
            item = tree.itemAt(pos)
            if item is None:
                item = tree.itemAt(tree.mapFromGlobal(global_pos))
            if item is None:
                return False
            raw_key = str(item.data(0, Qt.ItemDataRole.UserRole) or "")
            payload = self._left_tree_boundary_payload_for_key(raw_key)
            if payload:
                tree.setCurrentItem(item)
                menu = QMenu(self)
                show_action = QAction("モデルで表示", self)
                show_action.triggered.connect(lambda _checked=False, payload=dict(payload): self._select_preview_payload(payload))
                menu.addAction(show_action)
                item_kind = str(payload.get("tree_item_kind", "condition"))
                if item_kind == "node":
                    delete_label = "この節点を境界条件から削除"
                elif item_kind == "edge":
                    delete_label = "この辺を境界条件から削除"
                else:
                    delete_label = "この境界条件を削除"
                delete_action = QAction(delete_label, self)
                delete_action.triggered.connect(lambda _checked=False, key=raw_key: self.delete_left_tree_boundary_condition_item(key))
                delete_action.setEnabled(not self._input_mutation_locked())
                menu.addAction(delete_action)
                if not menu.isEmpty():
                    menu.exec(global_pos)
                return True
            payload = self._left_tree_load_payload_for_key(raw_key)
            if not payload:
                return False
            tree.setCurrentItem(item)
            menu = QMenu(self)
            if payload.get("nodes") or payload.get("edges") or payload.get("elements"):
                show_action = QAction("モデルで表示", self)
                show_action.triggered.connect(lambda _checked=False, payload=dict(payload): self._select_preview_payload(payload))
                menu.addAction(show_action)
            kind = str(payload.get("kind", ""))
            add_labels = {
                "node": "選択節点へ節点荷重を追加",
                "edge": "選択辺/要素へ面荷重を追加",
                "body": "選択要素材料へ体積力を追加",
            }
            if kind in add_labels:
                add_action = QAction(add_labels[kind], self)
                add_action.triggered.connect(lambda _checked=False, payload=dict(payload): self.add_selected_load_from_tree_payload(payload))
                add_action.setEnabled(not self._input_mutation_locked())
                menu.addAction(add_action)
            if isinstance(payload.get("source", {}), Mapping) and payload.get("source"):
                item_kind = str(payload.get("tree_item_kind", "condition"))
                if item_kind == "node":
                    delete_label = "この節点を荷重から削除"
                elif item_kind == "edge":
                    delete_label = "この辺を荷重から削除"
                else:
                    delete_label = "この荷重を削除"
                delete_action = QAction(delete_label, self)
                delete_action.triggered.connect(lambda _checked=False, key=raw_key: self.delete_left_tree_load_condition_item(key))
                delete_action.setEnabled(not self._input_mutation_locked())
                menu.addAction(delete_action)
            if not menu.isEmpty():
                menu.exec(global_pos)
            return True

        def _left_tree_boundary_payload_for_key(self, key: str) -> dict[str, Any]:
            text = str(key or "")
            if not text.startswith("boundary_condition:"):
                return {}
            payload = dict(getattr(self, "_boundary_navigation_specs_cache", {}).get(text, {}))
            if not payload:
                return {}
            if text.startswith("boundary_condition:type:"):
                return {}
            if ":node:" in text:
                payload["kind"] = "boundary_condition_node"
                payload["tree_item_kind"] = "node"
                payload.setdefault("remove_nodes", payload.get("nodes", []))
                return payload
            if ":edge:" in text:
                payload["kind"] = "boundary_condition_edge"
                payload["tree_item_kind"] = "edge"
                payload.setdefault("remove_edges", payload.get("edges", []))
                return payload
            if text.startswith("boundary_condition:item:"):
                payload["kind"] = "boundary_condition"
                payload["tree_item_kind"] = "condition"
                return payload
            return {}

        def delete_left_tree_boundary_condition_item(self, key: str | None = None) -> None:
            if key is None:
                tree = getattr(self, "tree", None)
                current = tree.currentItem() if tree is not None else None
                key = str(current.data(0, Qt.ItemDataRole.UserRole) or "") if current is not None else ""
            payload = self._left_tree_boundary_payload_for_key(str(key or ""))
            if payload:
                self._delete_boundary_condition_tree_payload(payload)

        def _left_tree_load_payload_for_key(self, key: str) -> dict[str, Any]:
            text = str(key or "")
            if not text.startswith("load_condition:"):
                return {}
            payload = dict(getattr(self, "_load_navigation_specs_cache", {}).get(text, {}))
            if not payload:
                return {}
            if text.startswith("load_condition:type:"):
                payload["tree_item_kind"] = "type"
                return payload
            if ":node:" in text:
                payload["kind"] = "node"
                payload["tree_item_kind"] = "node"
                payload.setdefault("remove_nodes", payload.get("nodes", []))
                return payload
            if ":edge:" in text:
                payload["kind"] = "edge"
                payload["tree_item_kind"] = "edge"
                payload.setdefault("remove_edges", payload.get("edges", []))
                return payload
            if text.startswith("load_condition:item:"):
                payload["tree_item_kind"] = "condition"
                return payload
            return {}

        def delete_left_tree_load_condition_item(self, key: str | None = None) -> None:
            if key is None:
                tree = getattr(self, "tree", None)
                current = tree.currentItem() if tree is not None else None
                key = str(current.data(0, Qt.ItemDataRole.UserRole) or "") if current is not None else ""
            payload = self._left_tree_load_payload_for_key(str(key or ""))
            if payload:
                self._delete_load_tree_payload(payload)

        def add_selected_load_from_tree_payload(self, payload: Mapping[str, Any]) -> None:
            kind = str(payload.get("kind", ""))
            if kind == "node":
                self.add_selected_nodal_load_condition()
            elif kind == "edge":
                self.add_selected_distributed_load_condition()
            elif kind == "body":
                self.add_selected_body_load_condition()

        def show_workflow_panel(self) -> None:
            self._activate_panel("workflow")
            self.refresh_workflow_guidance()

        def show_yaml_panel(self) -> None:
            self._activate_panel("yaml")

        def result_navigation_locked(self) -> bool:
            # Kept as a compatibility hook for the workflow/tree policies. Results now
            # lock mutation, not navigation: every input stage remains inspectable.
            return self._analysis_results_available()

        def result_navigation_target_allowed(self, key: str) -> bool:
            panel = self._panel_key_from_tree_key(str(key or ""))
            return panel in getattr(self, "panel_pages", {})

        def result_navigation_lock_message(self) -> str:
            return "解析結果を保持した読み取り専用参照モードです。入力工程は閲覧できますが、変更と保存は結果リセット後に行えます。"

        def show_result_navigation_locked_message(self, target: str = "") -> None:
            message = self.result_navigation_lock_message()
            if target:
                message = f"{message} 移動先: {target}"
            self.statusBar().showMessage(message)
            summary = getattr(self, "results_summary", None)
            if summary is not None:
                summary.setText(message)

        def _show_results_workspace(self, result_kind: str = "") -> None:
            if result_kind:
                self._activate_result_tree_selection(result_kind)
                self.tabs.setCurrentIndex(0)
                self._refresh_result_action_states()
                return
            page = self.panel_pages.get("results")
            if page is not None:
                self.panel_stack.setCurrentWidget(page)
            detail_index = self.tabs.indexOf(self.panel_stack)
            if detail_index >= 0 and hasattr(self.tabs, "setTabVisible"):
                self.tabs.setTabVisible(detail_index, True)
            self.tabs.setCurrentWidget(self.panel_stack)
            result_tabs = getattr(self, "results_tabs", None)
            if result_tabs is not None:
                result_tabs.setCurrentIndex(0)
            if self._current_summary_path() is None and getattr(self, "_loaded_result_summary_path", None) is None:
                self.results_summary.setText(
                    "No analysis results are available. Resolve input issues and run the analysis."
                    if self.gui_locale == "en"
                    else "解析結果がまだありません。入力課題を解消して解析を実行してください。"
                )
            self.results_summary.setAccessibleName(self.results_summary.text())
            self._refresh_result_action_states()

        def _activate_panel(self, panel: str) -> None:
            self._navigate_to_workspace(panel, source="action")

        def _navigation_target_blocked(self, raw_key: str, *, label: str = "") -> bool:
            panel = self._panel_key_from_tree_key(raw_key)
            if self.result_navigation_locked() and not self.result_navigation_target_allowed(raw_key):
                self.show_result_navigation_locked_message(label or panel)
                return True
            if self.analysis_reference_mode_active():
                return False
            if panel != "mesh":
                return False
            blockers = self.input_execution_blockers()
            if not any(str(item.get("source", "")) == "geometry_closure" for item in blockers):
                return False
            self.show_input_execution_blockers(label or panel, navigate_to_issue=False)
            return True

        def _navigation_tree_item(self, raw_key: str) -> QTreeWidgetItem | None:
            tree = getattr(self, "tree", None)
            if tree is None:
                return None
            panel = self._panel_key_from_tree_key(raw_key)
            for index in range(tree.topLevelItemCount()):
                root = tree.topLevelItem(index)
                found = self._find_tree_panel_item(root, raw_key)
                if found is None and panel != raw_key:
                    found = self._find_tree_panel_item(root, panel)
                if found is not None:
                    return found
            return None

        def _restore_navigation_tree_selection(
            self,
            previous: QTreeWidgetItem | None,
            rejected: QTreeWidgetItem | None,
        ) -> None:
            tree = getattr(self, "tree", None)
            if tree is None:
                return
            fallback = previous
            if fallback is None or fallback is rejected:
                fallback = self._navigation_tree_item(str(getattr(self, "current_panel_key", "analysis") or "analysis"))
            if fallback is not None and self.result_navigation_locked():
                fallback_key = str(fallback.data(0, Qt.ItemDataRole.UserRole) or "")
                if not self.result_navigation_target_allowed(fallback_key):
                    fallback = self._navigation_tree_item("solver")
            if fallback is None:
                return
            tree.blockSignals(True)
            tree.setCurrentItem(fallback)
            tree.blockSignals(False)
            self._set_tree_item_bold(rejected, False)
            self._set_tree_item_bold(fallback, True)
            self._focus_tree_category(fallback)

        def _navigate_to_workspace(
            self,
            raw_key: str,
            *,
            source: str,
            tree_item: QTreeWidgetItem | None = None,
            previous_tree_item: QTreeWidgetItem | None = None,
        ) -> bool:
            raw_key = str(raw_key or "analysis")
            panel = self._panel_key_from_tree_key(raw_key)
            if panel not in self.panel_pages:
                return False
            target_item = tree_item or self._navigation_tree_item(raw_key)
            label = str(target_item.text(0) or panel) if target_item is not None else panel
            if self._navigation_target_blocked(raw_key, label=label):
                self._restore_navigation_tree_selection(previous_tree_item, target_item)
                return False
            tree = getattr(self, "tree", None)
            previous = previous_tree_item or (tree.currentItem() if tree is not None else None)
            if tree is not None and target_item is not None and tree.currentItem() is not target_item:
                tree.blockSignals(True)
                tree.setCurrentItem(target_item)
                tree.blockSignals(False)
            self._apply_navigation_target(raw_key, target_item, previous, source=source)
            return True

        def _apply_navigation_target(
            self,
            raw_key: str,
            current: QTreeWidgetItem | None,
            previous: QTreeWidgetItem | None,
            *,
            source: str,
        ) -> None:
            result_kind = self._result_kind_from_tree_key(raw_key)
            panel = self._panel_key_from_tree_key(raw_key)
            if self.workspace_focus_mode_active() and not self._workspace_focus_panel_supported(panel):
                self.set_workspace_focus_mode(False)
            self._set_tree_item_bold(previous, False)
            self._set_tree_item_bold(current, True)
            self.current_panel_key = panel
            self._last_navigation_target = raw_key
            self._last_navigation_source = str(source)
            if current is not None:
                self._focus_tree_category(current)

            page = self.panel_pages.get(panel)
            inline_detail = panel in getattr(self, "inline_detail_panel_keys", set())
            model_display = panel in self._model_display_panel_keys()
            if page is not None and not inline_detail:
                self.panel_stack.setCurrentWidget(page)
            detail_workspace = self._current_gui_operation_mode() in {"detail", "maintenance"}
            if panel == "model_check":
                self.tabs.setCurrentWidget(self.panel_stack)
                self.refresh_model_check_overview()
                issue_table = getattr(self, "model_check_issue_table", None)
                if bool(getattr(self, "_model_check_dirty", False)) or issue_table is None or issue_table.rowCount() == 0:
                    self.run_model_check_async()
            elif panel in {"analysis", "workflow"}:
                self.tabs.setCurrentWidget(self.panel_stack)
            elif model_display:
                self.tabs.setCurrentWidget(self.model_workspace_page)
            elif panel == "solver":
                self.tabs.setCurrentWidget(self.panel_stack)
                self.refresh_solver_panel()
            elif panel == "yaml":
                self.tabs.setCurrentWidget(self.yaml_editor)
            elif panel == "results":
                self._show_results_workspace(result_kind)
            elif panel == "report":
                if self.show_latest_report_if_available():
                    self.tabs.setCurrentWidget(self.result_view)
                else:
                    self.tabs.setCurrentWidget(self.panel_stack)
            elif detail_workspace and page is not None:
                self.tabs.setCurrentWidget(self.panel_stack)
            else:
                self.tabs.setCurrentIndex(0)

            self._apply_context_visibility(panel)
            if panel in self._model_display_panel_keys():
                if self._cfg_prefers_deferred_load_refresh(self.cfg) or bool(getattr(self, "_model_preview_dirty", False)):
                    self.request_preview_update(reset_view=False, reason=f"navigate {panel}")
                else:
                    self.update_preview(reset_view=False)

            self._syncing_scene_from_tree_selection = True
            try:
                if panel == "boundary_conditions":
                    if bool(getattr(self, "_boundary_condition_tree_dirty", False)):
                        self.populate_boundary_condition_tree()
                        self._boundary_condition_tree_dirty = False
                    self._activate_boundary_navigation_item(raw_key)
                if panel == "loads":
                    self._activate_load_navigation_item(raw_key)
                if panel == "materials":
                    self._activate_material_navigation_item(raw_key)
                if panel == "mesh":
                    if bool(getattr(self, "_mesh_quality_table_dirty", False)):
                        if self._cfg_prefers_deferred_load_refresh(self.cfg):
                            self.populate_mesh_quality_violation_table_async()
                        else:
                            self.populate_mesh_quality_violation_table()
                        self._mesh_quality_table_dirty = False
                    self._activate_mesh_quality_navigation_item(raw_key)
                if panel == "stages":
                    self._activate_stage_navigation_item(raw_key)
            finally:
                self._syncing_scene_from_tree_selection = False
            self.refresh_workflow_guidance()

        def show_stage_workspace_tab(self, index: int = 0) -> None:
            workspace = getattr(self, "stage_form_workspace", None)
            stack = getattr(self, "form_workspace_stack", None)
            tabs = getattr(self, "stage_workspace_tabs", None)
            if workspace is None or stack is None or tabs is None:
                return
            stack.setCurrentWidget(workspace)
            self.tabs.setCurrentWidget(stack)
            target_index = max(0, min(index, tabs.count() - 1))
            if not tabs.isTabVisible(target_index):
                target_index = next((candidate for candidate in range(tabs.count()) if tabs.isTabVisible(candidate)), 0)
            tabs.setCurrentIndex(target_index)

        def open_stage_detail_editor(self) -> None:
            combo = getattr(self, "gui_operation_mode_combo", None)
            if combo is not None:
                detail_index = combo.findData("detail")
                if detail_index >= 0 and combo.currentIndex() != detail_index:
                    combo.setCurrentIndex(detail_index)
            self.show_stage_workspace_tab(0)

        def _refresh_stage_standard_change_summary(self) -> None:
            label = getattr(self, "stage_standard_change_summary", None)
            table = getattr(self, "stage_change_table", None)
            if label is None or table is None:
                return
            counts = {"death": 0, "birth": 0, "material": 0, "boundary": 0, "load": 0}
            for row in range(table.rowCount()):
                item = table.item(row, 1)
                raw = item.data(Qt.ItemDataRole.UserRole) if item is not None else None
                text = str(raw if raw not in (None, "") else (item.text() if item is not None else "")).strip().lower()
                for key in counts:
                    if key in text:
                        counts[key] += 1
                        break
            total = table.rowCount()
            standard_mode = not self._show_internal_representation()
            has_changes = total > 0
            remove_button = getattr(self, "stage_standard_remove_change_button", None)
            apply_button = getattr(self, "stage_standard_apply_changes_button", None)
            if remove_button is not None:
                remove_button.setVisible(not standard_mode or has_changes)
            if apply_button is not None:
                apply_button.setVisible(not standard_mode or has_changes)
            if standard_mode:
                table.setVisible(has_changes)
            if self.gui_locale == "en":
                label.setText(
                    f"Changes: {total} / deactivated {counts['death']} / reactivated {counts['birth']} / "
                    f"material {counts['material']} / boundary {counts['boundary']} / load {counts['load']}"
                )
            else:
                label.setText(
                    f"変更: {total}件 / 無効化 {counts['death']} / 再有効化 {counts['birth']} / "
                    f"材料 {counts['material']} / 境界 {counts['boundary']} / 荷重 {counts['load']}"
                )

        def _apply_stage_standard_mode_visibility(self, panel_key: str, *, detail_mode: bool) -> None:
            if panel_key != "stages":
                return
            standard = not detail_mode
            standard_bar = getattr(self, "stage_standard_action_bar", None)
            if standard_bar is not None:
                standard_bar.setVisible(standard)
            detail_actions = getattr(self, "stage_change_actions_widget", None)
            if detail_actions is not None:
                detail_actions.setVisible(not standard)
            stage_table = getattr(self, "stage_table", None)
            if stage_table is not None:
                stage_table.setMinimumHeight(150 if standard else 240)
            change_table = getattr(self, "stage_change_table", None)
            if change_table is not None:
                change_table.setMinimumHeight(150 if standard else 260)
                change_table.setVisible(not standard or change_table.rowCount() > 0)
            self._refresh_stage_standard_change_summary()

        def _recent_projects_file(self) -> Path:
            return Path.home() / ".geofem_recent_projects.json"

        def _load_recent_projects(self) -> list[str]:
            path = self._recent_projects_file()
            try:
                data = json.loads(path.read_text(encoding="utf-8"))
            except Exception:
                return []
            if not isinstance(data, list):
                return []
            return [str(item) for item in data if isinstance(item, str)][:12]

        def _save_recent_projects(self) -> None:
            try:
                self._recent_projects_file().write_text(json.dumps(self.recent_projects[:12], ensure_ascii=False, indent=2), encoding="utf-8")
            except Exception:
                return

        def record_recent_project(self, path: str | Path) -> None:
            text = str(Path(path))
            self.recent_projects = [text] + [item for item in self.recent_projects if item != text]
            self.recent_projects = self.recent_projects[:12]
            self._save_recent_projects()
            self._refresh_recent_projects_menu()

        def _refresh_recent_projects_menu(self) -> None:
            menu = getattr(self, "menu_recent", None)
            if menu is None:
                return
            menu.clear()
            if not self.recent_projects:
                action = QAction("履歴なし", self)
                action.setEnabled(False)
                menu.addAction(action)
                return
            for path_text in self.recent_projects[:12]:
                action = QAction(path_text, self)
                action.triggered.connect(lambda _checked=False, p=path_text: self.open_recent_project(p))
                menu.addAction(action)

        def open_recent_project(self, path: str | Path) -> None:
            target = Path(path)
            if not target.exists():
                QMessageBox.warning(self, "GeoFEM", f"最近使ったファイルが見つかりません: {target}")
                self.recent_projects = [item for item in self.recent_projects if item != str(target)]
                self._save_recent_projects()
                self._refresh_recent_projects_menu()
                return
            self.current_input = target
            self.project_root = target.parent
            self._reset_autosave_failure_backoff()
            try:
                data, preview = read_mapping_file_guarded(target)
            except Exception as exc:
                QMessageBox.warning(self, "GeoFEM", f"入力を開けません: {exc}")
                return
            self._syncing_yaml = True
            self.yaml_editor.setPlainText(preview.text)
            self._syncing_yaml = False
            self._load_cfg(data, keep_yaml=True)
            self.record_recent_project(target)
            self.append_log(f"[GUI] 最近使った入力を開きました: {target}")

        def _project_lock_file(self) -> Path:
            return self.project_root / ".geofem_project.lock"

        def _current_lock_identity(self) -> dict[str, Any]:
            return {
                "user": getpass.getuser(),
                "host": socket.gethostname(),
                "pid": "gui",
                "time": datetime.now().isoformat(timespec="seconds"),
                "input": str(self.current_input or ""),
            }

        def _read_project_lock(self) -> dict[str, Any] | None:
            path = self._project_lock_file()
            if not path.exists():
                return None
            try:
                data = yaml.safe_load(path.read_text(encoding="utf-8")) or {}
            except Exception:
                return {"user": "unknown", "host": "unknown", "time": "", "input": ""}
            return dict(data) if isinstance(data, Mapping) else {"user": "unknown", "host": "unknown", "time": "", "input": ""}

        def _project_locked_by_other(self) -> bool:
            info = self._read_project_lock()
            if not info:
                return False
            return str(info.get("user")) != getpass.getuser() or str(info.get("host")) != socket.gethostname()

        def _audit_log_file(self) -> Path:
            return self.project_root / ".geofem_audit_log.jsonl"

        def write_audit_event(self, action: str, target: str = "", detail: Mapping[str, Any] | None = None) -> dict[str, Any]:
            event = {
                "time": datetime.now().isoformat(timespec="seconds"),
                "actor": f"{getpass.getuser()}@{socket.gethostname()}",
                "action": action,
                "target": target,
                "detail": dict(detail or {}),
            }
            path = self._audit_log_file()
            path.parent.mkdir(parents=True, exist_ok=True)
            with path.open("a", encoding="utf-8") as fh:
                fh.write(json.dumps(event, ensure_ascii=False, sort_keys=True) + "\n")
            return event

        def load_audit_log(self, limit: int = 200) -> list[dict[str, Any]]:
            path = self._audit_log_file()
            return read_jsonl_tail(path, limit=limit)

        def refresh_audit_log_table(self) -> None:
            table = getattr(self, "audit_log_table", None)
            if table is None:
                return
            rows = self.load_audit_log()
            table.setRowCount(len(rows))
            for row, event in enumerate(rows):
                detail = event.get("detail", {})
                values = [
                    event.get("time", ""),
                    event.get("actor", ""),
                    event.get("action", ""),
                    event.get("target", ""),
                    json.dumps(detail, ensure_ascii=False, sort_keys=True) if isinstance(detail, Mapping) else str(detail),
                ]
                for col, value in enumerate(values):
                    table.setItem(row, col, QTableWidgetItem(str(value)))
            self.tabs.setCurrentWidget(table)

        def lock_project(self) -> None:
            existing = self._read_project_lock()
            if existing and self._project_locked_by_other():
                QMessageBox.warning(self, "GeoFEM", f"他の利用者がロック中です: {existing}")
                return
            info = self._current_lock_identity()
            self._project_lock_file().parent.mkdir(parents=True, exist_ok=True)
            self._project_lock_file().write_text(yaml.safe_dump(info, allow_unicode=True, sort_keys=False), encoding="utf-8")
            self.project_lock_owner = info
            self.write_audit_event("lock_acquired", str(self._project_lock_file()), info)
            self.statusBar().showMessage(self.ui_message("status.project.locked", owner=f"{info['user']}@{info['host']}"))

        def unlock_project(self) -> None:
            if self._project_locked_by_other():
                QMessageBox.warning(self, "GeoFEM", f"他の利用者のロックは解除できません: {self._read_project_lock()}")
                return
            path = self._project_lock_file()
            existing = self._read_project_lock()
            if path.exists():
                path.unlink()
            self.project_lock_owner = None
            self.write_audit_event("lock_released", str(path), {"previous": existing or {}})
            self.statusBar().showMessage(self.ui_message("status.project.unlocked"))

        def force_unlock_project(self, reason: str = "", actor: str | None = None) -> bool:
            path = self._project_lock_file()
            existing = self._read_project_lock()
            if not existing or not path.exists():
                self.write_audit_event("lock_force_release_skipped", str(path), {"reason": reason, "actor": actor or getpass.getuser()})
                return False
            archive = path.with_suffix(path.suffix + f".released.{datetime.now().strftime('%Y%m%d%H%M%S')}")
            shutil.copyfile(path, archive)
            path.unlink()
            self.project_lock_owner = None
            self.write_audit_event(
                "lock_force_released",
                str(path),
                {"reason": reason, "actor": actor or getpass.getuser(), "previous": existing, "archive": str(archive)},
            )
            self.statusBar().showMessage(f"プロジェクトロックを強制解除しました: {reason}")
            return True

        def force_unlock_project_dialog(self) -> None:
            reason, ok = QInputDialog.getText(self, "GeoFEM", "強制解除理由")
            if ok:
                self.force_unlock_project(reason.strip())

        def handoff_project_lock(self, new_owner: str | None = None, note: str = "") -> dict[str, Any]:
            previous = self._read_project_lock()
            owner = (new_owner or getpass.getuser()).strip() or getpass.getuser()
            info = self._current_lock_identity()
            info["user"] = owner
            info["handoff_from"] = previous or {}
            info["handoff_note"] = note
            self._project_lock_file().parent.mkdir(parents=True, exist_ok=True)
            self._project_lock_file().write_text(yaml.safe_dump(info, allow_unicode=True, sort_keys=False), encoding="utf-8")
            self.project_lock_owner = info
            self.write_audit_event("lock_handoff", str(self._project_lock_file()), {"to": owner, "note": note, "previous": previous or {}})
            self.statusBar().showMessage(f"プロジェクトロックを引き継ぎました: {owner}")
            return info

        def handoff_project_lock_dialog(self) -> None:
            owner, ok = QInputDialog.getText(self, "GeoFEM", "引継ぎ先ユーザー", text=getpass.getuser())
            if not ok:
                return
            note, ok = QInputDialog.getText(self, "GeoFEM", "引継ぎメモ")
            if ok:
                self.handoff_project_lock(owner.strip(), note.strip())

        def _reset_autosave_timer(self) -> None:
            if not hasattr(self, "autosave_timer"):
                return
            self.autosave_timer.stop()
            if self._input_mutation_locked():
                return
            enabled = getattr(self, "autosave_enabled", None)
            if enabled is not None and not enabled.isChecked():
                return
            try:
                seconds = max(10, int(float(self.autosave_interval_sec.text())))
            except Exception:
                seconds = 60
            self.autosave_timer.start(seconds * 1000)

        def _reset_autosave_failure_backoff(self) -> None:
            self._autosave_failure_count = 0
            self._autosave_last_error = ""
            self._autosave_next_retry_monotonic = 0.0

        def _start_gui_watchdog(self) -> None:
            if not hasattr(self, "watchdog_timer"):
                return
            self._watchdog_last_tick = time.perf_counter()
            self.watchdog_timer.start(self._watchdog_interval_ms)

        def eventFilter(self, watched: Any, event: Any) -> bool:
            try:
                event_type = event.type()
                if event_type in {
                    QEvent.Type.MouseButtonPress,
                    QEvent.Type.MouseButtonRelease,
                    QEvent.Type.KeyPress,
                    QEvent.Type.KeyRelease,
                    QEvent.Type.Wheel,
                    QEvent.Type.FocusIn,
                    QEvent.Type.FocusOut,
                }:
                    obj_name = watched.objectName() if hasattr(watched, "objectName") else ""
                    label = getattr(event_type, "name", str(event_type))
                    self._last_ui_event = f"{label}:{obj_name or watched.__class__.__name__}"
            except Exception:
                pass
            return super().eventFilter(watched, event)

        def closeEvent(self, event: Any) -> None:
            try:
                app = QApplication.instance()
                if app is not None:
                    app.removeEventFilter(self)
                if hasattr(self, "watchdog_timer"):
                    self.watchdog_timer.stop()
                warmup_process = getattr(self, "_numba_warmup_process", None)
                if warmup_process is not None and warmup_process.state() != QProcess.ProcessState.NotRunning:
                    job_id = self._numba_warmup_job_id
                    self._numba_warmup_job_id = ""
                    warmup_process.blockSignals(True)
                    warmup_process.kill()
                    warmup_process.waitForFinished(1000)
                    self._numba_warmup_process = None
                    if job_id:
                        self._complete_gui_worker_job(job_id, status="cancelled", message="GUI closed during warmup")
            finally:
                super().closeEvent(event)

        def _watchdog_tick(self) -> None:
            now = time.perf_counter()
            elapsed_ms = (now - self._watchdog_last_tick) * 1000.0
            self._watchdog_last_tick = now
            if elapsed_ms <= self._watchdog_threshold_ms:
                return
            delay_ms = max(0.0, elapsed_ms - float(self._watchdog_interval_ms))
            record = self._watchdog_record(elapsed_ms, delay_ms)
            try:
                append_watchdog_record(self.project_root / "gui_freeze_watchdog.json", record)
            except Exception as exc:
                self.append_log(f"[GUI] watchdog記録失敗: {exc}")
                return
            self.append_log(f"[GUI] watchdog: event loop delay {delay_ms:.0f} ms")

        def _watchdog_record(self, elapsed_ms: float, delay_ms: float) -> dict[str, Any]:
            active_jobs = self.gui_jobs.active_jobs()
            job_name = ",".join(str(job.get("kind", "")) for job in active_jobs) if active_jobs else ""
            mesh_nodes, mesh_elements = self._watchdog_mesh_size()
            line_count = 0
            if getattr(self, "yaml_editor", None) is not None:
                line_count = int(self.yaml_editor.document().blockCount())
            return GuiFreezeWatchdogRecord(
                timestamp=utc_timestamp(),
                operation=self.statusBar().currentMessage(),
                job=job_name,
                elapsed_ms=round(float(elapsed_ms), 3),
                delay_ms=round(float(delay_ms), 3),
                target_file=str(self.current_input or ""),
                line_count=line_count,
                mesh_nodes=mesh_nodes,
                mesh_elements=mesh_elements,
                last_ui_event=self._last_ui_event,
                active_jobs=active_jobs,
            ).as_dict()

        def _watchdog_mesh_size(self) -> tuple[int | None, int | None]:
            mesh = self.cfg.get("mesh", {}) if isinstance(self.cfg, Mapping) else {}
            if not isinstance(mesh, Mapping):
                return None, None
            nodes = mesh.get("nodes")
            elements = mesh.get("elements")
            node_count = len(nodes) if isinstance(nodes, (Mapping, list, tuple)) else None
            element_count = len(elements) if isinstance(elements, (Mapping, list, tuple)) else None
            if node_count is None or element_count is None:
                try:
                    nx = max(0, int(float(mesh.get("nx", 0))))
                    ny = max(0, int(float(mesh.get("ny", 0))))
                except (TypeError, ValueError):
                    nx = ny = 0
                if nx and ny:
                    node_count = node_count if node_count is not None else (nx + 1) * (ny + 1)
                    element_count = element_count if element_count is not None else nx * ny
            return node_count, element_count

        def autosave_current_project(self) -> Path | None:
            if self._project_locked_by_other():
                self.statusBar().showMessage(f"自動保存を停止: 他者ロック {self._read_project_lock()}")
                return None
            base = self.current_input.stem if self.current_input is not None else "model"
            text = self.yaml_editor.toPlainText()
            result = write_autosave_files(self.project_root, base, text)
            self._last_autosave_sha256 = result.sha256
            self.write_audit_event("autosave", str(result.stamped), {"latest": str(result.latest), "bytes": result.byte_count, "mode": "sync"})
            self.refresh_recovery_candidates_table(activate=False)
            self.statusBar().showMessage(f"自動保存: {result.latest}")
            return result.latest

        def autosave_current_project_async(self) -> None:
            if self._input_mutation_locked():
                self.statusBar().showMessage(self._input_mutation_lock_message("自動保存"))
                return
            if self._project_locked_by_other():
                self.statusBar().showMessage(f"自動保存を停止: 他者ロック {self._read_project_lock()}")
                return
            if self._autosave_job_id:
                self.statusBar().showMessage(self.ui_message("status.autosave.running"))
                return
            retry_at = float(getattr(self, "_autosave_next_retry_monotonic", 0.0) or 0.0)
            if retry_at > time.monotonic():
                remaining = max(1, int(math.ceil(retry_at - time.monotonic())))
                self.statusBar().showMessage(f"自動保存を再試行待ち: あと{remaining}秒")
                return
            base = self.current_input.stem if self.current_input is not None else "model"
            text = self.yaml_editor.toPlainText()
            text_hash = hashlib.sha256(text.encode("utf-8")).hexdigest()
            if text_hash == self._last_autosave_sha256:
                self.statusBar().showMessage(self.ui_message("status.autosave.no_change"))
                return
            job_id = self.gui_jobs.start_job("autosave", target=str(self.project_root / "autosave"), metadata={"base": base})
            self._autosave_job_id = job_id
            runner = QtCallableRunner(job_id, lambda: write_autosave_files(self.project_root, base, text))
            self._gui_task_runners[job_id] = runner
            runner.signals.finished.connect(self._autosave_finished)
            runner.signals.failed.connect(self._autosave_failed)
            self.gui_thread_pool.start(runner)
            self.statusBar().showMessage(self.ui_message("status.autosave.background"))

        def _autosave_finished(self, job_id: str, result_obj: Any) -> None:
            if job_id != self._autosave_job_id:
                self._gui_task_runners.pop(job_id, None)
                return
            result = result_obj if isinstance(result_obj, AutosaveResult) else None
            message = str(result.latest) if result is not None else "unknown"
            self._complete_gui_worker_job(job_id, status="finished", message=message)
            self._autosave_job_id = ""
            if result is not None:
                self._reset_autosave_failure_backoff()
                self._last_autosave_sha256 = result.sha256
                self.write_audit_event("autosave", str(result.stamped), {"latest": str(result.latest), "bytes": result.byte_count, "mode": "async"})
                self.refresh_recovery_candidates_table(activate=False)
                self.statusBar().showMessage(f"自動保存: {result.latest}")
                self.append_log(f"[GUI] 自動保存完了: {result.latest}")

        def _autosave_failed(self, job_id: str, message: str) -> None:
            if job_id != self._autosave_job_id:
                self._gui_task_runners.pop(job_id, None)
                return
            previous_error = str(getattr(self, "_autosave_last_error", ""))
            self._autosave_failure_count = int(getattr(self, "_autosave_failure_count", 0)) + 1
            self._autosave_last_error = message
            retry_seconds = min(900, 30 * (2 ** min(self._autosave_failure_count - 1, 5)))
            self._autosave_next_retry_monotonic = time.monotonic() + retry_seconds
            # Record the first occurrence and changed failures, without flooding
            # an already failing output location on every timer tick.
            manifest = None
            if self._autosave_failure_count == 1 or message != previous_error:
                manifest = self._write_gui_worker_failure_manifest(job_id, message)
            self._complete_gui_worker_job(job_id, status="failed", message=message)
            self._autosave_job_id = ""
            self.statusBar().showMessage(f"自動保存失敗（{retry_seconds}秒後に再試行）: {message}")
            suffix = f" manifest={manifest}" if manifest is not None else ""
            self.append_log(f"[GUI] 自動保存失敗: {message}; retry={retry_seconds}s{suffix}")

        def _complete_gui_worker_job(self, job_id: str, *, status: str, message: str = "") -> None:
            self.gui_jobs.complete_job(job_id, status=status, message=message)
            self._gui_task_runners.pop(job_id, None)

        def start_numba_warmup_async(self) -> None:
            if self._numba_warmup_job_id or self.numba_warmup_summary:
                return
            if not gui_numba_warmup_enabled():
                self.numba_warmup_summary = {"enabled": False, "skip_reason": "disabled"}
                return
            job_id = self.gui_jobs.start_job("numba_warmup", target="representative_numba_kernels", metadata={"profile": "gui"})
            self._numba_warmup_job_id = job_id
            self.statusBar().showMessage("Preparing solver kernels in the background...")
            in_process = str(os.environ.get("GEOFEM_GUI_NUMBA_WARMUP_MODE", "")).strip().lower() == "in_process"
            if in_process or not isinstance(self.gui_thread_pool, QThreadPool):
                runner = QtCallableRunner(job_id, lambda: warmup_numba_kernels(profile="gui"))
                self._gui_task_runners[job_id] = runner
                runner.signals.finished.connect(self._numba_warmup_finished)
                runner.signals.failed.connect(self._numba_warmup_failed)
                self.gui_thread_pool.start(runner)
                return
            program, arguments = self._numba_warmup_command()
            process = QProcess(self)
            self._numba_warmup_process = process
            self._numba_warmup_stdout = ""
            self._numba_warmup_stderr = ""
            process.readyReadStandardOutput.connect(self._numba_warmup_read_stdout)
            process.readyReadStandardError.connect(self._numba_warmup_read_stderr)
            process.finished.connect(self._numba_warmup_process_finished)
            process.errorOccurred.connect(self._numba_warmup_process_error)
            process.start(program, arguments)

        def _numba_warmup_command(self) -> tuple[str, list[str]]:
            if getattr(sys, "frozen", False):
                cli_exe = Path(sys.executable).with_name("GeoFEM-CLI.exe")
                if cli_exe.exists():
                    return str(cli_exe), ["warmup", "--profile", "gui"]
            return sys.executable, ["-m", "geofem_app.cli", "warmup", "--profile", "gui"]

        def _numba_warmup_read_stdout(self) -> None:
            process = getattr(self, "_numba_warmup_process", None)
            if process is not None:
                self._numba_warmup_stdout += bytes(process.readAllStandardOutput()).decode("utf-8", errors="replace")

        def _numba_warmup_read_stderr(self) -> None:
            process = getattr(self, "_numba_warmup_process", None)
            if process is not None:
                self._numba_warmup_stderr += bytes(process.readAllStandardError()).decode("utf-8", errors="replace")

        def _numba_warmup_process_finished(self, exit_code: int, _exit_status: Any) -> None:
            job_id = self._numba_warmup_job_id
            if not job_id:
                return
            self._numba_warmup_read_stdout()
            self._numba_warmup_read_stderr()
            output = self._numba_warmup_stdout.strip()
            summary: dict[str, Any] | None = None
            for line in reversed(output.splitlines()):
                try:
                    candidate = json.loads(line)
                except Exception:
                    continue
                if isinstance(candidate, Mapping):
                    summary = dict(candidate)
                    break
            self._numba_warmup_process = None
            if int(exit_code) == 0 and summary is not None:
                self._numba_warmup_finished(job_id, summary)
                return
            message = self._numba_warmup_stderr.strip() or output or f"warmup process exited with code {exit_code}"
            self._numba_warmup_failed(job_id, message)

        def _numba_warmup_process_error(self, error: Any) -> None:
            process = getattr(self, "_numba_warmup_process", None)
            if process is None or not self._numba_warmup_job_id:
                return
            if process.state() != QProcess.ProcessState.NotRunning:
                return
            message = process.errorString() or str(error)
            self._numba_warmup_process = None
            self._numba_warmup_failed(self._numba_warmup_job_id, message)

        def _numba_warmup_finished(self, job_id: str, summary_obj: Any) -> None:
            if job_id != self._numba_warmup_job_id:
                self._gui_task_runners.pop(job_id, None)
                return
            summary = dict(summary_obj or {})
            elapsed = float(summary.get("elapsed_seconds", 0.0) or 0.0)
            failed = int(summary.get("failed_count", 0) or 0)
            warmed = int(summary.get("warmed_count", 0) or 0)
            self.numba_warmup_summary = summary
            status = "failed" if failed else "finished"
            message = f"{warmed} kernels, {elapsed:.3f}s"
            self._complete_gui_worker_job(job_id, status=status, message=message)
            self._numba_warmup_job_id = ""
            self.append_log(f"[GUI] numba warmup {status}: {message}")
            if failed:
                self.statusBar().showMessage(f"Numba warmup completed with {failed} failed kernels")
            else:
                self.statusBar().showMessage(f"Numba warmup completed: {elapsed:.3f}s")

        def _numba_warmup_failed(self, job_id: str, message: str) -> None:
            if job_id != self._numba_warmup_job_id:
                self._gui_task_runners.pop(job_id, None)
                return
            manifest = self._write_gui_worker_failure_manifest(job_id, message, context={"worker": "numba_warmup"})
            self.numba_warmup_summary = {"enabled": True, "failed_count": 1, "error": message}
            self._complete_gui_worker_job(job_id, status="failed", message=message)
            self._numba_warmup_job_id = ""
            suffix = f" manifest={manifest}" if manifest is not None else ""
            self.append_log(f"[GUI] numba warmup failed: {message}{suffix}")
            self.statusBar().showMessage(f"Numba warmup failed: {message}")

        def _write_gui_worker_failure_manifest(self, job_id: str, message: str, *, context: Mapping[str, Any] | None = None) -> Path | None:
            try:
                manifest = self.gui_jobs.failure_manifest(
                    job_id,
                    message=message,
                    context={
                        "current_input": str(self.current_input or ""),
                        "project_root": str(self.project_root),
                        "last_ui_event": self._last_ui_event,
                        **dict(context or {}),
                    },
                )
                out_dir = self.project_root / "runs" / "gui_worker_failures"
                out_dir.mkdir(parents=True, exist_ok=True)
                safe_job_id = re.sub(r"[^A-Za-z0-9_.-]+", "_", job_id)
                out = out_dir / f"{safe_job_id}.json"
                out.write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8")
                return out
            except Exception as exc:
                self.append_log(f"[GUI] worker失敗manifest保存失敗: {exc}")
                return None

        def recovery_candidates(self) -> list[dict[str, Any]]:
            candidates: dict[str, Path] = {}
            autosave_dir = self.project_root / "autosave"
            if autosave_dir.exists():
                for path in autosave_dir.glob("*.y*ml"):
                    candidates[str(path.resolve())] = path
            if self.current_input is not None and self.current_input.exists():
                candidates[str(self.current_input.resolve())] = self.current_input
            return recovery_candidate_infos(list(candidates.values()), current_text=self.yaml_editor.toPlainText())

        def refresh_recovery_candidates_table(self, activate: bool = True) -> None:
            table = getattr(self, "recovery_candidate_table", None)
            if table is None:
                return
            rows = self.recovery_candidates()
            table.setRowCount(len(rows))
            for row, candidate in enumerate(rows):
                values = [
                    row + 1,
                    candidate["path"],
                    candidate["time"],
                    candidate["bytes"],
                    str(candidate["sha256"])[:12],
                    candidate["changed"],
                ]
                for col, value in enumerate(values):
                    item = QTableWidgetItem(str(value))
                    item.setData(Qt.ItemDataRole.UserRole, candidate)
                    table.setItem(row, col, item)
            if activate:
                page = self.panel_pages.get("stages")
                if page is not None:
                    self.panel_stack.setCurrentWidget(page)

        def compare_recovery_candidates(self, left_row: int = 0, right_row: int = 1) -> dict[str, Any]:
            rows = self.recovery_candidates()
            if left_row < 0 or right_row < 0 or left_row >= len(rows) or right_row >= len(rows):
                return {"ok": False, "reason": "not enough candidates"}
            left = rows[left_row]
            right = rows[right_row]
            result = compare_recovery_files(left["path"], right["path"])
            self.write_audit_event("recovery_compare", f"{left['path']} :: {right['path']}", result)
            self.statusBar().showMessage(f"復旧候補比較: {result}")
            return result

        def restore_recovery_candidate(self, row: int = 0) -> bool:
            rows = self.recovery_candidates()
            if row < 0 or row >= len(rows):
                return False
            path = Path(rows[row]["path"])
            text, data = read_recovery_text(path)
            self.yaml_editor.setPlainText(text)
            if isinstance(data, Mapping):
                self._load_cfg(dict(data), keep_yaml=True)
            self.write_audit_event("recovery_restore", str(path), {"row": row})
            self.statusBar().showMessage(f"復旧候補を読み込みました: {path}")
            return True

        def _build_panels(self) -> None:
            self._add_panel("workflow", self._workflow_panel())
            self._add_panel("analysis", self._analysis_panel())
            self._add_panel("geometry", self._geometry_panel())
            self._add_panel("mesh", self._mesh_panel())
            self._add_panel("materials", self._materials_panel())
            self._add_panel("external", self._external_link_panel())
            self._add_panel("boundary_conditions", self._boundary_conditions_panel())
            self._add_panel("loads", self._loads_panel())
            self._add_panel("stages", self._stages_panel())
            self._add_panel("solver", self._solver_panel())
            self._add_panel("model_check", self._model_check_panel())
            self._add_panel("results", self._results_panel())
            self._add_panel("report", self._report_panel())
            self._add_panel("yaml", self._yaml_panel())

        def _workflow_panel_qt(self) -> Mapping[str, Any]:
            return {
                "QWidget": QWidget,
                "QVBoxLayout": QVBoxLayout,
                "QHBoxLayout": QHBoxLayout,
                "QGridLayout": QGridLayout,
                "QLabel": QLabel,
                "QTableWidget": QTableWidget,
                "QHeaderView": QHeaderView,
                "QPushButton": QPushButton,
                "QGroupBox": QGroupBox,
                "QScrollArea": QScrollArea,
                "QSizePolicy": QSizePolicy,
                "QTableWidgetItem": QTableWidgetItem,
                "Qt": Qt,
                "QBrush": QBrush,
                "QColor": QColor,
            }

        def _workflow_panel(self) -> QWidget:
            return build_workflow_panel(self, self._workflow_panel_qt())

        def refresh_workflow_guidance(self) -> None:
            refresh_workflow_guidance_view(self, self._workflow_panel_qt())
            self._apply_solver_navigation_state()
            self.refresh_model_check_overview()
            self.refresh_input_issue_tab_states()
            self._update_workspace_heading(getattr(self, "current_panel_key", "workflow"))
            self._refresh_analysis_reference_mode()
            self._sync_workspace_focus_mode_controls()

        def _solver_process_running(self) -> bool:
            return self.process is not None and self.process.state() != QProcess.ProcessState.NotRunning

        def _set_solver_navigation_suppressed(self, suppressed: bool) -> None:
            if bool(suppressed) and self.workspace_focus_mode_active():
                self.set_workspace_focus_mode(False)
            self._solver_navigation_suppressed = bool(suppressed)
            self._apply_solver_navigation_state()
            self._sync_workspace_focus_mode_controls()

        def _apply_solver_navigation_state(self) -> None:
            suppressed = bool(getattr(self, "_solver_navigation_suppressed", False)) or self._solver_process_running()
            for attr in (
                "workflow_ribbon_navigation",
                "workflow_ribbon_back_button",
                "workflow_ribbon_jump_button",
                "workflow_back_button",
                "workflow_jump_button",
            ):
                widget = getattr(self, attr, None)
                if widget is None:
                    continue
                if bool(widget.property("navigationAliasOnly")):
                    widget.setVisible(False)
                    widget.setEnabled(False)
                    continue
                widget.setVisible(not suppressed)
                if suppressed:
                    widget.setEnabled(False)
                elif attr in {"workflow_ribbon_jump_button", "workflow_jump_button", "workflow_ribbon_navigation"}:
                    widget.setEnabled(True)
            if suppressed:
                for button in getattr(self, "workflow_ribbon_step_buttons", []) or []:
                    button.setEnabled(False)

        def jump_to_workflow_guidance_row(self) -> None:
            workflow_panel_jump_to_row(self, self._workflow_panel_qt())

        def refresh_model_check_overview(self) -> None:
            yaml_label = getattr(self, "model_check_yaml_status", None)
            if yaml_label is not None:
                raw_text = self.yaml_editor.toPlainText() if hasattr(self, "yaml_editor") else ""
                try:
                    loaded = yaml.safe_load(raw_text) if raw_text.strip() else {}
                    if not isinstance(loaded, Mapping):
                        raise ValueError("YAML root is not a mapping")
                    keys = ", ".join(str(key) for key in list(loaded.keys())[:8])
                    prefix = "YAML Input State" if self.gui_locale == "en" else "YAML入力状態"
                    if self._show_internal_representation():
                        yaml_label.setText(f"{prefix}: OK / {len(raw_text.encode('utf-8'))} bytes / keys: {keys or '-'}")
                    else:
                        yaml_label.setText(f"{prefix}: Valid" if self.gui_locale == "en" else f"{prefix}: 正常")
                    yaml_label.setProperty("severity", "ok")
                except Exception as exc:
                    prefix = "YAML Input State" if self.gui_locale == "en" else "YAML入力状態"
                    yaml_label.setText(f"{prefix}: ERROR / {exc}")
                    yaml_label.setProperty("severity", "error")
            table = getattr(self, "model_check_workflow_table", None)
            if table is None:
                return
            guidance = build_workflow_guidance(self.cfg, result_dir=self._active_result_dir(), locale=self.gui_locale)
            input_step_ids = ["analysis", "geometry", "mesh", "materials", "boundary_conditions", "loads", "stages"]
            steps = [step for step in guidance.get("steps", []) if isinstance(step, Mapping) and str(step.get("id", "")) in input_step_ids]
            table.setRowCount(len(steps))
            for row, step in enumerate(steps):
                missing = ", ".join(self._present_input_reference(item) for item in step.get("missing_paths", [])[:4])
                values = [
                    f"{row + 1} {step.get('label', step.get('id', ''))}",
                    str(step.get("status_label", step.get("status", ""))),
                    missing or str(step.get("detail", "")),
                    str(step.get("next_action", "")),
                ]
                severity_color = QColor("#d1e7dd") if bool(step.get("completed")) else QColor("#fff3cd")
                if bool(step.get("required")) and not bool(step.get("completed")):
                    severity_color = QColor("#f8d7da")
                for col, value in enumerate(values):
                    item = QTableWidgetItem(str(value))
                    item.setBackground(severity_color)
                    table.setItem(row, col, item)

        def refresh_solver_panel(self) -> None:
            label = getattr(self, "solver_status_label", None)
            state = self._refresh_execution_action_states()
            phase = str(state["phase"])
            en = self.gui_locale == "en"
            if phase == "cancel_requested":
                status = "Run State: Stop requested" if en else "解析実行状態: 中断要求済み"
            elif phase == "running":
                status = "Run State: Running" if en else "解析実行状態: 実行中"
            elif phase == "preflight":
                status = "Run State: Pre-run check" if en else "解析実行状態: 直前チェック中"
            elif phase == "results":
                result_location = self._active_run_dir() or self._current_summary_path()
                location_suffix = f" / {result_location}" if self._show_internal_representation() and result_location is not None else ""
                status = (
                    f"Run State: Results available / read-only reference{location_suffix}"
                    if en
                    else f"解析実行状態: 結果あり / 読み取り専用参照{location_suffix}"
                )
            else:
                status = "Run State: Idle" if en else "解析実行状態: 待機中"
            if label is not None:
                label.setText(status)
            solver_log = getattr(self, "solver_log", None)
            main_log = getattr(self, "log", None)
            if solver_log is not None and main_log is not None and not solver_log.toPlainText():
                solver_log.setPlainText(main_log.toPlainText())
            self._refresh_solver_final_summary_table()
            self._refresh_analysis_reference_mode()

        def _solver_final_summary_rows(self) -> list[tuple[str, str, str]]:
            en = self.gui_locale == "en"

            def count_text(value: int) -> str:
                return f"{value} item{'s' if value != 1 else ''}" if en else f"{value}件"

            materials = self._mapping(self.cfg.get("materials", {}))
            material_count = len(materials)
            material_status = "OK" if material_count else "ERROR"
            material_state = self._material_assignment_state()
            missing = list(material_state.get("missing", []))
            undefined = list(material_state.get("undefined", []))
            unassigned_status = "OK" if not missing and not undefined else "ERROR"
            if missing or undefined:
                missing_text = self._short_issue_list([*missing, *undefined], limit=6)
                unassigned_text = f"{count_text(len(missing) + len(undefined))}: {missing_text}"
            else:
                unassigned_text = count_text(0)

            stages_raw = self.cfg.get("stages", self.cfg.get("steps", []))
            stages = [stage for stage in stages_raw if isinstance(stage, Mapping)] if isinstance(stages_raw, list) else []
            global_bc = len(self._ensure_list(self.cfg.get("boundary_conditions", self.cfg.get("bc", []))))
            global_mpc = len(self._ensure_list(self.cfg.get("mpc_constraints", self.cfg.get("mpc", []))))
            stage_bc = sum(len(self._ensure_list(stage.get("boundary_conditions", stage.get("bc", [])))) for stage in stages)
            stage_mpc = sum(len(self._ensure_list(stage.get("mpc_constraints", stage.get("mpc", [])))) for stage in stages)
            hydro = sum(self._stage_hydro_count(stage) for stage in stages)
            boundary_total = global_bc + global_mpc + stage_bc + stage_mpc + hydro
            if en:
                boundary_detail = f"support/displacement {global_bc + stage_bc} / hydraulic {hydro} / MPC {global_mpc + stage_mpc}"
            else:
                boundary_detail = f"支点/変位 {global_bc + stage_bc} / 水理 {hydro} / MPC {global_mpc + stage_mpc}"
            boundary_status = "OK" if boundary_total else "WARN"

            load_cases = self._ensure_list(self.cfg.get("load_cases", []))
            global_loads = len(self._ensure_list(self.cfg.get("loads", [])))
            stage_loads = sum(len(self._ensure_list(stage.get("loads", []))) for stage in stages)
            load_total = global_loads + stage_loads
            load_status = "OK" if load_total else ("Check" if en else "確認")
            if en:
                load_text = f"{count_text(load_total)} (cases {len(load_cases)} / global {global_loads} / stages {stage_loads})"
            else:
                load_text = f"{load_total}件 (ケース {len(load_cases)} / 全体 {global_loads} / ステージ {stage_loads})"
            stage_status = "OK" if stages else ("Check" if en else "確認")
            stage_text = count_text(len(stages)) if stages else ("0 items (single static analysis)" if en else "0件 (単一静的解析)")
            quality_text, quality_status = self._solver_mesh_quality_summary()
            analysis = self._mapping(self.cfg.get("analysis", {}))
            mesh_cfg = self._mapping(self.cfg.get("mesh", {}))
            deformation_mode = str(analysis.get("deformation_mode", analysis.get("geometry_mode", "small_deformation"))).lower().strip().replace("-", "_")
            deformation_mode = "large_deformation" if deformation_mode in {"large", "large_deformation", "large_displacement", "finite_deformation", "updated_lagrangian"} else "small_deformation"
            element_type = str(mesh_cfg.get("element_type", mesh_cfg.get("type", "QUAD4"))).upper()
            integration = str(mesh_cfg.get("integration", "FULL"))
            material_models = sorted({str(self._mapping(raw).get("model", self._mapping(raw).get("type", "elastic"))).lower() for raw in materials.values()}) or ["undefined"]
            uses_large = deformation_mode == "large_deformation" or any(self._stage_type_family_for_ui(str(stage.get("type", ""))) == "large_deformation" for stage in stages)
            uses_srm = any(self._stage_type_family_for_ui(str(stage.get("type", ""))) == "srm" for stage in stages)
            uses_hydro = bool(analysis.get("fields")) and any(str(field).lower() in {"p", "pressure", "pore_pressure"} for field in self._ensure_list(analysis.get("fields", []))) or hydro > 0
            large_stage = next((stage for stage in stages if self._stage_type_family_for_ui(str(stage.get("type", ""))) == "large_deformation"), {})
            large_cfg = self._mapping(large_stage.get("large_deformation", self._mapping(self.cfg.get("solver", {})).get("large_deformation", {}))) if isinstance(large_stage, Mapping) else {}
            final_only = bool(large_cfg.get("skip_intermediate_postprocessing", True))
            srm_stage = next((stage for stage in stages if self._stage_type_family_for_ui(str(stage.get("type", ""))) == "srm"), {})
            srm_cfg = self._mapping(srm_stage.get("srm", {})) if isinstance(srm_stage, Mapping) else {}
            hydro_steps = sum(int(self._mapping(stage.get("hydro", {})).get("steps", self._mapping(stage.get("consolidation", {})).get("steps", 1)) or 1) for stage in stages if self._stage_hydro_count(stage))
            pressure_dofs = "mesh nodes" if uses_hydro else "0"
            extra_en = [
                ("Deformation/Fast Path", f"{deformation_mode} / {element_type} / {integration} / {','.join(material_models)} / batched and fallback counts reported after run", "OK" if uses_large else "OK"),
                ("SRM Search", f"range {srm_cfg.get('factor_start', srm_cfg.get('factor_min', 'default'))}..{srm_cfg.get('factor_max', srm_cfg.get('factor_end', 'default'))}, bisection {srm_cfg.get('max_bisection', 'default')}, reasons reported after run" if uses_srm else "not used", "OK"),
                ("QUAD8 Fast Path", f"integration {integration}, integration points and fallback count reported after run" if element_type == "QUAD8" else "not QUAD8", "OK"),
                ("U-P Coupling", f"time steps {hydro_steps or 0}, pressure DOFs {pressure_dofs}, drainage/flow/mass-balance/convergence reported" if uses_hydro else "not used", "OK"),
                ("Fallback Warning", "fallback_count/fallback_reasons are warnings; analysis continues when possible", "OK"),
                ("Postprocess Policy", "final increment only" if final_only else "all increments", "OK"),
            ]
            extra_ja = [
                ("変形/高速化", f"{deformation_mode} / {element_type} / {integration} / {','.join(material_models)} / バッチ数とフォールバック数は実行後に表示", "OK"),
                ("SRM探索", f"範囲 {srm_cfg.get('factor_start', srm_cfg.get('factor_min', '既定'))}..{srm_cfg.get('factor_max', srm_cfg.get('factor_end', '既定'))}, 二分探索 {srm_cfg.get('max_bisection', '既定')}, 判定理由は実行後に表示" if uses_srm else "未使用", "OK"),
                ("QUAD8", f"積分 {integration}, 積分点数とフォールバック数は実行後に表示" if element_type == "QUAD8" else "未使用", "OK"),
                ("水土連成", f"時間ステップ {hydro_steps or 0}, 圧力DOF {pressure_dofs}, 排水/流量収支/圧力収束を表示" if uses_hydro else "未使用", "OK"),
                ("フォールバック", "fallback_count/fallback_reasons は警告として表示し、可能なら解析継続", "OK"),
                ("後処理方針", "最終増分のみ詳細後処理" if final_only else "全増分を詳細後処理", "OK"),
            ]
            if en:
                return [
                    ("Materials", count_text(material_count), material_status),
                    ("Unassigned", unassigned_text, unassigned_status),
                    ("Boundary Conditions", f"{count_text(boundary_total)} ({boundary_detail})", boundary_status),
                    ("Loads", load_text, load_status),
                    ("Stages", stage_text, stage_status),
                    ("Mesh Quality", quality_text, quality_status),
                    *extra_en,
                ]
            return [
                ("材料数", f"{material_count}件", material_status),
                ("未割当", unassigned_text, unassigned_status),
                ("境界条件数", f"{boundary_total}件 ({boundary_detail})", boundary_status),
                ("荷重条件数", load_text, load_status),
                ("ステージ数", stage_text, stage_status),
                ("メッシュ品質", quality_text, quality_status),
                *extra_ja,
            ]

        def _solver_mesh_quality_summary(self) -> tuple[str, str]:
            en = self.gui_locale == "en"
            mesh_cfg = self._mapping(self.cfg.get("mesh", {}))
            if bool(mesh_cfg.get("requires_rebuild", False)):
                return ("Rebuild required: geometry or mesh settings changed" if en else "要再構成: 形状またはメッシュ条件が変更されています"), "ERROR"
            try:
                from geofem_app.fem2d import mesh_from_config
                from geofem_app.mesh_quality import evaluate_mesh_quality

                mesh = mesh_from_config(self.cfg)
                report = evaluate_mesh_quality(mesh, self.cfg)
                summary = self._mapping(report.get("summary", {}))
                violation_count = int(summary.get("violation_count", 0) or 0)
                error_count = int(summary.get("error_count", 0) or 0)
                warning_count = int(summary.get("warning_count", 0) or 0)
                element_count = int(summary.get("element_count", len(getattr(mesh, "elements", []))) or 0)
                min_angle = float(summary.get("min_angle_deg", 0.0) or 0.0)
                max_aspect = float(summary.get("max_aspect_ratio", 0.0) or 0.0)
                status = "ERROR" if error_count else ("WARN" if warning_count else "OK")
                if en:
                    text = (
                        f"Elements {element_count} / Violations {violation_count} "
                        f"(ERROR {error_count} / WARN {warning_count}) / min angle {min_angle:.3g}° / max aspect {max_aspect:.3g}"
                    )
                else:
                    text = (
                        f"要素 {element_count} / 違反 {violation_count} "
                        f"(ERROR {error_count} / WARN {warning_count}) / 最小角 {min_angle:.3g}° / 最大Aspect {max_aspect:.3g}"
                    )
                return text, status
            except Exception as exc:
                if "nodes" not in mesh_cfg and "elements" not in mesh_cfg and "generator" not in mesh_cfg:
                    return ("Not generated: create the mesh" if en else "未生成: メッシュを作成してください"), "ERROR"
                return (f"Cannot check: {exc}" if en else f"確認不可: {exc}"), "WARN"

        def _refresh_solver_final_summary_table(self) -> None:
            table = getattr(self, "solver_final_summary_table", None)
            if table is None:
                return
            cache_key = getattr(self, "_last_edit_snapshot", "") or self._cfg_snapshot()
            cached_key = getattr(self, "_solver_final_summary_cache_key", "")
            if cache_key == cached_key:
                rows = list(getattr(self, "_solver_final_summary_cache_rows", []))
            else:
                rows = self._solver_final_summary_rows()
                self._solver_final_summary_cache_key = cache_key
                self._solver_final_summary_cache_rows = list(rows)
            table.setRowCount(len(rows))
            severity_colors = {
                "OK": QColor("#d1e7dd"),
                "WARN": QColor("#fff3cd"),
                "ERROR": QColor("#f8d7da"),
                "確認": QColor("#fff3cd"),
            }
            for row, (name, value, status) in enumerate(rows):
                for col, text in enumerate((name, value, status)):
                    item = QTableWidgetItem(str(text))
                    if col == 2 or status in {"ERROR", "WARN", "確認"}:
                        item.setBackground(severity_colors.get(status, QColor("#ffffff")))
                    if hasattr(Qt, "ItemFlag"):
                        item.setFlags(item.flags() & ~Qt.ItemFlag.ItemIsEditable)
                    table.setItem(row, col, item)

        def _select_tree_panel(self, panel: str) -> None:
            self._navigate_to_workspace(panel, source="tree_sync")

        def _find_tree_panel_item(self, item: QTreeWidgetItem | None, panel: str) -> QTreeWidgetItem | None:
            if item is None:
                return None
            if str(item.data(0, Qt.ItemDataRole.UserRole) or "") == panel:
                return item
            for index in range(item.childCount()):
                found = self._find_tree_panel_item(item.child(index), panel)
                if found is not None:
                    return found
            return None

        def _add_panel(self, key: str, page: QWidget) -> None:
            self._apply_panel_button_policy(key, page)
            self._apply_visual_hierarchy_policy(key, page)
            self._apply_help_policy(key, page)
            self._apply_accessibility_policy(page)
            scroll = QScrollArea()
            scroll.setWidgetResizable(True)
            scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
            scroll.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
            scroll.setProperty("panelKey", key)
            if key == "analysis":
                width = max(int(self.desktop_layout_profile.center_min_width), int(self.desktop_layout_profile.model_view_min_size[0]))
                height = int(self.desktop_layout_profile.model_view_min_size[1])
                page.setMinimumWidth(width)
                page.setMinimumHeight(max(height, page.minimumSizeHint().height(), page.sizeHint().height()))
                scroll.setMinimumWidth(width)
                scroll.setMinimumHeight(height)
                scroll.setProperty("alignedWithModelWorkspace", True)
            scroll.setWidget(page)
            self.panel_pages[key] = scroll
            self.panel_stack.addWidget(scroll)

        def _install_inline_detail_sheets(self) -> None:
            stack = getattr(self, "inline_detail_stack", None)
            if stack is None:
                return
            for key in getattr(self, "inline_detail_panel_keys", set()):
                page = self.panel_pages.get(key)
                if page is None:
                    continue
                if self.panel_stack.indexOf(page) >= 0:
                    self.panel_stack.removeWidget(page)
                if stack.indexOf(page) < 0:
                    stack.addWidget(page)
            self._set_inline_detail_panel(getattr(self, "current_panel_key", "analysis"))

        def _set_inline_detail_panel(self, panel_key: str) -> None:
            panel = self._panel_key_from_tree_key(str(panel_key or ""))
            group = getattr(self, "inline_detail_sheet_group", None)
            stack = getattr(self, "inline_detail_stack", None)
            if group is None or stack is None:
                return
            if panel in getattr(self, "inline_detail_panel_keys", set()):
                if panel == "stages":
                    if self._show_internal_representation():
                        group.setMinimumHeight(360)
                        group.setMaximumHeight(560)
                    else:
                        group.setMinimumHeight(280)
                        group.setMaximumHeight(430)
                else:
                    group.setMinimumHeight(220)
                    group.setMaximumHeight(320)
                page = self.panel_pages.get(panel)
                if page is not None and stack.indexOf(page) >= 0:
                    stack.setCurrentWidget(page)
                title = self._auxiliary_panel_texts().get(panel, (panel, ""))[0]
                prefix = "Detail Sheet" if self.gui_locale == "en" else "詳細シート"
                group.setTitle(f"{prefix}: {title}")
                group.setVisible(True)
                tabs = getattr(self, "tabs", None)
                model_page = getattr(self, "model_workspace_page", None)
                if tabs is not None and model_page is not None:
                    tabs.setCurrentWidget(model_page)
            else:
                empty = getattr(self, "inline_detail_empty", None)
                if empty is not None and stack.indexOf(empty) >= 0:
                    stack.setCurrentWidget(empty)
                group.setVisible(False)

        def _apply_detail_disclosure_defaults(self) -> None:
            advanced_titles = {
                "geometry": {
                    "CADレイヤ/スナップ表示",
                    "寸法/注記",
                    "NURBS/曲線重複edge",
                    "解析曲線/Boolean split graph",
                },
                "mesh": {"メッシュ制御点/ブロック分割", "GeoFEAS要素ライブラリ"},
                "materials": {"GeoFEAS材料ライブラリ"},
                "stages": {"画面選択からステージ条件を作成"},
                "results": {"出力比較", "SRM専用Post"},
                "report": {"図面レイアウト", "帳票ページWYSIWYG"},
            }
            self.detail_disclosure_groups: list[QGroupBox] = []
            for panel_key, titles in advanced_titles.items():
                scroll = self.panel_pages.get(panel_key)
                page = scroll.widget() if isinstance(scroll, QScrollArea) else None
                if page is None:
                    continue
                for group in page.findChildren(QGroupBox):
                    if group.title() in titles:
                        self._configure_collapsible_detail_group(group)

        def _configure_collapsible_detail_group(self, group: QGroupBox) -> None:
            if group.property("detailDisclosureConfigured"):
                return
            group.setCheckable(True)
            group.setChecked(False)
            group.setToolTip(f"{group.title()}を開閉します。")

            def set_children_visible(visible: bool, target: QGroupBox = group) -> None:
                for child in target.findChildren(QWidget):
                    if child is not target:
                        child.setVisible(visible)

            group.toggled.connect(set_children_visible)
            set_children_visible(False)
            group.setProperty("detailDisclosureConfigured", True)
            self.detail_disclosure_groups.append(group)

        def _connect_geometry_detail_sync_signals(self) -> None:
            for name in (
                "geometry_line_table",
                "geometry_tunnel_table",
                "geometry_layer_table",
                "geometry_annotation_table",
                "geometry_dimension_table",
                "geometry_curve_table",
                "geometry_curve_control_table",
                "geometry_overlap_table",
            ):
                table = getattr(self, name, None)
                if table is not None:
                    table.itemChanged.connect(self._mark_geometry_detail_dirty)
            editor = getattr(self, "geometry_regions_editor", None)
            if editor is not None:
                editor.textChanged.connect(self._mark_geometry_detail_dirty)
            expression = getattr(self, "geometry_boolean_expression", None)
            if expression is not None:
                expression.textChanged.connect(self._mark_geometry_detail_dirty)
            operation = getattr(self, "geometry_boolean_operation", None)
            if operation is not None:
                operation.currentIndexChanged.connect(self._mark_geometry_detail_dirty)

        def _mark_geometry_detail_dirty(self, *_args: Any) -> None:
            if getattr(self, "_geometry_detail_tables_syncing", False):
                return
            if self._current_gui_operation_mode() not in {"detail", "maintenance"}:
                return
            self._geometry_detail_tables_dirty = True

        @staticmethod
        def _geometry_has_display_primitives(geometry: Mapping[str, Any]) -> bool:
            primitive_keys = ("lines", "regions", "tunnels", "points", "curves", "arcs", "hatches", "blocks", "cad_lines")
            for key in primitive_keys:
                value = geometry.get(key)
                if isinstance(value, (list, tuple)) and len(value) > 0:
                    return True
            return False

        def _rectangle_display_geometry_from_mesh(self, mesh: Mapping[str, Any]) -> dict[str, Any]:
            generator = str(mesh.get("generator", "")).strip().lower()
            if generator not in {"rectangle", "structured_rectangle", "quad_rect", "tri_rect"}:
                return {}
            x_range = mesh.get("x_range", [mesh.get("x0", 0.0), mesh.get("x1", 1.0)])
            y_range = mesh.get("y_range", [mesh.get("y0", 0.0), mesh.get("y1", 1.0)])
            if not (isinstance(x_range, (list, tuple)) and len(x_range) >= 2 and isinstance(y_range, (list, tuple)) and len(y_range) >= 2):
                return {}
            try:
                x0, x1 = float(x_range[0]), float(x_range[1])
                y0, y1 = float(y_range[0]), float(y_range[1])
            except (TypeError, ValueError):
                return {}
            if abs(x1 - x0) <= 1.0e-12 or abs(y1 - y0) <= 1.0e-12:
                return {}
            layer = "template mesh outline"
            points = [(x0, y0), (x1, y0), (x1, y1), (x0, y1)]
            edge_names = ("bottom", "right", "top", "left")
            material = str(mesh.get("material", "") or "").strip()
            region: dict[str, Any] = {
                "id": "mesh_outline_region",
                "points": [[x0, y0], [x1, y0], [x1, y1], [x0, y1]],
                "source": "mesh_rectangle_outline",
            }
            if material:
                region["material"] = material
            return {
                "layers": [
                    {
                        "name": layer,
                        "visible": True,
                        "locked": False,
                        "color": "#7a5c00",
                        "source": "mesh_rectangle_outline",
                    }
                ],
                "lines": [
                    {
                        "id": f"mesh_outline_{name}",
                        "purpose": "model",
                        "layer": layer,
                        "start": [points[index][0], points[index][1]],
                        "end": [points[(index + 1) % len(points)][0], points[(index + 1) % len(points)][1]],
                        "source": "mesh_rectangle_outline",
                    }
                    for index, name in enumerate(edge_names)
                ],
                "regions": [region],
                "mesh_outline_source": {
                    "generator": generator,
                    "x_range": [x0, x1],
                    "y_range": [y0, y1],
                },
            }

        def _explicit_mesh_node_xy_map(self, mesh: Mapping[str, Any]) -> dict[str, tuple[float, float]]:
            raw_nodes = mesh.get("nodes")
            nodes: dict[str, tuple[float, float]] = {}
            if isinstance(raw_nodes, Mapping):
                for node_id, value in raw_nodes.items():
                    try:
                        target = value
                        if isinstance(value, Mapping):
                            target = value.get("coord", value.get("coords", value))
                        nodes[str(node_id)] = self._xy_pair(target)
                    except (TypeError, ValueError):
                        continue
            elif isinstance(raw_nodes, list):
                for index, value in enumerate(raw_nodes, start=1):
                    try:
                        node_id = str(index)
                        target = value
                        if isinstance(value, Mapping):
                            node_id = str(value.get("id", index))
                            target = value.get("coord", value.get("coords", value))
                        nodes[node_id] = self._xy_pair(target)
                    except (TypeError, ValueError):
                        continue
            return nodes

        def _explicit_mesh_element_corner_nodes(self, mesh: Mapping[str, Any], raw: Any) -> list[str]:
            default_type = str(mesh.get("element_type", mesh.get("type", ""))).strip().upper()
            if isinstance(raw, Mapping):
                element_type = str(raw.get("type", raw.get("element_type", default_type))).strip().upper()
                raw_nodes = raw.get("nodes", raw.get("connectivity", []))
            else:
                element_type = default_type
                raw_nodes = raw
            nodes = [str(value) for value in self._ensure_list(raw_nodes)]
            if element_type.startswith("TRI"):
                return nodes[:3]
            if element_type.startswith("QUAD"):
                return nodes[:4]
            if len(nodes) in {3, 6}:
                return nodes[:3]
            if len(nodes) in {4, 8}:
                return nodes[:4]
            return []

        def _explicit_mesh_display_geometry(self, mesh: Mapping[str, Any]) -> dict[str, Any]:
            nodes = self._explicit_mesh_node_xy_map(mesh)
            raw_elements = mesh.get("elements", [])
            if not nodes or not isinstance(raw_elements, list):
                return {}
            edge_counts: dict[tuple[str, str], int] = {}
            edge_orientation: dict[tuple[str, str], tuple[str, str]] = {}
            for raw in raw_elements:
                corners = self._explicit_mesh_element_corner_nodes(mesh, raw)
                if len(corners) < 3:
                    continue
                for index, start in enumerate(corners):
                    end = corners[(index + 1) % len(corners)]
                    if start == end or start not in nodes or end not in nodes:
                        continue
                    key = tuple(sorted((start, end)))
                    edge_counts[key] = edge_counts.get(key, 0) + 1
                    edge_orientation.setdefault(key, (start, end))
            lines: list[dict[str, Any]] = []
            for index, key in enumerate(edge_counts, start=1):
                if edge_counts[key] != 1:
                    continue
                start, end = edge_orientation[key]
                x1, y1 = nodes[start]
                x2, y2 = nodes[end]
                lines.append(
                    {
                        "id": f"mesh_boundary_{index}",
                        "purpose": "model",
                        "layer": "template mesh boundary",
                        "start": [x1, y1],
                        "end": [x2, y2],
                        "source": "template_mesh_boundary",
                    }
                )
            if not lines:
                return {}
            return {
                "layers": [
                    {
                        "name": "template mesh boundary",
                        "visible": True,
                        "locked": False,
                        "color": "#7a5c00",
                        "source": "template_mesh_boundary",
                    }
                ],
                "lines": lines,
                "mesh_outline_source": {"source": "explicit_mesh_boundary", "boundary_edges": len(lines)},
            }

        def _display_geometry_from_mesh(self, mesh: Mapping[str, Any]) -> dict[str, Any]:
            if not isinstance(mesh, Mapping):
                return {}
            return self._rectangle_display_geometry_from_mesh(mesh) or self._explicit_mesh_display_geometry(mesh)

        def _merge_generated_display_geometry(self, geometry: Mapping[str, Any], generated: Mapping[str, Any]) -> dict[str, Any]:
            merged = copy.deepcopy(dict(geometry)) if isinstance(geometry, Mapping) else {}
            for key, value in generated.items():
                if isinstance(value, list):
                    existing = merged.get(key)
                    if isinstance(existing, list) and existing:
                        continue
                elif key in merged and merged.get(key) not in (None, "", {}, []):
                    continue
                merged[key] = copy.deepcopy(value)
            return merged

        def _template_with_display_geometry(self, data: Mapping[str, Any]) -> dict[str, Any]:
            cfg = copy.deepcopy(dict(data))
            geometry = self._mapping(cfg.get("geometry", {}))
            if self._geometry_has_display_primitives(geometry):
                return cfg
            generated = self._display_geometry_from_mesh(self._mapping(cfg.get("mesh", {})))
            if generated:
                cfg["geometry"] = self._merge_generated_display_geometry(geometry, generated)
            return cfg

        def _ensure_editable_geometry_from_visible_mesh(self) -> bool:
            raw_geometry = self.cfg.get("geometry")
            geometry = self._geometry_cfg()
            primitive_keys = ("lines", "regions", "tunnels", "points", "curves", "arcs", "hatches")
            if isinstance(raw_geometry, Mapping) and any(key in geometry for key in primitive_keys):
                return False
            if self._geometry_has_display_primitives(geometry):
                return False
            generated = self._rectangle_display_geometry_from_mesh(self._mapping(self.cfg.get("mesh", {})))
            if not generated:
                return False
            self.cfg["geometry"] = self._merge_generated_display_geometry(geometry, generated)
            return True

        def _refresh_geometry_detail_from_cfg(self) -> None:
            previous = bool(getattr(self, "_geometry_detail_tables_syncing", False))
            self._geometry_detail_tables_syncing = True
            seeded = False
            try:
                seeded = self._ensure_editable_geometry_from_visible_mesh()
                self.populate_geometry_tables()
            finally:
                self._geometry_detail_tables_syncing = previous
            if not previous:
                self._geometry_detail_tables_dirty = False
            if seeded:
                self._syncing_yaml = True
                self.yaml_editor.setPlainText(yaml.safe_dump(self.cfg, allow_unicode=True, sort_keys=False))
                self._syncing_yaml = False

        def _apply_geometry_detail_to_cfg_if_dirty(self) -> bool:
            if not bool(getattr(self, "_geometry_detail_tables_dirty", False)):
                return True
            before = self._cfg_snapshot()
            if self.apply_geometry_panel(after_change=False) is False:
                self.statusBar().showMessage("詳細表示の作図内容に入力エラーがあるため、作図パレットへ戻れません。")
                return False
            self._geometry_detail_tables_dirty = False
            if self._cfg_snapshot() != before:
                self._after_form_change("詳細表示の作図内容を作図パレットへ同期しました")
            else:
                self._refresh_geometry_detail_from_cfg()
            return True

        def _add_right_pane_field_grid(self, parent_layout: QVBoxLayout, fields: list[tuple[str, QWidget]]) -> None:
            grid = QGridLayout()
            grid.setContentsMargins(0, 0, 0, 0)
            grid.setHorizontalSpacing(6)
            grid.setVerticalSpacing(5)
            for index, (label_text, widget) in enumerate(fields):
                row = index // 2
                base_col = (index % 2) * 2
                label = QLabel(label_text)
                label.setWordWrap(True)
                widget.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
                grid.addWidget(label, row, base_col)
                grid.addWidget(widget, row, base_col + 1)
            grid.setColumnStretch(1, 1)
            grid.setColumnStretch(3, 1)
            parent_layout.addLayout(grid)

        def _add_right_pane_equal_field_columns(self, parent_layout: QVBoxLayout, fields: list[tuple[str, QWidget]]) -> None:
            grid = QGridLayout()
            grid.setContentsMargins(0, 0, 0, 0)
            grid.setHorizontalSpacing(8)
            grid.setVerticalSpacing(6)
            for index, (label_text, widget) in enumerate(fields):
                wrapper = QWidget()
                wrapper.setProperty("rightPaneFieldRole", "equal-column")
                wrapper.setProperty("rightPaneFieldLabel", label_text)
                field_layout = QVBoxLayout(wrapper)
                field_layout.setContentsMargins(0, 0, 0, 0)
                field_layout.setSpacing(2)
                label = QLabel(label_text)
                label.setProperty("rightPaneFieldCaption", True)
                label.setWordWrap(True)
                widget.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
                field_layout.addWidget(label)
                field_layout.addWidget(widget)
                grid.addWidget(wrapper, index // 2, index % 2)
            grid.setColumnStretch(0, 1)
            grid.setColumnStretch(1, 1)
            parent_layout.addLayout(grid)

        def _add_right_pane_full_width_field(self, parent_layout: QVBoxLayout, label_text: str, widget: QWidget) -> None:
            wrapper = QWidget()
            wrapper.setProperty("rightPaneFieldRole", "full-width")
            wrapper.setProperty("rightPaneFieldLabel", label_text)
            field_layout = QVBoxLayout(wrapper)
            field_layout.setContentsMargins(0, 0, 0, 0)
            field_layout.setSpacing(2)
            label = QLabel(label_text)
            label.setProperty("rightPaneFieldCaption", True)
            label.setWordWrap(True)
            widget.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
            field_layout.addWidget(label)
            field_layout.addWidget(widget)
            parent_layout.addWidget(wrapper)

        def _make_right_pane_button(self, label: str, callback: Callable[..., Any], icon_role: str = "", *, context: str = "view") -> QPushButton:
            button = QPushButton(label)
            button.clicked.connect(callback)
            if icon_role:
                self._apply_button_icon(button, icon_role)
            self._install_work_context_menu(button, context)
            return button

        def _make_right_pane_menu_button(
            self,
            label: str,
            actions: list[tuple[str, str, Callable[..., Any]]],
            icon_role: str = "",
            *,
            context: str = "view",
        ) -> QPushButton:
            button = QPushButton(label)
            menu = QMenu(button)
            for ja_text, en_text, callback in actions:
                action = QAction(ja_text, button)
                action.setProperty("menuTextJa", ja_text)
                action.setProperty("menuTextEn", en_text)
                action.triggered.connect(lambda _checked=False, cb=callback: cb())
                menu.addAction(action)
            button.setMenu(menu)
            if icon_role:
                self._apply_button_icon(button, icon_role)
            self._install_work_context_menu(button, context)
            return button

