        @staticmethod
        def _stage_type_family_for_ui(stage_type: str) -> str:
            stype = str(stage_type or "static").strip().lower().replace("-", "_")
            if stype in {"geostatic", "k0", "initial_stress"}:
                return "geostatic"
            if stype in {"excavation", "death", "deactivate", "remove"}:
                return "excavation"
            if stype in {"consolidation", "u_p", "up", "coupled_consolidation"}:
                return "consolidation"
            if stype in {"srm", "safety_factor", "strength_reduction"}:
                return "srm"
            if stype in {"riks", "arc_length", "arclength"}:
                return "riks"
            if stype in {"large_deformation", "large_displacement", "finite_deformation", "updated_lagrangian"}:
                return "large_deformation"
            return "static"

        @staticmethod
        def _stage_detail_action_rows(buttons: list[QPushButton]) -> list[list[QPushButton]]:
            return [buttons[index : index + 2] for index in range(0, len(buttons), 2)]

        def _stage_detail_action_group_key(self) -> str:
            tabs = getattr(self, "stage_detail_tabs", None)
            if tabs is None:
                return "material"
            keys = ["material", "boundary", "load", "hydro", "mpc"]
            index = max(0, int(tabs.currentIndex()))
            if index >= len(keys):
                return keys[0]
            return keys[index]

        def _refresh_stage_detail_sheet_action_buttons(self) -> None:
            group = getattr(self, "stage_detail_sheet_action_group", None)
            stack = getattr(self, "stage_detail_sheet_action_stack", None)
            pages = getattr(self, "stage_detail_sheet_action_pages", {})
            if group is None or stack is None or not pages:
                return
            key = self._stage_detail_action_group_key()
            page = pages.get(key)
            if page is None:
                group.setVisible(False)
                return
            stack.setCurrentWidget(page)
            titles = {
                "material": ("材料変更", "Material"),
                "boundary": ("境界", "Boundary"),
                "load": ("荷重", "Load"),
                "hydro": ("水理", "Hydraulic"),
                "mpc": ("MPC", "MPC"),
            }
            ja, en = titles.get(key, (key, key))
            group.setTitle(f"Detail Sheet Actions: {en}" if self.gui_locale == "en" else f"詳細シート操作: {ja}")
            group.setVisible(self._show_internal_representation())

        def _build_stage_inspector_panel(self) -> QWidget:
            panel = QWidget()
            panel.setProperty("role", "stageInspectorPanel")
            layout = QVBoxLayout(panel)
            layout.setContentsMargins(0, 0, 0, 0)
            layout.setSpacing(8)
            self.aux_stage_selected_label = QLabel("選択ステージ: -")
            self.aux_stage_selected_label.setWordWrap(True)
            self.aux_stage_srm_hint = QLabel("SRMは前ステージまでの応力・材料・境界・荷重状態を引き継ぎ、強度低減係数を掃引します。")
            self.aux_stage_srm_hint.setWordWrap(True)
            self.aux_stage_srm_hint.setProperty("informationRole", "detail")
            layout.addWidget(self.aux_stage_selected_label)
            recommendation = getattr(self, "stage_recommendation_label", None)
            if recommendation is not None:
                layout.addWidget(recommendation)
            layout.addWidget(self.aux_stage_srm_hint)

            field_grid = QGridLayout()
            field_grid.setContentsMargins(0, 0, 0, 0)
            field_grid.setHorizontalSpacing(8)
            field_grid.setVerticalSpacing(6)
            self.stage_inspector_field_wrappers = []

            def add_field(label_text: str, widget: QWidget, family: str = "basic") -> None:
                wrapper = QWidget()
                wrapper.setProperty("stageInspectorFamily", family)
                wrapper.setProperty("stageInspectorLabel", label_text)
                wrapper_layout = QVBoxLayout(wrapper)
                wrapper_layout.setContentsMargins(0, 0, 0, 0)
                wrapper_layout.setSpacing(2)
                label = QLabel(label_text)
                label.setWordWrap(True)
                label.setProperty("rightPaneFieldCaption", True)
                widget.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
                wrapper_layout.addWidget(label)
                wrapper_layout.addWidget(widget)
                index = len(self.stage_inspector_field_wrappers)
                field_grid.addWidget(wrapper, index // 2, index % 2)
                self.stage_inspector_field_wrappers.append(wrapper)

            add_field("名称", self.stage_detail_name)
            add_field("種別", self.stage_detail_type)
            add_field("対象set/要素", self.stage_detail_target)
            add_field("増分数", self.stage_detail_increments)
            add_field("応力解放率", self.stage_detail_stress_release, "excavation")
            add_field("自重/K0", self.stage_detail_apply_gravity, "geostatic")
            add_field("K0", self.stage_detail_k0, "geostatic")
            add_field("地表Y", self.stage_detail_surface_y, "geostatic")
            add_field("gx", self.stage_detail_gx, "geostatic")
            add_field("gy", self.stage_detail_gy, "geostatic")
            add_field("荷重倍率", self.stage_detail_scale, "geostatic")
            add_field("圧密dt", self.stage_detail_dt, "consolidation")
            add_field("圧密steps", self.stage_detail_steps, "consolidation")
            add_field("貯留係数", self.stage_detail_storage, "consolidation")
            add_field("透水係数", self.stage_detail_permeability, "consolidation")
            add_field("Biot係数", self.stage_detail_biot_alpha, "consolidation")
            add_field("低減開始", self.stage_detail_srm_start, "srm")
            add_field("低減終了", self.stage_detail_srm_end, "srm")
            add_field("低減刻み", self.stage_detail_srm_step, "srm")
            if hasattr(self, "stage_detail_srm_failure_ratio"):
                add_field("破壊判定比", self.stage_detail_srm_failure_ratio, "srm")
            add_field("Riks弧長", self.stage_detail_riks_arc, "riks")
            add_field("Riks最大step", self.stage_detail_riks_steps, "riks")
            field_grid.setColumnStretch(0, 1)
            field_grid.setColumnStretch(1, 1)
            layout.addLayout(field_grid)

            self.stage_detail_solver.setMaximumHeight(78)
            solver_wrapper = QWidget()
            solver_wrapper.setProperty("rightPaneFieldRole", "full-width")
            solver_wrapper.setProperty("rightPaneFieldLabel", "solver YAML")
            solver_wrapper.setProperty("stageInspectorFamily", "solver")
            solver_layout = QVBoxLayout(solver_wrapper)
            solver_layout.setContentsMargins(0, 0, 0, 0)
            solver_layout.setSpacing(2)
            solver_label = QLabel("solver YAML")
            solver_label.setProperty("rightPaneFieldCaption", True)
            solver_layout.addWidget(solver_label)
            solver_layout.addWidget(self.stage_detail_solver)
            layout.addWidget(solver_wrapper)
            self.stage_inspector_field_wrappers.append(solver_wrapper)

            apply_detail_btn = self._make_right_pane_button("詳細を反映", self.apply_stage_detail_tables, "stages", context="stages")
            recommend_btn = self._make_right_pane_button(
                "推奨値を反映",
                lambda _checked=False: self.apply_stage_recommended_defaults(force=True),
                "stages",
                context="stages",
            )
            self.stage_inspector_apply_button = apply_detail_btn
            self.stage_inspector_recommend_button = recommend_btn
            self._add_uniform_panel_button_pair_grid(
                layout,
                [[apply_detail_btn], [recommend_btn]],
                columns=1,
                min_width=120,
            )
            detail_action_groups = getattr(self, "stage_detail_action_button_groups", {})
            if detail_action_groups:
                self.stage_detail_sheet_action_group = QGroupBox("詳細シート操作")
                self.stage_detail_sheet_action_group.setProperty("informationRole", "auxiliary")
                detail_action_layout = QVBoxLayout(self.stage_detail_sheet_action_group)
                detail_action_layout.setContentsMargins(6, 6, 6, 6)
                detail_action_layout.setSpacing(6)
                self.stage_detail_sheet_action_stack = QStackedWidget()
                self.stage_detail_sheet_action_pages: dict[str, QWidget] = {}
                for group_key, buttons in detail_action_groups.items():
                    page = QWidget()
                    page.setProperty("stageDetailSheetActionGroup", group_key)
                    page_layout = QVBoxLayout(page)
                    page_layout.setContentsMargins(0, 0, 0, 0)
                    page_layout.setSpacing(6)
                    for button in buttons:
                        button.setProperty("stageDetailSheetRightPaneButton", True)
                    self._add_uniform_panel_button_pair_grid(
                        page_layout,
                        self._stage_detail_action_rows(list(buttons)),
                        columns=2,
                        min_width=120,
                    )
                    page_layout.addStretch(1)
                    self.stage_detail_sheet_action_stack.addWidget(page)
                    self.stage_detail_sheet_action_pages[str(group_key)] = page
                detail_action_layout.addWidget(self.stage_detail_sheet_action_stack)
                layout.addWidget(self.stage_detail_sheet_action_group)
                self._refresh_stage_detail_sheet_action_buttons()
            layout.addStretch(1)
            self._refresh_stage_inspector_visibility()
            return panel

        def _refresh_stage_inspector_visibility(self) -> None:
            if getattr(self, "stage_inspector_field_wrappers", None) is None:
                return
            en = self.gui_locale == "en"
            field_labels = {
                "名称": "Name",
                "種別": "Type",
                "対象set/要素": "Target set/elements",
                "増分数": "Increments",
                "応力解放率": "Stress release",
                "自重/K0": "Gravity/K0",
                "地表Y": "Surface Y",
                "荷重倍率": "Load scale",
                "圧密dt": "Consolidation dt",
                "圧密steps": "Consolidation steps",
                "貯留係数": "Storage",
                "透水係数": "Permeability",
                "Biot係数": "Biot alpha",
                "低減開始": "Reduction start",
                "低減終了": "Reduction end",
                "低減刻み": "Reduction step",
                "破壊判定比": "Failure plastic ratio",
                "Riks弧長": "Riks arc length",
                "Riks最大step": "Riks max steps",
                "solver YAML": "Solver YAML",
            }
            field_labels_ja = {"solver YAML": "ソルバ詳細"}
            combo = getattr(self, "stage_detail_type", None)
            family = self._stage_type_family_for_ui(self._combo_value(combo, "static"))
            visible_families = {"basic", family}
            if family in {"excavation", "consolidation", "srm", "riks", "large_deformation"}:
                visible_families.add("solver")
            for wrapper in self.stage_inspector_field_wrappers:
                label_key = str(wrapper.property("stageInspectorLabel") or wrapper.property("rightPaneFieldLabel") or "")
                labels = wrapper.findChildren(QLabel)
                if labels and label_key:
                    labels[0].setText(field_labels.get(label_key, label_key) if en else field_labels_ja.get(label_key, label_key))
                wrapper_family = str(wrapper.property("stageInspectorFamily") or "basic")
                visible = wrapper_family in visible_families
                if not self._show_internal_representation() and wrapper_family != "basic":
                    visible = False
                wrapper.setVisible(visible)
            stage_group = getattr(self, "aux_stage_inspector_group", None)
            if stage_group is not None:
                aux_label_map = {"solver YAML": "Solver YAML"}
                aux_label_map_ja = {"Solver YAML": "ソルバ詳細"}
                for label in stage_group.findChildren(QLabel):
                    text = str(label.text() or "")
                    if en and text in aux_label_map:
                        label.setText(aux_label_map[text])
                    elif not en and text in aux_label_map_ja:
                        label.setText(aux_label_map_ja[text])
            srm_hint = getattr(self, "aux_stage_srm_hint", None)
            if srm_hint is not None:
                srm_hint.setText(
                    "SRM inherits the stress, material, boundary, and load state up to the previous stage, then sweeps the strength-reduction factor."
                    if en
                    else "SRMは前ステージまでの応力・材料・境界・荷重状態を引き継ぎ、強度低減係数を掃引します。"
                )
                srm_hint.setVisible(family == "srm" and self._show_internal_representation())
            for attr, ja, en_text in (
                ("stage_inspector_apply_button", "詳細を反映", "Apply Detail"),
                ("stage_inspector_recommend_button", "推奨値を反映", "Apply Defaults"),
                ("aux_stage_more_button", "その他", "More"),
            ):
                button = getattr(self, attr, None)
                if button is not None:
                    button.setText(en_text if en else ja)
                    self._prepare_panel_action_button(button)
            more_button = getattr(self, "aux_stage_more_button", None)
            if more_button is not None and more_button.menu() is not None:
                for action in more_button.menu().actions():
                    action.setText(str(action.property("menuTextEn") if en else action.property("menuTextJa") or action.text()))
            selected_label = getattr(self, "aux_stage_selected_label", None)
            if selected_label is not None:
                row = self._selected_stage_row()
                stages = self._stages()
                if row is not None and 0 <= row < len(stages):
                    stage = stages[row]
                    stage_type = choice_label("stage_type", stage.get("type", "static"), locale=self.gui_locale)
                    selected_label.setText(
                        f"Selected Stage: {row + 1} / {stage.get('name', f'Stage-{row + 1}')} / {stage_type}"
                        if en
                        else f"選択ステージ: {row + 1} / {stage.get('name', f'Stage-{row + 1}')} / {stage_type}"
                    )
                else:
                    selected_label.setText("Selected Stage: none" if en else "選択ステージ: なし")
            self._refresh_stage_detail_sheet_action_buttons()

