        def _current_gui_operation_mode(self) -> str:
            combo = getattr(self, "gui_operation_mode_combo", None)
            if combo is None:
                return getattr(self, "gui_operation_mode", "standard")
            return str(combo.currentData() or "standard")

        def _hide_notification_banner(self) -> None:
            banner = getattr(self, "notification_banner", None)
            if banner is not None:
                banner.setVisible(False)

        def notify_user(
            self,
            message: Any,
            *,
            severity: str = "info",
            timeout_ms: int = 7000,
        ) -> None:
            """Show routine feedback without interrupting the current workflow."""

            text = str(message or "").strip()
            if not text:
                return
            tone = {"success": "ok", "ok": "ok", "warning": "warning", "error": "error"}.get(
                str(severity).lower(),
                "info",
            )
            banner = getattr(self, "notification_banner", None)
            if banner is not None:
                timer = getattr(self, "_notification_hide_timer", None)
                if timer is not None:
                    timer.stop()
                banner.setText(text)
                banner.setProperty("severity", tone)
                banner.setVisible(True)
                banner.style().unpolish(banner)
                banner.style().polish(banner)
                if timeout_ms > 0 and timer is not None:
                    timer.start(int(timeout_ms))
            self.statusBar().showMessage(text, max(0, int(timeout_ms)))

        def _show_internal_representation(self) -> bool:
            return self._current_gui_operation_mode() in {"detail", "maintenance"}

        def _present_input_reference(self, value: Any) -> str:
            raw = str(value or "")
            if self._show_internal_representation():
                return raw
            return friendly_input_reference(raw, locale=self.gui_locale)

        def _apply_presentation_choice_locale(self) -> None:
            presentation_hints = {
                "The stored identifier is available in the YAML view.",
                "保存時の内部値はYAML表示で確認できます。",
                "Choose by its user-facing name; the analysis-data value is managed automatically.",
                "表示名で選択できます。解析データ用の値は自動で管理されます。",
            }
            for combo in self.findChildren(QComboBox):
                if not str(combo.property("presentationChoiceGroup") or ""):
                    continue
                relabel_combo(combo, locale=self.gui_locale)
                if self._show_internal_representation():
                    tooltip = (
                        "The stored identifier is available in the YAML view."
                        if self.gui_locale == "en"
                        else "保存時の内部値はYAML表示で確認できます。"
                    )
                else:
                    tooltip = (
                        "Choose by its user-facing name; the analysis-data value is managed automatically."
                        if self.gui_locale == "en"
                        else "表示名で選択できます。解析データ用の値は自動で管理されます。"
                    )
                existing_lines = [
                    line
                    for line in str(combo.toolTip() or "").splitlines()
                    if line.strip() and line.strip() not in presentation_hints
                ]
                combo.setToolTip("\n".join([tooltip, *existing_lines]))

        def _operation_mode_locale_rows(self) -> dict[str, tuple[str, str]]:
            if self.gui_locale == "en":
                return {
                    "standard": ("Standard", "Standard: Show only the operations needed for normal input, analysis, and result review."),
                    "detail": ("Advanced", "Advanced: Reach every feature including CAD repair, quality checks, and YAML."),
                    "geofeas": ("GeoFEAS-like", "GeoFEAS-like: Follow the public workflow order for input and review."),
                    "vgflow": ("VGFlow Link", "VGFlow Link: Focus on seepage linkage and hydraulic conditions."),
                    "maintenance": ("Maintenance", "Maintenance: Prioritize audit, recovery, verification, and detailed data review."),
                }
            return {
                "standard": ("標準", "標準: 通常の入力、解析、結果確認に必要な操作だけを表示します。"),
                "detail": ("詳細", "詳細: CAD修復、品質検証、YAMLなど全機能へ到達できます。"),
                "geofeas": ("GeoFEAS風", "GeoFEAS風: 公開手順ベースの作業順で入力と確認を進めます。"),
                "vgflow": ("VGFlow連携", "VGFlow連携: 浸透流連携と水理条件を中心に表示します。"),
                "maintenance": ("保守/検証", "保守/検証: 監査、復旧、検証、詳細データ確認を優先します。"),
            }

        def _apply_operation_surface_locale(self) -> None:
            rows = self._operation_mode_locale_rows()
            self.operation_mode_descriptions = {key: description for key, (_label, description) in rows.items()}
            combo = getattr(self, "gui_operation_mode_combo", None)
            if combo is not None:
                current = combo.currentData()
                combo.blockSignals(True)
                for index in range(combo.count()):
                    mode_key = str(combo.itemData(index) or "")
                    label, description = rows.get(mode_key, (mode_key, ""))
                    combo.setItemText(index, label)
                    combo.setItemData(index, description, Qt.ItemDataRole.ToolTipRole)
                selected = combo.findData(current)
                if selected >= 0:
                    combo.setCurrentIndex(selected)
                combo.blockSignals(False)
                combo.setToolTip(
                    "Switch the visible feature set for your task."
                    if self.gui_locale == "en"
                    else "作業目的に合わせて、表示する機能量を切り替えます。"
                )
            self._apply_presentation_choice_locale()
            self._refresh_stage_standard_controls_locale()
            label = getattr(self, "operation_mode_label", None)
            if label is not None:
                label.setText("Operation Mode" if self.gui_locale == "en" else "操作モード")
            label = getattr(self, "command_search_label", None)
            if label is not None:
                label.setText("Command Search" if self.gui_locale == "en" else "コマンド検索")
            command_search = getattr(self, "command_search", None)
            if command_search is not None:
                command_search.setToolTip(
                    "Search by command name, purpose, or shortcut."
                    if self.gui_locale == "en"
                    else "コマンド名、用途、ショートカットで検索します。"
                )
                if command_search.lineEdit() is not None:
                    command_search.lineEdit().setPlaceholderText("Command Search" if self.gui_locale == "en" else "コマンド検索")
            run_button = getattr(self, "command_run_button", None)
            if run_button is not None:
                run_button.setText("Run Command" if self.gui_locale == "en" else "コマンド実行")
                run_button.setToolTip(
                    "Run the command selected in the search box. Use the Run section for analysis execution."
                    if self.gui_locale == "en"
                    else "検索欄で選んだコマンドを実行します。解析実行は下部の実行から行います。"
                )
            pin_button = getattr(self, "command_pin_button", None)
            if pin_button is not None:
                pin_button.setText("Pin" if self.gui_locale == "en" else "ピン")
            log_label = getattr(self, "global_log_label", None)
            if log_label is not None:
                log_label.setText("Run Log" if self.gui_locale == "en" else "実行ログ")
            log_toggle = getattr(self, "global_log_toggle_button", None)
            if log_toggle is not None:
                expanded = bool(log_toggle.isChecked())
                log_toggle.setText(("Hide" if expanded else "Show") if self.gui_locale == "en" else ("隠す" if expanded else "表示"))
                log_toggle.setToolTip(
                    "Show or collapse the run log."
                    if self.gui_locale == "en"
                    else "実行ログを表示または折り畳みます。"
                )
            cad_more = getattr(self, "model_cad_more_button", None)
            if cad_more is not None:
                self._set_cad_advanced_visible(cad_more.isChecked())
            quick_label = getattr(self, "quick_access_toolbar_label", None)
