        def _refresh_stage_standard_controls_locale(self) -> None:
            en = self.gui_locale == "en"
            texts = {
                "stage_list_label": ("ステージ一覧", "Stage List"),
                "stage_change_section_label": (
                    "ステージごとの変更入力（材料・境界・荷重・無効化/再有効化）",
                    "Stage Changes (material, boundary, load, deactivate/reactivate)",
                ),
                "stage_standard_add_stage_button": ("ステージ追加", "Add Stage"),
                "stage_standard_manage_button": ("ステージ整理", "Manage Stages"),
                "stage_standard_add_change_button": ("変更を追加", "Add Change"),
                "stage_standard_remove_change_button": ("選択削除", "Delete"),
                "stage_standard_apply_changes_button": ("反映", "Apply"),
                "stage_standard_open_detail_button": ("詳細編集", "Advanced Edit"),
            }
            for attr, (ja, en_text) in texts.items():
                widget = getattr(self, attr, None)
                if widget is not None:
                    widget.setText(en_text if en else ja)
            for menu_button_name in ("stage_standard_manage_button", "stage_standard_add_change_button"):
                menu_button = getattr(self, menu_button_name, None)
                if menu_button is not None and menu_button.menu() is not None:
                    for action in menu_button.menu().actions():
                        action.setText(str(action.property("menuTextEn") if en else action.property("menuTextJa") or action.text()))
            self._refresh_stage_standard_change_summary()

        def _operation_mode_changed(self, _index: int) -> None:
            self.gui_operation_mode = self._current_gui_operation_mode()
            self._apply_presentation_choice_locale()
            issues = getattr(self, "_last_model_check_issues", None)
            if isinstance(issues, list):
                apply_model_check_issues_view(self, issues, self._model_check_panel_qt())
            current_panel = getattr(self, "current_panel_key", "workflow")
            self._refresh_tree(select_panel=current_panel)
            stage_inspector_group = getattr(self, "aux_stage_inspector_group", None)
            if stage_inspector_group is not None:
                if self._show_internal_representation():
                    stage_inspector_group.setTitle("Stage Inspector" if self.gui_locale == "en" else "ステージインスペクタ")
                else:
                    stage_inspector_group.setTitle("Selected Stage" if self.gui_locale == "en" else "選択ステージ")
            if self.gui_operation_mode in {"detail", "maintenance"} and current_panel in {"workflow", "geometry", "mesh"}:
                self._refresh_geometry_detail_from_cfg()
            self._refresh_stage_inspector_visibility()
            self._apply_context_visibility(current_panel)
            self._refresh_result_action_states()

        def _result_tree_entries(self) -> list[tuple[str, str]]:
            return [
                ("result:element_stress", "応力コンター"),
                ("result:displacement_vectors", "変位ベクトル"),
                ("result:displacement_contour", "変位コンタ"),
                ("result:displacements", "変形図/変位表"),
                ("result:pore_pressure", "水圧コンタ"),
                ("result:safety_factor", "FL/安全率"),
                ("result:analysis_log", "収束履歴"),
                ("result:performance", "性能履歴"),
            ]

        def _panel_key_from_tree_key(self, key: str) -> str:
            text = str(key)
            if text.startswith("result:"):
                return "results"
            if text.startswith("boundary_condition:"):
                return "boundary_conditions"
            if text.startswith("load_condition:"):
                return "loads"
            if text.startswith("material_assignment:"):
                return "materials"
            if text.startswith("mesh_quality:"):
                return "mesh"
            if text.startswith("stage:"):
                return "stages"
            return text

        def _result_kind_from_tree_key(self, key: str) -> str:
            text = str(key)
            return text.split(":", 1)[1] if text.startswith("result:") else ""

        def _boundary_condition_type_specs(self) -> list[tuple[str, str]]:
            return [
                ("fixed", "固定 ux=uy=0"),
                ("roller_y", "水平ローラ uy=0"),
                ("roller_x", "鉛直ローラ ux=0"),
                ("pin", "ピン ux=uy=0"),
                ("prescribed", "強制変位"),
                ("hydro", "水理境界"),
                ("mpc", "MPC"),
            ]

        def _boundary_condition_type_label(self, kind: str) -> str:
            labels = dict(self._boundary_condition_type_specs())
            return labels.get(str(kind), str(kind) or "境界条件")

        def _boundary_condition_kind_from_spec(self, spec: Mapping[str, Any], *, hydro_key: str = "") -> str:
            if hydro_key:
                return "hydro"
            if any(key in spec for key in ("master", "slave", "master_node", "slave_node")):
                return "mpc"
            support = str(spec.get("support_type", spec.get("type", "")) or "").lower().strip()
            aliases = {
                "fix": "fixed",
                "fixed": "fixed",
                "pin": "pin",
                "pinned": "pin",
                "roller_y": "roller_y",
                "horizontal_roller": "roller_y",
                "roller_x": "roller_x",
                "vertical_roller": "roller_x",
                "prescribed": "prescribed",
                "displacement": "prescribed",
            }
            if support in aliases:
                return aliases[support]
            if bool(spec.get("fixed", False)):
                return "fixed"

            def is_zero(value: Any) -> bool:
                try:
                    return abs(float(value)) <= 1.0e-12
                except Exception:
                    return False

            dof = str(spec.get("dof", "") or "").lower().strip()
            if dof in {"ux", "uy"}:
                return "roller_x" if dof == "ux" and is_zero(spec.get("value", 0.0)) else "roller_y" if dof == "uy" and is_zero(spec.get("value", 0.0)) else "prescribed"
            ux_present = "ux" in spec and spec.get("ux") is not None
            uy_present = "uy" in spec and spec.get("uy") is not None
            if ux_present and uy_present:
                return "fixed" if is_zero(spec.get("ux")) and is_zero(spec.get("uy")) else "prescribed"
            if ux_present:
                return "roller_x" if is_zero(spec.get("ux")) else "prescribed"
            if uy_present:
                return "roller_y" if is_zero(spec.get("uy")) else "prescribed"
            return "fixed"

        def _boundary_condition_nodes_and_edges(self, spec: Mapping[str, Any], *, mesh: Any | None = None) -> tuple[list[str], list[tuple[str, str]]]:
            if mesh is None:
                try:
                    from geofem_app.fem2d import mesh_from_config

                    mesh = mesh_from_config(self.cfg)
                except Exception:
                    mesh = None
            nodes: set[str] = set()
            edges: list[tuple[str, str]] = []
            for key in ("master", "slave", "master_node", "slave_node"):
                value = spec.get(key)
                if value is not None and str(value).strip():
                    nodes.add(str(value).strip())
            if mesh is not None:
                nodes.update(str(node) for node in self._node_targets_for_spec(mesh, spec))
                edges = [(str(a), str(b)) for a, b in self._edge_targets_for_spec(mesh, spec)]
                for a, b in edges:
                    nodes.add(str(a))
                    nodes.add(str(b))
            else:
                for value in self._ensure_list(spec.get("nodes", spec.get("node", []))):
                    if value is not None:
                        nodes.add(str(value))
                raw_edges = spec.get("edges", spec.get("edge", []))
                for edge in self._ensure_list(raw_edges):
                    edge_nodes = [str(value) for value in self._ensure_list(edge)]
                    if len(edge_nodes) >= 2:
                        pair = (edge_nodes[0], edge_nodes[1])
                        edges.append(pair)
                        nodes.update(pair)
            return sorted(nodes, key=self._natural_sort_key), edges

        def _boundary_condition_navigation_specs(self) -> list[dict[str, Any]]:
            try:
                from geofem_app.fem2d import mesh_from_config

                mesh = mesh_from_config(self.cfg)
            except Exception:
                mesh = None
            specs: list[dict[str, Any]] = []

            def target_text(raw: Mapping[str, Any], nodes: list[str], edges: list[tuple[str, str]]) -> str:
                text = self._node_spec_text(raw)
                if text:
                    return text
                if edges:
                    return ", ".join(f"{a}-{b}" for a, b in edges[:4])
                if nodes:
                    return ",".join(nodes[:8])
                return ""

            def condition_summary(raw: Mapping[str, Any], kind: str, hydro_key: str = "") -> str:
                if kind == "hydro":
                    for value_key in ("pressure", "flux", "beta", "value"):
                        if value_key in raw:
                            return f"{hydro_key or 'hydro'} {value_key}={raw.get(value_key)}"
                    return hydro_key or "hydro"
                if kind == "mpc":
                    return f"{raw.get('master', raw.get('master_node', ''))}->{raw.get('slave', raw.get('slave_node', ''))} {raw.get('dof', raw.get('component', ''))}"
                return self._boundary_condition_type_label(kind)

            def add_condition(
                key: str,
                scope_label: str,
                index: int,
                raw: Mapping[str, Any],
                *,
                hydro_key: str = "",
                source: Mapping[str, Any] | None = None,
            ) -> None:
                kind = self._boundary_condition_kind_from_spec(raw, hydro_key=hydro_key)
                nodes, edges = self._boundary_condition_nodes_and_edges(raw, mesh=mesh)
                label = f"{scope_label} {index}: {condition_summary(raw, kind, hydro_key)}"
                target = target_text(raw, nodes, edges)
                if target:
                    label = f"{label} [{target}]"
                specs.append(
                    {
                        "key": key,
                        "kind": kind,
                        "label": label,
                        "nodes": nodes,
                        "edges": edges,
                        "target": target,
                        "source": dict(source or {}),
                        "tooltip": yaml.safe_dump(dict(raw), allow_unicode=True, sort_keys=False).strip(),
                    }
                )

            for index, raw in enumerate(self._ensure_list(self.cfg.get("boundary_conditions", self.cfg.get("bc", []))), start=1):
                if isinstance(raw, Mapping):
                    add_condition(f"boundary_condition:item:global:{index}", "全体", index, raw, source={"scope": "global_bc", "index": index - 1})
            for index, raw in enumerate(self._ensure_list(self.cfg.get("mpc_constraints", self.cfg.get("mpc", []))), start=1):
                if isinstance(raw, Mapping):
                    add_condition(f"boundary_condition:item:global_mpc:{index}", "全体MPC", index, raw, source={"scope": "global_mpc", "index": index - 1})

            for stage_index, stage in enumerate(self._stages(), start=1):
                stage_name = str(stage.get("name", f"Stage-{stage_index}"))
                for index, raw in enumerate(self._ensure_list(stage.get("boundary_conditions", stage.get("bc", []))), start=1):
                    if isinstance(raw, Mapping):
                        add_condition(
                            f"boundary_condition:item:stage:{stage_index}:{index}",
                            stage_name,
                            index,
                            raw,
                            source={"scope": "stage_bc", "stage_index": stage_index - 1, "index": index - 1},
                        )
                hydro = stage.get("hydro", stage.get("consolidation", {}))
                if isinstance(hydro, Mapping):
                    hydro_index = 1
                    for hydro_key in ("pressure_bcs", "pore_pressure_bcs", "pore_flux_bcs", "pore_robin_bcs"):
                        for list_index, raw in enumerate(self._ensure_list(hydro.get(hydro_key, [])), start=1):
                            if isinstance(raw, Mapping):
                                add_condition(
                                    f"boundary_condition:item:hydro:{stage_index}:{hydro_key}:{hydro_index}",
                                    stage_name,
                                    hydro_index,
                                    raw,
                                    hydro_key=hydro_key,
                                    source={
                                        "scope": "hydro",
                                        "stage_index": stage_index - 1,
                                        "hydro_key": hydro_key,
                                        "index": list_index - 1,
                                    },
                                )
                                hydro_index += 1
                for index, raw in enumerate(self._ensure_list(stage.get("mpc_constraints", stage.get("mpc", []))), start=1):
                    if isinstance(raw, Mapping):
                        add_condition(
                            f"boundary_condition:item:mpc:{stage_index}:{index}",
                            stage_name,
                            index,
                            raw,
                            source={"scope": "stage_mpc", "stage_index": stage_index - 1, "index": index - 1},
                        )
            return specs

        def _add_boundary_condition_navigation_items(self, parent: QTreeWidgetItem, select_panel: str | None) -> QTreeWidgetItem | None:
            specs = self._boundary_condition_navigation_specs()
            specs_by_kind: dict[str, list[dict[str, Any]]] = {}
            for spec in specs:
                specs_by_kind.setdefault(str(spec.get("kind", "")), []).append(spec)
            self._boundary_navigation_specs_cache = {}
            selected_item: QTreeWidgetItem | None = None
            for kind, label in self._boundary_condition_type_specs():
                kind_specs = specs_by_kind.get(kind, [])
                nodes = sorted(
                    {str(node) for spec in kind_specs for node in self._ensure_list(spec.get("nodes", []))},
                    key=self._natural_sort_key,
                )
                edges = [edge for spec in kind_specs for edge in self._ensure_list(spec.get("edges", []))]
                type_key = f"boundary_condition:type:{kind}"
                display = f"{label} ({len(kind_specs)})" if kind_specs else label
                type_item = QTreeWidgetItem([display])
                type_item.setData(0, Qt.ItemDataRole.UserRole, type_key)
                type_item.setToolTip(0, f"{label}: {len(kind_specs)}件 / {len(nodes)}節点")
                parent.addChild(type_item)
                self._boundary_navigation_specs_cache[type_key] = {
                    "key": type_key,
                    "kind": kind,
                    "label": label,
                    "nodes": nodes,
                    "edges": edges,
                    "specs": kind_specs,
                }
                if select_panel == type_key:
                    selected_item = type_item
                for spec in kind_specs:
                    item_key = str(spec.get("key", ""))
                    condition_item = QTreeWidgetItem([str(spec.get("label", label))])
                    condition_item.setData(0, Qt.ItemDataRole.UserRole, item_key)
                    condition_item.setToolTip(0, str(spec.get("tooltip", "")))
                    type_item.addChild(condition_item)
                    self._boundary_navigation_specs_cache[item_key] = dict(spec)
                    if select_panel == item_key:
                        selected_item = condition_item
                    for node in self._ensure_list(spec.get("nodes", [])):
                        node_id = str(node)
                        node_key = f"{item_key}:node:{node_id}"
                        node_item = QTreeWidgetItem([f"節点 {node_id}"])
                        node_item.setData(0, Qt.ItemDataRole.UserRole, node_key)
                        condition_item.addChild(node_item)
                        self._boundary_navigation_specs_cache[node_key] = {
                            "key": node_key,
                            "kind": kind,
                            "source": spec.get("source", {}),
                            "nodes": [node_id],
                            "edges": [],
                            "remove_nodes": [node_id],
                        }
                        if select_panel == node_key:
                            selected_item = node_item
                    for edge in self._ensure_list(spec.get("edges", [])):
                        edge_nodes = [str(value) for value in self._ensure_list(edge)]
                        if len(edge_nodes) < 2:
                            continue
                        edge_key = f"{item_key}:edge:{edge_nodes[0]}-{edge_nodes[1]}"
                        edge_item = QTreeWidgetItem([f"辺 {edge_nodes[0]}-{edge_nodes[1]}"])
                        edge_item.setData(0, Qt.ItemDataRole.UserRole, edge_key)
                        condition_item.addChild(edge_item)
                        self._boundary_navigation_specs_cache[edge_key] = {
                            "key": edge_key,
                            "kind": kind,
                            "source": spec.get("source", {}),
                            "nodes": edge_nodes[:2],
                            "edges": [(edge_nodes[0], edge_nodes[1])],
                            "remove_edges": [(edge_nodes[0], edge_nodes[1])],
                        }
                        if select_panel == edge_key:
                            selected_item = edge_item
                    condition_item.setExpanded(True)
                type_item.setExpanded(bool(kind_specs))
            return selected_item

        def _activate_boundary_navigation_item(self, key: str) -> None:
            text = str(key or "")
            if not text.startswith("boundary_condition:"):
                self._active_boundary_condition_kind = ""
                return
            payload = self._boundary_navigation_specs_cache.get(text, {})
            kind = str(payload.get("kind", "") or "")
            if not kind and text.startswith("boundary_condition:type:"):
                kind = text.rsplit(":", 1)[-1]
            self._active_boundary_condition_kind = kind
            if kind in {"fixed", "roller_y", "roller_x", "pin", "prescribed"}:
                combo = getattr(self, "boundary_batch_kind", None)
                if combo is not None:
                    index = combo.findData(kind)
                    if index >= 0:
                        combo.setCurrentIndex(index)
                scope_combo = getattr(self, "boundary_batch_scope", None)
                if scope_combo is not None:
                    scope = "stage" if ":stage:" in text else "global" if ":global:" in text else ""
                    if scope:
                        scope_index = scope_combo.findData(scope)
                        if scope_index >= 0:
                            scope_combo.setCurrentIndex(scope_index)
            nodes = [str(node) for node in self._ensure_list(payload.get("nodes", [])) if str(node)]
            edges = list(payload.get("edges", [])) if isinstance(payload.get("edges", []), list) else []
            if nodes or edges:
                self._select_preview_payload({"nodes": nodes, "edges": edges})
                self.statusBar().showMessage(f"{self._boundary_condition_type_label(kind)} の対象節点 {len(nodes)}件を表示しました。")
            elif kind:
                self.statusBar().showMessage(f"{self._boundary_condition_type_label(kind)} を選択中です。範囲選択して右クリックから一括設定/解除できます。")

        @staticmethod
        def _load_condition_type_specs() -> list[tuple[str, str]]:
            return [
                ("node", "節点荷重"),
                ("edge", "面荷重"),
                ("body", "体積力/自重"),
            ]

        def _load_condition_kind_from_spec(self, spec: Mapping[str, Any]) -> str:
            ltype = str(spec.get("type", "")).lower().strip()
            if "edge" in spec or "edges" in spec or ltype in {"edge", "edges", "traction", "distributed"}:
                return "edge"
            if ltype in {"gravity", "self_weight", "body"} or bool(spec.get("self_weight", False)):
                return "body"
            return "node"

        def _load_condition_nodes_edges_elements(self, spec: Mapping[str, Any], *, mesh: Any = None) -> tuple[list[str], list[tuple[str, str]], list[str]]:
            nodes: list[str] = []
            edges: list[tuple[str, str]] = []
            elements: list[str] = []
            if mesh is None:
                return nodes, edges, elements
            kind = self._load_condition_kind_from_spec(spec)
            try:
                if kind == "edge":
                    edges = self._edge_targets_for_spec(mesh, spec)
                    nodes = sorted({nid for edge in edges for nid in edge}, key=self._natural_sort_key)
                elif kind == "body":
                    materials: set[str] = set()
                    if "material" in spec:
                        materials.add(str(spec["material"]))
                    if "materials" in spec:
                        raw = spec["materials"]
                        if isinstance(raw, str):
                            materials.update(part.strip() for part in raw.replace(";", ",").split(",") if part.strip())
                        else:
                            materials.update(str(value) for value in self._ensure_list(raw))
                    if materials:
                        elements = sorted(
                            [str(element.id) for element in mesh.elements if str(getattr(element, "material", "")) in materials],
                            key=self._natural_sort_key,
                        )
                    else:
                        elements = sorted(self._element_targets_for_spec(mesh, spec), key=self._natural_sort_key)
                else:
                    nodes = self._node_targets_for_spec(mesh, spec)
            except Exception:
                return [], [], []
            return nodes, edges, elements

        def _load_condition_navigation_specs(self) -> list[dict[str, Any]]:
            try:
                from geofem_app.fem2d import mesh_from_config

                mesh = mesh_from_config(self.cfg)
            except Exception:
                mesh = None
            specs: list[dict[str, Any]] = []

            def target_text(raw: Mapping[str, Any], nodes: list[str], edges: list[tuple[str, str]], elements: list[str]) -> str:
                kind = self._load_condition_kind_from_spec(raw)
                if kind == "edge":
                    text = self._edge_spec_text(raw)
                    return text or ", ".join(f"{a}-{b}" for a, b in edges[:4])
                if kind == "body":
                    text = self._body_spec_text(raw)
                    return text or ",".join(elements[:8])
                text = self._node_spec_text(raw)
                return text or ",".join(nodes[:8])

            def summary(raw: Mapping[str, Any], kind: str) -> str:
                if kind == "edge":
                    if str(raw.get("distribution", "")).lower() in {"linear", "varying", "gradient"} or any(key in raw for key in ("tx1", "ty1", "tx2", "ty2")):
                        return f"偏分布面荷重 tx={raw.get('tx1', raw.get('qx1', raw.get('tx', raw.get('qx', 0.0))))}->{raw.get('tx2', raw.get('qx2', raw.get('tx', raw.get('qx', 0.0))))}, ty={raw.get('ty1', raw.get('qy1', raw.get('ty', raw.get('qy', 0.0))))}->{raw.get('ty2', raw.get('qy2', raw.get('ty', raw.get('qy', 0.0))))}"
                    return f"面荷重 tx={raw.get('tx', raw.get('qx', 0.0))}, ty={raw.get('ty', raw.get('qy', 0.0))}"
                if kind == "body":
                    if "material" in raw:
                        return f"材料体積力 {raw.get('material')} bx={raw.get('bx', raw.get('gx', 0.0))}, by={raw.get('by', raw.get('gy', -1.0))}"
                    if "materials" in raw:
                        return f"材料体積力 {raw.get('materials')} bx={raw.get('bx', raw.get('gx', 0.0))}, by={raw.get('by', raw.get('gy', -1.0))}"
                    return f"自重/体積力 gx={raw.get('gx', 0.0)}, gy={raw.get('gy', -1.0)}"
                return f"節点荷重 fx={raw.get('fx', raw.get('px', 0.0))}, fy={raw.get('fy', raw.get('py', 0.0))}"

            def add_load(key: str, scope_label: str, index: int, raw: Mapping[str, Any], *, source: Mapping[str, Any]) -> None:
                kind = self._load_condition_kind_from_spec(raw)
                nodes, edges, elements = self._load_condition_nodes_edges_elements(raw, mesh=mesh)
                label = f"{scope_label} {index}: {summary(raw, kind)}"
                target = target_text(raw, nodes, edges, elements)
                if target:
                    label = f"{label} [{target}]"
                specs.append(
                    {
                        "key": key,
                        "kind": kind,
                        "label": label,
                        "nodes": nodes,
                        "edges": edges,
                        "elements": elements,
                        "target": target,
                        "source": dict(source),
                        "tooltip": yaml.safe_dump(dict(raw), allow_unicode=True, sort_keys=False).strip(),
                    }
                )

            for index, raw in enumerate(self._ensure_list(self.cfg.get("loads", [])), start=1):
                if isinstance(raw, Mapping):
                    add_load(f"load_condition:item:global:{index}", "全体", index, raw, source={"scope": "global_load", "index": index - 1})
            for stage_index, stage in enumerate(self._stages(), start=1):
                stage_name = str(stage.get("name", f"Stage-{stage_index}"))
                for index, raw in enumerate(self._ensure_list(stage.get("loads", [])), start=1):
                    if isinstance(raw, Mapping):
                        add_load(
                            f"load_condition:item:stage:{stage_index}:{index}",
                            stage_name,
                            index,
                            raw,
                            source={"scope": "stage_load", "stage_index": stage_index - 1, "index": index - 1},
                        )
            return specs

        def _add_load_condition_navigation_items(self, parent: QTreeWidgetItem, select_panel: str | None) -> QTreeWidgetItem | None:
            specs = self._load_condition_navigation_specs()
            specs_by_kind: dict[str, list[dict[str, Any]]] = {}
            for spec in specs:
                specs_by_kind.setdefault(str(spec.get("kind", "")), []).append(spec)
            self._load_navigation_specs_cache = {}
            selected_item: QTreeWidgetItem | None = None
            for kind, label in self._load_condition_type_specs():
                kind_specs = specs_by_kind.get(kind, [])
                nodes = sorted({str(node) for spec in kind_specs for node in self._ensure_list(spec.get("nodes", []))}, key=self._natural_sort_key)
                edges = [edge for spec in kind_specs for edge in self._ensure_list(spec.get("edges", []))]
                type_key = f"load_condition:type:{kind}"
                display = f"{label} ({len(kind_specs)})" if kind_specs else label
                type_item = QTreeWidgetItem([display])
                type_item.setData(0, Qt.ItemDataRole.UserRole, type_key)
                type_item.setToolTip(0, f"{label}: {len(kind_specs)}件 / {len(nodes)}節点")
                parent.addChild(type_item)
                self._load_navigation_specs_cache[type_key] = {
                    "key": type_key,
                    "kind": kind,
                    "label": label,
                    "nodes": nodes,
                    "edges": edges,
                    "specs": kind_specs,
                    "tree_item_kind": "type",
                }
                if select_panel == type_key:
                    selected_item = type_item
                for spec in kind_specs:
                    item_key = str(spec.get("key", ""))
                    condition_item = QTreeWidgetItem([str(spec.get("label", label))])
                    condition_item.setData(0, Qt.ItemDataRole.UserRole, item_key)
                    condition_item.setToolTip(0, str(spec.get("tooltip", "")))
                    type_item.addChild(condition_item)
                    item_payload = dict(spec)
                    item_payload["tree_item_kind"] = "condition"
                    self._load_navigation_specs_cache[item_key] = item_payload
                    if select_panel == item_key:
                        selected_item = condition_item
                    if kind == "node":
                        for node in self._ensure_list(spec.get("nodes", [])):
                            node_id = str(node)
                            node_key = f"{item_key}:node:{node_id}"
                            node_item = QTreeWidgetItem([f"節点 {node_id}"])
                            node_item.setData(0, Qt.ItemDataRole.UserRole, node_key)
                            condition_item.addChild(node_item)
                            self._load_navigation_specs_cache[node_key] = {
                                "key": node_key,
                                "kind": kind,
                                "source": spec.get("source", {}),
                                "nodes": [node_id],
                                "edges": [],
                                "remove_nodes": [node_id],
                                "tree_item_kind": "node",
                            }
                            if select_panel == node_key:
                                selected_item = node_item
                    if kind == "edge":
                        for edge in self._ensure_list(spec.get("edges", [])):
                            edge_nodes = [str(value) for value in self._ensure_list(edge)]
                            if len(edge_nodes) < 2:
                                continue
                            edge_key = f"{item_key}:edge:{edge_nodes[0]}-{edge_nodes[1]}"
                            edge_item = QTreeWidgetItem([f"辺 {edge_nodes[0]}-{edge_nodes[1]}"])
                            edge_item.setData(0, Qt.ItemDataRole.UserRole, edge_key)
                            condition_item.addChild(edge_item)
                            self._load_navigation_specs_cache[edge_key] = {
                                "key": edge_key,
                                "kind": kind,
                                "source": spec.get("source", {}),
                                "nodes": edge_nodes[:2],
                                "edges": [(edge_nodes[0], edge_nodes[1])],
                                "remove_edges": [(edge_nodes[0], edge_nodes[1])],
                                "tree_item_kind": "edge",
                            }
                            if select_panel == edge_key:
                                selected_item = edge_item
                    condition_item.setExpanded(True)
                type_item.setExpanded(bool(kind_specs))
            return selected_item

        def _activate_load_navigation_item(self, key: str) -> None:
            text = str(key or "")
            if not text.startswith("load_condition:"):
                self._active_load_condition_kind = ""
                return
            payload = self._load_navigation_specs_cache.get(text, {})
            kind = str(payload.get("kind", "") or "")
            if not kind and text.startswith("load_condition:type:"):
                kind = text.rsplit(":", 1)[-1]
            self._active_load_condition_kind = kind
            scope_combo = getattr(self, "load_batch_scope", None)
            if scope_combo is not None:
                scope = "stage" if ":stage:" in text else "global" if ":global:" in text else ""
                if scope:
                    index = scope_combo.findData(scope)
                    if index >= 0:
                        scope_combo.setCurrentIndex(index)
            payload_for_selection = {
                "nodes": [str(node) for node in self._ensure_list(payload.get("nodes", [])) if str(node)],
                "edges": list(payload.get("edges", [])) if isinstance(payload.get("edges", []), list) else [],
                "elements": [str(element) for element in self._ensure_list(payload.get("elements", [])) if str(element)],
            }
            if payload_for_selection["nodes"] or payload_for_selection["edges"] or payload_for_selection["elements"]:
                self._select_preview_payload(payload_for_selection)
                self.statusBar().showMessage(f"荷重条件の対象を表示しました。右クリックで同種荷重の追加/削除ができます。")
            elif kind:
                label = dict(self._load_condition_type_specs()).get(kind, kind)
                self.statusBar().showMessage(f"{label} を選択中です。モデルを範囲選択して右クリックから追加できます。")

        def _stage_navigation_specs(self) -> list[dict[str, Any]]:
            specs: list[dict[str, Any]] = []
            for index, stage in enumerate(self._stages(), start=1):
                if not isinstance(stage, Mapping):
                    continue
                name = str(stage.get("name", f"Stage-{index}") or f"Stage-{index}")
                stype = str(stage.get("type", "static") or "static")
                changes = 0
                changes += len(self._ensure_list(stage.get("construction_events", stage.get("construction", []))))
                changes += len(self._ensure_list(stage.get("element_properties", [])))
                changes += len(self._ensure_list(stage.get("boundary_conditions", stage.get("bc", []))))
                changes += len(self._ensure_list(stage.get("loads", [])))
                changes += self._stage_hydro_count(stage)
                target = self._element_spec_text(stage)
                label = f"{index} {name} / {stype}"
                if target:
                    label += f" [{target}]"
                label += f" ({changes})"
                specs.append(
                    {
                        "key": f"stage:item:{index}",
                        "index": index - 1,
                        "label": label,
                        "name": name,
                        "type": stype,
                        "target": target,
                        "changes": changes,
                        "tooltip": yaml.safe_dump(dict(stage), allow_unicode=True, sort_keys=False).strip(),
                    }
                )
            return specs

        def _add_stage_navigation_items(self, parent: QTreeWidgetItem, select_panel: str | None) -> QTreeWidgetItem | None:
            self._stage_navigation_specs_cache = {}
            selected_item: QTreeWidgetItem | None = None
            for spec in self._stage_navigation_specs():
                item_key = str(spec.get("key", ""))
                item = QTreeWidgetItem([str(spec.get("label", ""))])
                item.setData(0, Qt.ItemDataRole.UserRole, item_key)
                item.setToolTip(0, str(spec.get("tooltip", "")))
                parent.addChild(item)
                self._stage_navigation_specs_cache[item_key] = dict(spec)
                if select_panel == item_key:
                    selected_item = item
            return selected_item

        def _activate_stage_navigation_item(self, key: str) -> None:
            text = str(key or "")
            if not text.startswith("stage:"):
                return
            payload = self._stage_navigation_specs_cache.get(text, {})
            index = payload.get("index")
            if index is None:
                try:
                    index = int(text.rsplit(":", 1)[-1]) - 1
                except Exception:
                    index = None
            if isinstance(index, int):
                table = getattr(self, "stage_table", None)
                stages = self._stages()
                if table is not None and 0 <= index < len(stages):
                    table.selectRow(index)
                self.populate_stage_detail_tables()
                self.refresh_stage_cross_compare_table()
                self.refresh_stage_conflict_table()
                self.refresh_stage_guidance()
                self.statusBar().showMessage(f"ステージ {index + 1} を選択しました。下の変更表と右ペインの操作を使って編集できます。")

        def _material_group_navigation_key(self, material_name: str) -> str:
            material = str(material_name or "").strip()
            return f"material_assignment:material:{material}" if material else "material_assignment:missing"

        def _material_navigation_specs(self) -> list[dict[str, Any]]:
            specs: list[dict[str, Any]] = []
            geometry = self._mapping(self.cfg.get("geometry", {}))
            regions = geometry.get("regions", [])
            if isinstance(regions, list):
                for index, raw in enumerate(regions):
                    if not isinstance(raw, Mapping):
                        continue
                    if str(raw.get("source", "")).strip() == "mesh_rectangle_outline":
                        continue
                    region_id = str(raw.get("id", f"region_{index + 1}") or f"region_{index + 1}")
                    material = self._region_material_for_id(region_id, index=index, raw=raw)
                    specs.append(
                        {
                            "key": f"material_assignment:region:{region_id}",
                            "kind": "material_assignment",
                            "target_kind": "region",
                            "label": f"領域 {region_id}" + (f" / {material}" if material else " / 未割当"),
                            "material": material,
                            "geometry": [region_id],
                            "elements": [],
                        }
                    )
            mesh = self._mapping(self.cfg.get("mesh", {}))
            elements = mesh.get("elements", [])
            if isinstance(elements, list):
                for index, raw in enumerate(elements):
                    if not isinstance(raw, Mapping):
                        continue
                    element_id = str(raw.get("id", index + 1) or index + 1)
                    material = str(raw.get("material", "") or "").strip()
                    region = str(raw.get("region_id", raw.get("region", "")) or "").strip()
                    label = f"要素 {element_id}" + (f" / {material}" if material else " / 未割当")
                    if region:
                        label = f"{label} [{region}]"
                    specs.append(
                        {
                            "key": f"material_assignment:element:{element_id}",
                            "kind": "material_assignment",
                            "target_kind": "element",
                            "label": label,
                            "material": material,
                            "geometry": [],
                            "elements": [element_id],
                            "region": region,
                        }
                    )
            return specs

        def _add_material_navigation_items(self, parent: QTreeWidgetItem, select_panel: str | None) -> QTreeWidgetItem | None:
            specs = self._material_navigation_specs()
            grouped: dict[str, list[dict[str, Any]]] = {}
            for spec in specs:
                grouped.setdefault(str(spec.get("material", "") or ""), []).append(spec)
            material_order = list(self._material_names())
            for material in grouped:
                if material and material not in material_order:
                    material_order.append(material)
            if "" in grouped:
                material_order.append("")
            self._material_navigation_specs_cache = {}
            selected_item: QTreeWidgetItem | None = None
            for material in material_order:
                group_specs = grouped.get(material, [])
                group_key = self._material_group_navigation_key(material)
                geometry_ids = sorted(
                    {str(value) for spec in group_specs for value in self._ensure_list(spec.get("geometry", [])) if str(value)},
                    key=self._natural_sort_key,
                )
                element_ids = sorted(
                    {str(value) for spec in group_specs for value in self._ensure_list(spec.get("elements", [])) if str(value)},
                    key=self._natural_sort_key,
                )
                label = f"材料: {material} ({len(group_specs)})" if material else f"未割当 ({len(group_specs)})"
                group_item = QTreeWidgetItem([label])
                group_item.setData(0, Qt.ItemDataRole.UserRole, group_key)
                group_item.setToolTip(0, f"領域 {len(geometry_ids)} / 要素 {len(element_ids)}")
                parent.addChild(group_item)
                self._material_navigation_specs_cache[group_key] = {
                    "key": group_key,
                    "kind": "material",
                    "material": material,
                    "geometry": geometry_ids,
                    "elements": element_ids,
                    "items": group_specs,
                }
                if select_panel == group_key:
                    selected_item = group_item
                for spec in sorted(group_specs, key=lambda item: (str(item.get("target_kind", "")), self._natural_sort_key(str(item.get("label", ""))))):
                    item_key = str(spec.get("key", ""))
                    child = QTreeWidgetItem([str(spec.get("label", item_key))])
                    child.setData(0, Qt.ItemDataRole.UserRole, item_key)
                    child.setToolTip(0, f"material={material or '未割当'}")
                    group_item.addChild(child)
                    self._material_navigation_specs_cache[item_key] = dict(spec)
                    if select_panel == item_key:
                        selected_item = child
                group_item.setExpanded(bool(group_specs))
            return selected_item

        def _activate_material_navigation_item(self, key: str) -> None:
            text = str(key or "")
            if not text.startswith("material_assignment:"):
                return
            payload = self._material_navigation_specs_cache.get(text, {})
            if not payload:
                return
            selection_payload = {
                "geometry": [str(value) for value in self._ensure_list(payload.get("geometry", [])) if str(value)],
                "elements": [str(value) for value in self._ensure_list(payload.get("elements", [])) if str(value)],
            }
            if selection_payload["geometry"] or selection_payload["elements"]:
                self._select_preview_payload(selection_payload)
                material = str(payload.get("material", "") or "未割当")
                self.statusBar().showMessage(f"材料 {material} の対象を作図パレットで強調しました。")

        def _mesh_quality_navigation_specs(self) -> list[dict[str, Any]]:
            try:
                from geofem_app.fem2d import mesh_from_config

                mesh = mesh_from_config(self.cfg)
            except Exception:
                return []
            element_by_id = {str(element.id): element for element in getattr(mesh, "elements", [])}
            specs: list[dict[str, Any]] = []
            for violation in self._mesh_quality_violations(mesh):
                element_id = str(violation.get("element", violation.get("id", "")) or "")
                if not element_id:
                    continue
                element = element_by_id.get(element_id)
                nodes = [str(node) for node in getattr(element, "nodes", [])] if element is not None else []
                reason = str(violation.get("reason", violation.get("metric", "")) or "")
                specs.append(
                    {
                        "key": f"mesh_quality:element:{element_id}",
                        "kind": "mesh_quality_violation",
                        "label": f"要素 {element_id}" + (f" / {reason}" if reason else ""),
                        "elements": [element_id],
                        "nodes": nodes,
                        "reason": reason,
                        "violation": dict(violation),
                    }
                )
            return specs

        def _add_mesh_quality_navigation_items(self, parent: QTreeWidgetItem, select_panel: str | None) -> QTreeWidgetItem | None:
            specs = self._mesh_quality_navigation_specs()
            self._mesh_quality_navigation_specs_cache = {}
            selected_item: QTreeWidgetItem | None = None
            group_key = "mesh_quality:violations"
            element_ids = sorted(
                {str(value) for spec in specs for value in self._ensure_list(spec.get("elements", [])) if str(value)},
                key=self._natural_sort_key,
            )
            node_ids = sorted(
                {str(value) for spec in specs for value in self._ensure_list(spec.get("nodes", [])) if str(value)},
                key=self._natural_sort_key,
            )
            group_item = QTreeWidgetItem([f"不良メッシュ ({len(specs)})"])
            group_item.setData(0, Qt.ItemDataRole.UserRole, group_key)
            group_item.setToolTip(0, f"品質違反 要素 {len(element_ids)} / 節点 {len(node_ids)}")
            parent.addChild(group_item)
            self._mesh_quality_navigation_specs_cache[group_key] = {
                "key": group_key,
                "kind": "mesh_quality",
                "elements": element_ids,
                "nodes": node_ids,
                "items": specs,
            }
            if select_panel == group_key:
                selected_item = group_item
            for spec in specs:
                item_key = str(spec.get("key", ""))
                child = QTreeWidgetItem([str(spec.get("label", item_key))])
                child.setData(0, Qt.ItemDataRole.UserRole, item_key)
                child.setToolTip(0, str(spec.get("reason", "")))
                group_item.addChild(child)
                self._mesh_quality_navigation_specs_cache[item_key] = dict(spec)
                if select_panel == item_key:
                    selected_item = child
            group_item.setExpanded(bool(specs))
            return selected_item

        def _should_populate_mesh_quality_navigation(self, select_panel: str | None) -> bool:
            target = str(select_panel or "")
            if target.startswith("mesh_quality:"):
                return True
            if self._panel_key_from_tree_key(target) == "mesh":
                return True
            current = self._panel_key_from_tree_key(str(getattr(self, "current_panel_key", "") or ""))
            return current == "mesh"

        def _should_populate_tree_branch(self, panel_key: str, select_panel: str | None, prefixes: tuple[str, ...]) -> bool:
            target = str(select_panel or "")
            if target.startswith(prefixes):
                return True
            if self._panel_key_from_tree_key(target) == panel_key:
                return True
            current = self._panel_key_from_tree_key(str(getattr(self, "current_panel_key", "") or ""))
            return current == panel_key

        def _activate_mesh_quality_navigation_item(self, key: str) -> None:
            text = str(key or "")
            if not text.startswith("mesh_quality:"):
                return
            payload = self._mesh_quality_navigation_specs_cache.get(text, {})
            if not payload:
                return
            selection_payload = {
                "elements": [str(value) for value in self._ensure_list(payload.get("elements", [])) if str(value)],
                "nodes": [str(value) for value in self._ensure_list(payload.get("nodes", [])) if str(value)],
            }
            if selection_payload["elements"] or selection_payload["nodes"]:
                self._select_preview_payload(selection_payload)
                self.statusBar().showMessage(f"不良メッシュ {len(selection_payload['elements'])} 要素を作図パレットで強調しました。")

        def _activate_result_tree_selection(self, kind: str) -> None:
            if not kind:
                return
            self.current_result_kind = kind
            if self._latest_stage_dir() is None:
                summary = self._current_summary_path()
                if summary is not None:
                    self._load_result_summary(summary)
            if self._latest_stage_dir() is None:
                self.results_summary.setText(
                    "No analysis results yet. Run analysis, then select a result figure from the left tree."
                    if self.gui_locale == "en"
                    else "解析結果がまだありません。解析実行後に左ツリーから結果図を選択できます。"
                )
                self.tabs.setCurrentWidget(self.result_view)
                self._sync_aux_result_controls()
                return
            self.load_result_table_async(kind)
            self._sync_aux_result_controls()

