        def _apply_context_visibility(self, panel_key: str) -> None:
            mode = self._current_gui_operation_mode()
            detail_mode = mode in {"detail", "maintenance"}
            inline_detail = panel_key in getattr(self, "inline_detail_panel_keys", set())
            compact = self._is_compact_gui()
            geometry_panels = {"workflow", "geometry", "mesh", "materials", "boundary_conditions", "loads", "stages"}
            form_only_panels = {"analysis"}
            selection_panels = {"geometry", "mesh", "materials", "boundary_conditions", "loads", "stages"}
            command_tools = getattr(self, "left_command_tools_widget", None)
            if command_tools is not None:
                command_tools.setVisible(detail_mode)
            self.primary_action_group.setVisible(False)
            self.view_toolbar_model_widget.setVisible((panel_key not in geometry_panels or detail_mode) and panel_key not in form_only_panels and not compact)
            show_advanced_selection_tools = panel_key in selection_panels and detail_mode and not inline_detail and not compact
            self.view_toolbar_selection_widget.setVisible(show_advanced_selection_tools)
            self.view_toolbar_display_widget.setVisible((panel_key not in geometry_panels or detail_mode) and panel_key not in form_only_panels and not compact)
            if getattr(self, "model_cad_palette_widget", None) is not None:
                self.model_cad_palette_widget.setVisible(panel_key == "geometry")
            if getattr(self, "model_cad_more_button", None) is not None:
                self.model_cad_more_button.setVisible(panel_key == "geometry")
            if getattr(self, "model_cad_advanced_widget", None) is not None:
                show_advanced_cad = panel_key == "geometry" and (detail_mode or self.model_cad_more_button.isChecked())
                self.model_cad_advanced_widget.setVisible(show_advanced_cad)
            if getattr(self, "model_cad_edit_widget", None) is not None:
                self.model_cad_edit_widget.setVisible(False)
            if getattr(self, "model_mesh_palette_widget", None) is not None:
                self.model_mesh_palette_widget.setVisible(panel_key == "mesh")
            if getattr(self, "model_mesh_edit_widget", None) is not None:
                self.model_mesh_edit_widget.setVisible(False)
            self._refresh_mesh_tool_button_state()
            for widget in getattr(self, "view_toolbar_display_compact_widgets", []):
                widget.setVisible(not compact)
            self.selection_builder_toolbar_widget.setVisible(show_advanced_selection_tools)
            self.detail_action_group.setVisible(detail_mode and panel_key not in form_only_panels and not compact)
            self.project_action_group.setVisible((detail_mode or mode == "maintenance") and panel_key not in form_only_panels and not compact)
            self.confirm_action_group.setVisible(False)
            self._apply_bottom_panel_context(panel_key, detail_mode=detail_mode)
            self._apply_workspace_tab_visibility(panel_key, detail_mode=detail_mode)
            stage_tabs = getattr(self, "stage_workspace_tabs", None)
            internal_tab = getattr(self, "stage_internal_data_tab", None)
            if stage_tabs is not None and internal_tab is not None:
                internal_index = stage_tabs.indexOf(internal_tab)
                if internal_index >= 0:
                    stage_tabs.setTabVisible(internal_index, detail_mode)
                    if not detail_mode and stage_tabs.currentIndex() == internal_index:
                        stage_tabs.setCurrentIndex(0)
            self._apply_stage_standard_mode_visibility(panel_key, detail_mode=detail_mode)
            self._set_inline_detail_panel(panel_key)
            self._apply_fixed_workspace_target(panel_key)
            self.right_panel_stack.setCurrentWidget(self.auxiliary_panel)
            self._apply_workspace_split_context(panel_key, detail_mode=detail_mode, compact=compact, geometry_panels=geometry_panels)
            self._update_auxiliary_panel(panel_key)
            self._update_workspace_heading(panel_key)
            self._enforce_workspace_focus_visibility()

        def _apply_workspace_split_context(self, panel_key: str, *, detail_mode: bool, compact: bool, geometry_panels: set[str]) -> None:
            splitter = getattr(self, "workspace_splitter", None)
            if splitter is None or splitter.count() < 3:
                return
            previous_panel = str(getattr(self, "_workspace_splitter_panel", "") or "")
            force_restore = bool(getattr(self, "_workspace_splitter_force_restore", False))
            if previous_panel and previous_panel != panel_key:
                self._remember_workspace_splitter_state()
            if previous_panel == panel_key and not force_restore:
                sizes = [max(0, int(value)) for value in splitter.sizes()]
                profile = self.desktop_layout_profile
                minimum_left = max(profile.tree_min_width, 280 if profile.large_desktop else 260)
                left_panel = getattr(self, "left_navigation_panel", None)
                if len(sizes) == 3 and left_panel is not None and not left_panel.isHidden() and sizes[0] < minimum_left:
                    delta = minimum_left - sizes[0]
                    adjusted = [minimum_left, max(320, sizes[1] - delta), sizes[2]]
                    adjusted[1] += sum(sizes) - sum(adjusted)
                    self._workspace_splitter_applying = True
                    try:
                        splitter.setSizes(adjusted)
                    finally:
                        self._workspace_splitter_applying = False
                return
            self._workspace_splitter_force_restore = False
            current_sizes = [max(0, int(value)) for value in splitter.sizes()]
            total = sum(current_sizes) or int(getattr(self.desktop_layout_profile, "window_width", self.width()))
            if total <= 0:
                return
            saved = getattr(self, "_workspace_split_sizes_by_panel", {}).get(panel_key)
            matched_center_panels = {"analysis", "workflow", "geometry", "mesh", "materials", "boundary_conditions", "loads", "stages", "model_check", "solver"}
            if not saved and previous_panel in matched_center_panels and panel_key in matched_center_panels:
                saved = current_sizes
            if saved and len(saved) == 3 and sum(saved) > 0:
                scale = total / float(sum(saved))
                restored = [max(0, int(round(value * scale))) for value in saved]
                restored[1] += total - sum(restored)
                self._workspace_splitter_applying = True
                try:
                    splitter.setSizes(restored)
                finally:
                    self._workspace_splitter_applying = False
                self._workspace_splitter_panel = panel_key
                return
            profile = self.desktop_layout_profile
            stage_width_matched_panels = {"analysis", "model_check", "solver"}
            use_model_workspace_width = panel_key in stage_width_matched_panels or panel_key in geometry_panels
            use_canvas_priority = use_model_workspace_width and (compact or not detail_mode)
            if use_canvas_priority:
                left = max(profile.tree_min_width, 280 if profile.large_desktop else 260)
                right = profile.panel_min_width
            else:
                left, _center, right = profile.horizontal_split_sizes
            left = min(left, max(profile.tree_min_width, int(total * 0.24)))
            right = min(right, max(profile.panel_min_width, int(total * 0.28)))
            center = max(profile.center_min_width, total - left - right)
            overflow = left + center + right - total
            if overflow > 0:
                center = max(320, center - overflow)
            self._workspace_splitter_applying = True
            try:
                splitter.setSizes([left, center, right])
            finally:
                self._workspace_splitter_applying = False
            self._workspace_splitter_panel = panel_key

        def _remember_workspace_splitter_state(self, _position: int = 0, _index: int = 0) -> None:
            if bool(getattr(self, "_workspace_splitter_applying", False)):
                return
            splitter = getattr(self, "workspace_splitter", None)
            panel = str(getattr(self, "_workspace_splitter_panel", "") or getattr(self, "current_panel_key", "") or "")
            left = getattr(self, "left_navigation_panel", None)
            right = getattr(self, "right_panel_stack", None)
            if splitter is None or not panel or (left is not None and left.isHidden()) or (right is not None and right.isHidden()):
                return
            sizes = [max(0, int(value)) for value in splitter.sizes()]
            if len(sizes) == 3 and all(value > 0 for value in sizes):
                self._workspace_split_sizes_by_panel[panel] = sizes

        def _selected_geometry_shape_ids(self) -> list[str]:
            shape_ids: list[str] = []
            for item in self.scene.selectedItems():
                data = item.data(0)
                if not isinstance(data, Mapping):
                    continue
                kind = str(data.get("kind", ""))
                if kind in {"selection_highlight", "geometry_endpoint"}:
                    continue
                if kind == "geometry_region" and data.get("id") not in (None, ""):
                    shape_ids.append(str(data.get("id")))
                elif kind.startswith("geometry_") and data.get("id") not in (None, ""):
                    shape_ids.append(str(data.get("id")))
            return list(dict.fromkeys(shape_ids))

        def _selection_context_text(self) -> str:
            try:
                entities = self._selected_preview_entities()
            except Exception:
                entities = {"nodes": set(), "edges": [], "elements": set()}
            shape_ids = self._selected_geometry_shape_ids()
            if shape_ids:
                shown = ",".join(shape_ids[:3])
                shape_text = f"形状{shown}" + (f" +{len(shape_ids) - 3}" if len(shape_ids) > 3 else "")
            else:
                shape_text = "形状0"
            if self.gui_locale == "en":
                return (
                    f"Selected: Nodes {len(entities['nodes'])} / Edges {len(entities['edges'])} / "
                    f"Elements {len(entities['elements'])} / Shapes {','.join(shape_ids[:3]) if shape_ids else 0}"
                )
            return f"選択中: 節点{len(entities['nodes'])} / 辺{len(entities['edges'])} / 要素{len(entities['elements'])} / {shape_text}"

        def _right_click_context_text(self, panel_key: str) -> str:
            panel = self._panel_key_from_tree_key(panel_key)
            if self.draw_mode in self._cad_drawing_modes():
                return (
                    "Right click: disabled - finish or cancel the current drawing first."
                    if self.gui_locale == "en"
                    else "右クリック: 不可 - 作図中です。先に確定またはキャンセルしてください。"
                )
            palette_panels = {"geometry", "mesh", "materials", "boundary_conditions", "loads", "stages"}
            if panel not in palette_panels:
                return (
                    "Right click: disabled - this task has no drawing-palette menu."
                    if self.gui_locale == "en"
                    else "右クリック: 不可 - この作業では作図パレットの対象操作がありません。"
                )
            actions = [spec for spec in self._context_menu_action_specs("view") if spec[0] != "-"]
            if not actions:
                return (
                    "Right click: disabled - no menu items are available for this task."
                    if self.gui_locale == "en"
                    else "右クリック: 不可 - この作業に有効なメニュー項目がありません。"
                )
            try:
                entities = self._selected_preview_entities()
            except Exception:
                entities = {"nodes": set(), "edges": [], "elements": set()}
            shape_ids = self._selected_geometry_shape_ids()
            has_selection = bool(entities["nodes"] or entities["edges"] or entities["elements"] or shape_ids)
            if panel == "materials":
                if has_selection:
                    return (
                        "Right click: available - assign or clear material on the selected shape/element."
                        if self.gui_locale == "en"
                        else "右クリック: 可 - 選択した形状/要素へ材料の割当・解除ができます。"
                    )
                return (
                    "Right click: available on a shape/element - material assignment needs a target selection."
                    if self.gui_locale == "en"
                    else "右クリック: 可 - 形状/要素上で右クリックすると対象を選択します。材料割当には対象選択が必要です。"
                )
            if panel == "boundary_conditions":
                if has_selection:
                    return (
                        "Right click: available - batch set or clear boundary conditions on the selection."
                        if self.gui_locale == "en"
                        else "右クリック: 可 - 選択範囲へ境界条件を一括設定・解除できます。"
                    )
                return (
                    "Right click: available on nodes/edges/elements - blank space has no target operation."
                    if self.gui_locale == "en"
                    else "右クリック: 可 - 節点/辺/要素上で右クリックすると対象を選択します。空白では対象操作はありません。"
                )
            if panel == "loads":
                if has_selection:
                    return (
                        "Right click: available - add loads to selected nodes, edges, or elements."
                        if self.gui_locale == "en"
                        else "右クリック: 可 - 選択した節点/辺/要素へ荷重を設定できます。"
                    )
                return (
                    "Right click: available on nodes/edges/elements - load setup needs a target selection."
                    if self.gui_locale == "en"
                    else "右クリック: 可 - 節点/辺/要素上で右クリックすると対象を選択します。荷重設定には対象選択が必要です。"
                )
            if panel == "stages":
                if has_selection:
                    return (
                        "Right click: available - deactivate or reactivate the selection, or add boundary and load changes."
                        if self.gui_locale == "en"
                        else "右クリック: 可 - 選択対象の無効化・再有効化、境界、荷重を現在ステージへ追加できます。"
                    )
                return (
                    "Right click: available on nodes, edges, or elements - stage changes need a target selection."
                    if self.gui_locale == "en"
                    else "右クリック: 可 - 節点/辺/要素上で右クリックすると対象を選択します。ステージ変更には対象選択が必要です。"
                )
            if panel == "mesh":
                if has_selection:
                    return (
                        "Right click: available - edit mesh conditions, rebuild, or handle quality issues."
                        if self.gui_locale == "en"
                        else "右クリック: 可 - 選択対象のメッシュ条件・再構成・品質修復を操作できます。"
                    )
                return (
                    "Right click: available on mesh items - select a region, element, or quality issue first."
                    if self.gui_locale == "en"
                    else "右クリック: 可 - メッシュ対象上で右クリックすると選択します。不良メッシュ修復は違反選択が必要です。"
                )
            if has_selection:
                return (
                    "Right click: available - edit, delete, or set grid conditions for the selection."
                    if self.gui_locale == "en"
                    else "右クリック: 可 - 選択した形状の編集・削除・格子条件設定ができます。"
                )
            return (
                "Right click: available on geometry - blank space only shows general view actions."
                if self.gui_locale == "en"
                else "右クリック: 可 - 形状上で右クリックすると対象を選択します。空白では一般表示操作のみです。"
            )

        def _refresh_auxiliary_selection_context(self, panel_key: str | None = None) -> None:
            if getattr(self, "aux_current_task_label", None) is None:
                return
            panel = self._panel_key_from_tree_key(str(panel_key or getattr(self, "current_panel_key", "workflow")))
            title = self._auxiliary_panel_texts().get(panel, (panel, ""))[0]
            if getattr(self, "aux_selection_context_group", None) is not None:
                self.aux_selection_context_group.setTitle("Current" if self.gui_locale == "en" else "現在")
            self.aux_current_task_label.setText(
                f"Current Task: {title}" if self.gui_locale == "en" else f"現在の作業: {title}"
            )
            self.aux_current_selection_label.setText(self._selection_context_text())
            self.aux_context_menu_status_label.setText(self._right_click_context_text(panel))
            self._refresh_edit_history_display(panel)
            self._refresh_operation_button_enabled_states(panel)

        def _update_auxiliary_panel(self, panel_key: str) -> None:
            panel_key = self._panel_key_from_tree_key(panel_key)
            labels = self._auxiliary_panel_texts()
            title, summary = labels.get(
                panel_key,
                ("Task", "Only the required actions are shown here.")
                if self.gui_locale == "en"
                else ("作業", "必要な操作だけをここに表示します。"),
            )
            self.aux_panel_title.setText(title)
            detail_mode = self._current_gui_operation_mode() in {"detail", "maintenance"}
            mode_summary = self.operation_mode_descriptions.get(self._current_gui_operation_mode(), "") if detail_mode else ""
            self.aux_panel_summary.setText(f"{mode_summary}\n{summary}" if mode_summary else summary)
            stats = self._auxiliary_status_lines(panel_key)
            self.aux_panel_stats.setText("\n".join(stats[:3]))
            self.aux_panel_stats.setVisible(bool(stats))
            self._refresh_auxiliary_selection_context(panel_key)
            for label in (
                self.aux_current_task_label,
                self.aux_current_selection_label,
                self.aux_context_menu_status_label,
                getattr(self, "aux_edit_history_label", None),
                self.aux_panel_title,
                self.aux_panel_summary,
                self.aux_panel_stats,
            ):
                if label is None:
                    continue
                label.setMinimumHeight(min(72, max(32, label.sizeHint().height())) if detail_mode else 0)
            geometry_panels = {"workflow", "geometry", "mesh", "materials", "boundary_conditions", "loads", "stages"}
            inline_detail = panel_key in getattr(self, "inline_detail_panel_keys", set())
            selection_panels = {"geometry", "mesh", "materials", "boundary_conditions", "loads", "stages"}
            selection_context = getattr(self, "aux_selection_context_group", None)
            if selection_context is not None:
                selection_context.setVisible(detail_mode or panel_key in selection_panels)
            if getattr(self, "aux_current_task_label", None) is not None:
                self.aux_current_task_label.setVisible(detail_mode)
            if getattr(self, "aux_edit_history_label", None) is not None:
                self.aux_edit_history_label.setVisible(detail_mode)
            if getattr(self, "aux_current_selection_label", None) is not None:
                self.aux_current_selection_label.setVisible(panel_key in selection_panels)
            if getattr(self, "aux_context_menu_status_label", None) is not None:
                self.aux_context_menu_status_label.setVisible(panel_key in selection_panels)
            if getattr(self, "aux_return_from_detail_button", None) is not None:
                return_panel = str(getattr(self, "_detail_return_panel", "") or panel_key)
                return_to_geometry = return_panel in geometry_panels
                if self.gui_locale == "en":
                    return_text = "Back to Drawing Palette" if return_to_geometry else "Back to Standard View"
                else:
                    return_text = "作図パレットへ戻る" if return_to_geometry else "標準表示へ戻る"
                self.aux_return_from_detail_button.setText(return_text)
                self.aux_return_from_detail_button.setVisible(False)
                self._prepare_panel_action_button(self.aux_return_from_detail_button)
            if getattr(self, "aux_run_button", None) is not None:
                self.aux_run_button.setVisible(False)
            material_actions = getattr(self, "aux_material_action_group", None)
            if material_actions is not None:
                material_actions.setVisible(panel_key == "materials")
            boundary_actions = getattr(self, "aux_boundary_action_group", None)
            if boundary_actions is not None:
                boundary_actions.setVisible(panel_key == "boundary_conditions")
            load_actions = getattr(self, "aux_load_action_group", None)
            if load_actions is not None:
                load_actions.setVisible(panel_key == "loads")
            stage_actions = getattr(self, "aux_stage_action_group", None)
            if stage_actions is not None:
                stage_actions.setVisible(panel_key == "stages" and detail_mode)
            stage_inspector = getattr(self, "aux_stage_inspector_group", None)
            if stage_inspector is not None:
                selected_stage = self._selected_stage_row()
                has_selected_stage = selected_stage is not None and 0 <= selected_stage < len(self._stages())
                stage_inspector.setVisible(panel_key == "stages" and (detail_mode or has_selected_stage))
                if panel_key == "stages":
                    self._refresh_stage_inspector_visibility()
            confirm_actions = getattr(self, "aux_confirm_action_group", None)
            if confirm_actions is not None:
                confirm_actions.setVisible(panel_key == "model_check")
            solver_actions = getattr(self, "aux_solver_action_group", None)
            if solver_actions is not None:
                solver_actions.setVisible(panel_key == "solver")
            geometry_settings = getattr(self, "aux_geometry_settings_group", None)
            if geometry_settings is not None:
                geometry_settings.setVisible(panel_key == "geometry")
            mesh_settings = getattr(self, "aux_mesh_settings_group", None)
            if mesh_settings is not None:
                mesh_settings.setVisible(panel_key == "mesh")
            result_controls = getattr(self, "aux_result_control_group", None)
            if result_controls is not None:
                result_available = self._current_summary_path() is not None
                result_controls.setVisible(panel_key == "results" and result_available)
                if panel_key == "results" and result_available:
                    self._sync_aux_result_controls()
            if getattr(self, "aux_action_group", None) is not None:
                self.aux_action_group.setVisible(False)
                self.aux_action_group.setMaximumHeight(0)

        def _sync_aux_result_controls(self) -> None:
            if not hasattr(self, "aux_result_stage_combo") or self._syncing_aux_result_controls:
                return
            self._syncing_aux_result_controls = True
            try:
                if not self.result_stage_dirs:
                    summary = self._current_summary_path()
                    if summary is not None:
                        self.result_stage_dirs = self._stage_dirs_from_summary(summary)
                        self.result_stage_dir = self.result_stage_dirs[-1] if self.result_stage_dirs else self.result_stage_dir
                stage_combo = self.aux_result_stage_combo
                stage_combo.blockSignals(True)
                stage_combo.clear()
                for index, stage_dir in enumerate(self.result_stage_dirs):
                    stage_combo.addItem(f"{index + 1}: {self._result_stage_display_name(stage_dir, index)}", str(stage_dir))
                current_index = 0
                if self.result_stage_dir is not None:
                    for index, stage_dir in enumerate(self.result_stage_dirs):
                        if stage_dir.resolve() == self.result_stage_dir.resolve():
                            current_index = index
                            break
                if stage_combo.count() > 0:
                    stage_combo.setCurrentIndex(current_index)
                stage_combo.blockSignals(False)
                slider = self.aux_result_stage_slider
                slider.blockSignals(True)
                slider.setMaximum(max(0, len(self.result_stage_dirs) - 1))
                slider.setValue(current_index if self.result_stage_dirs else 0)
                slider.setEnabled(len(self.result_stage_dirs) > 1)
                slider.blockSignals(False)
                self.aux_result_time_label.setText(self._aux_result_time_text())
                deformation_value = self._current_deformation_scale_value()
                deformation_text = f"{deformation_value:g}"
                deformation_slider = getattr(self, "aux_deformation_scale_slider", None)
                if deformation_slider is not None:
                    deformation_slider.blockSignals(True)
                    deformation_slider.setValue(max(0, min(200, int(round(deformation_value)))))
                    deformation_slider.blockSignals(False)
                deformation_edit = getattr(self, "aux_deformation_scale_edit", None)
                if deformation_edit is not None:
                    deformation_edit.blockSignals(True)
                    deformation_edit.setText(deformation_text)
                    deformation_edit.blockSignals(False)
                self._refresh_deformation_scale_hint()
                self._sync_combo_items_from_widget(self.aux_result_component_combo, getattr(self, "result_component", None), self.post_component)
                self._sync_combo_items_from_widget(self.aux_result_colormap_combo, getattr(self, "result_colormap", None), self.result_colormap_name)
                enabled = bool(self.result_stage_dirs)
                for widget in (self.aux_result_stage_combo, self.aux_result_component_combo, self.aux_result_colormap_combo, getattr(self, "aux_deformation_scale_slider", None), getattr(self, "aux_deformation_scale_edit", None), getattr(self, "aux_deformation_scale_hint", None)):
                    if widget is None:
                        continue
                    widget.setEnabled(enabled)
            finally:
                self._syncing_aux_result_controls = False

        def _current_deformation_scale_value(self) -> float:
            widget = getattr(self, "deformation_scale", None)
            text = widget.text() if widget is not None else getattr(self, "_deformation_scale_text", "1.0")
            try:
                return max(0.0, float(str(text).strip() or "1.0"))
            except ValueError:
                return 1.0

        def _apply_deformation_scale_value(self, value: float) -> None:
            value = max(0.0, float(value))
            text = f"{value:g}"
            self._deformation_scale_text = text
            widget = getattr(self, "deformation_scale", None)
            if widget is not None:
                widget.blockSignals(True)
                widget.setText(text)
                widget.blockSignals(False)
            edit = getattr(self, "aux_deformation_scale_edit", None)
            if edit is not None:
                edit.blockSignals(True)
                edit.setText(text)
                edit.blockSignals(False)
            slider = getattr(self, "aux_deformation_scale_slider", None)
            if slider is not None:
                slider.blockSignals(True)
                slider.setValue(max(0, min(200, int(round(value)))))
                slider.blockSignals(False)
            self.request_preview_update(reset_view=False, reason="deformation scale")
            self._refresh_deformation_scale_hint()

        def _refresh_deformation_scale_hint(self) -> None:
            label = getattr(self, "aux_deformation_scale_hint", None)
            if label is not None:
                label.setText(self._deformation_scale_hint_text())

        def _deformation_scale_hint_text(self) -> str:
            displacements = getattr(self, "result_displacements", {}) or {}
            if not displacements:
                return "Displacement result: not loaded." if self.gui_locale == "en" else "変位結果: 未読込"
            max_u = max((math.hypot(float(ux), float(uy)) for ux, uy in displacements.values()), default=0.0)
            factor = self._current_deformation_scale_value()
            display_u = max_u * factor
            extent = self._current_mesh_diagonal_length()
            max_text = self._format_deformation_metric(max_u)
            display_text = self._format_deformation_metric(display_u)
            if extent > 0.0:
                ratio = display_u / extent * 100.0
                extent_text = self._format_deformation_metric(extent)
                ratio_text = self._format_deformation_metric(ratio)
                if self.gui_locale == "en":
                    return f"Max U: {max_text} / shown: {display_text} ({ratio_text}% of model diagonal {extent_text})"
                return f"実変位最大: {max_text} / 表示変位: {display_text}（モデル対角 {extent_text} の {ratio_text}%）"
            if self.gui_locale == "en":
                return f"Max U: {max_text} / shown: {display_text}"
            return f"実変位最大: {max_text} / 表示変位: {display_text}"

        def _format_deformation_metric(self, value: float) -> str:
            value = float(value)
            abs_value = abs(value)
            if abs_value > 0.0 and (abs_value < 1.0e-3 or abs_value >= 1.0e4):
                return f"{value:.3e}"
            return f"{value:.4g}"

        def _current_mesh_diagonal_length(self) -> float:
            try:
                mesh = self._preview_mesh_from_config()
            except Exception:
                return 0.0
            if not getattr(mesh, "node_ids", None):
                return 0.0
            xs = [float(mesh.coords[index, 0]) for index in range(len(mesh.node_ids))]
            ys = [float(mesh.coords[index, 1]) for index in range(len(mesh.node_ids))]
            if not xs or not ys:
                return 0.0
            return math.hypot(max(xs) - min(xs), max(ys) - min(ys))

        def _aux_deformation_scale_slider_changed(self, value: int) -> None:
            if self._syncing_aux_result_controls:
                return
            self._apply_deformation_scale_value(float(value))

        def _aux_deformation_scale_edited(self) -> None:
            if self._syncing_aux_result_controls:
                return
            text = getattr(self, "aux_deformation_scale_edit", None)
            raw = text.text() if text is not None else ""
            try:
                value = float(str(raw).strip() or "1.0")
            except ValueError:
                value = self._current_deformation_scale_value()
            self._apply_deformation_scale_value(value)

        def _sync_combo_items_from_widget(self, target: QComboBox, source: QComboBox | None, current: str) -> None:
            target.blockSignals(True)
            target.clear()
            items: list[tuple[str, Any]] = []
            if source is not None:
                items = [
                    (
                        source.itemText(index),
                        source.itemData(index) if source.itemData(index) not in (None, "") else source.itemText(index),
                    )
                    for index in range(source.count())
                ]
            if not items and target is getattr(self, "aux_result_component_combo", None):
                items = [(value, value) for value in ["q", "p", "sigma_x", "sigma_y", "tau_xy", "u_norm", "ux", "uy", "pore_pressure", "FL"]]
            if not items and target is getattr(self, "aux_result_colormap_combo", None):
                items = [(value, value) for value in ["Geo blue-red", "Safety FL", "Viridis", "Terrain", "Gray"]]
            for label, value in items:
                target.addItem(str(label), value)
            if current:
                index = target.findData(current)
                if index < 0:
                    index = target.findText(current)
                if index < 0:
                    target.addItem(current, current)
                    index = target.findData(current)
                target.setCurrentIndex(index)
            target.blockSignals(False)

        def _aux_result_time_text(self) -> str:
            summary = self._current_summary_data()
            stage = self._current_summary_stage(summary) if isinstance(summary, Mapping) else None
            stage_name = ""
            time_text = ""
            if isinstance(stage, Mapping):
                raw_stage_name = str(stage.get("name", stage.get("stage", "")) or "")
                stage_name = raw_stage_name if self._show_internal_representation() else friendly_stage_name(raw_stage_name, locale=self.gui_locale)
                for key in ("time", "end_time", "stage_time"):
                    if stage.get(key) is not None:
                        time_text = str(stage.get(key))
                        break
            if not stage_name and self.result_stage_dir is not None:
                stage_name = self._result_stage_display_name(self.result_stage_dir)
            parts = [part for part in (stage_name, f"t={time_text}" if time_text else "") if part]
            prefix = "Stage/Time: " if self.gui_locale == "en" else "ステージ/時刻: "
            return prefix + (" / ".join(parts) if parts else "-")

        def _aux_result_stage_changed(self, index: int) -> None:
            if self._syncing_aux_result_controls or index < 0:
                return
            raw = self.aux_result_stage_combo.itemData(index)
            if raw:
                self.result_stage_dir = Path(str(raw))
            selector = getattr(self, "result_stage_selector", None)
            if selector is not None and index < selector.count():
                selector.blockSignals(True)
                selector.setCurrentIndex(index)
                selector.blockSignals(False)
            self.clear_post_state()
            kind = self.current_result_kind
            if not kind and self.result_stage_dir is not None:
                kind = self._default_result_visual_kind(self.result_stage_dir)
            if kind:
                self._activate_result_tree_selection(kind)
            self._sync_aux_result_controls()

        def _aux_result_stage_slider_changed(self, value: int) -> None:
            if self._syncing_aux_result_controls:
                return
            combo = getattr(self, "aux_result_stage_combo", None)
            if combo is not None and 0 <= value < combo.count():
                combo.setCurrentIndex(value)

        def _aux_result_component_changed(self, text: str) -> None:
            if self._syncing_aux_result_controls:
                return
            value = self._combo_value(self.aux_result_component_combo, str(text or "")).strip()
            if not value:
                return
            for combo in (getattr(self, "result_component", None), getattr(self, "result_table_component", None)):
                if combo is None:
                    continue
                combo.blockSignals(True)
                if combo.findText(value) < 0:
                    combo.addItem(value)
                combo.setCurrentText(value)
                combo.blockSignals(False)
            self.post_component = value
            self.reload_selected_result_component_async()

        def _aux_result_colormap_changed(self, text: str) -> None:
            if self._syncing_aux_result_controls:
                return
            value = str(text or "").strip()
            if not value:
                return
            self._set_colormap_without_reload(value)
            self.result_colormap_name = value
            self.update_preview()

        def _auxiliary_status_lines(self, panel_key: str) -> list[str]:
            lines: list[str] = []
            issue_lines = self.workflow_step_issue_lines(panel_key, panel_key, limit=3)
            if issue_lines:
                lines.extend(issue_lines)
            elif panel_key in {"materials", "boundary_conditions", "loads"}:
                completion_line = self.workflow_step_completion_line(panel_key, panel_key, include_ok=True)
                if completion_line:
                    lines.append(
                        f"Completion: {completion_line}"
                        if self.gui_locale == "en"
                        else f"完了条件: {completion_line}"
                    )
            guidance = getattr(self, "workflow_guidance", {})
            if isinstance(guidance, Mapping):
                next_step = guidance.get("next_step")
                if isinstance(next_step, Mapping):
                    missing_count = len(self._ensure_list(next_step.get("missing_paths", [])))
                    if missing_count:
                        if bool(next_step.get("required", False)):
                            lines.append(
                                f"Missing inputs: {missing_count}"
                                if self.gui_locale == "en"
                                else f"未入力/不足: {missing_count}件"
                            )
                        else:
                            label = str(next_step.get("label", ""))
                            lines.append(
                                f"Optional setup: {label}"
                                if self.gui_locale == "en"
                                else f"任意設定: {label}"
                            )
            check_table = getattr(self, "check_table", None)
            if check_table is not None and check_table.rowCount() > 0:
                lines.append(
                    f"Model Check: {check_table.rowCount()}"
                    if self.gui_locale == "en"
                    else f"モデルチェック: {check_table.rowCount()}件"
                )
            if panel_key == "results":
                if self.result_stage_dir is not None:
                    stage_prefix = "Stage" if self.gui_locale == "en" else "ステージ"
                    lines.append(f"{stage_prefix}: {self._result_stage_display_name(self.result_stage_dir)}")
                if self.post_mode and self.post_mode != "none":
                    mode_label = choice_label("post_mode", self.post_mode, locale=self.gui_locale)
                    component_label = choice_label("result_component", self.post_component, locale=self.gui_locale)
                    if self.gui_locale == "en":
                        lines.append(f"View: {mode_label} / Component: {component_label}")
                    else:
                        lines.append(f"図: {mode_label} / 成分: {component_label}")
                elif self._active_result_dir() is None:
                    lines.append("No analysis results" if self.gui_locale == "en" else "解析結果なし")
            mesh_cfg = self._mapping(self.cfg.get("mesh", {}))
            if panel_key in {"geometry", "mesh"} and bool(mesh_cfg.get("requires_rebuild", False)):
                if bool(mesh_cfg.get("partial_rebuild_required", False)):
                    lines.append("Region mesh rebuild required" if self.gui_locale == "en" else "形状別メッシュ再構成が必要")
                else:
                    lines.append("Mesh rebuild required" if self.gui_locale == "en" else "メッシュ再構成が必要")
            if panel_key in {"geometry", "mesh", "boundary_conditions", "loads", "stages"}:
                try:
                    entities = self._selected_preview_entities()
                    if self.gui_locale == "en":
                        selection_text = f"Selection: Nodes {len(entities['nodes'])} / Edges {len(entities['edges'])} / Elements {len(entities['elements'])}"
                    else:
                        selection_text = f"選択: 節点{len(entities['nodes'])} / 辺{len(entities['edges'])} / 要素{len(entities['elements'])}"
                    lines.append(selection_text)
                except Exception:
                    pass
            return lines

