        def _current_detail_panel_target(self, panel_key: str) -> str:
            return self._panel_key_from_tree_key(panel_key)

        def open_current_detail_panel(self) -> None:
            panel_key = self._panel_key_from_tree_key(str(getattr(self, "current_panel_key", "workflow")))
            target_panel = self._current_detail_panel_target(panel_key)
            previous_mode = self._current_gui_operation_mode()
            if previous_mode not in {"detail", "maintenance"}:
                self._detail_return_mode = previous_mode
                self._detail_return_panel = panel_key
            if target_panel == "analysis" or target_panel in self._model_display_panel_keys():
                self.current_panel_key = target_panel
                self._select_tree_panel(target_panel)
                self._apply_context_visibility(target_panel)
                self._update_auxiliary_panel(target_panel)
                self.statusBar().showMessage("作業ビューは廃止しました。現在の工程に必要な表示へ固定しています。")
                return
            if target_panel in {"geometry", "mesh"}:
                self._refresh_geometry_detail_from_cfg()
            if target_panel in getattr(self, "inline_detail_panel_keys", set()):
                self.current_panel_key = target_panel
                self._select_tree_panel(target_panel)
                self._apply_context_visibility(target_panel)
                self._update_auxiliary_panel(target_panel)
                self.statusBar().showMessage("詳細シートを作図パレット下部に表示しました。")
                return
            if previous_mode != "detail":
                index = self.gui_operation_mode_combo.findData("detail")
                if index >= 0:
                    self.gui_operation_mode_combo.setCurrentIndex(index)
            self._select_tree_panel(target_panel)
            page = self.panel_pages.get(target_panel)
            if page is not None:
                self.panel_stack.setCurrentWidget(page)
                self.tabs.setCurrentWidget(self.panel_stack)
                self.right_panel_stack.setCurrentWidget(self.auxiliary_panel)
            self._update_auxiliary_panel(target_panel)

        def return_from_detail_panel(self) -> None:
            target_mode = str(getattr(self, "_detail_return_mode", "standard") or "standard")
            if target_mode in {"detail", "maintenance"}:
                target_mode = "standard"
            target_panel = str(getattr(self, "_detail_return_panel", "workflow") or "workflow")
            if target_panel in {"workflow", "geometry", "mesh"} and not self._apply_geometry_detail_to_cfg_if_dirty():
                return
            index = self.gui_operation_mode_combo.findData(target_mode)
            if index >= 0:
                self.gui_operation_mode_combo.setCurrentIndex(index)
            self._select_tree_panel(target_panel)
            self._apply_context_visibility(target_panel)
            if target_panel in {"workflow", "geometry", "mesh"}:
                self.tabs.setCurrentIndex(0)
                self.statusBar().showMessage("CAD風作図パレットへ戻りました。")
            else:
                self.statusBar().showMessage("標準表示へ戻りました。")

