        def _refresh_tree(self, select_panel: str | None = None) -> None:
            self.tree.blockSignals(True)
            self.tree.clear()
            root = QTreeWidgetItem(["GeoFEM 2D"])
            root.setData(0, Qt.ItemDataRole.UserRole, "workflow")
            groups = self._tree_groups_for_mode(self._current_gui_operation_mode())
            first_child: QTreeWidgetItem | None = None
            selected_child: QTreeWidgetItem | None = None
            result_locked = self.result_navigation_locked()
            lock_message = self.result_navigation_lock_message()
            for group, entries in groups.items():
                if not entries:
                    continue
                parent = QTreeWidgetItem([group])
                parent.setData(0, Qt.ItemDataRole.UserRole, entries[0][0])
                parent_allowed = not result_locked or self.result_navigation_target_allowed(entries[0][0])
                if not parent_allowed:
                    parent.setDisabled(True)
                    parent.setToolTip(0, lock_message)
                for key, label in entries:
                    child = QTreeWidgetItem([label])
                    child.setData(0, Qt.ItemDataRole.UserRole, key)
                    child_allowed = not result_locked or self.result_navigation_target_allowed(key)
                    if not child_allowed:
                        child.setDisabled(True)
                        child.setToolTip(0, lock_message)
                    parent.addChild(child)
                    if key == "results":
                        for result_key, result_label in self._result_tree_entries():
                            result_child = QTreeWidgetItem([result_label])
                            result_child.setData(0, Qt.ItemDataRole.UserRole, result_key)
                            result_child.setToolTip(0, "解析結果を表示します。")
                            child.addChild(result_child)
                            if result_key == select_panel and selected_child is None:
                                selected_child = result_child
                        child.setExpanded(True)
                    if key == "boundary_conditions":
                        if self._should_populate_tree_branch("boundary_conditions", select_panel, ("boundary_condition:",)):
                            boundary_selected = self._add_boundary_condition_navigation_items(child, select_panel)
                            if boundary_selected is not None and selected_child is None:
                                selected_child = boundary_selected
                            child.setExpanded(True)
                    if key == "materials":
                        if self._should_populate_tree_branch("materials", select_panel, ("material_assignment:",)):
                            material_selected = self._add_material_navigation_items(child, select_panel)
                            if material_selected is not None and selected_child is None:
                                selected_child = material_selected
                            child.setExpanded(True)
                    if key == "mesh":
                        if self._should_populate_mesh_quality_navigation(select_panel):
                            quality_selected = self._add_mesh_quality_navigation_items(child, select_panel)
                            if quality_selected is not None and selected_child is None:
                                selected_child = quality_selected
                            child.setExpanded(True)
                    if key == "loads":
                        if self._should_populate_tree_branch("loads", select_panel, ("load_condition:",)):
                            load_selected = self._add_load_condition_navigation_items(child, select_panel)
                            if load_selected is not None and selected_child is None:
                                selected_child = load_selected
                            child.setExpanded(True)
                    if key == "stages":
                        if self._should_populate_tree_branch("stages", select_panel, ("stage:",)):
                            stage_selected = self._add_stage_navigation_items(child, select_panel)
                            if stage_selected is not None and selected_child is None:
                                selected_child = stage_selected
                            child.setExpanded(True)
                    if first_child is None and child_allowed:
                        first_child = child
                    if key == select_panel and selected_child is None and child_allowed:
                        selected_child = child
                root.addChild(parent)
            self.tree.addTopLevelItem(root)
            root.setExpanded(True)
            target = selected_child or first_child or root
            self._focus_tree_category(target)
            self.tree.blockSignals(False)
            self.tree.setCurrentItem(target)

        def _focus_tree_category(self, current: QTreeWidgetItem | None) -> None:
            tree = getattr(self, "tree", None)
            if tree is None or current is None:
                return
            root = tree.topLevelItem(0)
            if root is None:
                return
            parent = current.parent()
            if parent is None and current is not root:
                parent = current
            group_parent = parent
            while group_parent is not None and group_parent.parent() is not root:
                group_parent = group_parent.parent()
            root.setExpanded(True)
            for index in range(root.childCount()):
                group = root.child(index)
                group.setExpanded(group is group_parent or group is parent or group is current)
            if parent is not None:
                parent.setExpanded(True)
            current.setExpanded(True)

        def _set_tree_item_bold(self, item: QTreeWidgetItem | None, bold: bool) -> None:
            if item is None:
                return
            font = item.font(0)
            font.setBold(bold)
            item.setFont(0, font)

        def _refresh_tree_issue_colors(self, blockers: list[Mapping[str, Any]] | None = None) -> None:
            tree = getattr(self, "tree", None)
            if tree is None:
                return
            blockers = blockers if blockers is not None else self.input_execution_blockers(getattr(self, "workflow_guidance", None))
            issue_panels = {str(item.get("panel", item.get("id", ""))) for item in blockers}
            issue_panels.update(str(item.get("id", "")) for item in blockers)
            red = QBrush(QColor("#b42318"))
            normal = QBrush()

            def visit(item: QTreeWidgetItem | None) -> None:
                if item is None:
                    return
                raw_key = str(item.data(0, Qt.ItemDataRole.UserRole) or "")
                panel = self._panel_key_from_tree_key(raw_key)
                has_issue = raw_key in issue_panels or panel in issue_panels
                item.setForeground(0, red if has_issue else normal)
                item.setToolTip(0, "\n".join(self.workflow_step_issue_lines(panel, panel, blockers, limit=4)) if has_issue else "")
                for child_index in range(item.childCount()):
                    visit(item.child(child_index))

            for index in range(tree.topLevelItemCount()):
                visit(tree.topLevelItem(index))

        def _tree_changed(self, current: QTreeWidgetItem | None, _previous: QTreeWidgetItem | None) -> None:
            if current is None:
                return
            raw_key = str(current.data(0, Qt.ItemDataRole.UserRole) or "analysis")
            self._navigate_to_workspace(
                raw_key,
                source="tree",
                tree_item=current,
                previous_tree_item=_previous,
            )

        def _yaml_text_changed(self) -> None:
            if not self._syncing_yaml:
                self._model_check_dirty = True
                self.statusBar().showMessage("YAMLに未反映の直接編集があります。必要なら「YAMLから反映」を押してください。")
            self.refresh_model_check_overview()

        def _cfg_mesh_estimated_size_for_load(self, cfg: Mapping[str, Any]) -> tuple[int, int]:
            mesh = self._mapping(cfg.get("mesh", {})) if isinstance(cfg, Mapping) else {}
            nodes = mesh.get("nodes", {})
            elements = mesh.get("elements", [])
            node_count = len(nodes) if isinstance(nodes, Mapping) else (len(nodes) if isinstance(nodes, list) else 0)
            element_count = len(elements) if isinstance(elements, list) else 0
            if node_count or element_count:
                return (node_count, element_count)
            generator = str(mesh.get("generator", "")).strip().lower()
            if generator in {"", "rectangle", "structured_rectangle", "quad_rect", "tri_rect"} and ("nx" in mesh or "ny" in mesh):
                try:
                    nx = max(1, int(float(mesh.get("nx", 1))))
                    ny = max(1, int(float(mesh.get("ny", 1))))
                except Exception:
                    nx = ny = 0
                if nx and ny:
                    etype = str(mesh.get("element_type", mesh.get("type", "QUAD4"))).upper()
                    element_count = nx * ny * (2 if etype.startswith("TRI") else 1)
                    node_count = (nx + 1) * (ny + 1)
                    if etype in {"TRI6", "QUAD8"}:
                        node_count += element_count * 2
                    return (node_count, element_count)
            for node_key in ("node_count", "estimated_nodes", "nodes_estimate"):
                try:
                    node_count = max(node_count, int(float(mesh.get(node_key, 0) or 0)))
                except Exception:
                    pass
            for element_key in ("element_count", "estimated_elements", "elements_estimate"):
                try:
                    element_count = max(element_count, int(float(mesh.get(element_key, 0) or 0)))
                except Exception:
                    pass
            return (node_count, element_count)

        def _cfg_uses_srm(self, cfg: Mapping[str, Any]) -> bool:
            analysis = self._mapping(cfg.get("analysis", {})) if isinstance(cfg, Mapping) else {}
            solver = self._mapping(cfg.get("solver", {})) if isinstance(cfg, Mapping) else {}
            if "srm" in str(analysis.get("type", "")).lower() or bool(analysis.get("srm", False)):
                return True
            if "srm" in str(solver.get("method", "")).lower() or isinstance(solver.get("srm"), Mapping):
                return True
            stages = cfg.get("stages", cfg.get("steps", [])) if isinstance(cfg, Mapping) else []
            for stage in self._ensure_list(stages):
                if isinstance(stage, Mapping) and ("srm" in str(stage.get("type", "")).lower() or isinstance(stage.get("srm"), Mapping)):
                    return True
            return False

        def _cfg_prefers_deferred_load_refresh(self, cfg: Mapping[str, Any]) -> bool:
            gui_cfg = self._mapping(cfg.get("gui", {})) if isinstance(cfg, Mapping) else {}
            if bool(gui_cfg.get("defer_large_model_load", False)):
                return True
            node_count, element_count = self._cfg_mesh_estimated_size_for_load(cfg)
            try:
                threshold = max(1, int(float(gui_cfg.get("large_model_load_defer_threshold", 5000))))
            except Exception:
                threshold = 5000
            try:
                srm_threshold = max(1, int(float(gui_cfg.get("large_srm_load_defer_threshold", 700))))
            except Exception:
                srm_threshold = 700
            size = max(node_count, element_count)
            return size >= threshold or (self._cfg_uses_srm(cfg) and size >= srm_threshold)

        def _show_deferred_model_load_notice(self) -> None:
            node_count, element_count = self._deferred_load_mesh_size
            message = (
                f"Large model loaded: nodes={node_count}, elements={element_count}. "
                "Preview and diagnostics are deferred to keep the GUI responsive."
            )
            if getattr(self, "scene", None) is not None:
                self.scene.clear()
                self.scene.addText(message)
            if getattr(self, "mesh_summary", None) is not None:
                self.mesh_summary.setText(message)
            if getattr(self, "check_summary", None) is not None:
                self.check_summary.setText("Model check is deferred. It will run in the background when opened, and before analysis execution.")
            self.preview_performance_profile = {
                "schema": "geofem.gui.preview_performance.v1",
                "panel": str(getattr(self, "current_panel_key", "")),
                "mode": "deferred_load",
                "elapsed_seconds": 0.0,
                "node_count": node_count,
                "element_count": element_count,
                "scene_item_count": len(self.scene.items()) if getattr(self, "scene", None) is not None else 0,
                "recorded_at": datetime.now().isoformat(timespec="seconds"),
            }
            self.statusBar().showMessage(message)

        def _load_cfg(self, cfg: Mapping[str, Any], *, keep_yaml: bool) -> None:
            self.cfg = dict(cfg)
            startup_deferred = bool(getattr(self, "_startup_model_refresh_deferred", False))
            defer_heavy_refresh = self._cfg_prefers_deferred_load_refresh(self.cfg)
            self._last_load_deferred_heavy_refresh = bool(defer_heavy_refresh)
            self._deferred_load_mesh_size = self._cfg_mesh_estimated_size_for_load(self.cfg) if defer_heavy_refresh else (0, 0)
            if not keep_yaml:
                self._syncing_yaml = True
                self.yaml_editor.setPlainText(yaml.safe_dump(self.cfg, allow_unicode=True, sort_keys=False))
                self._syncing_yaml = False
            previous_startup_deferred = bool(getattr(self, "_startup_model_refresh_deferred", False))
            if defer_heavy_refresh:
                self._startup_model_refresh_deferred = True
            try:
                self.populate_forms()
            finally:
                self._startup_model_refresh_deferred = previous_startup_deferred
            if hasattr(self, "tree"):
                current_item = self.tree.currentItem()
                current_tree_key = str(current_item.data(0, Qt.ItemDataRole.UserRole) or "") if current_item is not None else ""
                self._refresh_tree(select_panel=current_tree_key or str(getattr(self, "current_panel_key", "analysis") or "analysis"))
            self._refresh_named_selection_table()
            self._refresh_selection_compare_table()
            self._refresh_input_assistance_table()
            if startup_deferred or defer_heavy_refresh:
                self._model_preview_dirty = True
                if defer_heavy_refresh and not startup_deferred:
                    self._show_deferred_model_load_notice()
            else:
                self.update_preview()
            if startup_deferred or defer_heavy_refresh:
                self._model_check_dirty = True
            else:
                self.run_model_check()
            self.refresh_workflow_guidance()
            self._last_edit_snapshot = self._cfg_snapshot()
            self._last_geometry_snapshot = self._geometry_snapshot()
            if not self._suppress_edit_history:
                self.edit_undo_stack.clear()
                self.edit_redo_stack.clear()
                self.edit_undo_labels.clear()
                self.edit_redo_labels.clear()
            self._refresh_edit_history_display()

        def sync_from_yaml(self) -> bool:
            if self._guard_input_mutation("YAMLから反映"):
                return False
            try:
                cfg = self._parse_yaml_editor()
            except Exception as exc:
                QMessageBox.warning(self, "GeoFEM", f"YAMLを読めません: {exc}")
                return False
            self._load_cfg(cfg, keep_yaml=True)
            self.append_log(self.ui_message("log.yaml.applied"))
            return True

        def populate_forms(self) -> None:
            self._last_geometry_snapshot = self._geometry_snapshot()
            analysis = self._mapping(self.cfg.get("analysis", {}))
            self._set_combo(self.analysis_type, str(analysis.get("type", "static_plane_strain")))
            is_axisymmetric = str(analysis.get("type", "")).lower().startswith("axisymmetric") or bool(analysis.get("axisymmetric", False)) or str(analysis.get("geometry", "")).lower() == "axisymmetric"
            self._set_combo(self.analysis_geometry, "axisymmetric" if is_axisymmetric else "plane_strain")
            deformation_mode = str(analysis.get("deformation_mode", analysis.get("geometry_mode", "small_deformation"))).lower().strip().replace("-", "_")
            self._set_combo(self.analysis_deformation_mode, "large_deformation" if deformation_mode in {"large", "large_deformation", "large_displacement", "finite_deformation", "updated_lagrangian"} else "small_deformation")
            axisym_gui = self._mapping(analysis.get("axisymmetric_gui", {}))
            if hasattr(self, "axisym_show_radial_guides"):
                self.axisym_show_radial_guides.setChecked(bool(axisym_gui.get("display_radial_guides", True)))
            fields = self._ensure_list(analysis.get("fields", []))
            self.analysis_up_fields.setChecked(any(str(field).lower() in {"p", "pressure", "pore_pressure"} for field in fields))
            self.unit_system.setText(str(analysis.get("unit_system", "m-kN")))
            self.analysis_summary.setText(self.ui_message("analysis.summary.2d"))
            output = self._mapping(self.cfg.get("output", {}))
            output_policy = str(output.get("root_policy", "same_as_input")).strip() or "same_as_input"
            policy_widget = getattr(self, "analysis_output_policy", None)
            if policy_widget is not None:
                for index in range(policy_widget.count()):
                    if str(policy_widget.itemData(index) or "") == output_policy:
                        policy_widget.setCurrentIndex(index)
                        break
            if getattr(self, "analysis_output_custom_dir", None) is not None:
                self.analysis_output_custom_dir.setText(str(output.get("directory", "")))
            formats = {str(value).lower() for value in self._ensure_list(output.get("formats", ["csv", "vtk"]))}
            if getattr(self, "analysis_output_csv", None) is not None:
                self.analysis_output_csv.setChecked("csv" in formats or not formats)
            if getattr(self, "analysis_output_vtk", None) is not None:
                self.analysis_output_vtk.setChecked("vtk" in formats or "vtu" in formats)
            if getattr(self, "analysis_output_log", None) is not None:
                self.analysis_output_log.setChecked(bool(output.get("write_log", True)))
            self.update_analysis_output_path_preview()

            mesh = self._mapping(self.cfg.get("mesh", {}))
            generator = str(mesh.get("generator", "rectangle"))
            self._set_combo(self.mesh_generator, generator if generator == "rectangle" else "rectangle")
            x_range = mesh.get("x_range", [0.0, 10.0])
            y_range = mesh.get("y_range", [0.0, 2.0])
            if isinstance(x_range, list) and len(x_range) >= 2:
                self.mesh_x0.setText(str(x_range[0]))
                self.mesh_x1.setText(str(x_range[1]))
            if isinstance(y_range, list) and len(y_range) >= 2:
                self.mesh_y0.setText(str(y_range[0]))
                self.mesh_y1.setText(str(y_range[1]))
            self.mesh_nx.setText(str(mesh.get("nx", 8)))
            self.mesh_ny.setText(str(mesh.get("ny", 2)))
            self._set_combo(self.mesh_type, str(mesh.get("element_type", mesh.get("type", "QUAD4"))).upper())
            self._set_combo(self.mesh_integration, str(mesh.get("integration", "B-bar")))
            self.mesh_material.setText(str(mesh.get("material", "soil")))
            self._sync_mesh_edit_generation_fields(mesh)
            geometry = self._mapping(self.cfg.get("geometry", {}))
            self.mesh_boolean_expression.setText(str(mesh.get("boolean_expression", geometry.get("boolean_expression", "")) or ""))
            if hasattr(self, "geometry_boolean_expression"):
                self.geometry_boolean_expression.setText(str(geometry.get("boolean_expression", mesh.get("boolean_expression", "")) or ""))
            cad_boolean = self._mapping(geometry.get("cad_boolean", mesh.get("cad_boolean", {})))
            if hasattr(self, "geometry_boolean_operation"):
                selected_operation = str(cad_boolean.get("selected_operation", "expression" if self.mesh_boolean_expression.text().strip() else "union"))
                self._set_combo(self.geometry_boolean_operation, selected_operation)

            self.material_table.setRowCount(0)
            for name, raw in self._mapping(self.cfg.get("materials", {})).items():
                material = self._mapping(raw)
                self.add_material_row(
                    name=str(name),
                    model=str(material.get("model", material.get("type", "elastic"))),
                    E=material.get("E", material.get("young", 0.0)),
                    nu=material.get("nu", material.get("poisson", 0.3)),
                    gamma=material.get("gamma", material.get("unit_weight", 0.0)),
                    cohesion=material.get("cohesion", material.get("c", 0.0)),
                    phi=material.get("friction_angle", material.get("phi", 0.0)),
                    psi=material.get("dilation_angle", material.get("psi", material.get("friction_angle", material.get("phi", 0.0)))),
                    yield_stress=material.get("yield_stress", material.get("sigma_y", material.get("sy", 0.0))),
                    hardening=material.get("hardening", material.get("H", 0.0)),
                    k0="" if material.get("k0", material.get("K0")) is None else material.get("k0", material.get("K0")),
                    tension=material.get("tension_cutoff", False),
                    ft=material.get("ft", material.get("tensile_strength", "")),
                    extra=self._material_extra_yaml(material),
                )
            self._refresh_load_body_material_selector()

            if getattr(self, "_startup_model_refresh_deferred", False):
                self._set_display_options_dirty = True
            else:
                self._refresh_set_display_options()
            self._refresh_geometry_detail_from_cfg()
            self.populate_mesh_control_tables()
            self.populate_element_library_table()
            self.populate_boundary_table()
            if getattr(self, "_startup_model_refresh_deferred", False):
                self._boundary_condition_tree_dirty = True
            else:
                self.populate_boundary_condition_tree()
            self.populate_load_case_table()
            self.populate_load_table()
            for key in ("boundary_conditions", "loads", "stages", "solver"):
                editor = getattr(self, f"{key}_editor", None)
                if editor is not None:
                    value = self.cfg.get(key, [] if key != "solver" else {})
                    editor.setPlainText(yaml.safe_dump(value, allow_unicode=True, sort_keys=False))
            self.populate_stage_table()
            self.populate_stage_change_table()
            self.populate_stage_detail_tables()

        def populate_stage_table(self) -> None:
            table = getattr(self, "stage_table", None)
            if table is None:
                return
            stages = self._stages()
            selected = self._selected_stage_row()
            selected = 0 if selected is None else max(0, min(selected, len(stages) - 1))
            table.blockSignals(True)
            table.setRowCount(0)
            for i, stage in enumerate(stages, start=1):
                row = table.rowCount()
                table.insertRow(row)
                raw_stage_type = str(stage.get("type", "static"))
                values = [
                    str(i),
                    str(stage.get("name", f"Stage-{i}")),
                    choice_label("stage_type", raw_stage_type, locale=self.gui_locale),
                    self._element_spec_text(stage),
                    "" if stage.get("stress_release") is None else str(stage.get("stress_release")),
                    str(len(stage.get("boundary_conditions", stage.get("bc", []))) if isinstance(stage.get("boundary_conditions", stage.get("bc", [])), list) else 0),
                    str(len(stage.get("loads", [])) if isinstance(stage.get("loads", []), list) else 0),
                    str(self._stage_hydro_count(stage)),
                    str(len(stage.get("mpc_constraints", stage.get("mpc", []))) if isinstance(stage.get("mpc_constraints", stage.get("mpc", [])), list) else 0),
                    "yes" if isinstance(stage.get("solver", {}), Mapping) and stage.get("solver") else "",
                ]
                for col, value in enumerate(values):
                    item = QTableWidgetItem(value)
                    if col == 2:
                        item.setData(Qt.ItemDataRole.UserRole, raw_stage_type)
                    if col in {0, 2, 5, 6, 7, 8, 9}:
                        item.setFlags(item.flags() & ~Qt.ItemFlag.ItemIsEditable)
                    table.setItem(row, col, item)
            table.blockSignals(False)
            if stages:
                table.selectRow(selected)

        def stage_selection_changed(self) -> None:
            self.populate_stage_detail_tables()
            if getattr(self, "_startup_model_refresh_deferred", False):
                self._boundary_condition_tree_dirty = True
            else:
                self.populate_boundary_condition_tree()
            self.refresh_stage_cross_compare_table()
            self.refresh_stage_conflict_table()
            self.refresh_stage_guidance()
            self._refresh_stage_inspector_visibility()
            if getattr(self, "_startup_model_refresh_deferred", False):
                self._model_preview_dirty = True
            elif self._cfg_prefers_deferred_load_refresh(self.cfg):
                self._model_preview_dirty = True
                self.request_preview_update(reset_view=False, reason="stage selection")
            else:
                self.update_preview()

        def apply_analysis_panel(self) -> None:
            analysis = dict(self._mapping(self.cfg.get("analysis", {})))
            analysis["dimension"] = "2D"
            analysis_type = self._combo_value(self.analysis_type, "static_plane_strain")
            analysis_geometry = self._combo_value(self.analysis_geometry, "plane_strain")
            if analysis_geometry == "axisymmetric":
                analysis["axisymmetric"] = True
                analysis["geometry"] = "axisymmetric"
                if analysis_type == "static_plane_strain":
                    analysis_type = "axisymmetric_static"
            else:
                analysis.pop("axisymmetric", None)
                analysis["geometry"] = "plane_strain"
                if analysis_type == "axisymmetric_static":
                    analysis_type = "static_plane_strain"
            analysis["type"] = analysis_type
            deformation_mode = self._combo_value(self.analysis_deformation_mode, "small_deformation") if hasattr(self, "analysis_deformation_mode") else "small_deformation"
            analysis["deformation_mode"] = "large_deformation" if deformation_mode == "large_deformation" else "small_deformation"
            if self.analysis_up_fields.isChecked():
                analysis["fields"] = ["u", "p"]
            else:
                analysis.pop("fields", None)
            if analysis_geometry == "axisymmetric":
                axisym_gui = dict(self._mapping(analysis.get("axisymmetric_gui", {})))
                axisym_gui.update(
                    {
                        "radial_coordinate": "x",
                        "axial_coordinate": "y",
                        "display_radial_guides": bool(getattr(self, "axisym_show_radial_guides", None) is None or self.axisym_show_radial_guides.isChecked()),
                    }
                )
                analysis["axisymmetric_gui"] = axisym_gui
            else:
                analysis.pop("axisymmetric_gui", None)
            analysis["unit_system"] = self.unit_system.text().strip() or "m-kN"
            self.cfg["analysis"] = analysis
            self._after_form_change("解析条件を反映しました")

        def _is_axisymmetric_analysis(self) -> bool:
            analysis = self._mapping(self.cfg.get("analysis", {}))
            return (
                str(analysis.get("type", "")).lower().startswith("axisymmetric")
                or bool(analysis.get("axisymmetric", False))
                or str(analysis.get("geometry", "")).lower() == "axisymmetric"
            )

        def _ensure_axisymmetric_analysis(self) -> None:
            analysis = dict(self._mapping(self.cfg.get("analysis", {})))
            analysis["dimension"] = "2D"
            analysis["axisymmetric"] = True
            analysis["geometry"] = "axisymmetric"
            atype = str(analysis.get("type", "axisymmetric_static"))
            if not atype or atype == "static_plane_strain":
                atype = "axisymmetric_static"
            analysis["type"] = atype
            gui = dict(self._mapping(analysis.get("axisymmetric_gui", {})))
            gui.update({"radial_coordinate": "x", "axial_coordinate": "y", "display_radial_guides": True})
            analysis["axisymmetric_gui"] = gui
            self.cfg["analysis"] = analysis
            if hasattr(self, "analysis_geometry"):
                self._set_combo(self.analysis_geometry, "axisymmetric")
            if hasattr(self, "analysis_type") and self.analysis_type.findData("axisymmetric_static") >= 0 and atype == "axisymmetric_static":
                self._set_combo(self.analysis_type, "axisymmetric_static")

        def _axisymmetric_reference_sets_from_mesh(self, mesh: Any) -> dict[str, list[str]]:
            if not getattr(mesh, "node_ids", None):
                return {}
            xs = [float(mesh.coords[i, 0]) for i in range(len(mesh.node_ids))]
            ys = [float(mesh.coords[i, 1]) for i in range(len(mesh.node_ids))]
            xmin, xmax = min(xs), max(xs)
            ymin, ymax = min(ys), max(ys)
            span = max(xmax - xmin, ymax - ymin, 1.0)
            tol = max(span * 1.0e-8, 1.0e-10)

            def nodes_where(predicate: Any, key: Any) -> list[str]:
                pairs: list[tuple[str, float, float]] = []
                for i, nid in enumerate(mesh.node_ids):
                    x = float(mesh.coords[i, 0])
                    y = float(mesh.coords[i, 1])
                    if predicate(x, y):
                        pairs.append((str(nid), x, y))
                pairs.sort(key=key)
                return [nid for nid, _x, _y in pairs]

            inner = nodes_where(lambda x, _y: abs(x - xmin) <= tol, lambda item: (item[2], item[1], self._natural_sort_key(item[0])))
            outer = nodes_where(lambda x, _y: abs(x - xmax) <= tol, lambda item: (item[2], item[1], self._natural_sort_key(item[0])))
            bottom = nodes_where(lambda _x, y: abs(y - ymin) <= tol, lambda item: (item[1], item[2], self._natural_sort_key(item[0])))
            top = nodes_where(lambda _x, y: abs(y - ymax) <= tol, lambda item: (item[1], item[2], self._natural_sort_key(item[0])))
            axis = nodes_where(lambda x, _y: abs(x) <= tol, lambda item: (item[2], item[1], self._natural_sort_key(item[0])))
            if not axis:
                axis = list(inner)
            return {
                "axisymmetric_axis": axis,
                "axisymmetric_inner_radius": inner,
                "axisymmetric_outer_radius": outer,
                "axisymmetric_bottom": bottom,
                "axisymmetric_top": top,
            }

        def _axisymmetric_reference_sets(self, *, update: bool = False) -> dict[str, list[str]]:
            from geofem_app.fem2d import mesh_from_config

            mesh = mesh_from_config(self.cfg)
            sets = self._axisymmetric_reference_sets_from_mesh(mesh)
            if update and sets:
                mesh_cfg = self._mesh_cfg()
                node_sets = mesh_cfg.setdefault("node_sets", {})
                if not isinstance(node_sets, dict):
                    node_sets = {}
                    mesh_cfg["node_sets"] = node_sets
                for name, nodes in sets.items():
                    if nodes:
                        node_sets[name] = nodes
            return sets

        def apply_axisymmetric_reference_sets(self, *_args: Any) -> None:
            try:
                self._ensure_axisymmetric_analysis()
                sets = self._axisymmetric_reference_sets(update=True)
            except Exception as exc:
                QMessageBox.warning(self, "GeoFEM", f"Axisymmetric sets could not be created: {exc}")
                return
            count = sum(1 for nodes in sets.values() if nodes)
            self._after_form_change(f"Axisymmetric r/z reference sets created: {count}")

        def apply_axisymmetric_standard_presets(self, *args: Any, **kwargs: Any) -> Any:
            return boundary_load_controller.apply_axisymmetric_standard_presets(self, self._boundary_load_controller_qt(), *args, **kwargs)

        def _append_axisymmetric_boundary_conditions(self, *args: Any, **kwargs: Any) -> Any:
            return boundary_load_controller._append_axisymmetric_boundary_conditions(self, self._boundary_load_controller_qt(), *args, **kwargs)

        def apply_axisymmetric_boundary_preset(self, *args: Any, **kwargs: Any) -> Any:
            return boundary_load_controller.apply_axisymmetric_boundary_preset(self, self._boundary_load_controller_qt(), *args, **kwargs)

        def apply_axisymmetric_load_preset(self, *args: Any, **kwargs: Any) -> Any:
            return boundary_load_controller.apply_axisymmetric_load_preset(self, self._boundary_load_controller_qt(), *args, **kwargs)

        def apply_axisymmetric_hydro_preset(self, *args: Any, **kwargs: Any) -> Any:
            return boundary_load_controller.apply_axisymmetric_hydro_preset(self, self._boundary_load_controller_qt(), *args, **kwargs)

        def _sync_mesh_edit_generation_fields(self, mesh: Mapping[str, Any] | None = None) -> None:
            if getattr(self, "mesh_edit_type", None) is None:
                return
            mesh_map = self._mapping(mesh if mesh is not None else self.cfg.get("mesh", {}))
            element_type = str(mesh_map.get("element_type", mesh_map.get("requested_element_type", mesh_map.get("type", "QUAD4")))).upper()
            self._set_combo(self.mesh_edit_type, element_type)
            target_size = mesh_map.get("target_size", mesh_map.get("division_width", ""))
            self.mesh_edit_target_size.setText("" if target_size in (None, "") else str(target_size))
            self.mesh_edit_nx.setText(str(mesh_map.get("nx", self.mesh_nx.text() or 8)))
            self.mesh_edit_ny.setText(str(mesh_map.get("ny", self.mesh_ny.text() or 2)))

        def _mesh_edit_float(self, editor: QLineEdit | None, default: float, *, allow_blank: bool = True) -> float:
            text = editor.text().strip() if editor is not None else ""
            if not text and allow_blank:
                return float(default)
            try:
                value = float(text)
            except (TypeError, ValueError):
                return float(default)
            return value if math.isfinite(value) else float(default)

        def _mesh_edit_int(self, editor: QLineEdit | None, default: int) -> int:
            text = editor.text().strip() if editor is not None else ""
            try:
                value = int(float(text)) if text else int(default)
            except (TypeError, ValueError):
                value = int(default)
            return max(1, value)

        def _mesh_edit_target_size_value(self) -> float:
            mesh = self._mapping(self.cfg.get("mesh", {}))
            try:
                default = float(mesh.get("target_size", mesh.get("division_width", 1.0)) or 1.0)
            except (TypeError, ValueError):
                default = 1.0
            return max(self._mesh_edit_float(getattr(self, "mesh_edit_target_size", None), default), 1.0e-9)

        def _geometry_region_ids(self) -> list[str]:
            geometry = self._mapping(self.cfg.get("geometry", {}))
            raw_regions = geometry.get("regions", [])
            ids: list[str] = []
            if not isinstance(raw_regions, list):
                return ids
            for index, raw in enumerate(raw_regions, start=1):
                if isinstance(raw, Mapping):
                    ids.append(str(raw.get("id", f"region_{index}") or f"region_{index}"))
                else:
                    ids.append(f"region_{index}")
            return ids

        def _region_setting_key_candidates(self, region_key: str) -> list[str]:
            region_key = str(region_key)
            candidates = [region_key]
            region_ids = self._geometry_region_ids()
            if region_key in region_ids:
                candidates.append(f"region_{region_ids.index(region_key) + 1}")
            elif region_key.startswith("region_"):
                suffix = region_key.removeprefix("region_")
                if suffix.isdigit():
                    index = int(suffix) - 1
                    if 0 <= index < len(region_ids):
                        candidates.append(region_ids[index])
                else:
                    candidates.append(suffix)
            elif region_key.isdigit():
                candidates.append(f"region_{region_key}")
                index = int(region_key) - 1
                if 0 <= index < len(region_ids):
                    candidates.append(region_ids[index])
            return list(dict.fromkeys(candidates))

        def _mesh_region_settings(self, mesh: dict[str, Any]) -> dict[str, Any]:
            raw = mesh.get("region_settings", {})
            if isinstance(raw, dict):
                if "region_settings" not in mesh:
                    mesh["region_settings"] = raw
                return raw
            converted: dict[str, Any] = {}
            if isinstance(raw, list):
                for index, item in enumerate(raw, start=1):
                    if isinstance(item, Mapping):
                        converted[f"region_{index}"] = dict(item)
            mesh["region_settings"] = converted
            return converted

        def _selected_mesh_region_keys(self) -> list[str]:
            mesh = self._mapping(self.cfg.get("mesh", {}))
            raw_elements = mesh.get("elements", [])
            element_meta = {
                str(raw.get("id", index + 1)): dict(raw)
                for index, raw in enumerate(raw_elements if isinstance(raw_elements, list) else [])
                if isinstance(raw, Mapping)
            }
            regions: list[str] = []
            for item in self.scene.selectedItems():
                data = item.data(0)
                if not isinstance(data, Mapping):
                    continue
                kind = str(data.get("kind", ""))
                if kind == "geometry_region" and data.get("id") not in (None, ""):
                    regions.append(str(data.get("id")))
                    continue
                element_id = str(data.get("element", data.get("id", "")))
                if kind in {"element", "edge", "mesh_quality_violation"} and element_id:
                    meta = element_meta.get(element_id, {})
                    region_id = meta.get("region_id", data.get("region_id"))
                    if region_id not in (None, ""):
                        regions.append(str(region_id))
                        continue
                    region_number = meta.get("region", data.get("region"))
                    if region_number not in (None, ""):
                        regions.append(f"region_{region_number}")
            return list(dict.fromkeys(regions))

        def _mesh_grid_condition_defaults(self, region_keys: list[str] | None = None) -> dict[str, Any]:
            mesh = self._mesh_cfg()
            element_type = str(mesh.get("element_type", mesh.get("requested_element_type", mesh.get("type", "QUAD4")))).upper()
            if getattr(self, "mesh_type", None) is not None and self.mesh_type.currentText().strip():
                element_type = self.mesh_type.currentText().strip().upper()
            target = mesh.get("target_size", mesh.get("division_width", 1.0))
            try:
                nx = int(float(mesh.get("nx", self.mesh_nx.text() if getattr(self, "mesh_nx", None) is not None else 8) or 8))
            except (TypeError, ValueError):
                nx = 8
            try:
                ny = int(float(mesh.get("ny", self.mesh_ny.text() if getattr(self, "mesh_ny", None) is not None else 2) or 2))
            except (TypeError, ValueError):
                ny = 2
            settings = self._mesh_region_settings(mesh)
            for region_key in region_keys or []:
                for candidate in self._region_setting_key_candidates(region_key):
                    raw = settings.get(candidate)
                    if not isinstance(raw, Mapping):
                        continue
                    element_type = str(raw.get("element_type", raw.get("requested_element_type", raw.get("type", element_type)))).upper()
                    target = raw.get("target_size", raw.get("division_width", target))
                    try:
                        nx = int(float(raw.get("nx", nx) or nx))
                    except (TypeError, ValueError):
                        pass
                    try:
                        ny = int(float(raw.get("ny", ny) or ny))
                    except (TypeError, ValueError):
                        pass
                    return {
                        "element_type": element_type,
                        "requested_element_type": element_type,
                        "target_size": target,
                        "division_width": target,
                        "nx": max(1, nx),
                        "ny": max(1, ny),
                    }
            return {
                "element_type": element_type or "QUAD4",
                "requested_element_type": element_type or "QUAD4",
                "target_size": target,
                "division_width": target,
                "nx": max(1, nx),
                "ny": max(1, ny),
            }

        def _mesh_grid_condition_text(self, setting: Mapping[str, Any]) -> str:
            element_type = str(setting.get("element_type", setting.get("requested_element_type", "QUAD4"))).upper()
            try:
                target = float(setting.get("target_size", setting.get("division_width", 1.0)) or 1.0)
            except (TypeError, ValueError):
                target = 1.0
            try:
                nx = max(1, int(float(setting.get("nx", 8) or 8)))
            except (TypeError, ValueError):
                nx = 8
            try:
                ny = max(1, int(float(setting.get("ny", 2) or 2)))
            except (TypeError, ValueError):
                ny = 2
            return f"{element_type}, {target:g}, {nx}, {ny}"

        def _parse_mesh_grid_condition_text(self, text: str, defaults: Mapping[str, Any]) -> dict[str, Any]:
            tokens = [part.strip() for part in re.split(r"[,;\s]+", str(text)) if part.strip()]
            if not tokens:
                raise ValueError("格子条件を入力してください。例: QUAD4, 0.5, 4, 2")
            allowed_types = {"QUAD4", "QUAD8", "TRI3", "TRI6"}
            element_type = str(defaults.get("element_type", defaults.get("requested_element_type", "QUAD4"))).upper()
            target_raw = defaults.get("target_size", defaults.get("division_width", 1.0))
            nx_raw = defaults.get("nx", 8)
            ny_raw = defaults.get("ny", 2)
            value_index = 0
            first = tokens[0].upper()
            if first in allowed_types:
                element_type = first
                value_index = 1
            elif re.search(r"[A-Za-z]", tokens[0]):
                raise ValueError("要素種別は QUAD4 / QUAD8 / TRI3 / TRI6 のいずれかを指定してください。")
            try:
                target = float(target_raw or 1.0)
            except (TypeError, ValueError):
                target = 1.0
            try:
                nx = int(float(nx_raw or 8))
            except (TypeError, ValueError):
                nx = 8
            try:
                ny = int(float(ny_raw or 2))
            except (TypeError, ValueError):
                ny = 2
            if value_index < len(tokens):
                try:
                    target = float(tokens[value_index])
                except (TypeError, ValueError) as exc:
                    raise ValueError("密度/サイズは正の数値で指定してください。") from exc
                value_index += 1
            if value_index < len(tokens):
                try:
                    nx = int(float(tokens[value_index]))
                except (TypeError, ValueError) as exc:
                    raise ValueError("nx は正の整数で指定してください。") from exc
                value_index += 1
            if value_index < len(tokens):
                try:
                    ny = int(float(tokens[value_index]))
                except (TypeError, ValueError) as exc:
                    raise ValueError("ny は正の整数で指定してください。") from exc
                value_index += 1
            if value_index < len(tokens):
                raise ValueError("入力は「要素種別, 密度/サイズ, nx, ny」の順で指定してください。")
            if not math.isfinite(target) or target <= 0.0:
                raise ValueError("密度/サイズは正の数値で指定してください。")
            if nx <= 0 or ny <= 0:
                raise ValueError("nx と ny は正の整数で指定してください。")
            return {
                "element_type": element_type,
                "requested_element_type": element_type,
                "target_size": float(target),
                "division_width": float(target),
                "nx": int(nx),
                "ny": int(ny),
            }

        def apply_selected_geometry_grid_settings(self, *_args: Any, text: str | None = None) -> None:
            selected_regions = self._selected_mesh_region_keys()
            if not selected_regions:
                message = "格子条件を設定する形状領域をモデルビューで選択してください。"
                self.statusBar().showMessage(message)
                QMessageBox.information(self, "GeoFEM", message)
                return
            defaults = self._mesh_grid_condition_defaults(selected_regions)
            if text is None:
                default_text = self._mesh_grid_condition_text(defaults)
                entered, ok = QInputDialog.getText(
                    self,
                    "形状別格子条件",
                    "要素種別, 密度/サイズ, nx, ny",
                    QLineEdit.EchoMode.Normal,
                    default_text,
                )
                if not ok:
                    return
                text = entered
            try:
                setting = self._parse_mesh_grid_condition_text(text, defaults)
            except ValueError as exc:
                QMessageBox.warning(self, "GeoFEM", str(exc))
                return
            mesh = self._mesh_cfg()
            settings = self._mesh_region_settings(mesh)
            before = copy.deepcopy(settings)
            for region_key in selected_regions:
                for candidate in self._region_setting_key_candidates(region_key):
                    settings[candidate] = dict(setting)
            if before == settings:
                self.statusBar().showMessage("選択形状の格子条件は変更されていません。")
                return
            mesh["requires_rebuild"] = True
            mesh["stale_reason"] = f"形状別格子条件変更: {', '.join(selected_regions)}"
            mesh["geometry_revision"] = self._current_geometry_revision()
            if isinstance(mesh.get("elements"), list) and mesh.get("elements") and isinstance(mesh.get("nodes"), Mapping):
                self.reset_mesh_regions_for_rebuild(selected_regions, reason="形状別格子条件変更")
                return
            mesh["partial_rebuild_required"] = True
            mesh["region_rebuild_required"] = selected_regions
            message = f"選択形状の格子条件を設定しました: {', '.join(selected_regions)}"
            self._after_form_change(message)

        def _material_names(self) -> list[str]:
            return [str(name) for name in self._mapping(self.cfg.get("materials", {})).keys() if str(name).strip()]

        def _refresh_load_body_material_selector(self) -> None:
            combo = getattr(self, "load_body_material", None)
            if combo is None:
                return
            current_data = combo.currentData()
            current_text = combo.currentText().strip()
            combo.blockSignals(True)
            combo.clear()
            combo.addItem("選択要素の材料", "__selected__")
            for name in self._material_names():
                combo.addItem(name, name)
            selected = combo.findData(current_data) if current_data is not None else -1
            if selected < 0 and current_text:
                selected = combo.findText(current_text)
            if selected >= 0:
                combo.setCurrentIndex(selected)
            combo.blockSignals(False)
            self._refresh_operation_button_enabled_states()

        def _material_color(self, material_name: str) -> QColor:
            palette = [
                "#4c78a8",
                "#f58518",
                "#54a24b",
                "#e45756",
                "#72b7b2",
                "#b279a2",
                "#ff9da6",
                "#9d755d",
                "#6f4e7c",
                "#2f855a",
                "#d97706",
                "#0f766e",
            ]
            names = self._material_names()
            if material_name in names:
                index = names.index(material_name)
            else:
                index = int(hashlib.sha256(str(material_name).encode("utf-8")).hexdigest()[:8], 16)
            return QColor(palette[index % len(palette)])

        def _material_brush(self, material_name: str, *, alpha: int = 70) -> QBrush:
            color = self._material_color(material_name)
            color.setAlpha(max(0, min(int(alpha), 255)))
            return QBrush(color)

        def _region_material_for_id(self, region_key: str, *, index: int | None = None, raw: Mapping[str, Any] | None = None) -> str:
            if isinstance(raw, Mapping):
                material = str(raw.get("material", raw.get("mat", "")) or "").strip()
                if material:
                    return material
            mesh = self._mapping(self.cfg.get("mesh", {}))
            settings = self._mapping(mesh.get("region_settings", {}))
            candidates = self._region_setting_key_candidates(region_key)
            if index is not None:
                candidates.extend([f"region_{index + 1}", str(index + 1)])
            for candidate in dict.fromkeys(candidates):
                setting = settings.get(candidate)
                if isinstance(setting, Mapping):
                    material = str(setting.get("material", "") or "").strip()
                    if material:
                        return material
            return ""

        def _assign_material_to_regions(self, material_name: str, region_keys: list[str] | None = None) -> list[str]:
            material_name = str(material_name).strip()
            targets = list(dict.fromkeys(str(value) for value in (region_keys or self._selected_mesh_region_keys()) if str(value).strip()))
            if not material_name or not targets:
                return []
            mesh = self._mesh_cfg()
            settings = self._mesh_region_settings(mesh)
            target_candidates: set[str] = set()
            for target in targets:
                target_candidates.update(self._region_setting_key_candidates(target))
            assigned: list[str] = []
            geometry = self._geometry_cfg()
            regions = geometry.get("regions", [])
            if isinstance(regions, list):
                for index, raw in enumerate(regions):
                    if not isinstance(raw, dict):
                        continue
                    region_id = str(raw.get("id", f"region_{index + 1}") or f"region_{index + 1}")
                    candidates = set(self._region_setting_key_candidates(region_id))
                    candidates.update({f"region_{index + 1}", str(index + 1)})
                    if not candidates.intersection(target_candidates):
                        continue
                    if str(raw.get("material", "") or "") != material_name:
                        raw["material"] = material_name
                    assigned.append(region_id)
            for target in targets:
                for candidate in self._region_setting_key_candidates(target):
                    current = settings.get(candidate)
                    setting = dict(current) if isinstance(current, Mapping) else {}
                    setting["material"] = material_name
                    settings[candidate] = setting
            return list(dict.fromkeys([*assigned, *targets]))

        def _clear_material_from_regions(self, region_keys: list[str] | None = None) -> list[str]:
            targets = list(dict.fromkeys(str(value) for value in (region_keys or self._selected_mesh_region_keys()) if str(value).strip()))
            if not targets:
                return []
            mesh = self._mesh_cfg()
            settings = self._mesh_region_settings(mesh)
            target_candidates: set[str] = set()
            for target in targets:
                target_candidates.update(self._region_setting_key_candidates(target))
            changed: list[str] = []
            geometry = self._geometry_cfg()
            regions = geometry.get("regions", [])
            if isinstance(regions, list):
                for index, raw in enumerate(regions):
                    if not isinstance(raw, dict):
                        continue
                    region_id = str(raw.get("id", f"region_{index + 1}") or f"region_{index + 1}")
                    candidates = set(self._region_setting_key_candidates(region_id))
                    candidates.update({f"region_{index + 1}", str(index + 1)})
                    if not candidates.intersection(target_candidates):
                        continue
                    raw.pop("material", None)
                    raw.pop("mat", None)
                    changed.append(region_id)
            for target in targets:
                for candidate in self._region_setting_key_candidates(target):
                    current = settings.get(candidate)
                    if isinstance(current, Mapping):
                        setting = dict(current)
                        setting.pop("material", None)
                        settings[candidate] = setting
            elements = mesh.get("elements", [])
            if isinstance(elements, list):
                for raw in elements:
                    if not isinstance(raw, dict):
                        continue
                    element_regions = {
                        str(raw.get("region_id", "")),
                        str(raw.get("region", "")),
                        f"region_{raw.get('region', '')}",
                    }
                    if element_regions.intersection(target_candidates):
                        raw["material"] = ""
            return list(dict.fromkeys([*changed, *targets]))

        def _mesh_has_region_elements(self, region_keys: list[str]) -> bool:
            mesh = self._mapping(self.cfg.get("mesh", {}))
            candidate_keys: set[str] = set()
            for region_key in region_keys:
                candidate_keys.update(self._region_setting_key_candidates(region_key))
            elements = mesh.get("elements", [])
            if not isinstance(elements, list):
                return False
            for raw in elements:
                if not isinstance(raw, Mapping):
                    continue
                element_regions = {
                    str(raw.get("region_id", "")),
                    str(raw.get("region", "")),
                    f"region_{raw.get('region', '')}",
                }
                if element_regions.intersection(candidate_keys):
                    return True
            return False

        def _finish_material_assignment_change(self, region_keys: list[str], message: str = "材料割当を更新しました") -> None:
            mesh = self._mesh_cfg()
            targets = list(dict.fromkeys(str(value) for value in region_keys if str(value).strip()))
            settings = self._mapping(mesh.get("region_settings", {}))
            material_by_candidate: dict[str, str] = {}
            for target in targets:
                material = ""
                for candidate in self._region_setting_key_candidates(target):
                    raw = settings.get(candidate)
                    if isinstance(raw, Mapping):
                        material = str(raw.get("material", "") or "").strip()
                        if material:
                            break
                if not material:
                    material = self._region_material_for_id(target)
                if material:
                    for candidate in self._region_setting_key_candidates(target):
                        material_by_candidate[candidate] = material
            elements = mesh.get("elements", [])
            if isinstance(elements, list):
                for raw in elements:
                    if not isinstance(raw, dict):
                        continue
                    element_regions = {
                        str(raw.get("region_id", "")),
                        str(raw.get("region", "")),
                        f"region_{raw.get('region', '')}",
                    }
                    for candidate in element_regions:
                        material = material_by_candidate.get(candidate)
                        if material:
                            raw["material"] = material
                            break
            if str(mesh.get("stale_reason", "")).startswith("材料割当変更"):
                mesh.pop("stale_reason", None)
            self._after_form_change(message)

        def assign_material_to_selected_geometry_regions(self, material_name: str | None = None) -> None:
            selected_regions = self._selected_mesh_region_keys()
            if not selected_regions:
                message = "材料を割り当てる形状領域をモデルビューで選択してください。"
                self.statusBar().showMessage(message)
                QMessageBox.information(self, "GeoFEM", message)
                return
            materials = self._mapping(self.cfg.get("materials", {}))
            material_names = self._material_names()
            if material_name is None:
                if not material_names:
                    self.open_material_detail_for_new()
                    return
                material_name, ok = QInputDialog.getItem(self, "材料割当", "材料", material_names, 0, False)
                if not ok:
                    return
            material_name = str(material_name or "").strip()
            if material_name not in materials:
                QMessageBox.warning(self, "GeoFEM", f"材料 '{material_name}' は未定義です。材料詳細で先に登録してください。")
                return
            assigned = self._assign_material_to_regions(material_name, selected_regions)
            if not assigned:
                self.statusBar().showMessage("材料割当の対象がありません。")
                return
            self._finish_material_assignment_change(assigned, f"材料割当を更新しました: {material_name}")

        def clear_material_from_selected_geometry_regions(self) -> None:
            selected_regions = self._selected_mesh_region_keys()
            if not selected_regions:
                message = "材料割当を解除する形状領域をモデルビューで選択してください。"
                self.statusBar().showMessage(message)
                QMessageBox.information(self, "GeoFEM", message)
                return
            cleared = self._clear_material_from_regions(selected_regions)
            if not cleared:
                self.statusBar().showMessage("材料割当解除の対象がありません。")
                return
            self._after_form_change("材料割当を解除しました / 材料未割当はERRORとして扱われます")

        def open_material_detail_for_new(self, *_args: Any) -> None:
            selected_regions = self._selected_mesh_region_keys()
            default_name = f"mat_{selected_regions[0]}" if selected_regions else f"material_{len(self._material_names()) + 1}"
            if getattr(self, "material_library_name", None) is not None:
                self.material_library_name.setText(default_name)
            self._pending_material_assignment_regions = list(selected_regions)
            self._pending_material_assignment_name = default_name
            previous_panel = self._panel_key_from_tree_key(str(getattr(self, "current_panel_key", "materials")))
            previous_mode = self._current_gui_operation_mode()
            if previous_mode not in {"detail", "maintenance"}:
                self._detail_return_mode = previous_mode
                self._detail_return_panel = previous_panel
            if "materials" in getattr(self, "inline_detail_panel_keys", set()):
                self.current_panel_key = "materials"
                self._select_tree_panel("materials")
                self._apply_context_visibility("materials")
            else:
                index = self.gui_operation_mode_combo.findData("detail")
                if index >= 0:
                    self.gui_operation_mode_combo.setCurrentIndex(index)
                self._select_tree_panel("materials")
                page = self.panel_pages.get("materials")
                if page is not None:
                    self.panel_stack.setCurrentWidget(page)
                    self.tabs.setCurrentWidget(self.panel_stack)
                    self.right_panel_stack.setCurrentWidget(self.auxiliary_panel)
            self._update_auxiliary_panel("materials")
            self.statusBar().showMessage("材料詳細で新規材料を定義してください。必須項目が未入力の場合は登録されません。")

        def _material_assignment_state(self) -> dict[str, list[str]]:
            materials = self._mapping(self.cfg.get("materials", {}))
            geometry = self._mapping(self.cfg.get("geometry", {}))
            raw_regions = geometry.get("regions", [])
            missing: list[str] = []
            undefined: list[str] = []
            assigned: list[str] = []
            if isinstance(raw_regions, list):
                for index, raw in enumerate(raw_regions):
                    if not isinstance(raw, Mapping):
                        continue
                    if str(raw.get("source", "")).strip() == "mesh_rectangle_outline":
                        continue
                    region_id = str(raw.get("id", f"region_{index + 1}") or f"region_{index + 1}")
                    material = self._region_material_for_id(region_id, index=index, raw=raw)
                    if not material:
                        missing.append(region_id)
                    elif material not in materials:
                        undefined.append(f"{region_id}:{material}")
                    else:
                        assigned.append(region_id)
            if not raw_regions:
                mesh = self._mapping(self.cfg.get("mesh", {}))
                elements = mesh.get("elements", [])
                if isinstance(elements, list):
                    for raw in elements:
                        if not isinstance(raw, Mapping):
                            continue
                        eid = str(raw.get("id", ""))
                        material = str(raw.get("material", "") or "").strip()
                        if not material:
                            missing.append(eid)
                        elif material not in materials:
                            undefined.append(f"{eid}:{material}")
                        else:
                            assigned.append(eid)
            return {"missing": missing, "undefined": undefined, "assigned": assigned}

        def _material_assignment_blockers(self) -> list[dict[str, Any]]:
            state = self._material_assignment_state()
            missing = state["missing"]
            undefined = state["undefined"]
            if not missing and not undefined:
                return []
            paths = [f"geometry.regions.{region}.material" for region in missing[:5]]
            paths.extend(f"materials.{item.split(':', 1)[1]}" for item in undefined[:5])
            count = len(missing) + len(undefined)
            return [
                {
                    "source": "material_assignment",
                    "id": "materials",
                    "label": "材料割当",
                    "panel": "materials",
                    "missing_paths": paths,
                    "count": count,
                }
            ]

        def _check_geometry_material_assignments(self, add: Callable[[str, str, str, Mapping[str, Any] | None], None]) -> None:
            state = self._material_assignment_state()
            if state["missing"]:
                add("ERROR", "materials.assignment", f"材料未割当の対象: {', '.join(state['missing'][:10])}", {"regions": state["missing"][:80]})
            if state["undefined"]:
                add("ERROR", "materials.assignment", f"未定義材料の割当: {', '.join(state['undefined'][:10])}", {"regions": state["undefined"][:80]})
            if state["assigned"] and not state["missing"] and not state["undefined"]:
                add("INFO", "materials.assignment", f"材料割当済み対象 {len(state['assigned'])} 件", {"regions": state["assigned"][:80]})

        def _apply_mesh_edit_generation_settings_to_config(self) -> bool:
            mesh = self._mesh_cfg()
            selected_regions = self._selected_mesh_region_keys()
            self._mesh_edit_setting_scope_regions = selected_regions
            before = {
                "element_type": mesh.get("element_type", mesh.get("requested_element_type", mesh.get("type"))),
                "target_size": mesh.get("target_size"),
                "division_width": mesh.get("division_width"),
                "nx": mesh.get("nx"),
                "ny": mesh.get("ny"),
                "region_settings": copy.deepcopy(mesh.get("region_settings", {})),
            }
            element_type = self.mesh_edit_type.currentText().strip().upper() if getattr(self, "mesh_edit_type", None) is not None else self.mesh_type.currentText().strip().upper()
            try:
                current_nx = int(float(self.mesh_nx.text() or 8))
            except (TypeError, ValueError):
                current_nx = 8
            try:
                current_ny = int(float(self.mesh_ny.text() or 2))
            except (TypeError, ValueError):
                current_ny = 2
            nx = self._mesh_edit_int(getattr(self, "mesh_edit_nx", None), current_nx)
            ny = self._mesh_edit_int(getattr(self, "mesh_edit_ny", None), current_ny)
            target_text = self.mesh_edit_target_size.text().strip() if getattr(self, "mesh_edit_target_size", None) is not None else ""
            target: float | None = None
            if target_text:
                try:
                    parsed = float(target_text)
                    if math.isfinite(parsed) and parsed > 0.0:
                        target = parsed
                except (TypeError, ValueError):
                    target = None
            if target is None:
                bbox = self._geometry_bbox(self._mapping(self.cfg.get("geometry", {})))
                if bbox is not None:
                    width = max(float(bbox[1] - bbox[0]), 1.0e-9)
                    height = max(float(bbox[3] - bbox[2]), 1.0e-9)
                    target = max(width / max(nx, 1), height / max(ny, 1))
            if selected_regions:
                settings = self._mesh_region_settings(mesh)
                for region_key in selected_regions:
                    setting = {
                        "element_type": element_type,
                        "requested_element_type": element_type,
                        "nx": nx,
                        "ny": ny,
                    }
                    if target is not None:
                        setting["target_size"] = float(target)
                        setting["division_width"] = float(target)
                    for candidate in self._region_setting_key_candidates(region_key):
                        settings[candidate] = dict(setting)
                if element_type:
                    self._set_combo(self.mesh_type, element_type)
                self.mesh_nx.setText(str(nx))
                self.mesh_ny.setText(str(ny))
                if target is not None and getattr(self, "mesh_edit_target_size", None) is not None:
                    self.mesh_edit_target_size.setText(f"{target:g}")
                return before["region_settings"] != mesh.get("region_settings", {})
            if element_type:
                mesh["element_type"] = element_type
                mesh["requested_element_type"] = element_type
                self._set_combo(self.mesh_type, element_type)
            mesh["nx"] = nx
            mesh["ny"] = ny
            self.mesh_nx.setText(str(nx))
            self.mesh_ny.setText(str(ny))
            if target is not None:
                mesh["target_size"] = float(target)
                mesh["division_width"] = float(target)
                if getattr(self, "mesh_edit_target_size", None) is not None:
                    self.mesh_edit_target_size.setText(f"{target:g}")
            after = {
                "element_type": mesh.get("element_type", mesh.get("requested_element_type", mesh.get("type"))),
                "target_size": mesh.get("target_size"),
                "division_width": mesh.get("division_width"),
                "nx": mesh.get("nx"),
                "ny": mesh.get("ny"),
                "region_settings": copy.deepcopy(mesh.get("region_settings", {})),
            }
            return before != after

        def apply_mesh_edit_generation_settings(self, *_args: Any) -> None:
            changed = self._apply_mesh_edit_generation_settings_to_config()
            mesh = self._mesh_cfg()
            if changed:
                scoped_regions = list(getattr(self, "_mesh_edit_setting_scope_regions", []) or [])
                if scoped_regions and isinstance(mesh.get("elements"), list):
                    self.reset_mesh_regions_for_rebuild(scoped_regions, reason="メッシュ化条件変更")
                    return
                self._clear_mesh_result_for_rebuild(mesh)
                mesh["requires_rebuild"] = True
                mesh["stale_reason"] = "メッシュ化条件変更: 再構成待ち"
                mesh["geometry_revision"] = self._current_geometry_revision()
                self._after_form_change("メッシュ化条件を反映しました")
                return
            self.statusBar().showMessage("メッシュ化条件は変更されていません。")

        def _mesh_edit_radius_value(self) -> float:
            return max(self._mesh_edit_float(getattr(self, "mesh_edit_radius", None), 1.0), 1.0e-9)

        def _mesh_edit_grading_value(self) -> float:
            return max(self._mesh_edit_float(getattr(self, "mesh_edit_grading", None), 1.4), 1.0)

        def _mesh_edit_reference_point(self) -> tuple[float, float] | None:
            selected = self._selected_model_points()
            if selected:
                return selected[0]
            bounds = self._preview_bounds_for_geometry_or_mesh_config()
            x0, x1, y0, y1 = bounds
            return (x0 + x1) * 0.5, (y0 + y1) * 0.5

        def add_mesh_control_point_from_selection(self, *_args: Any) -> None:
            point = self._mesh_edit_reference_point()
            if point is None:
                QMessageBox.information(self, "GeoFEM", "制御点を追加する形状または点を選択してください。")
                return
            mesh = self._mesh_cfg()
            points = self._list_value(mesh, "control_points")
            x, y = point
            points.append({"id": f"cp_{len(points) + 1}", "point": [float(x), float(y)], "target_size": self._mesh_edit_target_size_value()})
            self._after_form_change("メッシュ制御点を追加しました")

        def add_mesh_refinement_from_selection(self, *_args: Any) -> None:
            point = self._mesh_edit_reference_point()
            if point is None:
                QMessageBox.information(self, "GeoFEM", "局所細分を追加する形状または点を選択してください。")
                return
            mesh = self._mesh_cfg()
            refinements = self._list_value(mesh, "refinements")
            x, y = point
            refinements.append({"id": f"refine_{len(refinements) + 1}", "center": [float(x), float(y)], "radius": self._mesh_edit_radius_value(), "factor": 2.0})
            self._after_form_change("メッシュ局所細分を追加しました")

        def add_mesh_size_map_from_selection(self, *_args: Any) -> None:
            point = self._mesh_edit_reference_point()
            if point is None:
                QMessageBox.information(self, "GeoFEM", "サイズ範囲を追加する形状または点を選択してください。")
                return
            mesh = self._mesh_cfg()
            size_map = self._list_value(mesh, "size_map")
            x, y = point
            size_map.append(
                {
                    "id": f"size_{len(size_map) + 1}",
                    "center": [float(x), float(y)],
                    "radius": self._mesh_edit_radius_value(),
                    "target_size": self._mesh_edit_target_size_value(),
                    "grading": self._mesh_edit_grading_value(),
                }
            )
            self._after_form_change("メッシュサイズ範囲を追加しました")

        def add_mesh_split_line_from_selection(self, *_args: Any) -> None:
            points = self._selected_model_points()
            if len(points) < 2:
                edge = self._selected_mesh_edge_points()
                if edge is not None:
                    points = [edge[0], edge[1]]
            if len(points) < 2:
                x0, x1, y0, y1 = self._preview_bounds_for_geometry_or_mesh_config()
                xm = (x0 + x1) * 0.5
                points = [(xm, y0), (xm, y1)]
            (x1, y1), (x2, y2) = points[0], points[1]
            mesh = self._mesh_cfg()
            split_lines = self._list_value(mesh, "split_lines")
            split_lines.append(
                {
                    "id": f"split_{len(split_lines) + 1}",
                    "start": [float(x1), float(y1)],
                    "end": [float(x2), float(y2)],
                    "target_size": self._mesh_edit_target_size_value(),
                    "locked": True,
                }
            )
            self._after_form_change("メッシュ分割線を追加しました")

        def _remove_mesh_control_by_data(self, data: Mapping[str, Any]) -> bool:
            mesh = self._mesh_cfg()
            kind = str(data.get("kind", ""))
            key_map = {
                "mesh_refinement": ("refinements", "local_refinements"),
                "mesh_control_point": ("control_points", "mesh_control_points"),
                "mesh_size_map": ("size_map", "local_size_map"),
                "mesh_split_line": ("split_lines", "split_line_constraints"),
            }
            keys = key_map.get(kind)
            if keys is None:
                return False
            target_id = str(data.get("id", ""))
            target_index = -1
            try:
                if data.get("index") is not None:
                    target_index = int(data.get("index"))
                elif data.get("id") is not None:
                    target_index = int(float(data.get("id"))) - 1
            except (TypeError, ValueError):
                target_index = -1
            for key in keys:
                raw_values = mesh.get(key)
                if not isinstance(raw_values, list):
                    continue
                kept: list[Any] = []
                removed = False
                for index, raw in enumerate(raw_values):
                    raw_id = str(raw.get("id", index + 1)) if isinstance(raw, Mapping) else str(index + 1)
                    matches_index = index == target_index
                    matches_id = bool(target_id) and raw_id == target_id
                    if matches_index or matches_id:
                        removed = True
                        continue
                    kept.append(raw)
                if removed:
                    mesh[key] = kept
                    return True
            return False

        def delete_selected_mesh_edit_items(self, *_args: Any) -> None:
            selected_data: list[Mapping[str, Any]] = []
            mesh_result_selected = False
            selected_regions: list[str] = []
            for item in self.scene.selectedItems():
                data = item.data(0)
                if not isinstance(data, Mapping):
                    continue
                kind = str(data.get("kind", ""))
                if kind in {"mesh_refinement", "mesh_control_point", "mesh_size_map", "mesh_split_line"}:
                    selected_data.append(data)
                elif kind == "geometry_region" and data.get("id") not in (None, ""):
                    selected_regions.append(str(data.get("id")))
                elif kind in {"element", "edge", "node", "mesh_quality_violation"}:
                    mesh_result_selected = True
            removed = 0
            for data in selected_data:
                if self._remove_mesh_control_by_data(data):
                    removed += 1
            if removed:
                self.clear_preview_selection()
                self._after_form_change(f"メッシュ制御を削除しました: {removed} 件")
                return
            if mesh_result_selected:
                target_regions = list(dict.fromkeys([*selected_regions, *self._selected_mesh_region_keys()]))
                if target_regions:
                    self.reset_mesh_regions_for_rebuild(target_regions)
                else:
                    self.reset_mesh_for_rebuild()
                return
            if selected_regions:
                self.reset_mesh_regions_for_rebuild(list(dict.fromkeys(selected_regions)))
                return
            self.statusBar().showMessage("削除するメッシュ制御またはメッシュ要素をモデルビューで選択してください。")

        def _clear_mesh_result_for_rebuild(self, mesh: dict[str, Any]) -> None:
            for key in (
                "nodes",
                "elements",
                "node_sets",
                "element_sets",
                "shape_meshes",
                "mesh_quality",
                "quality_violations",
                "auto_mesh_confirmed_at",
                "rebuilt_from_geometry_at",
                "tunnel_excluded_cells",
                "partial_rebuild_required",
                "region_rebuild_required",
                "deleted_region_meshes",
            ):
                mesh.pop(key, None)

        def reset_mesh_regions_for_rebuild(self, region_keys: list[str] | None = None, *, reason: str = "形状別メッシュ削除") -> None:
            mesh = self._mesh_cfg()
            elements = mesh.get("elements", [])
            nodes = mesh.get("nodes", {})
            if not isinstance(elements, list) or not isinstance(nodes, Mapping):
                self.reset_mesh_for_rebuild()
                return
            targets = list(dict.fromkeys(str(value) for value in (region_keys or self._selected_mesh_region_keys()) if str(value)))
            if not targets:
                self.reset_mesh_for_rebuild()
                return
            candidate_keys = set(targets)
            for target in targets:
                candidate_keys.update(self._region_setting_key_candidates(target))
            removed_ids: set[str] = set()
            kept: list[Any] = []
            for raw in elements:
                if not isinstance(raw, Mapping):
                    kept.append(raw)
                    continue
                eid = str(raw.get("id", len(kept) + 1))
                element_regions = {
                    str(raw.get("region_id", "")),
                    str(raw.get("region", "")),
                    f"region_{raw.get('region', '')}",
                }
                if element_regions.intersection(candidate_keys):
                    removed_ids.add(eid)
                    continue
                kept.append(raw)
            if not removed_ids:
                self.statusBar().showMessage("選択した形状に対応するメッシュが見つかりません。")
                return
            if not kept:
                self.reset_mesh_for_rebuild()
                return
            mesh["elements"] = kept
            used_nodes = {str(nid) for element in kept if isinstance(element, Mapping) for nid in self._ensure_list(element.get("nodes", []))}
            mesh["nodes"] = {str(nid): value for nid, value in nodes.items() if str(nid) in used_nodes}
            node_sets = mesh.get("node_sets", {})
            if isinstance(node_sets, Mapping):
                filtered_sets: dict[str, list[str]] = {}
                for name, values in node_sets.items():
                    ids = [str(nid) for nid in self._ensure_list(values) if str(nid) in used_nodes]
                    if ids:
                        filtered_sets[str(name)] = list(dict.fromkeys(ids))
                filtered_sets["all"] = list(mesh["nodes"])
                mesh["node_sets"] = filtered_sets
            element_sets = mesh.get("element_sets", {})
            kept_ids = {str(raw.get("id", index + 1)) for index, raw in enumerate(kept) if isinstance(raw, Mapping)}
            if isinstance(element_sets, Mapping):
                filtered_element_sets: dict[str, list[str]] = {}
                for name, values in element_sets.items():
                    ids = [str(eid) for eid in self._ensure_list(values) if str(eid) in kept_ids]
                    if ids:
                        filtered_element_sets[str(name)] = list(dict.fromkeys(ids))
                filtered_element_sets["all"] = [str(raw.get("id", index + 1)) for index, raw in enumerate(kept) if isinstance(raw, Mapping)]
                mesh["element_sets"] = filtered_element_sets
            shape_meshes = mesh.get("shape_meshes", [])
            if isinstance(shape_meshes, list):
                updated_shapes: list[Any] = []
                for raw_shape in shape_meshes:
                    if not isinstance(raw_shape, dict):
                        updated_shapes.append(raw_shape)
                        continue
                    shape = dict(raw_shape)
                    shape_regions = {
                        str(shape.get("region_id", "")),
                        str(shape.get("region", "")),
                        f"region_{shape.get('region', '')}",
                    }
                    if shape_regions.intersection(candidate_keys):
                        shape["element_ids"] = []
                        shape["node_ids"] = []
                        shape["element_count"] = 0
                        shape["status"] = "deleted_requires_rebuild"
                    else:
                        shape["element_ids"] = [str(eid) for eid in self._ensure_list(shape.get("element_ids", [])) if str(eid) in kept_ids]
                        shape["element_count"] = len(shape["element_ids"])
                    updated_shapes.append(shape)
                mesh["shape_meshes"] = updated_shapes
            deleted = [str(value) for value in self._ensure_list(mesh.get("deleted_region_meshes", []))]
            mesh["deleted_region_meshes"] = list(dict.fromkeys([*deleted, *targets]))
            mesh["region_rebuild_required"] = targets
            mesh["partial_rebuild_required"] = True
            mesh["requires_rebuild"] = True
            mesh["stale_reason"] = f"{reason}: {', '.join(targets)}"
            mesh["geometry_revision"] = self._current_geometry_revision()
            self.clear_preview_selection()
            self._after_form_change(f"{reason}: {len(removed_ids)} 要素を削除しました")

        def reset_mesh_for_rebuild(self, *_args: Any) -> None:
            mesh = self._mesh_cfg()
            self._clear_mesh_result_for_rebuild(mesh)
            mesh["requires_rebuild"] = True
            mesh["stale_reason"] = "メッシュ削除: 再構成待ち"
            mesh["geometry_revision"] = self._current_geometry_revision()
            self.clear_preview_selection()
            self._after_form_change("メッシュを削除し、再構成待ちにしました")

        def rebuild_mesh_from_shape(self, *_args: Any) -> None:
            geometry = self._mapping(self.cfg.get("geometry", {}))
            try:
                self._apply_mesh_edit_generation_settings_to_config()
                if self._geometry_bbox(geometry) is not None:
                    mesh_cfg = self._mesh_cfg()
                    mesh_cfg["mode"] = "auto_mixed"
                    mesh_cfg.setdefault("target_size", self._mesh_edit_target_size_value())
                    mesh_cfg.setdefault("division_width", mesh_cfg.get("target_size", self._mesh_edit_target_size_value()))
                    self.apply_auto_geometry_mesh()
                else:
                    self.apply_mesh_panel()
            except Exception as exc:
                QMessageBox.warning(self, "GeoFEM", f"メッシュ再構成に失敗しました: {exc}")

