        def show_boundary_condition_tree_context_menu(self, pos: Any) -> None:
            tree = getattr(self, "boundary_condition_tree", None)
            if tree is None:
                return
            item = tree.itemAt(pos)
            if item is None:
                return
            tree.setCurrentItem(item)
            payload = item.data(0, Qt.ItemDataRole.UserRole)
            if not isinstance(payload, Mapping) or not isinstance(payload.get("source", {}), Mapping):
                return
            kind = str(payload.get("kind", ""))
            if kind == "boundary_condition_node":
                delete_label = "この節点を境界条件から削除"
            elif kind == "boundary_condition_edge":
                delete_label = "この辺を境界条件から削除"
            else:
                delete_label = "この境界条件を削除"
            menu = QMenu(self)
            show_action = QAction("モデルで表示", self)
            show_action.triggered.connect(lambda _checked=False, payload=dict(payload): self._select_preview_payload(payload))
            menu.addAction(show_action)
            delete_action = QAction(delete_label, self)
            delete_action.triggered.connect(lambda _checked=False, item=item: self.delete_boundary_condition_tree_item(item))
            menu.addAction(delete_action)
            menu.exec(tree.viewport().mapToGlobal(pos))

        def delete_boundary_condition_tree_item(self, item: Any | None = None) -> None:
            tree = getattr(self, "boundary_condition_tree", None)
            if item is None and tree is not None:
                item = tree.currentItem()
            if item is None:
                return
            payload = item.data(0, Qt.ItemDataRole.UserRole)
            if not isinstance(payload, Mapping):
                return
            if self._delete_boundary_condition_tree_payload(payload):
                nodes = [str(node) for node in self._ensure_list(payload.get("nodes", [])) if str(node)]
                if nodes:
                    self._select_preview_payload({"nodes": nodes})

        def _delete_boundary_condition_tree_payload(self, payload: Mapping[str, Any]) -> bool:
            source = payload.get("source", {})
            if not isinstance(source, Mapping):
                return False
            scope = str(source.get("scope", ""))
            try:
                index = int(source.get("index", -1))
            except Exception:
                index = -1
            if index < 0:
                return False

            remove_nodes = [str(node) for node in self._ensure_list(payload.get("remove_nodes", [])) if str(node)]
            remove_edges = [
                tuple(str(value) for value in self._ensure_list(edge)[:2])
                for edge in self._ensure_list(payload.get("remove_edges", []))
                if len(self._ensure_list(edge)) >= 2
            ]
            delete_whole = str(payload.get("kind", "")) == "boundary_condition" and not remove_nodes and not remove_edges
            changed = False
            stage_to_restore: int | None = None

            def update_condition_list(items: Any) -> list[Any]:
                nonlocal changed
                values = list(self._ensure_list(items))
                if index >= len(values):
                    return values
                if delete_whole:
                    values.pop(index)
                    changed = True
                    return values
                raw = values[index]
                if not isinstance(raw, Mapping):
                    return values
                updated, item_changed = self._remove_boundary_tree_targets_from_spec(raw, remove_nodes=remove_nodes, remove_edges=remove_edges)
                if item_changed:
                    changed = True
                    if updated is None:
                        values.pop(index)
                    else:
                        values[index] = updated
                return values

            if scope == "global_bc":
                key = "boundary_conditions" if "boundary_conditions" in self.cfg or "bc" not in self.cfg else "bc"
                self.cfg[key] = update_condition_list(self.cfg.get(key, []))
            elif scope == "global_mpc":
                key = "mpc_constraints" if "mpc_constraints" in self.cfg or "mpc" not in self.cfg else "mpc"
                self.cfg[key] = update_condition_list(self.cfg.get(key, []))
            elif scope in {"stage_bc", "stage_mpc", "hydro"}:
                try:
                    stage_index = int(source.get("stage_index", -1))
                except Exception:
                    stage_index = -1
                stages = self._stages()
                if stage_index < 0 or stage_index >= len(stages):
                    return False
                stage_to_restore = stage_index
                stage = stages[stage_index]
                if scope == "stage_bc":
                    key = "boundary_conditions" if "boundary_conditions" in stage or "bc" not in stage else "bc"
                    stage[key] = update_condition_list(stage.get(key, []))
                elif scope == "stage_mpc":
                    key = "mpc_constraints" if "mpc_constraints" in stage or "mpc" not in stage else "mpc"
                    stage[key] = update_condition_list(stage.get(key, []))
                else:
                    hydro_key = str(source.get("hydro_key", ""))
                    if not hydro_key:
                        return False
                    hydro = stage.get("hydro", stage.get("consolidation", {}))
                    if not isinstance(hydro, Mapping):
                        return False
                    hydro_dict = dict(hydro)
                    hydro_dict[hydro_key] = update_condition_list(hydro_dict.get(hydro_key, []))
                    if not hydro_dict[hydro_key]:
                        hydro_dict.pop(hydro_key, None)
                    stage["hydro"] = hydro_dict
                stages[stage_index] = stage
                self.cfg["stages"] = stages
            else:
                return False

            if not changed:
                QMessageBox.information(self, "GeoFEM", "削除対象の境界条件項目が見つかりません。")
                return False
            self._after_form_change("境界条件ツリーから対象を削除しました")
            if stage_to_restore is not None and getattr(self, "stage_table", None) is not None:
                self.stage_table.selectRow(stage_to_restore)
                self.populate_boundary_condition_tree()
            return True

        def _remove_boundary_tree_targets_from_spec(
            self,
            raw: Mapping[str, Any],
            *,
            remove_nodes: list[str],
            remove_edges: list[tuple[str, str]],
        ) -> tuple[dict[str, Any] | None, bool]:
            spec = copy.deepcopy(dict(raw))
            node_set = {str(node) for node in remove_nodes}
            edge_set = {tuple(sorted((str(a), str(b)), key=self._natural_sort_key)) for a, b in remove_edges}
            if not node_set and not edge_set:
                return None, True

            endpoint_keys = ("master", "slave", "master_node", "slave_node")
            if node_set and any(str(spec.get(key, "")).strip() in node_set for key in endpoint_keys):
                return None, True

            changed = False

            def explicit_edges(value: Any) -> list[tuple[str, str]]:
                raw_edges = self._ensure_list(value)
                if len(raw_edges) == 2 and not isinstance(raw_edges[0], (list, tuple, Mapping)):
                    return [(str(raw_edges[0]), str(raw_edges[1]))]
                edges: list[tuple[str, str]] = []
                for raw_edge in raw_edges:
                    nodes = [str(node) for node in self._ensure_list(raw_edge)]
                    if len(nodes) >= 2:
                        edges.append((nodes[0], nodes[1]))
                return edges

            def keep_edge(edge: tuple[str, str]) -> bool:
                key = tuple(sorted((str(edge[0]), str(edge[1])), key=self._natural_sort_key))
                if key in edge_set:
                    return False
                if node_set and ({str(edge[0]), str(edge[1])} & node_set):
                    return False
                return True

            if "edge" in spec:
                edges = explicit_edges(spec.get("edge", []))
                kept = [edge for edge in edges if keep_edge(edge)]
                if len(kept) != len(edges):
                    changed = True
                    spec.pop("edge", None)
                    if kept:
                        spec["edges"] = [[a, b] for a, b in kept]
            if "edges" in spec:
                edges = explicit_edges(spec.get("edges", []))
                kept = [edge for edge in edges if keep_edge(edge)]
                if len(kept) != len(edges):
                    changed = True
                    if kept:
                        spec["edges"] = [[a, b] for a, b in kept]
                    else:
                        spec.pop("edges", None)

            if node_set:
                if "node" in spec and str(spec.get("node")) in node_set:
                    spec.pop("node", None)
                    changed = True
                if "nodes" in spec:
                    raw_nodes = spec.get("nodes")
                    if isinstance(raw_nodes, str):
                        nodes, _edges = self._boundary_condition_nodes_and_edges(spec)
                        kept_nodes = [node for node in nodes if node not in node_set]
                        if len(kept_nodes) != len(nodes):
                            spec["nodes"] = kept_nodes
                            changed = True
                    else:
                        values = self._ensure_list(raw_nodes)
                        kept_values = [value for value in values if str(value) not in node_set]
                        if len(kept_values) != len(values):
                            if kept_values:
                                spec["nodes"] = kept_values
                            else:
                                spec.pop("nodes", None)
                            changed = True
                if not changed and ("set" in spec or bool(spec.get("all", False))):
                    nodes, edges = self._boundary_condition_nodes_and_edges(spec)
                    if edges:
                        kept_edges = [edge for edge in edges if keep_edge(edge)]
                        if len(kept_edges) != len(edges):
                            spec.pop("set", None)
                            spec.pop("all", None)
                            spec.pop("nodes", None)
                            if kept_edges:
                                spec["edges"] = [[a, b] for a, b in kept_edges]
                            changed = True
                    else:
                        kept_nodes = [node for node in nodes if node not in node_set]
                        if len(kept_nodes) != len(nodes):
                            spec.pop("set", None)
                            spec.pop("all", None)
                            if kept_nodes:
                                spec["nodes"] = kept_nodes
                            changed = True

            if edge_set and not changed and ("set" in spec or bool(spec.get("all", False)) or "nodes" in spec):
                _nodes, edges = self._boundary_condition_nodes_and_edges(spec)
                kept_edges = [edge for edge in edges if keep_edge(edge)]
                if len(kept_edges) != len(edges):
                    spec.pop("set", None)
                    spec.pop("all", None)
                    spec.pop("nodes", None)
                    if kept_edges:
                        spec["edges"] = [[a, b] for a, b in kept_edges]
                    changed = True

            if not changed:
                return spec, False
            if not self._boundary_condition_spec_has_target(spec):
                return None, True
            return spec, True

        def _boundary_condition_spec_has_target(self, spec: Mapping[str, Any]) -> bool:
            for key in ("master", "slave", "master_node", "slave_node"):
                if str(spec.get(key, "")).strip():
                    return True
            for key in ("node", "nodes", "edge", "edges", "set"):
                if key in spec and self._ensure_list(spec.get(key, [])):
                    return True
            return bool(spec.get("all", False))

        def _delete_load_tree_payload(self, payload: Mapping[str, Any]) -> bool:
            source = payload.get("source", {})
            if not isinstance(source, Mapping):
                return False
            scope = str(source.get("scope", ""))
            try:
                index = int(source.get("index", -1))
            except Exception:
                index = -1
            if index < 0:
                return False
            remove_nodes = [str(node) for node in self._ensure_list(payload.get("remove_nodes", [])) if str(node)]
            remove_edges = [
                tuple(str(value) for value in self._ensure_list(edge)[:2])
                for edge in self._ensure_list(payload.get("remove_edges", []))
                if len(self._ensure_list(edge)) >= 2
            ]
            delete_whole = str(payload.get("tree_item_kind", "")) == "condition" and not remove_nodes and not remove_edges
            changed = False
            stage_to_restore: int | None = None

            def update_load_list(items: Any) -> list[Any]:
                nonlocal changed
                values = list(self._ensure_list(items))
                if index >= len(values):
                    return values
                if delete_whole:
                    values.pop(index)
                    changed = True
                    return values
                raw = values[index]
                if not isinstance(raw, Mapping):
                    return values
                updated, item_changed = self._remove_load_tree_targets_from_spec(raw, remove_nodes=remove_nodes, remove_edges=remove_edges)
                if item_changed:
                    changed = True
                    if updated is None:
                        values.pop(index)
                    else:
                        values[index] = updated
                return values

            if scope == "global_load":
                self.cfg["loads"] = update_load_list(self.cfg.get("loads", []))
            elif scope == "stage_load":
                try:
                    stage_index = int(source.get("stage_index", -1))
                except Exception:
                    stage_index = -1
                stages = self._stages()
                if stage_index < 0 or stage_index >= len(stages):
                    return False
                stage_to_restore = stage_index
                stage = stages[stage_index]
                stage["loads"] = update_load_list(stage.get("loads", []))
                stages[stage_index] = stage
                self.cfg["stages"] = stages
            else:
                return False
            if not changed:
                QMessageBox.information(self, "GeoFEM", "削除対象の荷重項目が見つかりません。")
                return False
            self._after_form_change("荷重ツリーから対象を削除しました")
            if stage_to_restore is not None and getattr(self, "stage_table", None) is not None:
                self.stage_table.selectRow(stage_to_restore)
            return True

        def _remove_load_tree_targets_from_spec(
            self,
            raw: Mapping[str, Any],
            *,
            remove_nodes: list[str],
            remove_edges: list[tuple[str, str]],
        ) -> tuple[dict[str, Any] | None, bool]:
            spec = copy.deepcopy(dict(raw))
            node_set = {str(node) for node in remove_nodes}
            edge_set = {tuple(sorted((str(a), str(b)), key=self._natural_sort_key)) for a, b in remove_edges}
            if not node_set and not edge_set:
                return None, True
            try:
                from geofem_app.fem2d import mesh_from_config

                mesh = mesh_from_config(self.cfg)
            except Exception:
                mesh = None
            changed = False

            def keep_edge(edge: tuple[str, str]) -> bool:
                key = tuple(sorted((str(edge[0]), str(edge[1])), key=self._natural_sort_key))
                if key in edge_set:
                    return False
                if node_set and ({str(edge[0]), str(edge[1])} & node_set):
                    return False
                return True

            kind = self._load_condition_kind_from_spec(spec)
            if kind == "edge":
                edges = self._edge_targets_for_spec(mesh, spec) if mesh is not None else []
                if not edges:
                    raw_edges = spec.get("edges", spec.get("edge", []))
                    raw_list = self._ensure_list(raw_edges)
                    if len(raw_list) == 2 and not isinstance(raw_list[0], (list, tuple, Mapping)):
                        edges = [(str(raw_list[0]), str(raw_list[1]))]
                    else:
                        edges = [
                            (str(nodes[0]), str(nodes[1]))
                            for nodes in ([str(value) for value in self._ensure_list(edge)] for edge in raw_list)
                            if len(nodes) >= 2
                        ]
                kept = [edge for edge in edges if keep_edge(edge)]
                if len(kept) != len(edges):
                    for key in ("edge", "edges", "nodes", "set", "all"):
                        spec.pop(key, None)
                    if kept:
                        spec["edges"] = [[a, b] for a, b in kept]
                    changed = True

            if kind == "node" and node_set:
                nodes = self._node_targets_for_spec(mesh, spec) if mesh is not None else []
                if not nodes:
                    if "node" in spec:
                        nodes = [str(spec["node"])]
                    elif "nodes" in spec:
                        nodes = [str(value) for value in self._ensure_list(spec["nodes"])]
                kept_nodes = [node for node in nodes if node not in node_set]
                if len(kept_nodes) != len(nodes):
                    for key in ("node", "nodes", "set", "all"):
                        spec.pop(key, None)
                    if kept_nodes:
                        spec["nodes"] = kept_nodes
                    changed = True

            if not changed:
                return spec, False
            if not self._load_condition_spec_has_target(spec):
                return None, True
            return spec, True

        def _load_condition_spec_has_target(self, spec: Mapping[str, Any]) -> bool:
            kind = self._load_condition_kind_from_spec(spec)
            if kind == "body":
                return True
            if kind == "edge":
                return any(key in spec for key in ("edge", "edges", "nodes", "set")) or bool(spec.get("all", False))
            return any(key in spec for key in ("node", "nodes", "set")) or bool(spec.get("all", False))

