        def apply_yaml_fragment(self, key: str, *, expected: type) -> None:
            if self._guard_input_mutation(f"{key}を反映"):
                return
            editor = getattr(self, f"{key}_editor")
            try:
                value = yaml.safe_load(editor.toPlainText())
            except Exception as exc:
                QMessageBox.warning(self, "GeoFEM", f"{key}を読めません: {exc}")
                return
            if value is None:
                value = [] if expected is list else {}
            if not isinstance(value, expected):
                QMessageBox.warning(self, "GeoFEM", f"{key}は{expected.__name__}で入力してください。")
                return
            self.cfg[key] = value
            self._after_form_change(f"{key}を反映しました")

