        def _after_form_change(self, message: str) -> None:
            if self._guard_input_mutation(message):
                self._restore_locked_input_snapshot()
                return
            current_tree_key = ""
            current_item = self.tree.currentItem() if hasattr(self, "tree") else None
            if current_item is not None:
                current_tree_key = str(current_item.data(0, Qt.ItemDataRole.UserRole) or "")
            geometry_changed = self._mark_mesh_stale_if_geometry_changed(message)
            self._model_check_dirty = True
            if geometry_changed:
                self._invalidate_cad_repair_preview_cache()
            if geometry_changed and "メッシュ再構成" not in message:
                message = f"{message} / メッシュ再構成が必要です"
            self._record_edit_snapshot(message)
            self._syncing_yaml = True
            self.yaml_editor.setPlainText(yaml.safe_dump(self.cfg, allow_unicode=True, sort_keys=False))
            self._syncing_yaml = False
            self.populate_forms()
            current_panel = self._panel_key_from_tree_key(current_tree_key or str(getattr(self, "current_panel_key", "")))
            if current_panel == "boundary_conditions":
                active_kind = str(getattr(self, "_active_boundary_condition_kind", "") or "")
                select_key = current_tree_key if current_tree_key.startswith("boundary_condition:type:") else "boundary_conditions"
                if active_kind and select_key == "boundary_conditions":
                    select_key = f"boundary_condition:type:{active_kind}"
                self._refresh_tree(select_panel=select_key)
            elif current_panel == "loads":
                active_kind = str(getattr(self, "_active_load_condition_kind", "") or "")
                select_key = current_tree_key if current_tree_key.startswith("load_condition:type:") else "loads"
                if active_kind and select_key == "loads":
                    select_key = f"load_condition:type:{active_kind}"
                self._refresh_tree(select_panel=select_key)
            elif current_panel == "materials":
                select_key = current_tree_key if current_tree_key.startswith("material_assignment:") else "materials"
                self._refresh_tree(select_panel=select_key)
            elif current_panel == "mesh":
                select_key = current_tree_key if current_tree_key.startswith("mesh_quality:") else "mesh"
                self._refresh_tree(select_panel=select_key)
            elif current_panel == "stages":
                select_key = current_tree_key if current_tree_key.startswith("stage:") else "stages"
                self._refresh_tree(select_panel=select_key)
            self._refresh_named_selection_table()
            self._refresh_selection_compare_table()
            self._refresh_input_assistance_table()
            self.request_preview_update(reset_view=True, reason=message, delay_ms=0)
            self.schedule_model_check()
            self.refresh_workflow_guidance()
            self.append_log(f"[GUI] {message}")

        def _cfg_snapshot(self) -> str:
            return yaml.safe_dump(self.cfg, allow_unicode=True, sort_keys=True)

        @staticmethod
        def _edit_history_label(message: str) -> str:
            text = re.sub(r"\s+", " ", str(message or "").strip())
            if not text:
                return "編集"
            text = text.split(" / ", 1)[0].strip()
            return text if len(text) <= 40 else text[:37] + "..."

        def _trim_edit_history_metadata(self) -> None:
            history_limit = max(1, int(getattr(self, "edit_history_limit", EDIT_HISTORY_LIMIT) or EDIT_HISTORY_LIMIT))
            for stack_name, label_name in (("edit_undo_stack", "edit_undo_labels"), ("edit_redo_stack", "edit_redo_labels")):
                stack = list(getattr(self, stack_name, []))
                labels = list(getattr(self, label_name, []))
                if len(stack) > history_limit:
                    stack = stack[-history_limit:]
                if len(labels) > len(stack):
                    labels = labels[-len(stack) :] if stack else []
                elif len(labels) < len(stack):
                    labels = ["編集"] * (len(stack) - len(labels)) + labels
                setattr(self, stack_name, stack)
                setattr(self, label_name, labels)

        def _edit_history_summary_text(self) -> str:
            self._trim_edit_history_metadata()
            undo_label = self.edit_undo_labels[-1] if self.edit_undo_labels else ("None" if self.gui_locale == "en" else "なし")
            redo_label = self.edit_redo_labels[-1] if self.edit_redo_labels else ("None" if self.gui_locale == "en" else "なし")
            if self.gui_locale == "en":
                return f"Previous: {undo_label} / Next: {redo_label}"
            return f"直前: {undo_label} / 次: {redo_label}"

        def _refresh_edit_history_display(self, panel_key: str | None = None) -> None:
            label = getattr(self, "aux_edit_history_label", None)
            if label is not None:
                panel = self._panel_key_from_tree_key(str(panel_key or getattr(self, "current_panel_key", "")))
                visible = panel in {"geometry", "mesh", "materials", "boundary_conditions", "loads"}
                label.setVisible(visible)
                label.setText(self._edit_history_summary_text())
                label.setToolTip(
                    "Undo/Redo history names for this editing workflow."
                    if self.gui_locale == "en"
                    else "Undo/Redoで戻る編集名を表示します。"
                )
            if hasattr(self, "_refresh_cad_tool_button_state"):
                self._refresh_cad_tool_button_state()
            if hasattr(self, "_refresh_mesh_tool_button_state"):
                self._refresh_mesh_tool_button_state()

        def _geometry_snapshot(self) -> str:
            geometry = self._mapping(self.cfg.get("geometry", {}))
            mesh_affecting_keys = (
                "lines",
                "regions",
                "tunnels",
                "blocks",
                "points",
                "curves",
                "arcs",
                "hatches",
                "boolean_expression",
                "cad_boolean",
            )
            mesh_geometry = {key: geometry.get(key) for key in mesh_affecting_keys if key in geometry}

            def normalize(value: Any) -> Any:
                if isinstance(value, bool) or value is None:
                    return value
                if isinstance(value, (int, float)):
                    return round(float(value), 12)
                if isinstance(value, Mapping):
                    out: dict[str, Any] = {}
                    for key, raw in value.items():
                        key_text = str(key)
                        if key_text in {"graph_stale", "diagnostics", "repair_diagnostics", "cad_repair_diagnostics"}:
                            continue
                        if key_text == "trim_edge_overrides" and isinstance(raw, Mapping):
                            filtered = {str(edge): state for edge, state in raw.items() if str(state) != "active"}
                            if filtered:
                                out[key_text] = normalize(filtered)
                            continue
                        normalized = normalize(raw)
                        if normalized in ({}, [], None, ""):
                            continue
                        out[key_text] = normalized
                    return out
                if isinstance(value, list):
                    return [normalize(item) for item in value]
                if isinstance(value, tuple):
                    return [normalize(item) for item in value]
                return value

            mesh_geometry = normalize(mesh_geometry)
            return yaml.safe_dump(mesh_geometry, allow_unicode=True, sort_keys=True)

        def _current_geometry_revision(self) -> str:
            return hashlib.sha256(self._geometry_snapshot().encode("utf-8")).hexdigest()[:12]

        def _reason_is_geometry_edit(self, reason: str) -> bool:
            text = str(reason)
            geometry_tokens = (
                "形状",
                "CAD",
                "cad",
                "geometry",
                "Geometry",
                "線分",
                "直線",
                "折れ線",
                "水位線",
                "線形",
                "端点",
                "閉合",
                "領域",
                "矩形",
                "多角形",
                "円形",
                "トンネル",
                "曲線",
                "折点",
                "点を登録",
                "補助線",
                "重複edge",
                "Boolean",
            )
            return any(token in text for token in geometry_tokens)

        def _mark_mesh_stale_if_geometry_changed(self, reason: str) -> bool:
            current = self._geometry_snapshot()
            if current == getattr(self, "_last_geometry_snapshot", ""):
                return False
            if not self._reason_is_geometry_edit(reason):
                self._last_geometry_snapshot = current
                return False
            mesh = self.cfg.setdefault("mesh", {})
            if isinstance(mesh, dict):
                self._clear_mesh_result_for_rebuild(mesh)
                mesh["requires_rebuild"] = True
                mesh["stale_reason"] = f"形状変更: {reason}"
                mesh["geometry_revision"] = self._current_geometry_revision()
                mesh["reset_by_geometry_change"] = True
            self._last_geometry_snapshot = current
            return True

        def mark_mesh_rebuilt_for_current_geometry(self) -> None:
            mesh = self._mesh_cfg()
            mesh.pop("requires_rebuild", None)
            mesh.pop("partial_rebuild_required", None)
            mesh.pop("region_rebuild_required", None)
            mesh.pop("deleted_region_meshes", None)
            mesh.pop("stale_reason", None)
            mesh.pop("reset_by_geometry_change", None)
            mesh["geometry_revision"] = self._current_geometry_revision()
            mesh["rebuilt_from_geometry_at"] = datetime.now().isoformat(timespec="seconds")

        def _record_edit_snapshot(self, message: str = "", *, force: bool = False) -> None:
            current = self._cfg_snapshot()
            previous = self._last_edit_snapshot
            history_limit = max(1, int(getattr(self, "edit_history_limit", EDIT_HISTORY_LIMIT) or EDIT_HISTORY_LIMIT))
            mode = self.edit_undo_granularity.currentData() if getattr(self, "edit_undo_granularity", None) is not None else "operation"
            group = self._edit_history_group(message)
            history_label = self._edit_history_label(message)
            if force and current and not self._suppress_edit_history:
                self.edit_undo_stack.append(current)
                self.edit_undo_labels.append(history_label)
                self.edit_undo_stack = self.edit_undo_stack[-history_limit:]
                self.edit_undo_labels = self.edit_undo_labels[-len(self.edit_undo_stack) :]
                self.edit_redo_stack.clear()
                self.edit_redo_labels.clear()
                self._last_edit_snapshot = current
                if group:
                    self._last_edit_group = group
                self._refresh_edit_history_display()
                return
            should_record = force or mode != "manual"
            if mode == "form" and group and group == self._last_edit_group and not force:
                should_record = False
            if not self._suppress_edit_history and should_record and previous and previous != current:
                self.edit_undo_stack.append(previous)
                self.edit_undo_labels.append(history_label)
                self.edit_undo_stack = self.edit_undo_stack[-history_limit:]
                self.edit_undo_labels = self.edit_undo_labels[-len(self.edit_undo_stack) :]
                self.edit_redo_stack.clear()
                self.edit_redo_labels.clear()
            self._last_edit_snapshot = current
            if group:
                self._last_edit_group = group
            self._refresh_edit_history_display()

        @staticmethod
        def _edit_history_group(message: str) -> str:
            text = str(message or "").strip()
            for token in ("を", ":", " "):
                if token in text:
                    return text.split(token, 1)[0]
            return text

        def create_manual_edit_undo_point(self, label: str = "手動戻し点") -> None:
            if self._guard_input_mutation(label):
                return
            self._record_edit_snapshot(label, force=True)
            self.statusBar().showMessage(label)

        def undo_edit(self) -> None:
            if self._guard_input_mutation("編集を元に戻す"):
                return
            if not self.edit_undo_stack:
                self.statusBar().showMessage("編集を元に戻す: 戻す履歴がありません。")
                self._refresh_edit_history_display()
                return
            current = self._cfg_snapshot()
            snapshot = self.edit_undo_stack.pop()
            label = self.edit_undo_labels.pop() if self.edit_undo_labels else "編集"
            self.edit_redo_stack.append(current)
            self.edit_redo_labels.append(label)
            self.edit_redo_stack = self.edit_redo_stack[-max(1, int(getattr(self, "edit_history_limit", EDIT_HISTORY_LIMIT) or EDIT_HISTORY_LIMIT)):]
            self.edit_redo_labels = self.edit_redo_labels[-len(self.edit_redo_stack) :]
            self._apply_edit_snapshot(snapshot, f"編集を元に戻す: {label}")
            self.statusBar().showMessage(f"Undo: {label}")
            self._refresh_edit_history_display()

        def redo_edit(self) -> None:
            if self._guard_input_mutation("編集をやり直す"):
                return
            if not self.edit_redo_stack:
                self.statusBar().showMessage("編集をやり直す: やり直す履歴がありません。")
                self._refresh_edit_history_display()
                return
            current = self._cfg_snapshot()
            snapshot = self.edit_redo_stack.pop()
            label = self.edit_redo_labels.pop() if self.edit_redo_labels else "編集"
            self.edit_undo_stack.append(current)
            self.edit_undo_labels.append(label)
            self.edit_undo_stack = self.edit_undo_stack[-max(1, int(getattr(self, "edit_history_limit", EDIT_HISTORY_LIMIT) or EDIT_HISTORY_LIMIT)):]
            self.edit_undo_labels = self.edit_undo_labels[-len(self.edit_undo_stack) :]
            self._apply_edit_snapshot(snapshot, f"編集をやり直す: {label}")
            self.statusBar().showMessage(f"Redo: {label}")
            self._refresh_edit_history_display()

        def _apply_edit_snapshot(self, snapshot: str, label: str) -> None:
            try:
                cfg = yaml.safe_load(snapshot) or {}
            except Exception as exc:
                QMessageBox.warning(self, "GeoFEM", f"{label}できません: {exc}")
                return
            self._suppress_edit_history = True
            try:
                self._load_cfg(cfg, keep_yaml=False)
            finally:
                self._suppress_edit_history = False
            self._last_edit_snapshot = snapshot
            self.append_log(f"[GUI] {label}")

        def _model_check_cache_signature(self) -> str:
            cfg = copy.deepcopy(self.cfg)
            geometry = cfg.get("geometry") if isinstance(cfg, dict) else None
            if isinstance(geometry, dict):
                for key in ("cad_repair_diagnostics", "diagnostics", "repair_diagnostics"):
                    geometry.pop(key, None)
            text = yaml.safe_dump(cfg, allow_unicode=True, sort_keys=True)
            return hashlib.sha256(text.encode("utf-8")).hexdigest()

        @staticmethod
        def _copy_model_check_issues(issues: Any) -> list[tuple[str, str, str, dict[str, Any]]]:
            copied: list[tuple[str, str, str, dict[str, Any]]] = []
            for issue in list(issues or []):
                if isinstance(issue, (list, tuple)) and len(issue) >= 4:
                    severity, target, detail, payload = issue[:4]
                    copied.append(
                        (
                            str(severity),
                            str(target),
                            str(detail),
                            dict(payload) if isinstance(payload, Mapping) else {},
                        )
                    )
                else:
                    copied.append(("WARN", "model_check", str(issue), {}))
            return copied

        def _cached_model_check_issues(self, signature: str) -> list[tuple[str, str, str, dict[str, Any]]] | None:
            if signature and signature == getattr(self, "_model_check_cached_signature", ""):
                return self._copy_model_check_issues(getattr(self, "_model_check_cache_issues", []))
            return None

        def _store_model_check_cache(self, signature: str, issues: Any) -> None:
            if not signature:
                return
            self._model_check_cached_signature = signature
            self._model_check_cache_issues = self._copy_model_check_issues(issues)

        def run_model_check(self) -> None:
            self._model_check_dirty = False
            signature = self._model_check_cache_signature()
            cached = self._cached_model_check_issues(signature)
            if cached is not None:
                self._apply_model_check_issues(cached)
                return
            issues = self.collect_model_issues()
            self._store_model_check_cache(signature, issues)
            self._apply_model_check_issues(issues)

        def schedule_model_check(self, delay_ms: int = 150) -> None:
            if self._model_check_job_id:
                self._model_check_reschedule_pending = True
                return
            self.model_check_timer.start(max(0, int(delay_ms)))

        def run_model_check_async(self) -> None:
            self._model_check_dirty = False
            if self._model_check_job_id:
                self._model_check_reschedule_pending = True
                self.statusBar().showMessage(self.ui_message("status.model_check.running"))
                return
            signature = self._model_check_cache_signature()
            cached = self._cached_model_check_issues(signature)
            if cached is not None:
                self._apply_model_check_issues(cached)
                self.statusBar().showMessage("Model check reused cached diagnostics.")
                return
            cfg_snapshot = self._config_with_external_mesh_base_dir()
            target = str(self.current_input) if self.current_input is not None else "current-config"
            job_id = self.gui_jobs.start_job("model_check", target=target, metadata={"mode": "async"})
            self._model_check_job_id = job_id
            self._model_check_job_snapshot = signature
            self.check_summary.setText(
                "Model check is running in the background..."
                if self.gui_locale == "en"
                else "モデルチェックをバックグラウンド実行中..."
            )
            self.statusBar().showMessage(self.check_summary.text())
            runner = QtCallableRunner(job_id, lambda: collect_model_issues_snapshot(type(self), cfg_snapshot))
            self._gui_task_runners[job_id] = runner
            runner.signals.finished.connect(self._model_check_finished)
            runner.signals.failed.connect(self._model_check_failed)
            self.gui_thread_pool.start(runner)

        def _model_check_finished(self, job_id: str, issues_obj: Any) -> None:
            if job_id != self._model_check_job_id:
                self._gui_task_runners.pop(job_id, None)
                return
            issues = list(issues_obj or [])
            self._complete_gui_worker_job(job_id, status="finished", message=f"{len(issues)} issues")
            self._model_check_job_id = ""
            self._store_model_check_cache(getattr(self, "_model_check_job_snapshot", ""), issues)
            self._model_check_job_snapshot = ""
            self._apply_model_check_issues(issues)
            self.append_log(f"[GUI] モデルチェック完了: {len(issues)}件")
            self._restart_pending_model_check()

        def _model_check_failed(self, job_id: str, message: str) -> None:
            if job_id != self._model_check_job_id:
                self._gui_task_runners.pop(job_id, None)
                return
            manifest = self._write_gui_worker_failure_manifest(job_id, message)
            self._complete_gui_worker_job(job_id, status="failed", message=message)
            self._model_check_job_id = ""
            self._model_check_job_snapshot = ""
            self._apply_model_check_issues([("ERROR", "model_check", message, {})])
            suffix = f" manifest={manifest}" if manifest is not None else ""
            self.append_log(f"[GUI] モデルチェック失敗: {message}{suffix}")
            self._restart_pending_model_check()

        def _restart_pending_model_check(self) -> None:
            if self._model_check_reschedule_pending:
                self._model_check_reschedule_pending = False
                self.model_check_timer.start(100)

        def _apply_model_check_issues(self, issues: list[tuple[str, str, str, dict[str, Any]]]) -> None:
            apply_model_check_issues_view(self, issues, self._model_check_panel_qt())
            self._refresh_input_assistance_table()
            self.refresh_input_issue_tab_states()

        def _refresh_input_assistance_table(self) -> None:
            table = getattr(self, "input_assist_table", None)
            if table is None:
                return
            try:
                summary = build_input_assistance_summary(self.cfg, locale=str(getattr(self, "gui_locale", DEFAULT_GUI_LOCALE)))
            except Exception:
                summary = {"guidance_rows": []}
            rows = [row for row in summary.get("guidance_rows", []) if isinstance(row, Mapping)]
            table.setRowCount(min(len(rows), 240))
            fields = ["area", "path", "field", "unit", "recommended", "prohibited", "status", "message", "template_id"]
            for row_index, row in enumerate(rows[:240]):
                for col, field in enumerate(fields):
                    table.setItem(row_index, col, QTableWidgetItem(str(row.get(field, ""))))
            table.resizeRowsToContents()

        def collect_model_issues(self) -> list[tuple[str, str, str, dict[str, Any]]]:
            issues: list[tuple[str, str, str, dict[str, Any]]] = []

            def add(severity: str, target: str, detail: str, payload: Mapping[str, Any] | None = None) -> None:
                issues.append((severity, target, detail, dict(payload or {})))

            try:
                assistance = build_input_assistance_summary(self.cfg, locale=str(getattr(self, "gui_locale", DEFAULT_GUI_LOCALE)))
                for row in assistance.get("diagnostics", []):
                    if not isinstance(row, Mapping):
                        continue
                    severity = str(row.get("severity", "INFO"))
                    if severity not in {"ERROR", "WARN"}:
                        continue
                    issue_path = str(row.get("path", ""))
                    add(
                        severity,
                        f"入力補助.{issue_path}",
                        str(row.get("message", "")),
                        {"path": issue_path, "suggestion": row.get("suggestion", ""), "source": "input_assistance"},
                    )
                if not assistance.get("diagnostics", []):
                    add("INFO", "入力補助", f"単位系 {assistance.get('unit_system', '')} / 補助項目 {assistance.get('guidance_count', 0)} 件")
            except Exception as exc:
                add("WARN", "入力補助", f"入力補助診断を生成できません: {exc}")

            self._check_geometry_material_assignments(add)

            try:
                from geofem_app.fem2d import (
                    collect_constraints,
                    interfaces_from_config,
                    mesh_from_config,
                    plane_strain_materials,
                    validate_2d_core_scope,
                )

                validate_2d_core_scope(self.cfg)
                mesh = mesh_from_config(self.cfg)
                materials = plane_strain_materials(self.cfg)
                interfaces = interfaces_from_config(self.cfg, mesh)
                add("INFO", "mesh", f"節点 {len(mesh.node_ids)} / 要素 {len(mesh.elements)} / インターフェース {len(interfaces)}")
                structural = [raw for raw in self._ensure_list(self.cfg.get("structural_elements", [])) if isinstance(raw, Mapping)]
                if structural:
                    add("INFO", "element_library", f"梁/棒/バネ要素 {len(structural)} 件を2D解析接続済みライブラリとして保持")
                analysis = self._mapping(self.cfg.get("analysis", {}))
                is_axisymmetric = str(analysis.get("type", "")).lower().startswith("axisymmetric") or bool(analysis.get("axisymmetric", False)) or str(analysis.get("geometry", "")).lower() == "axisymmetric"
                if is_axisymmetric:
                    min_radius = float(mesh.coords[:, 0].min()) if len(mesh.node_ids) else 0.0
                    if min_radius < -1.0e-12:
                        bad_nodes = [nid for i, nid in enumerate(mesh.node_ids) if float(mesh.coords[i, 0]) < -1.0e-12]
                        add("ERROR", "axisymmetric", f"軸対称解析では半径Xが負の節点があります: min={min_radius:g}", {"nodes": bad_nodes[:80]})
                    else:
                        add("INFO", "axisymmetric", f"軸対称半径X範囲 OK: min={min_radius:g}")
                add("INFO", "materials", f"{len(materials)} 件")
                if not materials:
                    add("ERROR", "materials", "材料がありません。")
                missing = [element.id for element in mesh.elements if element.material not in materials]
                if missing:
                    add("ERROR", "materials", f"未定義材料を参照する要素: {', '.join(missing[:10])}", {"elements": missing[:50]})
                self._check_duplicate_elements(mesh, add)
                self._check_mesh_quality_thresholds(mesh, add)
                used_nodes = {nid for element in mesh.elements for nid in element.nodes}
                for interface in interfaces:
                    used_nodes.update(interface.minus_nodes)
                    used_nodes.update(interface.plus_nodes)
                node_set = set(mesh.node_ids)
                for idx, raw in enumerate(structural, start=1):
                    nodes = [str(nid) for nid in self._ensure_list(raw.get("nodes", []))]
                    missing_structural = [nid for nid in nodes if nid not in node_set]
                    if missing_structural:
                        add("ERROR", f"structural_elements[{idx}]", f"未定義節点: {', '.join(missing_structural[:8])}", {"nodes": missing_structural[:80]})
                    else:
                        used_nodes.update(nodes)
                isolated_nodes = [nid for nid in mesh.node_ids if nid not in used_nodes]
                if isolated_nodes:
                    add("WARN", "mesh", f"未接続節点: {', '.join(isolated_nodes[:12])}", {"nodes": isolated_nodes[:80]})
                bad_area: list[str] = []
                inverted: list[str] = []
                for element in mesh.elements:
                    corner_count = 3 if element.type.startswith("TRI") else 4
                    points = [mesh.coords[mesh.node_index[nid]] for nid in element.nodes[:corner_count]]
                    area2 = 0.0
                    for a, b in zip(points, points[1:] + points[:1]):
                        area2 += float(a[0] * b[1] - b[0] * a[1])
                    if abs(area2) <= 1.0e-12:
                        bad_area.append(element.id)
                    elif area2 < 0.0:
                        inverted.append(element.id)
                if bad_area:
                    add("ERROR", "mesh", f"ゼロ/極小面積要素: {', '.join(bad_area[:10])}", {"elements": bad_area[:50]})
                if inverted:
                    add("ERROR", "mesh", f"負面積(節点順反転)要素: {', '.join(inverted[:10])}", {"elements": inverted[:50]})
                merged_check_bcs = list(self._ensure_list(self.cfg.get("boundary_conditions", self.cfg.get("bc", []))))
                global_check_bcs = list(merged_check_bcs)
                self._check_boundary_conflicts(mesh, global_check_bcs, "boundary_conditions", add)
                for idx, bc in enumerate(merged_check_bcs, start=1):
                    self._check_node_target(mesh, bc, f"boundary_conditions[{idx}]", add)
                for stage in self._stages():
                    merged_check_bcs.extend(self._ensure_list(stage.get("boundary_conditions", stage.get("bc", []))))
                for stage_index, stage in enumerate(self._stages(), start=1):
                    for idx, bc in enumerate(self._ensure_list(stage.get("boundary_conditions", stage.get("bc", []))), start=1):
                        self._check_node_target(mesh, bc, f"stages[{stage_index}].boundary_conditions[{idx}]", add)
                try:
                    constraints = collect_constraints(mesh, merged_check_bcs)
                except Exception as exc:
                    constraints = {}
                    add("ERROR", "boundary_conditions", f"拘束条件の解釈に失敗しました: {exc}")
                if not constraints:
                    add("WARN", "boundary_conditions", "変位拘束がありません。剛体モードの可能性があります。")
                else:
                    add("INFO", "boundary_conditions", f"拘束DOF {len(constraints)}")
                if constraints:
                    self._check_rigid_body_modes(mesh, constraints, "boundary_conditions", add)
                loads = self._ensure_list(self.cfg.get("loads", []))
                for idx, load in enumerate(loads, start=1):
                    self._check_load_target(mesh, load, f"loads[{idx}]", add)
                self._check_load_boundary_inconsistency(mesh, constraints, loads, "loads", add)
                stages = self._stages()
                if is_axisymmetric:
                    self._check_axisymmetric_gui_model(mesh, constraints, loads, stages, add)
                self._check_duplicate_stage_names(stages, add)
                active_after_previous = {element.id for element in mesh.elements if element.active}
                analysis_fields = {str(field).lower() for field in self._ensure_list(analysis.get("fields", ["u"]))}
                for stage_index, stage in enumerate(stages, start=1):
                    label = f"stages[{stage_index}]"
                    stype = str(stage.get("type", "")).lower().strip()
                    self._check_stage_scalar_consistency(stage, label, analysis_fields, add)
                    has_element_ref = any(key in stage for key in ("set", "element_set", "elementSet", "element", "elements")) or bool(stage.get("all", False))
                    if has_element_ref:
                        targets = self._stage_element_targets(mesh, stage)
                        if not targets:
                            add("ERROR", label, "ステージの要素参照が空または不正です。", {})
                    if stype in {"excavation", "death", "deactivate"} and not self._stage_element_targets(mesh, stage):
                        add("ERROR", label, "掘削/deathステージに有効な対象要素がありません。")
                    if stype in {"excavation", "death", "deactivate"}:
                        targets = self._stage_element_targets(mesh, stage)
                        already_inactive = sorted(targets - active_after_previous, key=self._natural_sort_key)
                        if already_inactive:
                            add("WARN", label, f"すでに非アクティブな要素を再掘削/death対象にしています: {', '.join(already_inactive[:10])}", {"elements": already_inactive[:50]})
                        active_after_previous.difference_update(targets)
                    for prop_index, prop in enumerate(self._ensure_list(stage.get("element_properties", [])), start=1):
                        if not isinstance(prop, Mapping):
                            add("ERROR", f"{label}.element_properties[{prop_index}]", "要素プロパティはマッピングで指定してください。")
                            continue
                        targets = self._element_targets_for_spec(mesh, prop)
                        if not targets:
                            add("ERROR", f"{label}.element_properties[{prop_index}]", "要素プロパティの対象セット/要素が不正です。")
                        material = str(prop.get("material", "")).strip()
                        if material and material not in materials:
                            add("ERROR", f"{label}.element_properties[{prop_index}]", f"未定義材料 '{material}' を参照しています。", {"elements": list(targets)[:50]})
                    stage_bcs = self._ensure_list(stage.get("boundary_conditions", stage.get("bc", [])))
                    stage_constraints: dict[int, float] = {}
                    self._check_boundary_conflicts(mesh, global_check_bcs + list(stage_bcs), f"{label}.boundary_conditions", add)
                    try:
                        stage_constraints = collect_constraints(mesh, global_check_bcs + list(stage_bcs))
                        self._check_rigid_body_modes(mesh, stage_constraints, label, add, active_elements=self._active_elements_after_stage_index(mesh, stage_index - 1))
                    except Exception as exc:
                        add("ERROR", f"{label}.boundary_conditions", f"ステージ拘束条件の解釈に失敗しました: {exc}")
                    for idx, load in enumerate(self._ensure_list(stage.get("loads", [])), start=1):
                        self._check_load_target(mesh, load, f"{label}.loads[{idx}]", add)
                    self._check_load_boundary_inconsistency(mesh, stage_constraints, self._ensure_list(stage.get("loads", [])), f"{label}.loads", add)
                    hydro = stage.get("hydro", stage.get("consolidation", {}))
                    if isinstance(hydro, Mapping):
                        for key in ("pressure_bcs", "pore_pressure_bcs", "pore_flux_bcs", "pore_robin_bcs"):
                            for idx, spec in enumerate(self._ensure_list(hydro.get(key, [])), start=1):
                                self._check_pore_target(mesh, spec, f"{label}.hydro.{key}[{idx}]", add)
                    for idx, spec in enumerate(self._ensure_list(stage.get("mpc_constraints", stage.get("mpc", []))), start=1):
                        if not isinstance(spec, Mapping):
                            add("ERROR", f"{label}.mpc[{idx}]", "MPCはマッピングで指定してください。")
                            continue
                        master = str(spec.get("master", spec.get("master_node", ""))).strip()
                        slave = str(spec.get("slave", spec.get("slave_node", ""))).strip()
                        missing_nodes = [nid for nid in (master, slave) if not nid or nid not in mesh.node_index]
                        dof_name = str(spec.get("dof", spec.get("component", "ux"))).lower().strip()
                        if missing_nodes:
                            add("ERROR", f"{label}.mpc[{idx}]", f"MPCのmaster/slave節点が不正です: {', '.join(missing_nodes)}", {"nodes": [nid for nid in missing_nodes if nid in mesh.node_index]})
                        elif dof_name not in {"ux", "uy"}:
                            add("ERROR", f"{label}.mpc[{idx}]", f"MPCのDOFが2Dで未対応です: {dof_name}")
                        else:
                            add("INFO", f"{label}.mpc[{idx}]", "MPC対象を確認しました。", {"nodes": [master, slave]})
                has_stage_loads = any(self._ensure_list(stage.get("loads", [])) for stage in stages)
                if not loads and not has_stage_loads and not stages:
                    add("WARN", "loads", "荷重またはステージ荷重がありません。")
                stages = self.cfg.get("stages", self.cfg.get("steps", []))
                if stages:
                    add("INFO", "stages", f"{len(stages)} ステージ")
                geometry = self._mapping(self.cfg.get("geometry", {}))
                line_count = len(geometry.get("lines", [])) if isinstance(geometry.get("lines", []), list) else 0
                tunnel_count = len(geometry.get("tunnels", [])) if isinstance(geometry.get("tunnels", []), list) else 0
                if line_count or tunnel_count:
                    add("INFO", "geometry", f"登録線 {line_count} / トンネル {tunnel_count}")
                checks = self._mapping(self.cfg.get("checks", {}))
                near = self._mapping(checks.get("near_points", {}))
                if near:
                    count = int(near.get("count", 0))
                    severity = "WARN" if count else "INFO"
                    add(severity, "near_points", f"{count} 件 / 許容距離 {near.get('tolerance')}")
            except Exception as exc:
                add("ERROR", "model", str(exc))
            return issues

        def request_preview_update(self, *, reset_view: bool = False, reason: str = "", delay_ms: int | None = None) -> None:
            if not hasattr(self, "preview_update_timer"):
                self.update_preview(reset_view=reset_view)
                return
            self._preview_update_pending_reset_view = self._preview_update_pending_reset_view or bool(reset_view)
            if reason:
                self._preview_update_pending_reason = reason
            if self.preview_update_timer.isActive():
                self.preview_update_timer.stop()
            delay = max(0, int(delay_ms if delay_ms is not None else self._preview_update_delay_ms))
            if delay == 0:
                self._run_pending_preview_update()
                return
            self.preview_update_timer.start(delay)

        def _run_pending_preview_update(self) -> None:
            reset_view = bool(self._preview_update_pending_reset_view)
            self._preview_update_pending_reset_view = False
            self._preview_update_pending_reason = ""
            if self._start_preview_mesh_worker_if_needed(reset_view=reset_view):
                return
            self.update_preview(reset_view=reset_view)

        def _preview_mesh_cache_signature(self) -> str:
            payload = {
                "mesh": self.cfg.get("mesh", {}),
                "sets": self.cfg.get("sets", {}),
                "default_material": self.cfg.get("default_material", ""),
                "input_base_dir": str(self.current_input.resolve().parent) if self.current_input is not None else "",
            }
            text = yaml.safe_dump(payload, allow_unicode=True, sort_keys=True)
            return hashlib.sha256(text.encode("utf-8")).hexdigest()

        def _config_with_external_mesh_base_dir(self) -> dict[str, Any]:
            cfg = copy.deepcopy(dict(self.cfg))
            mesh = cfg.get("mesh")
            if isinstance(mesh, Mapping) and str(mesh.get("source", "")).strip().lower() in {"external", "file"} and self.current_input is not None:
                updated_mesh = dict(mesh)
                updated_mesh.setdefault("base_dir", str(self.current_input.resolve().parent))
                cfg["mesh"] = updated_mesh
            return cfg

        def _preview_mesh_estimated_size(self) -> tuple[int, int]:
            mesh = self._mapping(self.cfg.get("mesh", {}))
            generator = str(mesh.get("generator", "")).strip().lower()
            if generator in {"rectangle", "structured_rectangle", "quad_rect", "tri_rect"}:
                try:
                    nx = max(1, int(mesh.get("nx", 1)))
                    ny = max(1, int(mesh.get("ny", 1)))
                except Exception:
                    return (0, 0)
                etype = str(mesh.get("element_type", mesh.get("type", "QUAD4"))).upper()
                element_count = nx * ny * (2 if etype.startswith("TRI") else 1)
                node_count = (nx + 1) * (ny + 1)
                if etype in {"TRI6", "QUAD8"}:
                    node_count += element_count * 2
                return (node_count, element_count)
            nodes = mesh.get("nodes", {})
            elements = mesh.get("elements", [])
            node_count = len(nodes) if isinstance(nodes, Mapping) else (len(nodes) if isinstance(nodes, list) else 0)
            element_count = len(elements) if isinstance(elements, list) else 0
            return (node_count, element_count)

        def _start_preview_mesh_worker_if_needed(self, *, reset_view: bool) -> bool:
            key = self._preview_mesh_cache_signature()
            if key == getattr(self, "_preview_mesh_cache_key", "") and getattr(self, "_preview_mesh_cache_value", None) is not None:
                return False
            node_count, element_count = self._preview_mesh_estimated_size()
            if max(node_count, element_count) < 50000:
                return False
            if getattr(self, "_preview_mesh_worker_job_id", "") and key == getattr(self, "_preview_mesh_worker_signature", ""):
                self._preview_mesh_worker_reset_view = self._preview_mesh_worker_reset_view or reset_view
                return True
            cfg_snapshot = copy.deepcopy(self.cfg)
            job_id = self.gui_jobs.start_job("preview_mesh", target="model_preview", metadata={"signature": key, "nodes": node_count, "elements": element_count})
            self._preview_mesh_worker_job_id = job_id
            self._preview_mesh_worker_signature = key
            self._preview_mesh_worker_reset_view = reset_view
            runner = QtCallableRunner(job_id, lambda: __import__("geofem_app.fem2d", fromlist=["mesh_from_config"]).mesh_from_config(cfg_snapshot))
            self._gui_task_runners[job_id] = runner
            runner.signals.finished.connect(self._preview_mesh_worker_finished)
            runner.signals.failed.connect(self._preview_mesh_worker_failed)
            self.gui_thread_pool.start(runner)
            self.scene.clear()
            self.scene.addText("大規模メッシュのプレビューをバックグラウンド生成中...")
            self.statusBar().showMessage("大規模メッシュのプレビュー生成をバックグラウンド実行中...")
            return True

        def _preview_mesh_worker_finished(self, job_id: str, mesh: Any) -> None:
            if job_id != getattr(self, "_preview_mesh_worker_job_id", ""):
                self._gui_task_runners.pop(job_id, None)
                return
            key = getattr(self, "_preview_mesh_worker_signature", "")
            reset_view = bool(getattr(self, "_preview_mesh_worker_reset_view", False))
            self._complete_gui_worker_job(job_id, status="finished", message="preview mesh generated")
            self._preview_mesh_worker_job_id = ""
            self._preview_mesh_worker_signature = ""
            self._preview_mesh_worker_reset_view = False
            self._preview_mesh_cache_key = key
            self._preview_mesh_cache_value = mesh
            self.update_preview(reset_view=reset_view)

        def _preview_mesh_worker_failed(self, job_id: str, message: str) -> None:
            if job_id != getattr(self, "_preview_mesh_worker_job_id", ""):
                self._gui_task_runners.pop(job_id, None)
                return
            self._complete_gui_worker_job(job_id, status="failed", message=message)
            self._preview_mesh_worker_job_id = ""
            self._preview_mesh_worker_signature = ""
            self._preview_mesh_worker_reset_view = False
            self.scene.clear()
            self.scene.addText(f"プレビュー生成に失敗しました: {message}")
            self.append_log(f"[GUI] 大規模メッシュプレビュー生成失敗: {message}")

        def _record_preview_performance(self, started_at: float, panel_key: str, mesh: Any | None = None, *, mode: str = "sync") -> None:
            node_count = len(getattr(mesh, "node_ids", []) or []) if mesh is not None else 0
            element_count = len(getattr(mesh, "elements", []) or []) if mesh is not None else 0
            self.preview_performance_profile = {
                "schema": "geofem.gui.preview_performance.v1",
                "panel": str(panel_key),
                "mode": str(mode),
                "elapsed_seconds": max(time.perf_counter() - float(started_at), 0.0),
                "node_count": node_count,
                "element_count": element_count,
                "scene_item_count": len(self.scene.items()) if getattr(self, "scene", None) is not None else 0,
                "recorded_at": datetime.now().isoformat(timespec="seconds"),
            }

        def _preview_mesh_from_config(self) -> Any:
            key = self._preview_mesh_cache_signature()
            cached = getattr(self, "_preview_mesh_cache_value", None)
            if key == getattr(self, "_preview_mesh_cache_key", "") and cached is not None:
                return cached
            from geofem_app.fem2d import mesh_from_config

            cfg = self._config_with_external_mesh_base_dir()
            mesh = mesh_from_config(cfg)
            self._preview_mesh_cache_key = key
            self._preview_mesh_cache_value = mesh
            return mesh

        def _invalidate_cad_repair_preview_cache(self) -> None:
            self._preview_cad_repair_cache_key = ""
            self._preview_cad_repair_cache_value = {}
            self._geometry_repair_line_ids = set()
            self._geometry_repair_endpoint_keys = set()

        def _apply_cad_repair_diagnostics_summary(self, summary: Mapping[str, Any]) -> None:
            self._geometry_repair_line_ids = set(str(value) for value in summary.get("repair_line_ids", []))
            self._geometry_repair_endpoint_keys = {
                (str(value[0]), str(value[1]))
                for value in summary.get("repair_endpoint_keys", [])
                if isinstance(value, (list, tuple)) and len(value) == 2
            }

        def _store_cad_repair_diagnostics_cache(self, diagnostics: Any, key: str | None = None) -> dict[str, Any]:
            cache_key = key if key is not None else self._geometry_snapshot()
            payload = dict(diagnostics) if isinstance(diagnostics, Mapping) else {}
            self._preview_cad_repair_cache_key = cache_key
            self._preview_cad_repair_cache_value = payload
            summary = payload.get("summary", {})
            if isinstance(summary, Mapping):
                self._apply_cad_repair_diagnostics_summary(summary)
            return payload

        def _cad_repair_diagnostics_for_geometry(self) -> Mapping[str, Any]:
            key = self._geometry_snapshot()
            cached = getattr(self, "_preview_cad_repair_cache_value", {})
            if key == getattr(self, "_preview_cad_repair_cache_key", "") and isinstance(cached, Mapping):
                summary = cached.get("summary", {})
                if isinstance(summary, Mapping):
                    self._apply_cad_repair_diagnostics_summary(summary)
                return cached
            try:
                diagnostics = self.cad_repair_diagnostics_snapshot()
            except Exception:
                diagnostics = {}
            return self._store_cad_repair_diagnostics_cache(diagnostics, key)

        def _cad_repair_preview_summary(self) -> Mapping[str, Any]:
            diagnostics = self._cad_repair_diagnostics_for_geometry()
            summary = diagnostics.get("summary", {}) if isinstance(diagnostics, Mapping) else {}
            if not isinstance(summary, Mapping):
                summary = {}
            self._apply_cad_repair_diagnostics_summary(summary)
            return summary

        def _preview_render_signature(self, panel_key: str) -> str:
            set_value = ""
            if getattr(self, "set_display", None) is not None:
                set_value = str(self.set_display.currentData() or "")
            display = {
                "panel": panel_key,
                "cfg": self._cfg_snapshot(),
                "post_mode": getattr(self, "post_mode", ""),
                "post_component": getattr(self, "post_component", ""),
                "set": set_value,
                "quality": str(self.display_quality_mode.currentData() if getattr(self, "display_quality_mode", None) is not None else "auto"),
                "detail_limit": self.display_detail_limit.text() if getattr(self, "display_detail_limit", None) is not None else "",
                "show_nodes": bool(getattr(self, "show_node_ids", None) is not None and self.show_node_ids.isChecked()),
                "show_elements": bool(getattr(self, "show_element_ids", None) is not None and self.show_element_ids.isChecked()),
                "show_grid": bool(getattr(self, "show_grid_lines", None) is not None and self.show_grid_lines.isChecked()),
                "grid": self.snap_grid_size.text() if getattr(self, "snap_grid_size", None) is not None else "",
                "stage_dir": str(getattr(self, "result_stage_dir", "") or ""),
                "result_counts": (
                    len(getattr(self, "result_displacements", {}) or {}),
                    len(getattr(self, "result_element_values", {}) or {}),
                    len(getattr(self, "result_node_values", {}) or {}),
                    len(getattr(self, "result_distribution", []) or []),
                ),
            }
            text = yaml.safe_dump(display, allow_unicode=True, sort_keys=True)
            return hashlib.sha256(text.encode("utf-8")).hexdigest()

        def _preview_selection_stride(self, total: int, display_policy: DisplayQualityPolicy) -> int:
            if not display_policy.reduced:
                return 1
            limit = max(100, min(1200, int(getattr(display_policy, "max_vectors", 400) or 400) * 3))
            return max(1, math.ceil(max(0, int(total)) / limit))

        def _preview_item_selectable(self, index: int, total: int, display_policy: DisplayQualityPolicy, *, highlighted: bool = False) -> bool:
            if highlighted:
                return True
            stride = self._preview_selection_stride(total, display_policy)
            return stride <= 1 or int(index) % stride == 0

        @staticmethod
        def _add_polygon_to_path(path: Any, points: list[Any]) -> None:
            if len(points) < 3:
                return
            path.moveTo(points[0])
            for point in points[1:]:
                path.lineTo(point)
            path.closeSubpath()

        @staticmethod
        def _add_line_to_path(path: Any, p0: Any, p1: Any) -> None:
            path.moveTo(p0)
            path.lineTo(p1)

        def _draw_batched_mesh_elements(
            self,
            mesh: Any,
            scale: float,
            ox: float,
            oy: float,
            *,
            node_index: Mapping[str, int],
            edge_map: Mapping[str, list[tuple[int, int]]],
            stage_active: set[str],
            set_elements: set[str],
            set_label: str,
            fill: QBrush,
            pen: QPen,
            set_fill: QBrush,
            set_pen: QPen,
            original_mesh_faded: bool,
            faded_fill: QBrush,
            faded_inactive_fill: QBrush,
            faded_pen: QPen,
        ) -> None:
            active_path = QPainterPath()
            inactive_path = QPainterPath()
            edge_path = QPainterPath()
            batched_count = 0
            for element in mesh.elements:
                ids = [node_index[nid] for nid in element.nodes]
                corner_count = 3 if element.type.startswith("TRI") else 4
                polygon_points = [
                    QPointF(float(mesh.coords[idx, 0]) * scale + ox, oy - float(mesh.coords[idx, 1]) * scale)
                    for idx in ids[:corner_count]
                ]
                if element.id in set_elements:
                    continue
                target_path = active_path if element.id in stage_active else inactive_path
                self._add_polygon_to_path(target_path, polygon_points)
                for a, b in edge_map[element.type]:
                    pa = QPointF(float(mesh.coords[ids[a], 0]) * scale + ox, oy - float(mesh.coords[ids[a], 1]) * scale)
                    pb = QPointF(float(mesh.coords[ids[b], 0]) * scale + ox, oy - float(mesh.coords[ids[b], 1]) * scale)
                    self._add_line_to_path(edge_path, pa, pb)
                batched_count += 1
            active_brush = faded_fill if original_mesh_faded else fill
            inactive_brush = faded_inactive_fill if original_mesh_faded else QBrush(QColor("#e9ecef"))
            active_item = self.scene.addPath(active_path, QPen(Qt.PenStyle.NoPen), active_brush)
            active_item.setData(0, {"kind": "mesh_lod_elements", "count": batched_count})
            active_item.setZValue(-4.0)
            if not inactive_path.isEmpty():
                inactive_item = self.scene.addPath(inactive_path, QPen(Qt.PenStyle.NoPen), inactive_brush)
                inactive_item.setData(0, {"kind": "mesh_lod_inactive_elements"})
                inactive_item.setZValue(-3.5)
            edge_pen = faded_pen if original_mesh_faded else pen
            edge_item = self.scene.addPath(edge_path, edge_pen)
            edge_item.setData(0, {"kind": "mesh_lod_edges", "count": batched_count})
            edge_item.setZValue(-3.0)

        def _draw_batched_mesh_nodes(
            self,
            mesh: Any,
            scale: float,
            ox: float,
            oy: float,
            *,
            set_nodes: set[str],
            set_label: str,
            original_mesh_faded: bool,
        ) -> None:
            node_path = QPainterPath()
            node_color = QColor(34, 34, 34, 65) if original_mesh_faded else QColor("#222222")
            node_pen = QPen(node_color)
            node_brush = QBrush(node_color)
            highlighted_pen = QPen(QColor("#ff9800"))
            highlighted_brush = QBrush(QColor("#ff9800"))
            radius = 1.5
            batched_count = 0
            for i, nid in enumerate(mesh.node_ids):
                x = float(mesh.coords[i, 0] * scale + ox)
                y = float(oy - mesh.coords[i, 1] * scale)
                if nid in set_nodes:
                    item = self.scene.addEllipse(x - 4.5, y - 4.5, 9.0, 9.0, highlighted_pen, highlighted_brush)
                    item.setToolTip(f"node {nid}: ({mesh.coords[i, 0]:.4g}, {mesh.coords[i, 1]:.4g})" + (f"\nset={set_label}" if set_label else ""))
                    item.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, True)
                    item.setData(0, {"kind": "node", "id": nid})
                    continue
                node_path.addEllipse(x - radius, y - radius, radius * 2.0, radius * 2.0)
                batched_count += 1
            item = self.scene.addPath(node_path, node_pen, node_brush)
            item.setData(0, {"kind": "mesh_lod_nodes", "count": batched_count})
            item.setZValue(1.0)

        def _geometry_shape_only_preview(self) -> bool:
            return self._panel_key_from_tree_key(str(getattr(self, "current_panel_key", ""))) == "geometry"

        def _preview_bounds_for_geometry_or_mesh_config(self) -> tuple[float, float, float, float]:
            geometry_bbox = self._geometry_bbox(self._mapping(self.cfg.get("geometry", {})))
            if geometry_bbox is not None:
                return geometry_bbox
            mesh = self._mapping(self.cfg.get("mesh", {}))
            xs: list[float] = []
            ys: list[float] = []
            raw_nodes = mesh.get("nodes", {})
            if isinstance(raw_nodes, Mapping):
                for value in raw_nodes.values():
                    try:
                        x, y = self._xy_pair(value)
                    except (TypeError, ValueError):
                        continue
                    xs.append(x)
                    ys.append(y)
            elif isinstance(raw_nodes, list):
                for value in raw_nodes:
                    try:
                        if isinstance(value, Mapping):
                            x, y = self._xy_pair(value.get("coord", value.get("coords", value)))
                        else:
                            x, y = self._xy_pair(value)
                    except (TypeError, ValueError):
                        continue
                    xs.append(x)
                    ys.append(y)
            x_range = mesh.get("x_range", [mesh.get("x0", 0.0), mesh.get("x1", 1.0)])
            y_range = mesh.get("y_range", [mesh.get("y0", 0.0), mesh.get("y1", 1.0)])
            try:
                x0, x1 = self._xy_pair(x_range)
                y0, y1 = self._xy_pair(y_range)
                xs.extend([x0, x1])
                ys.extend([y0, y1])
            except (TypeError, ValueError):
                pass
            if not xs or not ys:
                return (0.0, 1.0, 0.0, 1.0)
            return (min(xs), max(xs), min(ys), max(ys))

        @staticmethod
        def _preview_transform_from_bounds(xmin: float, xmax: float, ymin: float, ymax: float) -> tuple[float, float, float, float, float, float]:
            width = max(float(xmax - xmin), 1.0)
            height = max(float(ymax - ymin), 1.0)
            scale = min(900.0 / width, 620.0 / height)
            ox = -float(xmin) * scale + 30.0
            oy = float(ymax) * scale + 30.0
            return width, height, scale, ox, oy

        def _refresh_geometry_preview_diagnostics(self) -> None:
            self._geometry_open_endpoint_keys = self._geometry_open_endpoint_key_set()
            self._geometry_open_endpoint_count = len(self._geometry_open_endpoint_keys)
            cad_repair_summary = self._cad_repair_preview_summary()
            if getattr(self, "geometry_closure_summary", None) is not None:
                if self._geometry_open_endpoint_count:
                    repair_count = int(cad_repair_summary.get("candidate_count", 0) or 0)
                    extra = f" / 修復候補 {repair_count} 件" if repair_count else ""
                    self.geometry_closure_summary.setText(f"閉合診断: 未閉合端点 {self._geometry_open_endpoint_count} 件{extra}。赤色表示を接続または補助線化してください。")
                else:
                    repair_count = int(cad_repair_summary.get("candidate_count", 0) or 0)
                    if repair_count:
                        self.geometry_closure_summary.setText(f"閉合診断: 端点は閉合していますが、CAD修復候補 {repair_count} 件があります。赤色線分を確認してください。")
                    else:
                        self.geometry_closure_summary.setText("閉合診断: メッシュ分割対象線分は閉合しています。")

        def _draw_geometry_shape_preview(self, *, reset_view: bool, summary: str, draw_mesh_controls: bool = False) -> None:
            xmin, xmax, ymin, ymax = self._preview_bounds_for_geometry_or_mesh_config()
            width, height, scale, ox, oy = self._preview_transform_from_bounds(xmin, xmax, ymin, ymax)
            self.preview_scale = scale
            self.preview_ox = ox
            self.preview_oy = oy
            self._refresh_geometry_preview_diagnostics()
            self._draw_geometry_overlays(scale, ox, oy)
            if draw_mesh_controls:
                self._draw_mesh_control_overlays(scale, ox, oy)
            if reset_view:
                self.view.reset_to_scene()
            self._draw_xy_grid_for_bounds(xmin, xmax, ymin, ymax, scale, ox, oy)
            self._draw_distribution_plot()
            self.mesh_summary.setText(summary.format(width=width, height=height, target_count=self._model_geometry_target_count()))

        def _model_geometry_target_count(self) -> int:
            geometry = self._mapping(self.cfg.get("geometry", {}))
            count = 0
            lines = geometry.get("lines", [])
            if isinstance(lines, list):
                count += sum(
                    1
                    for line in lines
                    if isinstance(line, Mapping) and str(line.get("purpose", "model")).strip().lower() not in {"helper", "construction"}
                )
            for key in ("regions", "tunnels", "blocks"):
                values = geometry.get(key, [])
                if isinstance(values, list):
                    count += sum(1 for value in values if isinstance(value, Mapping))
            return count

        def update_preview(self, *, reset_view: bool = True) -> None:
            preview_started = time.perf_counter()
            self._refresh_set_display_options_if_dirty()
            self._model_preview_dirty = False
            panel_key = self._panel_key_from_tree_key(str(getattr(self, "current_panel_key", "")))
            signature = self._preview_render_signature(panel_key)
            if not reset_view and signature == getattr(self, "_last_preview_render_signature", "") and self.scene.items():
                self._record_preview_performance(preview_started, panel_key, getattr(self, "_preview_mesh_cache_value", None), mode="cached")
                return
            self._last_preview_render_signature = signature
            self.scene.clear()
            mesh_cfg = self._mapping(self.cfg.get("mesh", {}))
            geometry_shape_only = panel_key == "geometry"
            mesh_rebuild_required = bool(mesh_cfg.get("requires_rebuild", False))
            partial_rebuild_required = bool(mesh_cfg.get("partial_rebuild_required", False))
            if geometry_shape_only:
                self._draw_geometry_shape_preview(
                    reset_view=reset_view,
                    summary="形状/CAD: 形状のみ表示（メッシュ非表示） / メッシュ化対象 {target_count} 件 / 範囲 X={width:g}, Y={height:g}",
                )
                return
            if mesh_rebuild_required and (not partial_rebuild_required or "nodes" not in mesh_cfg or "elements" not in mesh_cfg):
                self._draw_geometry_shape_preview(
                    reset_view=reset_view,
                    summary="メッシュ未生成: 形状変更または削除によりメッシュをリセットしました。再構成してください。 / メッシュ化対象 {target_count} 件 / 範囲 X={width:g}, Y={height:g}",
                    draw_mesh_controls=panel_key == "mesh",
                )
                return
            try:
                mesh = self._preview_mesh_from_config()
            except Exception as exc:
                if panel_key == "materials":
                    self._draw_geometry_shape_preview(
                        reset_view=reset_view,
                        summary="材料割当: 形状領域を表示しています。領域を選択して右クリックで材料を割り当ててください。 / メッシュ化対象 {target_count} 件 / 範囲 X={width:g}, Y={height:g}",
                    )
                    return
                self.scene.addText(f"プレビュー不可: {exc}")
                return
            geometry_bbox = None
            if geometry_bbox is not None:
                xmin, xmax, ymin, ymax = geometry_bbox
            else:
                xs = mesh.coords[:, 0]
                ys = mesh.coords[:, 1]
                xmin, xmax = float(xs.min()), float(xs.max())
                ymin, ymax = float(ys.min()), float(ys.max())
            width, height, scale, ox, oy = self._preview_transform_from_bounds(xmin, xmax, ymin, ymax)
            self.preview_scale = scale
            self.preview_ox = ox
            self.preview_oy = oy
            node_index = mesh.node_index
            edge_map = {
                "TRI3": [(0, 1), (1, 2), (2, 0)],
                "TRI6": [(0, 3), (3, 1), (1, 4), (4, 2), (2, 5), (5, 0)],
                "QUAD4": [(0, 1), (1, 2), (2, 3), (3, 0)],
                "QUAD8": [(0, 4), (4, 1), (1, 5), (5, 2), (2, 6), (6, 3), (3, 7), (7, 0)],
            }
            fill = QBrush(QColor("#e9f2ff"))
            pen = QPen(QColor("#1f4e79"))
            selected_pen = QPen(QColor("#d35400"))
            selected_pen.setWidth(2)
            stage_active, stage_label = self._stage_visual_state(mesh)
            set_nodes, set_elements, set_label = self._selected_set_targets(mesh)
            set_fill = QBrush(QColor(255, 193, 7, 110))
            set_pen = QPen(QColor("#ff9800"))
            set_pen.setWidth(2)
            self._post_element_display_values = self._display_element_values(mesh)
            self._post_label_bounds = []
            display_policy = self._display_quality_policy(mesh)
            self._current_display_quality_policy = display_policy
            self._geometry_open_endpoint_keys = self._geometry_open_endpoint_key_set()
            self._geometry_open_endpoint_count = len(self._geometry_open_endpoint_keys)
            cad_repair_summary = self._cad_repair_preview_summary()
            if getattr(self, "geometry_closure_summary", None) is not None:
                if self._geometry_open_endpoint_count:
                    repair_count = int(cad_repair_summary.get("candidate_count", 0) or 0)
                    extra = f" / 修復候補 {repair_count} 件" if repair_count else ""
                    self.geometry_closure_summary.setText(f"閉合診断: 未閉合端点 {self._geometry_open_endpoint_count} 件{extra}。赤色表示を接続または補助線化してください。")
                else:
                    repair_count = int(cad_repair_summary.get("candidate_count", 0) or 0)
                    if repair_count:
                        self.geometry_closure_summary.setText(f"閉合診断: 端点は閉合していますが、CAD修復候補 {repair_count} 件があります。赤色線分を確認してください。")
                    else:
                        self.geometry_closure_summary.setText("閉合診断: メッシュ分割対象線分は閉合しています。")
            draw_element_boundaries = display_policy.draw_element_boundaries
            original_mesh_faded = self._deformed_result_overlay_active()
            faded_fill = QBrush(QColor(233, 242, 255, 32))
            faded_inactive_fill = QBrush(QColor(233, 236, 239, 24))
            faded_pen = QPen(QColor(31, 78, 121, 70))
            draw_grid_after_geometry_fit = geometry_shape_only
            if not draw_grid_after_geometry_fit:
                self._draw_xy_grid(mesh, scale, ox, oy, include_mesh_bounds=True)
            if not geometry_shape_only:
                element_count = len(mesh.elements)
                batch_mesh_elements = bool(display_policy.batch_mesh_items and not self._post_element_display_values)
                if batch_mesh_elements:
                    self._draw_batched_mesh_elements(
                        mesh,
                        scale,
                        ox,
                        oy,
                        node_index=node_index,
                        edge_map=edge_map,
                        stage_active=stage_active,
                        set_elements=set_elements,
                        set_label=set_label,
                        fill=fill,
                        pen=faded_pen if original_mesh_faded else pen,
                        set_fill=set_fill,
                        set_pen=set_pen,
                        original_mesh_faded=original_mesh_faded,
                        faded_fill=faded_fill,
                        faded_inactive_fill=faded_inactive_fill,
                        faded_pen=faded_pen,
                    )
                for element_index, element in enumerate(mesh.elements):
                    if batch_mesh_elements and element.id not in set_elements:
                        continue
                    ids = [node_index[nid] for nid in element.nodes]
                    polygon_points = []
                    corner_count = 3 if element.type.startswith("TRI") else 4
                    for idx in ids[:corner_count]:
                        xy = mesh.coords[idx]
                        polygon_points.append(QPointF(float(xy[0]) * scale + ox, oy - float(xy[1]) * scale))
                    material_fill = self._material_brush(element.material, alpha=72) if str(element.material).strip() in self._material_names() else fill
                    element_fill = QBrush(QColor("#e9ecef")) if element.id not in stage_active else material_fill
                    if self._post_element_display_values:
                        element_fill = QBrush(QColor("#e9ecef")) if element.id not in stage_active else self._element_result_brush(element.id, fill)
                    if original_mesh_faded:
                        element_fill = faded_inactive_fill if element.id not in stage_active else faded_fill
                    if element.id in set_elements:
                        element_fill = set_fill
                    item_pen = set_pen if element.id in set_elements else (faded_pen if original_mesh_faded else pen)
                    element_selectable = self._preview_item_selectable(
                        element_index,
                        element_count,
                        display_policy,
                        highlighted=element.id in set_elements or element.id not in stage_active,
                    )
                    item = self.scene.addPolygon(QPolygonF(polygon_points), item_pen, element_fill)
                    item.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, element_selectable)
                    active_note = "active" if element.id in stage_active else "inactive in selected stage"
                    set_note = f"\\nset={set_label}" if element.id in set_elements and set_label else ""
                    lod_note = "\\nselection decimated for large model" if not element_selectable else ""
                    item.setToolTip(f"element {element.id}\\n{element.type} / material={element.material} / integration={element.integration}\\n{active_note}{set_note}{lod_note}")
                    item.setData(0, {"kind": "element", "id": element.id, "type": element.type, "material": element.material})
                    if draw_element_boundaries:
                        for a, b in edge_map[element.type]:
                            pa = mesh.coords[ids[a]]
                            pb = mesh.coords[ids[b]]
                            base_edge_pen = faded_pen if original_mesh_faded else pen
                            edge_item = self.scene.addLine(pa[0] * scale + ox, oy - pa[1] * scale, pb[0] * scale + ox, oy - pb[1] * scale, selected_pen if element.id not in stage_active or not element.active else base_edge_pen)
                            edge_item.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, element_selectable)
                            edge_item.setData(0, {"kind": "edge", "id": f"{element.nodes[a]}-{element.nodes[b]}", "nodes": [element.nodes[a], element.nodes[b]], "element": element.id})
                            edge_item.setToolTip(f"edge {element.nodes[a]}-{element.nodes[b]} / element {element.id}")
                    if display_policy.draw_element_labels:
                        center = QPointF(
                            sum(point.x() for point in polygon_points) / len(polygon_points),
                            sum(point.y() for point in polygon_points) / len(polygon_points),
                        )
                        label = self.scene.addText(element.id)
                        label.setDefaultTextColor(QColor("#1f4e79"))
                        label.setPos(center)
                    if (
                        getattr(self, "show_contour_labels", None) is not None
                        and self.show_contour_labels.isChecked()
                        and display_policy.draw_contour_labels
                        and not original_mesh_faded
                        and self.post_mode in {"contour", "plastic", "srm"}
                        and element.id in self._post_element_display_values
                    ):
                        center = QPointF(
                            sum(point.x() for point in polygon_points) / len(polygon_points),
                            sum(point.y() for point in polygon_points) / len(polygon_points),
                        )
                        self._add_non_overlapping_text(
                            f"{self._post_element_display_values[element.id]:.3g}",
                            center.x() + 4.0,
                            center.y() - 14.0,
                            QColor("#111111"),
                            {"kind": "contour_label", "element": element.id, "value": self._post_element_display_values[element.id]},
                        )
            self._draw_geometry_overlays(scale, ox, oy)
            if geometry_shape_only:
                if reset_view:
                    self.view.reset_to_scene()
                self._draw_xy_grid(mesh, scale, ox, oy, include_mesh_bounds=False)
                self._draw_distribution_plot()
                self.mesh_summary.setText(
                    f"形状/CAD: 形状のみ表示（メッシュ非表示） / メッシュ化対象 {self._model_geometry_target_count()} 件 / 範囲 X={width:g}, Y={height:g}"
                )
                return
            self._draw_mesh_control_overlays(scale, ox, oy)
            self._draw_mesh_quality_violation_overlays(mesh, scale, ox, oy)
            if self._is_axisymmetric_analysis() and (
                getattr(self, "axisym_show_radial_guides", None) is None or self.axisym_show_radial_guides.isChecked()
            ):
                self._draw_axisymmetric_guides(mesh, scale, ox, oy)
            self._draw_element_library_overlays(mesh, scale, ox, oy)
            if display_policy.draw_node_labels:
                text_color = QColor("#333333")
            node_count = len(mesh.node_ids)
            if display_policy.batch_node_items:
                self._draw_batched_mesh_nodes(
                    mesh,
                    scale,
                    ox,
                    oy,
                    set_nodes=set_nodes,
                    set_label=set_label,
                    original_mesh_faded=original_mesh_faded,
                )
            else:
                for i, nid in enumerate(mesh.node_ids):
                    x = mesh.coords[i, 0] * scale + ox
                    y = oy - mesh.coords[i, 1] * scale
                    highlighted = nid in set_nodes
                    radius = 4.5 if highlighted else 2.2
                    node_selectable = self._preview_item_selectable(i, node_count, display_policy, highlighted=highlighted)
                    node_item = QGraphicsEllipseItem(x - radius, y - radius, radius * 2.0, radius * 2.0)
                    node_color = QColor("#ff9800") if highlighted else (QColor(34, 34, 34, 65) if original_mesh_faded else QColor("#222222"))
                    node_item.setBrush(QBrush(node_color))
                    node_item.setPen(QPen(node_color))
                    lod_note = "\\nselection decimated for large model" if not node_selectable else ""
                    node_item.setToolTip(f"node {nid}: ({mesh.coords[i, 0]:.4g}, {mesh.coords[i, 1]:.4g})" + (f"\\nset={set_label}" if highlighted and set_label else "") + lod_note)
                    node_item.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, node_selectable)
                    node_item.setData(0, {"kind": "node", "id": nid})
                    self.scene.addItem(node_item)
                    if display_policy.draw_node_labels:
                        label = QGraphicsTextItem(str(nid))
                        label.setDefaultTextColor(text_color)
                        label.setPos(x + 3.0, y + 3.0)
                        self.scene.addItem(label)
            self._draw_stage_overlays(mesh, scale, ox, oy)
            self._draw_stage_diff_overlay(mesh, scale, ox, oy)
            self._draw_result_overlays(mesh, scale, ox, oy)
            if not original_mesh_faded:
                self._draw_contour_polylines(mesh, scale, ox, oy)
            self._draw_distribution_plot()
            self._draw_result_legend()
            if reset_view:
                self.view.reset_to_scene()
            suffix = f" / 表示ステージ: {stage_label}" if stage_label else ""
            if set_label:
                suffix += f" / セット: {set_label}"
            selection_stride = max(
                self._preview_selection_stride(len(mesh.elements), display_policy),
                self._preview_selection_stride(len(mesh.node_ids), display_policy),
            )
            if selection_stride > 1:
                suffix += f" / selection LOD 1/{selection_stride}"
            if partial_rebuild_required:
                deleted = ", ".join(str(value) for value in self._ensure_list(mesh_cfg.get("deleted_region_meshes", []))[:4])
                suffix += f" / 形状別メッシュ再構成待ち: {deleted or 'あり'}"
            if self._current_display_quality_policy is not None and self._current_display_quality_policy.reduced:
                suffix += " / 表示品質: 自動低減"
            self.mesh_summary.setText(f"節点 {len(mesh.node_ids)} / 要素 {len(mesh.elements)} / 範囲 X={width:g}, Y={height:g}{suffix}")

            self._record_preview_performance(preview_started, panel_key, mesh)

        def _deformed_result_overlay_active(self) -> bool:
            if not self.result_displacements:
                return False
            if self.post_mode not in {"contour", "node_contour", "plastic", "srm", "deformed", "vector"}:
                return False
            overlay = getattr(self, "show_deformed_overlay", None)
            return self.post_mode == "deformed" or overlay is None or overlay.isChecked()
            self.statusBar().showMessage(f"節点 {len(mesh.node_ids)} / 要素 {len(mesh.elements)}")

        def _draw_xy_grid_for_bounds(self, xmin: float, xmax: float, ymin: float, ymax: float, scale: float, ox: float, oy: float) -> None:
            if getattr(self, "show_grid_lines", None) is None or not self.show_grid_lines.isChecked():
                return
            try:
                spacing = float(self.snap_grid_size.text())
            except (TypeError, ValueError):
                spacing = 1.0
            if spacing <= 0.0:
                return
            xmin = float(xmin)
            xmax = float(xmax)
            ymin = float(ymin)
            ymax = float(ymax)
            pad = spacing * 2.0
            xmin -= pad
            xmax += pad
            ymin -= pad
            ymax += pad
            first_x = math.floor(xmin / spacing) * spacing
            first_y = math.floor(ymin / spacing) * spacing
            minor_pen = QPen(QColor(160, 174, 192, 58))
            axis_pen = QPen(QColor(38, 96, 150, 118))
            axis_pen.setWidth(2)
            max_lines = 500
            count = 0
            x = first_x
            while x <= xmax + spacing * 0.5 and count < max_lines:
                px = x * scale + ox
                pen = axis_pen if abs(x) <= spacing * 1.0e-9 else minor_pen
                item = self.scene.addLine(px, oy - ymin * scale, px, oy - ymax * scale, pen)
                item.setZValue(-100.0)
                item.setData(0, {"kind": "grid", "axis": "x", "value": x})
                x += spacing
                count += 1
            y = first_y
            while y <= ymax + spacing * 0.5 and count < max_lines:
                py = oy - y * scale
                pen = axis_pen if abs(y) <= spacing * 1.0e-9 else minor_pen
                item = self.scene.addLine(xmin * scale + ox, py, xmax * scale + ox, py, pen)
                item.setZValue(-100.0)
                item.setData(0, {"kind": "grid", "axis": "y", "value": y})
                y += spacing
                count += 1

        def _draw_xy_grid(self, mesh: Any, scale: float, ox: float, oy: float, *, include_mesh_bounds: bool = True) -> None:
            if getattr(self, "show_grid_lines", None) is None or not self.show_grid_lines.isChecked():
                return
            bbox = self._geometry_bbox(self._mapping(self.cfg.get("geometry", {})))
            if include_mesh_bounds or bbox is None:
                xmin = float(mesh.coords[:, 0].min())
                xmax = float(mesh.coords[:, 0].max())
                ymin = float(mesh.coords[:, 1].min())
                ymax = float(mesh.coords[:, 1].max())
            else:
                xmin, xmax, ymin, ymax = (float(bbox[0]), float(bbox[1]), float(bbox[2]), float(bbox[3]))
            if include_mesh_bounds and bbox is not None:
                xmin = min(xmin, float(bbox[0]))
                xmax = max(xmax, float(bbox[1]))
                ymin = min(ymin, float(bbox[2]))
                ymax = max(ymax, float(bbox[3]))
            self._draw_xy_grid_for_bounds(xmin, xmax, ymin, ymax, scale, ox, oy)

        def _geometry_open_endpoint_key_set(self) -> set[tuple[str, str]]:
            geometry = self._mapping(self.cfg.get("geometry", {}))
            lines = geometry.get("lines", [])
            if not isinstance(lines, list):
                return set()
            try:
                tolerance = float(geometry.get("closure_tolerance", ""))
            except (TypeError, ValueError):
                try:
                    snap_grid_size = getattr(self, "snap_grid_size", None)
                    snap_grid_text = snap_grid_size.text() if snap_grid_size is not None else "1.0"
                    tolerance = max(float(snap_grid_text) * 1.0e-6, 1.0e-7)
                except (TypeError, ValueError):
                    tolerance = 1.0e-7
            endpoints: list[tuple[str, str, float, float]] = []
            anchors: list[tuple[float, float]] = []
            for raw in lines:
                if not isinstance(raw, Mapping):
                    continue
                if str(raw.get("purpose", "model")).strip().lower() == "helper":
                    continue
                line_id = str(raw.get("id", ""))
                if not line_id:
                    continue
                try:
                    x1, y1 = self._xy_pair(raw.get("start", raw.get("p1", [0.0, 0.0])))
                    x2, y2 = self._xy_pair(raw.get("end", raw.get("p2", [0.0, 0.0])))
                except ValueError:
                    continue
                endpoints.append((line_id, "start", x1, y1))
                endpoints.append((line_id, "end", x2, y2))
            for region in self._geometry_regions(geometry):
                anchors.extend(region)
            open_keys: set[tuple[str, str]] = set()
            for index, (line_id, endpoint, x, y) in enumerate(endpoints):
                connected = False
                for other_index, (_other_id, _other_endpoint, ox2, oy2) in enumerate(endpoints):
                    if index == other_index:
                        continue
                    if math.hypot(x - ox2, y - oy2) <= tolerance:
                        connected = True
                        break
                if not connected:
                    for ax, ay in anchors:
                        if math.hypot(x - ax, y - ay) <= tolerance:
                            connected = True
                            break
                if not connected:
                    open_keys.add((line_id, endpoint))
            return open_keys

        def _display_quality_policy(self, mesh: Any) -> DisplayQualityPolicy:
            def int_from_widget(name: str, default: int) -> int:
                widget = getattr(self, name, None)
                if widget is None:
                    return default
                try:
                    return int(float(widget.text()))
                except Exception:
                    return default

            requested_levels = int_from_widget("contour_level_count", 7)
            requested_curve_segments = int_from_widget("contour_curve_segments", 4)
            detail_limit = int_from_widget("display_detail_limit", 1500)
            vector_limit = int_from_widget("display_vector_limit", 400)
            mode_widget = getattr(self, "display_quality_mode", None)
            mode = str(mode_widget.currentData() or "auto") if mode_widget is not None else "auto"
            return resolve_display_quality_policy(
                mode=mode,
                node_count=len(getattr(mesh, "node_ids", [])),
                element_count=len(getattr(mesh, "elements", [])),
                detail_limit=detail_limit,
                vector_limit=vector_limit,
                requested_node_labels=bool(getattr(self, "show_node_ids", None) is not None and self.show_node_ids.isChecked()),
                requested_element_labels=bool(getattr(self, "show_element_ids", None) is not None and self.show_element_ids.isChecked()),
                requested_element_boundaries=bool(getattr(self, "show_element_boundaries", None) is None or self.show_element_boundaries.isChecked()),
                requested_contour_labels=bool(getattr(self, "show_contour_labels", None) is not None and self.show_contour_labels.isChecked()),
                requested_contour_levels=requested_levels,
                requested_curve_segments=requested_curve_segments,
            )

        def _draw_element_library_overlays(self, mesh: Any, scale: float, ox: float, oy: float) -> None:
            node_index = mesh.node_index

            def xy(nid: str) -> tuple[float, float] | None:
                if nid not in node_index:
                    return None
                idx = node_index[nid]
                return float(mesh.coords[idx, 0] * scale + ox), float(oy - mesh.coords[idx, 1] * scale)

            for raw in self._ensure_list(self.cfg.get("structural_elements", [])):
                if not isinstance(raw, Mapping) or not self._bool_text(str(raw.get("active", True)), True):
                    continue
                nodes = [str(nid) for nid in self._ensure_list(raw.get("nodes", []))]
                if len(nodes) < 2:
                    continue
                p0 = xy(nodes[0])
                p1 = xy(nodes[1])
                if p0 is None or p1 is None:
                    continue
                kind = str(raw.get("type", "")).lower()
                color = "#7b2cbf" if "beam" in kind else ("#198754" if "bar" in kind or "truss" in kind else "#d63384")
                pen = QPen(QColor(color))
                pen.setWidth(3)
                if "spring" in kind:
                    pen.setStyle(Qt.PenStyle.DashDotLine)
                self.scene.addLine(p0[0], p0[1], p1[0], p1[1], pen)
                label = self.scene.addText(str(raw.get("id", raw.get("type", ""))))
                label.setDefaultTextColor(QColor(color))
                label.setPos((p0[0] + p1[0]) * 0.5 + 4.0, (p0[1] + p1[1]) * 0.5 + 4.0)

            for raw in self._ensure_list(self.cfg.get("interfaces", self.cfg.get("interface_elements", []))):
                if not isinstance(raw, Mapping) or not self._bool_text(str(raw.get("active", True)), True):
                    continue
                if "nodes" in raw:
                    nodes = [str(nid) for nid in self._ensure_list(raw.get("nodes", []))]
                    if len(nodes) >= 4:
                        minus = nodes[:2]
                        plus = nodes[2:4]
                    else:
                        continue
                else:
                    minus = [str(nid) for nid in self._ensure_list(raw.get("minus_nodes", raw.get("nodes_minus", [])))]
                    plus = [str(nid) for nid in self._ensure_list(raw.get("plus_nodes", raw.get("nodes_plus", [])))]
                if len(minus) < 2 or len(plus) < 2:
                    continue
                m0 = xy(minus[0])
                m1 = xy(minus[1])
                p0 = xy(plus[0])
                p1 = xy(plus[1])
                if None in {m0, m1, p0, p1}:
                    continue
                a = ((m0[0] + p0[0]) * 0.5, (m0[1] + p0[1]) * 0.5)
                b = ((m1[0] + p1[0]) * 0.5, (m1[1] + p1[1]) * 0.5)
                pen = QPen(QColor("#e76f51"))
                pen.setWidth(3)
                pen.setStyle(Qt.PenStyle.DashLine)
                self.scene.addLine(a[0], a[1], b[0], b[1], pen)
                label = self.scene.addText(str(raw.get("id", "joint")))
                label.setDefaultTextColor(QColor("#e76f51"))
                label.setPos((a[0] + b[0]) * 0.5 + 4.0, (a[1] + b[1]) * 0.5 + 4.0)

        def _draw_axisymmetric_guides(self, mesh: Any, scale: float, ox: float, oy: float) -> None:
            if not getattr(mesh, "node_ids", None):
                return
            xs = [float(mesh.coords[i, 0]) for i in range(len(mesh.node_ids))]
            ys = [float(mesh.coords[i, 1]) for i in range(len(mesh.node_ids))]
            xmin, xmax = min(xs), max(xs)
            ymin, ymax = min(ys), max(ys)
            x_axis = 0.0 if xmin <= 0.0 <= xmax else xmin
            axis_x = x_axis * scale + ox
            y_top = oy - ymax * scale
            y_bottom = oy - ymin * scale
            axis_pen = QPen(QColor("#0d6efd"))
            axis_pen.setWidth(2)
            axis_pen.setStyle(Qt.PenStyle.DashLine)
            axis_item = self.scene.addLine(axis_x, y_top, axis_x, y_bottom, axis_pen)
            axis_item.setData(0, {"kind": "axisymmetric_radial_guide", "role": "axis", "radius": x_axis})
            axis_item.setToolTip("axisymmetric z-axis / r=0 reference")

            radial_pen = QPen(QColor("#198754"))
            radial_pen.setWidth(2)
            span_y = max(ymax - ymin, 1.0)
            sample_ys = [ymin + span_y * ratio for ratio in (0.25, 0.5, 0.75)]
            start_r = max(x_axis, xmin)
            end_r = xmax
            for index, yy in enumerate(sample_ys, start=1):
                sx = start_r * scale + ox
                ex = end_r * scale + ox
                sy = oy - yy * scale
                item = self.scene.addLine(sx, sy, ex, sy, radial_pen)
                item.setData(0, {"kind": "axisymmetric_radial_guide", "role": "radial", "index": index})
                item.setToolTip("axisymmetric radial direction r = x")
                if ex > sx + 8.0:
                    self._draw_arrow(ex - 18.0, sy, ex, sy, radial_pen)
            label_r = self.scene.addText("r (x)")
            label_r.setDefaultTextColor(QColor("#198754"))
            label_r.setPos(xmax * scale + ox + 8.0, oy - (ymin + 0.5 * span_y) * scale - 12.0)
            label_r.setData(0, {"kind": "axisymmetric_radius_label", "role": "radial_axis"})
            label_z = self.scene.addText("z (y)")
            label_z.setDefaultTextColor(QColor("#0d6efd"))
            label_z.setPos(axis_x + 6.0, y_top - 20.0)
            label_z.setData(0, {"kind": "axisymmetric_radius_label", "role": "axis"})
            for radius_value, role in [(xmin, "inner"), (xmax, "outer")]:
                x = radius_value * scale + ox
                tick = self.scene.addLine(x, y_bottom - 6.0, x, y_bottom + 6.0, QPen(QColor("#495057")))
                tick.setData(0, {"kind": "axisymmetric_radius_label", "role": role, "radius": radius_value})
                label = self.scene.addText(f"{role} r={radius_value:.4g}")
                label.setDefaultTextColor(QColor("#495057"))
                label.setPos(x + 4.0, y_bottom + 8.0)
                label.setData(0, {"kind": "axisymmetric_radius_label", "role": role, "radius": radius_value})

        def _draw_geometry_overlays(self, scale: float, ox: float, oy: float) -> None:
            geometry = self._mapping(self.cfg.get("geometry", {}))
            layer_map = self._cad_layer_map(geometry)
            line_pen = QPen(QColor("#7a5c00"))
            line_pen.setStyle(Qt.PenStyle.DashLine)
            helper_pen = QPen(QColor("#6c757d"))
            helper_pen.setStyle(Qt.PenStyle.DotLine)
            tunnel_pen = QPen(QColor("#b02a37"))
            tunnel_pen.setStyle(Qt.PenStyle.DashLine)

            def map_xy(x: float, y: float) -> tuple[float, float]:
                return x * scale + ox, oy - y * scale

            for raw in geometry.get("hatches", []) if isinstance(geometry.get("hatches", []), list) else []:
                if not isinstance(raw, Mapping):
                    continue
                if not self._cad_layer_visible(raw, layer_map):
                    continue
                rings = self._hatch_rings(raw)
                if not rings:
                    continue
                for ring_index, ring in enumerate(rings):
                    points = [QPointF(*map_xy(px, py)) for px, py in ring]
                    brush = self._cad_brush_for_hatch(raw, layer_map)
                    if ring_index > 0:
                        brush = QBrush(QColor(255, 255, 255, 190))
                    self.scene.addPolygon(
                        QPolygonF(points),
                        self._cad_pen_for_geometry(raw, layer_map, "#6c757d", Qt.PenStyle.DotLine),
                        brush,
                    )

            lines = geometry.get("lines", [])
            if isinstance(lines, list):
                try:
                    lod_threshold = int(float(geometry.get("cad_lod_line_threshold", 1500)))
                except (TypeError, ValueError):
                    lod_threshold = 1500
                geometry_lod = len(lines) > max(1, lod_threshold)
                for raw in lines:
                    if not isinstance(raw, Mapping):
                        continue
                    if not self._cad_layer_visible(raw, layer_map):
                        continue
                    try:
                        x1, y1 = self._xy_pair(raw.get("start", raw.get("p1", [0.0, 0.0])))
                        x2, y2 = self._xy_pair(raw.get("end", raw.get("p2", [0.0, 0.0])))
                    except ValueError:
                        continue
                    sx, sy = map_xy(x1, y1)
                    ex, ey = map_xy(x2, y2)
                    purpose = str(raw.get("purpose", ""))
                    default_color = "#0aa2c0" if purpose == "waterline" else ("#6c757d" if purpose == "helper" else "#7a5c00")
                    default_style = Qt.PenStyle.DashLine if purpose == "waterline" else (Qt.PenStyle.DotLine if purpose == "helper" else Qt.PenStyle.DashLine)
                    line_id = str(raw.get("id", ""))
                    repair_line = line_id in getattr(self, "_geometry_repair_line_ids", set())
                    pen = self._cad_pen_for_geometry(
                        raw,
                        layer_map,
                        "#dc3545" if repair_line else default_color,
                        default_style,
                    )
                    if repair_line:
                        pen.setWidth(max(2, pen.width()))
                    item = self.scene.addLine(sx, sy, ex, ey, pen)
                    item.setToolTip(f"geometry line {raw.get('id', '')} layer={raw.get('layer', '')}")
                    item.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, not self._cad_layer_locked(raw, layer_map))
                    item.setData(0, {"kind": "geometry_line", "id": raw.get("id")})
                    for endpoint, px, py in (("start", sx, sy), ("end", ex, ey)):
                        open_endpoint = (line_id, endpoint) in getattr(self, "_geometry_open_endpoint_keys", set())
                        repair_endpoint = (line_id, endpoint) in getattr(self, "_geometry_repair_endpoint_keys", set())
                        if geometry_lod and not (open_endpoint or repair_endpoint):
                            continue
                        radius = 6.0 if open_endpoint or repair_endpoint else 4.0
                        handle = QGraphicsEllipseItem(px - radius, py - radius, radius * 2.0, radius * 2.0)
                        handle.setBrush(QBrush(QColor("#dc3545") if open_endpoint or repair_endpoint else QColor("#ffdd57")))
                        handle_pen = QPen(QColor("#7a0012") if open_endpoint or repair_endpoint else QColor("#7a5c00"))
                        handle_pen.setWidth(2 if open_endpoint or repair_endpoint else 1)
                        handle.setPen(handle_pen)
                        handle.setToolTip(
                            f"{raw.get('id', '')} {endpoint}"
                            + ("\n未閉合端点: 近傍点へ接続、延長、補助線化してください。" if open_endpoint else "")
                        )
                        handle.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, not self._cad_layer_locked(raw, layer_map))
                        handle.setData(0, {"kind": "geometry_endpoint", "id": raw.get("id"), "endpoint": endpoint, "open": open_endpoint})
                        self.scene.addItem(handle)

            tunnels = geometry.get("tunnels", [])
            if isinstance(tunnels, list):
                for raw in tunnels:
                    if not isinstance(raw, Mapping):
                        continue
                    if not self._cad_layer_visible(raw, layer_map):
                        continue
                    try:
                        cx, cy = self._xy_pair(raw.get("center", [0.0, 0.0]))
                        radius = float(raw.get("radius", 0.0))
                    except (TypeError, ValueError):
                        continue
                    if radius <= 0.0:
                        continue
                    sx, sy = map_xy(cx, cy)
                    rr = radius * scale
                    item = self.scene.addEllipse(sx - rr, sy - rr, rr * 2.0, rr * 2.0, self._cad_pen_for_geometry(raw, layer_map, "#b02a37", Qt.PenStyle.DashLine))
                    item.setToolTip(f"tunnel {raw.get('id', '')}")
                    item.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, not self._cad_layer_locked(raw, layer_map))
                    item.setData(0, {"kind": "geometry_tunnel", "id": raw.get("id")})

            for raw in geometry.get("points", []) if isinstance(geometry.get("points", []), list) else []:
                if not isinstance(raw, Mapping):
                    continue
                if not self._cad_layer_visible(raw, layer_map):
                    continue
                try:
                    x, y = self._xy_pair(raw.get("point", raw.get("position", [raw.get("x", 0.0), raw.get("y", 0.0)])))
                except ValueError:
                    continue
                sx, sy = map_xy(x, y)
                point_pen = self._cad_pen_for_geometry(raw, layer_map, "#0d6efd", Qt.PenStyle.SolidLine)
                point = QGraphicsEllipseItem(sx - 4.0, sy - 4.0, 8.0, 8.0)
                point.setBrush(QBrush(point_pen.color()))
                point.setPen(point_pen)
                point.setToolTip(f"point {raw.get('id', '')} role={raw.get('role', '')}")
                point.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, not self._cad_layer_locked(raw, layer_map))
                point.setData(0, {"kind": "geometry_point", "id": raw.get("id")})
                self.scene.addItem(point)

            self._draw_cad_draw_control_overlays(geometry, layer_map, scale, ox, oy)
            self._draw_curve_boundary_overlays(geometry, layer_map, scale, ox, oy)

            regions = geometry.get("regions", [])
            region_brush = QBrush(QColor(80, 160, 120, 35))
            region_pen = QPen(QColor("#198754"))
            region_pen.setStyle(Qt.PenStyle.DashLine)
            if isinstance(regions, list):
                for region_index, raw in enumerate(regions):
                    if not isinstance(raw, Mapping):
                        continue
                    if not self._cad_layer_visible(raw, layer_map):
                        continue
                    points_raw = raw.get("points", [])
                    if not isinstance(points_raw, list) or len(points_raw) < 3:
                        continue
                    points: list[QPointF] = []
                    for point in points_raw:
                        try:
                            px, py = self._xy_pair(point)
                        except ValueError:
                            points = []
                            break
                        sx, sy = map_xy(px, py)
                        points.append(QPointF(sx, sy))
                    if len(points) < 3:
                        continue
                    region_id = str(raw.get("id", f"region_{region_index + 1}") or f"region_{region_index + 1}")
                    material = self._region_material_for_id(region_id, index=region_index, raw=raw)
                    brush = self._material_brush(material, alpha=78) if material else region_brush
                    pen = self._cad_pen_for_geometry(raw, layer_map, "#198754", Qt.PenStyle.DashLine)
                    if material:
                        pen = QPen(self._material_color(material))
                        pen.setStyle(Qt.PenStyle.SolidLine)
                        pen.setWidth(2)
                    item = self.scene.addPolygon(QPolygonF(points), pen, brush)
                    material_note = f" / material={material}" if material else " / material未設定"
                    item.setToolTip(f"region {raw.get('id', '')}{material_note}")
                    item.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, not self._cad_layer_locked(raw, layer_map))
                    item.setData(0, {"kind": "geometry_region", "id": raw.get("id"), "material": material})

            for raw in geometry.get("annotations", []) if isinstance(geometry.get("annotations", []), list) else []:
                if not isinstance(raw, Mapping):
                    continue
                if not self._cad_layer_visible(raw, layer_map):
                    continue
                try:
                    x, y = self._xy_pair(raw.get("point", raw.get("position", [0.0, 0.0])))
                except ValueError:
                    continue
                text = str(raw.get("text", "")).strip()
                if not text:
                    continue
                sx, sy = map_xy(x, y)
                note_pen = self._cad_pen_for_geometry(raw, layer_map, "#0d6efd", Qt.PenStyle.SolidLine)
                note_color = note_pen.color()
                dot = QGraphicsEllipseItem(sx - 2.5, sy - 2.5, 5.0, 5.0)
                dot.setBrush(QBrush(note_color))
                dot.setPen(note_pen)
                dot.setToolTip(text)
                self.scene.addItem(dot)
                label = QGraphicsTextItem(text)
                label.setDefaultTextColor(note_color)
                label.setPos(sx + 4.0, sy - 18.0)
                label.setToolTip(text)
                self.scene.addItem(label)

            for raw in geometry.get("dimensions", []) if isinstance(geometry.get("dimensions", []), list) else []:
                if not isinstance(raw, Mapping):
                    continue
                if not self._cad_layer_visible(raw, layer_map):
                    continue
                try:
                    x1, y1 = self._xy_pair(raw.get("start", raw.get("p1", [0.0, 0.0])))
                    x2, y2 = self._xy_pair(raw.get("end", raw.get("p2", [0.0, 0.0])))
                except ValueError:
                    continue
                sx, sy = map_xy(x1, y1)
                ex, ey = map_xy(x2, y2)
                dim_pen = self._cad_pen_for_geometry(raw, layer_map, "#6f42c1", Qt.PenStyle.DashDotLine)
                self.scene.addLine(sx, sy, ex, ey, dim_pen)
                for endpoint, hx, hy in (("start", sx, sy), ("end", ex, ey)):
                    handle = QGraphicsEllipseItem(hx - 4.0, hy - 4.0, 8.0, 8.0)
                    handle.setBrush(QBrush(QColor("#e599f7")))
                    handle.setPen(dim_pen)
                    handle.setToolTip(f"dimension {raw.get('id', '')} {endpoint}")
                    handle.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, not self._cad_layer_locked(raw, layer_map))
                    handle.setData(0, {"kind": "dimension_endpoint", "id": raw.get("id"), "endpoint": endpoint})
                    self.scene.addItem(handle)
                label_text = str(raw.get("text", "") or f"{float(raw.get('value', math.hypot(x2 - x1, y2 - y1))):.3g}")
                label = QGraphicsTextItem(label_text)
                label.setDefaultTextColor(dim_pen.color())
                label.setPos((sx + ex) * 0.5 + 4.0, (sy + ey) * 0.5 - 18.0)
                label.setToolTip(label_text)
                self.scene.addItem(label)

            self._draw_cad_overlap_edges(scale, ox, oy)
            self._draw_cad_boolean_operation_overlay(scale, ox, oy)

            if self.region_points:
                preview_points = [QPointF(*map_xy(x, y)) for x, y in self.region_points]
                for a, b in zip(preview_points, preview_points[1:]):
                    self.scene.addLine(a.x(), a.y(), b.x(), b.y(), region_pen)
                for point in preview_points:
                    dot = QGraphicsEllipseItem(point.x() - 3.0, point.y() - 3.0, 6.0, 6.0)
                    dot.setBrush(QBrush(QColor("#198754")))
                    dot.setPen(QPen(QColor("#198754")))
                    self.scene.addItem(dot)

        def _draw_cad_draw_control_overlays(self, geometry: Mapping[str, Any], layer_map: Mapping[str, Mapping[str, Any]], scale: float, ox: float, oy: float) -> None:
            def map_xy(x: float, y: float) -> tuple[float, float]:
                return x * scale + ox, oy - y * scale

            for entity, key, color in (("curve", "curves", "#0d6efd"), ("arc", "arcs", "#b02a37")):
                values = geometry.get(key, [])
                if not isinstance(values, list):
                    continue
                for raw in values:
                    if not isinstance(raw, Mapping) or not self._cad_layer_visible(raw, layer_map):
                        continue
                    point_values = raw.get("control_points", raw.get("points", []))
                    points: list[tuple[float, float]] = []
                    for point in self._ensure_list(point_values):
                        try:
                            points.append(self._xy_pair(point))
                        except ValueError:
                            pass
                    if not points:
                        continue
                    control_pen = self._cad_pen_for_geometry(raw, layer_map, color, Qt.PenStyle.DotLine)
                    control_pen.setWidth(1)
                    mapped = [map_xy(x, y) for x, y in points]
                    for a, b in zip(mapped, mapped[1:]):
                        self.scene.addLine(a[0], a[1], b[0], b[1], control_pen)
                    for point_index, (sx, sy) in enumerate(mapped, start=1):
                        handle = QGraphicsEllipseItem(sx - 5.0, sy - 5.0, 10.0, 10.0)
                        handle.setBrush(QBrush(QColor(color)))
                        handle.setPen(control_pen)
                        handle.setToolTip(f"{entity} {raw.get('id', '')} control {point_index}")
                        handle.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, not self._cad_layer_locked(raw, layer_map))
                        handle.setData(0, {"kind": "cad_draw_control_point", "entity": entity, "id": raw.get("id"), "point": point_index})
                        self.scene.addItem(handle)

        def _draw_curve_boundary_overlays(self, geometry: Mapping[str, Any], layer_map: Mapping[str, Mapping[str, Any]], scale: float, ox: float, oy: float) -> None:
            regions = geometry.get("regions", [])
            if not isinstance(regions, list):
                return

            def map_xy(x: float, y: float) -> tuple[float, float]:
                return x * scale + ox, oy - y * scale

            for region_index, region in enumerate(regions, start=1):
                if not isinstance(region, Mapping) or not self._cad_layer_visible(region, layer_map):
                    continue
                curve_groups = [("boundary", self._curve_boundary_specs(region))]
                curve_groups.extend((f"hole_{index}", hole) for index, hole in enumerate(self._curve_hole_specs(region), start=1))
                for role, specs in curve_groups:
                    for curve_index, spec in enumerate(specs, start=1):
                        points = self._sample_curve_spec(spec, target=self._boolean_graph_target())
                        if len(points) < 2:
                            continue
                        pen = self._cad_pen_for_geometry(spec, layer_map, "#0f766e", Qt.PenStyle.SolidLine)
                        pen.setWidth(3)
                        mapped = [map_xy(x, y) for x, y in points]
                        for a, b in zip(mapped, mapped[1:]):
                            item = self.scene.addLine(a[0], a[1], b[0], b[1], pen)
                            item.setToolTip(f"curve region={region_index} {role} #{curve_index} type={spec.get('type', '')}")
                            item.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, not self._cad_layer_locked(spec, layer_map))
                            item.setData(0, {"kind": "geometry_curve", "region": region_index, "role": role, "index": curve_index})
                        control_points = spec.get("control_points", spec.get("points", []))
                        if isinstance(control_points, list) and control_points:
                            helper_pen = QPen(QColor("#6c757d"))
                            helper_pen.setStyle(Qt.PenStyle.DotLine)
                            helper_pen.setWidth(1)
                            controls: list[tuple[float, float]] = []
                            for point in control_points:
                                try:
                                    controls.append(self._xy_pair(point))
                                except ValueError:
                                    pass
                            mapped_controls = [map_xy(x, y) for x, y in controls]
                            for a, b in zip(mapped_controls, mapped_controls[1:]):
                                self.scene.addLine(a[0], a[1], b[0], b[1], helper_pen)
                            for cindex, (sx, sy) in enumerate(mapped_controls, start=1):
                                dot = QGraphicsEllipseItem(sx - 3.5, sy - 3.5, 7.0, 7.0)
                                dot.setBrush(QBrush(QColor("#ffd43b")))
                                dot.setPen(QPen(QColor("#7a5c00")))
                                dot.setToolTip(f"control point r{region_index}:{role}:{curve_index}:{cindex}")
                                dot.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, not self._cad_layer_locked(spec, layer_map))
                                dot.setData(0, {"kind": "curve_control_point", "region": region_index, "role": role, "curve_role": role, "control_role": "control", "curve": curve_index, "point": cindex})
                                self.scene.addItem(dot)
                        else:
                            for control_role, point_number in (("start", 1), ("end", 2), ("center", 0)):
                                if control_role not in spec:
                                    continue
                                try:
                                    px, py = self._xy_pair(spec.get(control_role))
                                except ValueError:
                                    continue
                                sx, sy = map_xy(px, py)
                                dot = QGraphicsEllipseItem(sx - 3.5, sy - 3.5, 7.0, 7.0)
                                dot.setBrush(QBrush(QColor("#ffd43b" if control_role != "center" else "#74c0fc")))
                                dot.setPen(QPen(QColor("#7a5c00" if control_role != "center" else "#1864ab")))
                                dot.setToolTip(f"{control_role} point r{region_index}:{role}:{curve_index}")
                                dot.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, not self._cad_layer_locked(spec, layer_map))
                                dot.setData(
                                    0,
                                    {
                                        "kind": "curve_control_point",
                                        "region": region_index,
                                        "role": role,
                                        "curve_role": role,
                                        "control_role": control_role,
                                        "curve": curve_index,
                                        "point": point_number,
                                    },
                                )
                                self.scene.addItem(dot)

        def _draw_mesh_control_overlays(self, scale: float, ox: float, oy: float) -> None:
            mesh = self._mapping(self.cfg.get("mesh", {}))

            def map_xy(x: float, y: float) -> tuple[float, float]:
                return x * scale + ox, oy - y * scale

            for index, (cx, cy, radius, factor) in enumerate(self._mesh_refinements(mesh), start=1):
                sx, sy = map_xy(cx, cy)
                rr = radius * scale
                pen = QPen(QColor("#fd7e14"))
                pen.setStyle(Qt.PenStyle.DashDotLine)
                pen.setWidth(2)
                item = self.scene.addEllipse(sx - rr, sy - rr, rr * 2.0, rr * 2.0, pen)
                item.setToolTip(f"mesh refinement {index}: factor={factor:g}")
                item.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, True)
                item.setData(0, {"kind": "mesh_refinement", "id": index, "index": index - 1})
            for split_index, (start, end, target_size) in enumerate(self._mesh_split_lines(mesh), start=1):
                sx1, sy1 = map_xy(start[0], start[1])
                sx2, sy2 = map_xy(end[0], end[1])
                pen = QPen(QColor("#7950f2"))
                pen.setWidth(3)
                pen.setStyle(Qt.PenStyle.DashLine)
                item = self.scene.addLine(sx1, sy1, sx2, sy2, pen)
                tip = f"split line {split_index}"
                if target_size is not None:
                    tip += f" target={target_size:g}"
                item.setToolTip(tip)
                item.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, True)
                item.setData(0, {"kind": "mesh_split_line", "id": split_index, "index": split_index - 1, "start": start, "end": end})
            raw_size_map = mesh.get("size_map", mesh.get("local_size_map", []))
            if isinstance(raw_size_map, list):
                for map_index, raw in enumerate(raw_size_map):
                    if not isinstance(raw, Mapping):
                        continue
                    try:
                        x, y = self._xy_pair(raw.get("center", raw.get("point", [raw.get("x", 0.0), raw.get("y", 0.0)])))
                        radius = float(raw.get("radius", raw.get("r", 0.0)))
                    except (TypeError, ValueError):
                        continue
                    if radius <= 0.0:
                        continue
                    sx, sy = map_xy(x, y)
                    rr = radius * scale
                    pen = QPen(QColor("#0ca678"))
                    pen.setStyle(Qt.PenStyle.DotLine)
                    pen.setWidth(2)
                    item = self.scene.addEllipse(sx - rr, sy - rr, rr * 2.0, rr * 2.0, pen)
                    item.setToolTip(f"local size map {raw.get('id', '')} target={raw.get('target_size', raw.get('size', ''))}")
                    item.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, True)
                    item.setData(0, {"kind": "mesh_size_map", "id": raw.get("id"), "index": map_index})
            raw_points = mesh.get("control_points", mesh.get("mesh_control_points", []))
            if isinstance(raw_points, list):
                for point_index, raw in enumerate(raw_points):
                    if not isinstance(raw, Mapping):
                        continue
                    try:
                        x, y = self._xy_pair(raw.get("point", raw.get("position", [raw.get("x", 0.0), raw.get("y", 0.0)])))
                    except ValueError:
                        continue
                    sx, sy = map_xy(x, y)
                    item = QGraphicsEllipseItem(sx - 5.0, sy - 5.0, 10.0, 10.0)
                    item.setBrush(QBrush(QColor("#20c997")))
                    item.setPen(QPen(QColor("#087f5b")))
                    item.setToolTip(f"mesh control point {raw.get('id', '')} target={raw.get('target_size', '')}")
                    item.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, True)
                    item.setData(0, {"kind": "mesh_control_point", "id": raw.get("id"), "index": point_index})
                    self.scene.addItem(item)

        def _draw_mesh_quality_violation_overlays(self, mesh: Any, scale: float, ox: float, oy: float) -> None:
            violations = self._mesh_quality_violations(mesh)
            if not violations:
                return
            by_element = {str(item["element"]): item for item in violations}
            node_index = mesh.node_index
            pen = QPen(QColor("#dc3545"))
            pen.setWidth(3)
            brush = QBrush(QColor(220, 53, 69, 42))
            for element in mesh.elements:
                violation = by_element.get(str(element.id))
                if violation is None:
                    continue
                corner_count = 3 if element.type.startswith("TRI") else 4
                polygon_points = []
                for nid in element.nodes[:corner_count]:
                    idx = node_index[nid]
                    xy = mesh.coords[idx]
                    polygon_points.append(QPointF(float(xy[0]) * scale + ox, oy - float(xy[1]) * scale))
                if len(polygon_points) < 3:
                    continue
                item = self.scene.addPolygon(QPolygonF(polygon_points), pen, brush)
                item.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, True)
                item.setData(0, {"kind": "mesh_quality_violation", "id": element.id, "element": element.id})
                item.setToolTip(f"quality violation element {element.id}: {violation.get('reason', '')}")

        def _draw_cad_overlap_edges(self, scale: float, ox: float, oy: float) -> None:
            geometry = self._geometry_cfg()
            states = dict(self._mapping(self._mapping(geometry.get("cad_boolean", {})).get("trim_edge_overrides", {})))
            states.update(dict(self._mapping(geometry.get("cad_overlap_edge_states", {}))))

            def map_xy(x: float, y: float) -> tuple[float, float]:
                return x * scale + ox, oy - y * scale

            for edge, graph in self._iter_cad_overlap_edges():
                edge_id = str(edge.get("id", ""))
                if str(states.get(edge_id, edge.get("ui_state", "active"))).lower() in {"suppressed", "hidden", "off", "false"}:
                    continue
                points = self._cad_graph_edge_points(edge, graph)
                if len(points) < 2:
                    continue
                pen = QPen(QColor("#d63384"))
                pen.setWidth(4)
                pen.setStyle(Qt.PenStyle.DashLine)
                mapped = [map_xy(x, y) for x, y in points]
                for a, b in zip(mapped, mapped[1:]):
                    item = self.scene.addLine(a[0], a[1], b[0], b[1], pen)
                    item.setToolTip(f"coincident CAD edge {edge_id}: {edge.get('coincident_edge_ids', [])}")
                    item.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, True)
                    item.setData(0, {"kind": "cad_overlap_edge", "id": edge_id})

        def _draw_cad_boolean_operation_overlay(self, scale: float, ox: float, oy: float) -> None:
            graph = self._active_cad_boolean_graph()
            if not graph:
                return
            geometry = self._mapping(self.cfg.get("geometry", {}))
            mesh = self._mapping(self.cfg.get("mesh", {}))
            cad_boolean = self._mapping(geometry.get("cad_boolean", mesh.get("cad_boolean", {})))
            operation = str(cad_boolean.get("manual_selected_operation", cad_boolean.get("selected_operation", ""))).strip()
            operations = self._mapping(graph.get("boolean_operations", {}))
            if not operation or operation not in operations:
                operation = "expression" if "expression" in operations else ("union" if "union" in operations else next(iter(operations), ""))
            if not operation:
                return
            try:
                from geofem_app.analytic_boolean import operation_loop_polygons

                rings = operation_loop_polygons(graph, operation=operation, target=graph.get("target", self._boolean_graph_target()))
            except Exception:
                rings = []
            pen = QPen(QColor("#0f766e"))
            pen.setWidth(3)
            pen.setStyle(Qt.PenStyle.SolidLine)
            manual = bool(cad_boolean.get("manual_selected_operation"))
            if manual:
                pen.setColor(QColor("#fd7e14"))
                pen.setStyle(Qt.PenStyle.DashDotLine)

            def map_xy(x: float, y: float) -> tuple[float, float]:
                return x * scale + ox, oy - y * scale

            for ring_index, ring in enumerate(rings, start=1):
                points_raw = ring.get("points", []) if isinstance(ring, Mapping) else []
                if not isinstance(points_raw, list) or len(points_raw) < 2:
                    continue
                points: list[tuple[float, float]] = []
                for point in points_raw:
                    try:
                        points.append(self._xy_pair(point))
                    except ValueError:
                        pass
                if len(points) < 2:
                    continue
                mapped = [map_xy(x, y) for x, y in points]
                for a, b in zip(mapped, mapped[1:]):
                    item = self.scene.addLine(a[0], a[1], b[0], b[1], pen)
                    item.setToolTip(f"CAD Boolean {operation} loop {ring_index}" + (" / manual override" if manual else ""))
                    item.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, True)
                    item.setData(0, {"kind": "cad_boolean_loop", "operation": operation, "loop": ring_index, "manual": manual})

        def _cad_graph_edge_points(self, edge: Mapping[str, Any], graph: Mapping[str, Any]) -> list[tuple[float, float]]:
            source = edge.get("source")
            try:
                t0 = float(edge.get("t0", 0.0))
                t1 = float(edge.get("t1", 1.0))
            except (TypeError, ValueError):
                t0, t1 = 0.0, 1.0
            if isinstance(source, Mapping):
                try:
                    from geofem_app.analytic_boolean import eval_curve

                    count = max(2, min(16, int(abs(t1 - t0) / 0.05) + 2))
                    return [eval_curve(source, t0 + (t1 - t0) * i / (count - 1)) for i in range(count)]
                except Exception:
                    pass
            vertices = graph.get("vertices", {})
            if isinstance(vertices, Mapping):
                start = self._mapping(vertices.get(str(edge.get("start_vertex"))))
                end = self._mapping(vertices.get(str(edge.get("end_vertex"))))
                try:
                    return [self._xy_pair(start.get("point", [0.0, 0.0])), self._xy_pair(end.get("point", [0.0, 0.0]))]
                except ValueError:
                    return []
            return []

        def _cad_layer_map(self, geometry: Mapping[str, Any]) -> dict[str, Mapping[str, Any]]:
            layers: dict[str, Mapping[str, Any]] = {}
            raw_layers = geometry.get("layers", [])
            if isinstance(raw_layers, list):
                for raw in raw_layers:
                    if not isinstance(raw, Mapping):
                        continue
                    name = str(raw.get("name", raw.get("id", ""))).strip()
                    if name:
                        layers[name] = raw
            return layers

        def _cad_layer_visible(self, raw: Mapping[str, Any], layer_map: Mapping[str, Mapping[str, Any]]) -> bool:
            if not self._bool_text(str(raw.get("visible", raw.get("active", True))), True):
                return False
            layer_name = str(raw.get("layer", "")).strip()
            if not layer_name:
                return True
            layer = layer_map.get(layer_name)
            if not isinstance(layer, Mapping):
                return True
            return self._bool_text(str(layer.get("visible", layer.get("on", layer.get("active", True)))), True)

        def _cad_layer_locked(self, raw: Mapping[str, Any], layer_map: Mapping[str, Mapping[str, Any]]) -> bool:
            if self._bool_text(str(raw.get("locked", raw.get("lock", False))), False):
                return True
            layer_name = str(raw.get("layer", "")).strip()
            if not layer_name:
                return False
            layer = layer_map.get(layer_name)
            if not isinstance(layer, Mapping):
                return False
            return self._bool_text(str(layer.get("locked", layer.get("lock", False))), False)

        def _cad_linetype_map(self, geometry: Mapping[str, Any]) -> dict[str, Mapping[str, Any]]:
            linetypes: dict[str, Mapping[str, Any]] = {}
            raw_linetypes = geometry.get("linetypes", [])
            if isinstance(raw_linetypes, list):
                for raw in raw_linetypes:
                    if not isinstance(raw, Mapping):
                        continue
                    for key in ("name", "id", "source_id"):
                        name = str(raw.get(key, "")).strip()
                        if name:
                            linetypes[name.lower()] = raw
            return linetypes

        def _cad_pen_for_geometry(
            self,
            raw: Mapping[str, Any],
            layer_map: Mapping[str, Mapping[str, Any]],
            fallback_color: str,
            fallback_style: Any,
        ) -> Any:
            layer = layer_map.get(str(raw.get("layer", "")), {})
            color = self._cad_color(raw.get("color", layer.get("color")), fallback_color)
            qcolor = QColor(color)
            try:
                opacity = float(raw.get("opacity", layer.get("opacity", 1.0)) or 1.0)
            except (TypeError, ValueError):
                opacity = 1.0
            if opacity <= 1.0:
                qcolor.setAlphaF(max(0.05, min(opacity, 1.0)))
            else:
                qcolor.setAlpha(max(5, min(int(opacity), 255)))
            pen = QPen(qcolor)
            raw_linetype = raw.get("linetype")
            layer_linetype = layer.get("linetype")
            linetype = layer_linetype if self._is_by_layer_linetype(raw_linetype) else raw_linetype
            if linetype in (None, ""):
                linetype = layer_linetype
            pattern = self._cad_linetype_pattern(raw, layer, linetype)
            if pattern:
                pen.setStyle(Qt.PenStyle.CustomDashLine)
                pen.setDashPattern(pattern)
            else:
                pen.setStyle(self._cad_line_style(linetype, fallback_style))
            try:
                weight = float(raw.get("lineweight", layer.get("lineweight", 0)) or 0.0)
            except (TypeError, ValueError):
                weight = 0.0
            if weight > 0.0:
                pen.setWidthF(max(1.0, min(weight / 100.0, 4.0)))
            return pen

        def _is_by_layer_linetype(self, raw: Any) -> bool:
            return str(raw or "").strip().lower() in {"", "bylayer", "by layer"}

        def _cad_linetype_pattern(self, raw: Mapping[str, Any], layer: Mapping[str, Any], linetype: Any) -> list[float] | None:
            direct = self._normalize_qt_dash_pattern(raw.get("linetype_pattern", raw.get("dash_pattern")))
            if direct:
                return direct
            layer_pattern = self._normalize_qt_dash_pattern(layer.get("linetype_pattern", layer.get("dash_pattern")))
            if layer_pattern:
                return layer_pattern
            if linetype in (None, ""):
                return None
            geometry = self._mapping(self.cfg.get("geometry", {}))
            definition = self._cad_linetype_map(geometry).get(str(linetype).strip().lower())
            if not definition:
                return None
            return self._normalize_qt_dash_pattern(definition.get("pattern", definition.get("dash_pattern")))

        def _normalize_qt_dash_pattern(self, raw: Any) -> list[float] | None:
            if raw in (None, ""):
                return None
            if isinstance(raw, str):
                values = [part for part in raw.replace(";", ",").replace(" ", ",").split(",") if part]
            elif isinstance(raw, (list, tuple)):
                values = list(raw)
            else:
                values = [raw]
            pattern: list[float] = []
            for value in values:
                if isinstance(value, Mapping):
                    value = value.get("length", value.get("value", 0.0))
                try:
                    raw_length = float(value)
                except (TypeError, ValueError):
                    continue
                if raw_length > 1.0e-12:
                    pattern.append(max(0.5, min(abs(raw_length), 64.0)))
                elif raw_length < -1.0e-12:
                    pattern.append(max(0.5, min(abs(raw_length), 64.0)))
                else:
                    pattern.append(0.5)
            if len(pattern) < 2:
                pattern.append(max(pattern[0], 0.5) if pattern else 1.0)
            return pattern

        def _cad_brush_for_hatch(self, raw: Mapping[str, Any], layer_map: Mapping[str, Mapping[str, Any]]) -> Any:
            layer = layer_map.get(str(raw.get("layer", "")), {})
            color = QColor(self._cad_color(raw.get("color", layer.get("color")), "#6c757d"))
            color.setAlpha(75 if bool(raw.get("solid", False)) else 55)
            brush = QBrush(color)
            pattern = str(raw.get("pattern", "")).lower()
            if not bool(raw.get("solid", False)):
                if "cross" in pattern:
                    brush.setStyle(Qt.BrushStyle.CrossPattern)
                elif "diag" in pattern or "ansi" in pattern:
                    brush.setStyle(Qt.BrushStyle.BDiagPattern)
                else:
                    brush.setStyle(Qt.BrushStyle.Dense4Pattern)
            return brush

        def _hatch_rings(self, raw: Mapping[str, Any]) -> list[list[tuple[float, float]]]:
            rings: list[list[tuple[float, float]]] = []
            raw_rings = raw.get("rings", raw.get("boundaries"))
            if isinstance(raw_rings, list):
                for raw_ring in raw_rings:
                    ring: list[tuple[float, float]] = []
                    if isinstance(raw_ring, list):
                        for point in raw_ring:
                            try:
                                ring.append(self._xy_pair(point))
                            except ValueError:
                                ring = []
                                break
                    if len(ring) >= 3:
                        rings.append(ring)
            if not rings:
                points_raw = raw.get("points", raw.get("boundary", []))
                ring = []
                if isinstance(points_raw, list):
                    for point in points_raw:
                        try:
                            ring.append(self._xy_pair(point))
                        except ValueError:
                            ring = []
                            break
                if len(ring) >= 3:
                    rings.append(ring)
            holes = raw.get("holes", raw.get("islands", []))
            if isinstance(holes, list):
                for raw_hole in holes:
                    hole: list[tuple[float, float]] = []
                    if isinstance(raw_hole, list):
                        for point in raw_hole:
                            try:
                                hole.append(self._xy_pair(point))
                            except ValueError:
                                hole = []
                                break
                    if len(hole) >= 3:
                        rings.append(hole)
            return rings

        def _geometry_curved_regions(self, geometry: Mapping[str, Any]) -> list[dict[str, Any]]:
            out: list[dict[str, Any]] = []
            raw_regions = geometry.get("regions", [])
            if not isinstance(raw_regions, list):
                return out
            for raw in raw_regions:
                if isinstance(raw, Mapping) and self._region_has_curve_parameters(raw):
                    out.append(dict(raw))
            return out

        def _region_has_curve_parameters(self, raw: Mapping[str, Any]) -> bool:
            if raw.get("curve_boundary") or raw.get("curve_holes"):
                return True
            for key in ("boundary", "segments", "curves", "edges"):
                value = raw.get(key)
                if isinstance(value, Mapping) and self._curve_mapping_has_parameters(value):
                    return True
                if isinstance(value, list) and any(isinstance(item, Mapping) and self._curve_mapping_has_parameters(item) for item in value):
                    return True
            holes = raw.get("holes", raw.get("islands", []))
            if isinstance(holes, list):
                for hole in holes:
                    if isinstance(hole, Mapping) and self._curve_mapping_has_parameters(hole):
                        return True
                    if isinstance(hole, list) and any(isinstance(item, Mapping) and self._curve_mapping_has_parameters(item) for item in hole):
                        return True
            return False

        @staticmethod
        def _curve_mapping_has_parameters(value: Mapping[str, Any]) -> bool:
            kind = str(value.get("type", value.get("kind", value.get("curve_type", "")))).strip().lower()
            return kind in {"line", "segment", "arc", "circle", "ellipse", "elliptic_arc", "bezier", "spline", "bspline", "b_spline", "nurbs", "nurbs_curve", "rational_bspline", "rational_b_spline"} or ("center" in value and ("radius" in value or "rx" in value or "ry" in value)) or ("start" in value and "end" in value)

        def _cad_color(self, raw: Any, fallback: str) -> str:
            if raw in (None, ""):
                return fallback
            value = str(raw).strip().lower()
            if value.startswith("#") and len(value) in {4, 7}:
                return value
            table = {
                "red": "#dc3545",
                "yellow": "#d39e00",
                "green": "#198754",
                "cyan": "#0dcaf0",
                "blue": "#0d6efd",
                "magenta": "#d63384",
                "white": "#f8f9fa",
                "gray": "#6c757d",
                "grey": "#6c757d",
                "lightgray": "#adb5bd",
                "black": "#212529",
            }
            if value in table:
                return table[value]
            try:
                aci = abs(int(float(value)))
            except ValueError:
                return fallback
            aci_table = {1: "#dc3545", 2: "#d39e00", 3: "#198754", 4: "#0dcaf0", 5: "#0d6efd", 6: "#d63384", 7: "#212529", 8: "#6c757d", 9: "#adb5bd"}
            return aci_table.get(aci, fallback)

        def _cad_line_style(self, raw: Any, fallback: Any) -> Any:
            if raw in (None, ""):
                return fallback
            value = str(raw).strip().lower()
            if value in {"continuous", "solid", "bylayer"}:
                return fallback
            if "dashdot" in value or "center" in value:
                return Qt.PenStyle.DashDotLine
            if "dot" in value:
                return Qt.PenStyle.DotLine
            if "dash" in value or "hidden" in value:
                return Qt.PenStyle.DashLine
            return fallback

