        @staticmethod
        def _point_segment_distance(
            px: float,
            py: float,
            x1: float,
            y1: float,
            x2: float,
            y2: float,
        ) -> float:
            dx = x2 - x1
            dy = y2 - y1
            length2 = dx * dx + dy * dy
            if length2 <= 1.0e-24:
                return math.hypot(px - x1, py - y1)
            t = max(0.0, min(1.0, ((px - x1) * dx + (py - y1) * dy) / length2))
            return math.hypot(px - (x1 + t * dx), py - (y1 + t * dy))

        def nearest_geometry_endpoint_at_scene_point(self, scene_point: QPointF) -> dict[str, Any] | None:
            geometry = self._geometry_cfg()
            layer_map = self._cad_layer_map(geometry)
            scale = self.preview_scale if abs(self.preview_scale) > 1.0e-30 else 1.0
            tolerance = max(12.0 / scale, 1.0e-8)
            x, y = self._scene_to_model(scene_point)
            best: tuple[float, dict[str, Any]] | None = None
            lines = geometry.get("lines", [])
            if not isinstance(lines, list):
                return None
            for raw in lines:
                if not isinstance(raw, Mapping):
                    continue
                if not self._cad_layer_visible(raw, layer_map) or self._cad_layer_locked(raw, layer_map):
                    continue
                line_id = str(raw.get("id", ""))
                if not line_id:
                    continue
                for endpoint in ("start", "end"):
                    try:
                        px, py = self._geometry_line_endpoint_xy(raw, endpoint)
                    except ValueError:
                        continue
                    distance = math.hypot(px - x, py - y)
                    if distance <= tolerance and (best is None or distance < best[0]):
                        best = (
                            distance,
                            {"kind": "geometry_endpoint", "id": line_id, "endpoint": endpoint, "open": False},
                        )
            return best[1] if best is not None else None

        def select_geometry_endpoint_items(self, data: Mapping[str, Any], *, additive: bool = False) -> bool:
            line_id = str(data.get("id", ""))
            endpoint = "start" if str(data.get("endpoint", "end")) == "start" else "end"
            if not line_id:
                return False
            if not additive:
                self.scene.clearSelection()
            selected = False
            for item in self.scene.items():
                item_data = item.data(0)
                if not isinstance(item_data, Mapping) or str(item_data.get("id", "")) != line_id:
                    continue
                kind = str(item_data.get("kind", ""))
                if kind == "geometry_line" or (kind == "geometry_endpoint" and str(item_data.get("endpoint", "")) == endpoint):
                    try:
                        if not (item.flags() & QGraphicsItem.GraphicsItemFlag.ItemIsSelectable):
                            continue
                    except Exception:
                        pass
                    item.setSelected(True)
                    selected = True
            if selected:
                self._sync_model_geometry_editor_from_selection()
            return selected

        def _select_geometry_line_items(self, line_id: str, *, additive: bool = False) -> bool:
            if not line_id:
                return False
            if not additive:
                self.scene.clearSelection()
            selected = False
            for item in self.scene.items():
                data = item.data(0)
                if not isinstance(data, Mapping) or str(data.get("id", "")) != line_id:
                    continue
                if data.get("kind") not in {"geometry_line", "geometry_endpoint"}:
                    continue
                try:
                    if not (item.flags() & QGraphicsItem.GraphicsItemFlag.ItemIsSelectable):
                        continue
                except Exception:
                    pass
                item.setSelected(True)
                selected = True
            if selected:
                self._sync_model_geometry_editor_from_selection()
                self.statusBar().showMessage(f"作図線を選択しました: {line_id}")
            return selected

        def _select_nearest_geometry_line_at_scene_point(self, scene_point: QPointF, *, additive: bool = False) -> bool:
            geometry = self._geometry_cfg()
            layer_map = self._cad_layer_map(geometry)
            x, y = self._scene_to_model(scene_point)
            scale = self.preview_scale if abs(self.preview_scale) > 1.0e-30 else 1.0
            tolerance = max(10.0 / scale, 1.0e-8)
            best_line_id: str | None = None
            best_distance: float | None = None
            lines = geometry.get("lines", [])
            if isinstance(lines, list):
                for raw in lines:
                    if not isinstance(raw, Mapping):
                        continue
                    if not self._cad_layer_visible(raw, layer_map) or self._cad_layer_locked(raw, layer_map):
                        continue
                    try:
                        x1, y1 = self._xy_pair(raw.get("start", raw.get("p1", [0.0, 0.0])))
                        x2, y2 = self._xy_pair(raw.get("end", raw.get("p2", [0.0, 0.0])))
                    except ValueError:
                        continue
                    distance = self._point_segment_distance(x, y, x1, y1, x2, y2)
                    if distance <= tolerance and (best_distance is None or distance < best_distance):
                        best_distance = distance
                        best_line_id = str(raw.get("id", ""))
            if best_line_id and self._select_geometry_line_items(best_line_id, additive=additive):
                return True

            best: tuple[float, Any] | None = None
            tolerance = 10.0
            for item in self.scene.items():
                data = item.data(0)
                if not isinstance(data, Mapping) or data.get("kind") != "geometry_line":
                    continue
                if not item.isVisible():
                    continue
                try:
                    if not (item.flags() & QGraphicsItem.GraphicsItemFlag.ItemIsSelectable):
                        continue
                    line = item.line()
                    p1 = item.mapToScene(line.p1())
                    p2 = item.mapToScene(line.p2())
                except Exception:
                    continue
                distance = self._point_segment_distance(scene_point.x(), scene_point.y(), p1.x(), p1.y(), p2.x(), p2.y())
                if distance <= tolerance and (best is None or distance < best[0]):
                    best = (distance, item)
            if best is None:
                return False
            data = best[1].data(0)
            ident = data.get("id", "") if isinstance(data, Mapping) else ""
            return self._select_geometry_line_items(str(ident), additive=additive)

        @staticmethod
        def _point_in_polygon_xy(x: float, y: float, points: list[tuple[float, float]]) -> bool:
            inside = False
            if len(points) < 3:
                return False
            j = len(points) - 1
            for i, (xi, yi) in enumerate(points):
                xj, yj = points[j]
                if (yi > y) != (yj > y):
                    denom = (yj - yi) if abs(yj - yi) > 1.0e-20 else 1.0e-20
                    x_cross = (xj - xi) * (y - yi) / denom + xi
                    if x < x_cross:
                        inside = not inside
                j = i
            return inside

        def _clear_mesh_lod_selection_proxies(self) -> None:
            for item in list(self.scene.items()):
                data = item.data(0)
                if isinstance(data, Mapping) and data.get("proxy") == "mesh_lod_selection":
                    try:
                        self.scene.removeItem(item)
                    except Exception:
                        pass

        def _add_mesh_lod_selection_proxy(
            self,
            mesh: Any,
            *,
            kind: str,
            identifier: str,
            nodes: list[str] | None = None,
            additive: bool = False,
        ) -> bool:
            if not additive:
                self.scene.clearSelection()
                self._clear_mesh_lod_selection_proxies()
            node_index = mesh.node_index
            nodes = [str(node) for node in (nodes or []) if str(node) in node_index]
            proxy: Any | None = None
            if kind == "node":
                if identifier not in node_index:
                    return False
                idx = node_index[identifier]
                x = float(mesh.coords[idx, 0] * self.preview_scale + self.preview_ox)
                y = float(self.preview_oy - mesh.coords[idx, 1] * self.preview_scale)
                proxy = self.scene.addEllipse(x - 6.0, y - 6.0, 12.0, 12.0, QPen(QColor("#ff6b00")), QBrush(QColor(255, 193, 7, 95)))
                proxy.setData(0, {"kind": "node", "id": identifier, "proxy": "mesh_lod_selection"})
                proxy.setToolTip(f"node {identifier}")
            elif kind == "edge" and len(nodes) >= 2:
                a, b = nodes[:2]
                ia = node_index[a]
                ib = node_index[b]
                proxy = self.scene.addLine(
                    float(mesh.coords[ia, 0] * self.preview_scale + self.preview_ox),
                    float(self.preview_oy - mesh.coords[ia, 1] * self.preview_scale),
                    float(mesh.coords[ib, 0] * self.preview_scale + self.preview_ox),
                    float(self.preview_oy - mesh.coords[ib, 1] * self.preview_scale),
                    QPen(QColor("#ff6b00"), 5),
                )
                proxy.setData(0, {"kind": "edge", "id": identifier, "nodes": [a, b], "proxy": "mesh_lod_selection"})
                proxy.setToolTip(f"edge {identifier}")
            elif kind == "element":
                element = next((candidate for candidate in mesh.elements if str(candidate.id) == str(identifier)), None)
                if element is None:
                    return False
                corner_count = 3 if element.type.startswith("TRI") else 4
                points = []
                for nid in element.nodes[:corner_count]:
                    if nid not in node_index:
                        return False
                    idx = node_index[nid]
                    points.append(QPointF(float(mesh.coords[idx, 0] * self.preview_scale + self.preview_ox), float(self.preview_oy - mesh.coords[idx, 1] * self.preview_scale)))
                proxy = self.scene.addPolygon(QPolygonF(points), QPen(QColor("#ff6b00"), 4), QBrush(QColor(255, 193, 7, 46)))
                proxy.setData(0, {"kind": "element", "id": element.id, "type": element.type, "material": element.material, "proxy": "mesh_lod_selection"})
                proxy.setToolTip(f"element {element.id}\n{element.type} / material={element.material}")
            if proxy is None:
                return False
            proxy.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, True)
            proxy.setZValue(9_997.0)
            proxy.setSelected(True)
            self._sync_model_geometry_editor_from_selection()
            self.statusBar().showMessage(f"驕ｸ謚槭＠縺ｾ縺励◆: {kind} {identifier} (LOD)")
            return True

        def _select_nearest_mesh_lod_item(self, scene_point: QPointF, *, additive: bool = False) -> bool:
            policy = getattr(self, "_current_display_quality_policy", None)
            if policy is None or not getattr(policy, "pick_nearest_mesh", False):
                return False
            mesh = getattr(self, "_preview_mesh_cache_value", None)
            if mesh is None:
                try:
                    mesh = self._preview_mesh_from_config()
                except Exception:
                    return False
            scale = max(float(getattr(self, "preview_scale", 1.0) or 1.0), 1.0e-12)
            mx = (float(scene_point.x()) - float(getattr(self, "preview_ox", 0.0))) / scale
            my = (float(getattr(self, "preview_oy", 0.0)) - float(scene_point.y())) / scale
            try:
                transform = self.view.transform()
                view_scale = max(min(abs(transform.m11()), abs(transform.m22())), 1.0e-9)
                scene_tolerance = max(4.0, 8.0 / view_scale)
            except Exception:
                scene_tolerance = 8.0
            model_tolerance = scene_tolerance / scale
            coords = mesh.coords
            if len(getattr(mesh, "node_ids", [])):
                dist2 = (coords[:, 0] - mx) ** 2 + (coords[:, 1] - my) ** 2
                node_pos = int(dist2.argmin())
                if float(dist2[node_pos]) <= model_tolerance * model_tolerance:
                    return self._add_mesh_lod_selection_proxy(mesh, kind="node", identifier=str(mesh.node_ids[node_pos]), additive=additive)
            edge_map = {
                "TRI3": [(0, 1), (1, 2), (2, 0)],
                "TRI6": [(0, 3), (3, 1), (1, 4), (4, 2), (2, 5), (5, 0)],
                "QUAD4": [(0, 1), (1, 2), (2, 3), (3, 0)],
                "QUAD8": [(0, 4), (4, 1), (1, 5), (5, 2), (2, 6), (6, 3), (3, 7), (7, 0)],
            }
            best_edge: tuple[float, str, list[str]] | None = None
            containing_element = ""
            for element in mesh.elements:
                node_ids = list(element.nodes)
                corner_count = 3 if element.type.startswith("TRI") else 4
                polygon = [
                    (float(coords[mesh.node_index[nid], 0]), float(coords[mesh.node_index[nid], 1]))
                    for nid in node_ids[:corner_count]
                    if nid in mesh.node_index
                ]
                if not containing_element and self._point_in_polygon_xy(mx, my, polygon):
                    containing_element = str(element.id)
                for a, b in edge_map.get(element.type, []):
                    if a >= len(node_ids) or b >= len(node_ids):
                        continue
                    na = node_ids[a]
                    nb = node_ids[b]
                    if na not in mesh.node_index or nb not in mesh.node_index:
                        continue
                    ia = mesh.node_index[na]
                    ib = mesh.node_index[nb]
                    distance = self._point_segment_distance(mx, my, float(coords[ia, 0]), float(coords[ia, 1]), float(coords[ib, 0]), float(coords[ib, 1]))
                    if distance <= model_tolerance and (best_edge is None or distance < best_edge[0]):
                        best_edge = (distance, f"{na}-{nb}", [na, nb])
            if best_edge is not None:
                return self._add_mesh_lod_selection_proxy(mesh, kind="edge", identifier=best_edge[1], nodes=best_edge[2], additive=additive)
            if containing_element:
                return self._add_mesh_lod_selection_proxy(mesh, kind="element", identifier=containing_element, additive=additive)
            return False

        def select_model_item_at_scene_point(self, scene_point: QPointF, *, item: Any = None, items: Any = None, additive: bool = False) -> bool:
            selectable_kinds = {"node", "edge", "element", "geometry_line", "geometry_region", "geometry_tunnel", "geometry_point"}
            current_panel = self._panel_key_from_tree_key(str(getattr(self, "current_panel_key", "")))

            def is_selectable(candidate: Any) -> bool:
                if candidate is None:
                    return False
                try:
                    if not candidate.isVisible():
                        return False
                except Exception:
                    pass
                try:
                    if not (candidate.flags() & QGraphicsItem.GraphicsItemFlag.ItemIsSelectable):
                        return False
                except Exception:
                    pass
                data = candidate.data(0)
                return isinstance(data, Mapping) and str(data.get("kind", "")) in selectable_kinds

            def pick_tolerance() -> float:
                try:
                    transform = self.view.transform()
                    scale = max(min(abs(transform.m11()), abs(transform.m22())), 1.0e-9)
                    return max(4.0, 8.0 / scale)
                except Exception:
                    return 8.0

            def fallback_distance(candidate: Any, tolerance: float) -> float | None:
                data = candidate.data(0)
                if not isinstance(data, Mapping):
                    return None
                kind = str(data.get("kind", ""))
                try:
                    rect = candidate.sceneBoundingRect()
                except Exception:
                    return None
                if kind in {"node", "geometry_point"}:
                    center = rect.center()
                    distance = math.hypot(scene_point.x() - center.x(), scene_point.y() - center.y())
                    radius = max(rect.width(), rect.height()) * 0.5
                    return distance if distance <= tolerance + radius else None
                if kind in {"edge", "geometry_line"}:
                    try:
                        line = candidate.line()
                        p1 = candidate.mapToScene(line.p1())
                        p2 = candidate.mapToScene(line.p2())
                        distance = self._point_segment_distance(scene_point.x(), scene_point.y(), p1.x(), p1.y(), p2.x(), p2.y())
                        if distance <= tolerance:
                            return distance
                    except Exception:
                        pass
                    if rect.adjusted(-tolerance, -tolerance, tolerance, tolerance).contains(scene_point):
                        center = rect.center()
                        return tolerance + math.hypot(scene_point.x() - center.x(), scene_point.y() - center.y()) * 1.0e-3
                    return None
                if kind in {"element", "geometry_region", "geometry_tunnel"}:
                    try:
                        if candidate.contains(candidate.mapFromScene(scene_point)):
                            return 0.0
                    except Exception:
                        pass
                    if rect.adjusted(-tolerance, -tolerance, tolerance, tolerance).contains(scene_point):
                        return tolerance * 2.0
                return None

            candidates: list[Any] = []
            for candidate in [item, *(list(items) if items is not None else [])]:
                if candidate is not None and candidate not in candidates:
                    candidates.append(candidate)
            try:
                for candidate in self.scene.items(scene_point):
                    if candidate not in candidates:
                        candidates.append(candidate)
            except Exception:
                pass
            selectable = [candidate for candidate in candidates if is_selectable(candidate)]
            fallback_distances: dict[int, float] = {}
            tolerance = pick_tolerance()
            try:
                search_rect = QRectF(
                    scene_point.x() - tolerance,
                    scene_point.y() - tolerance,
                    tolerance * 2.0,
                    tolerance * 2.0,
                )
                fallback_candidates = self.scene.items(search_rect)
            except Exception:
                fallback_candidates = self.scene.items()
            for candidate in fallback_candidates:
                if candidate in candidates or not is_selectable(candidate):
                    continue
                distance = fallback_distance(candidate, tolerance)
                if distance is None:
                    continue
                candidates.append(candidate)
                selectable.append(candidate)
                fallback_distances[id(candidate)] = distance

            def priority(candidate: Any) -> tuple[int, float, int]:
                data = candidate.data(0)
                kind = str(data.get("kind", "")) if isinstance(data, Mapping) else ""
                if current_panel == "geometry":
                    order = {
                        "geometry_line": 0,
                        "geometry_point": 1,
                        "geometry_region": 2,
                        "geometry_tunnel": 3,
                        "node": 8,
                        "edge": 9,
                        "element": 10,
                    }
                elif current_panel == "materials":
                    order = {
                        "geometry_region": 0,
                        "element": 1,
                        "node": 5,
                        "edge": 6,
                        "geometry_line": 8,
                        "geometry_point": 9,
                        "geometry_tunnel": 10,
                    }
                else:
                    order = {
                        "node": 0,
                        "edge": 1,
                        "element": 2,
                        "geometry_region": 6,
                        "geometry_line": 7,
                        "geometry_point": 8,
                        "geometry_tunnel": 9,
                    }
                return (
                    order.get(kind, 99),
                    fallback_distances.get(id(candidate), 0.0),
                    candidates.index(candidate) if candidate in candidates else 999,
                )

            if selectable:
                selected_item = sorted(selectable, key=priority)[0]
                data = selected_item.data(0)
                kind = str(data.get("kind", "")) if isinstance(data, Mapping) else ""
                if kind == "geometry_line":
                    return self._select_geometry_line_items(str(data.get("id", "")), additive=additive)
                if not additive:
                    self.scene.clearSelection()
                selected_item.setSelected(True)
                self._sync_model_geometry_editor_from_selection()
                self.statusBar().showMessage(f"選択しました: {kind} {data.get('id', '')}")
                return True
            if current_panel == "geometry" and self._select_nearest_geometry_line_at_scene_point(scene_point, additive=additive):
                return True
            if self._select_nearest_mesh_lod_item(scene_point, additive=additive):
                return True
            return False

        def _sync_model_geometry_editor_from_selection(self) -> None:
            if getattr(self, "model_geometry_point_x", None) is None:
                return
            line: dict[str, Any] | None = None
            target = "start"
            for item in self.scene.selectedItems():
                data = item.data(0)
                if isinstance(data, dict) and data.get("kind") == "geometry_endpoint":
                    candidate = self._geometry_line_by_id(str(data.get("id", "")))
                    if isinstance(candidate, dict):
                        line = candidate
                        target = "start" if str(data.get("endpoint", "end")) == "start" else "end"
                        index = self.model_geometry_point_target.findData("selected")
                        if index >= 0:
                            self.model_geometry_point_target.setCurrentIndex(index)
                        break
            if line is None:
                for item in self.scene.selectedItems():
                    data = item.data(0)
                    if isinstance(data, dict) and data.get("kind") == "geometry_line":
                        candidate = self._geometry_line_by_id(str(data.get("id", "")))
                        if isinstance(candidate, dict):
                            line = candidate
                            selected_target = str(self.model_geometry_point_target.currentData() or "selected")
                            if selected_target == "selected":
                                index = self.model_geometry_point_target.findData("start")
                                if index >= 0:
                                    self.model_geometry_point_target.setCurrentIndex(index)
                                selected_target = "start"
                            target = selected_target if selected_target in {"start", "end", "both"} else "start"
                            break
            if line is None:
                return
            try:
                x1, y1 = self._xy_pair(line.get("start", [0.0, 0.0]))
                x2, y2 = self._xy_pair(line.get("end", [0.0, 0.0]))
            except ValueError:
                return
            if target == "end":
                x, y = x2, y2
            elif target == "both":
                x, y = (x1 + x2) * 0.5, (y1 + y2) * 0.5
            else:
                x, y = x1, y1
            self.model_geometry_point_x.setText(f"{x:.12g}")
            self.model_geometry_point_y.setText(f"{y:.12g}")

        def _clear_selection_highlight_overlays(self) -> None:
            for item in list(getattr(self, "selection_highlight_items", [])):
                try:
                    self.scene.removeItem(item)
                except Exception:
                    pass
            self.selection_highlight_items = []

        def _refresh_selection_highlight_overlays(self) -> None:
            self._clear_selection_highlight_overlays()
            highlight_items: list[Any] = []
            node_pen = QPen(QColor("#ff6b00"))
            node_pen.setWidth(3)
            node_brush = QBrush(QColor(255, 193, 7, 72))
            edge_pen = QPen(QColor("#ff6b00"))
            edge_pen.setWidth(6)
            element_pen = QPen(QColor("#ff6b00"))
            element_pen.setWidth(4)
            for item in list(self.scene.selectedItems()):
                data = item.data(0)
                if not isinstance(data, Mapping):
                    continue
                kind = str(data.get("kind", ""))
                if kind == "node":
                    rect = item.sceneBoundingRect()
                    center = rect.center()
                    radius = max(7.0, max(rect.width(), rect.height()) * 0.85)
                    overlay = self.scene.addEllipse(center.x() - radius, center.y() - radius, radius * 2.0, radius * 2.0, node_pen, node_brush)
                    overlay.setData(0, {"kind": "selection_highlight", "target_kind": "node", "target": data.get("id", "")})
                    overlay.setZValue(10_000.0)
                    highlight_items.append(overlay)
                elif kind == "edge":
                    try:
                        line = item.line()
                        p1 = item.mapToScene(line.p1())
                        p2 = item.mapToScene(line.p2())
                    except Exception:
                        continue
                    overlay = self.scene.addLine(p1.x(), p1.y(), p2.x(), p2.y(), edge_pen)
                    overlay.setData(0, {"kind": "selection_highlight", "target_kind": "edge", "target": data.get("id", "")})
                    overlay.setZValue(9_999.0)
                    highlight_items.append(overlay)
                elif kind in {"element", "geometry_region"}:
                    try:
                        polygon = item.polygon()
                        mapped = QPolygonF([item.mapToScene(point) for point in polygon])
                    except Exception:
                        continue
                    overlay = self.scene.addPolygon(mapped, element_pen)
                    overlay.setData(0, {"kind": "selection_highlight", "target_kind": kind, "target": data.get("id", "")})
                    overlay.setZValue(9_998.0)
                    highlight_items.append(overlay)
            self.selection_highlight_items = highlight_items

        def _edge_tuple_key(self, edge: Any) -> tuple[str, ...]:
            edge_nodes = [str(value) for value in self._ensure_list(edge)]
            if len(edge_nodes) < 2:
                return ()
            return tuple(sorted((edge_nodes[0], edge_nodes[1]), key=self._natural_sort_key))

        def _select_left_tree_item_from_palette(self, key: str) -> None:
            tree = getattr(self, "tree", None)
            if tree is None or not key or getattr(self, "_syncing_tree_from_scene_selection", False):
                return
            root = tree.topLevelItem(0)
            item = self._find_tree_panel_item(root, key)
            if item is None:
                return
            previous = tree.currentItem()
            self._syncing_tree_from_scene_selection = True
            tree.blockSignals(True)
            try:
                if previous is not item:
                    self._set_tree_item_bold(previous, False)
                tree.setCurrentItem(item)
                self._set_tree_item_bold(item, True)
                self._focus_tree_category(item)
                tree.scrollToItem(item)
            finally:
                tree.blockSignals(False)
                self._syncing_tree_from_scene_selection = False

        def _tree_key_for_boundary_scene_selection(self, data_items: list[Mapping[str, Any]]) -> str:
            nodes = {str(data.get("id")) for data in data_items if data.get("kind") == "node" and data.get("id") not in (None, "")}
            edges = {
                self._edge_tuple_key(data.get("nodes", []))
                for data in data_items
                if data.get("kind") == "edge"
            }
            edges.discard(())
            cache = getattr(self, "_boundary_navigation_specs_cache", {})
            for key, payload in cache.items():
                text = str(key)
                if not text.startswith("boundary_condition:item:") or ":node:" not in text:
                    continue
                payload_nodes = {str(node) for node in self._ensure_list(payload.get("nodes", []))}
                if nodes and payload_nodes.intersection(nodes):
                    return text
            for key, payload in cache.items():
                text = str(key)
                if not text.startswith("boundary_condition:item:") or ":edge:" not in text:
                    continue
                payload_edges = {self._edge_tuple_key(edge) for edge in self._ensure_list(payload.get("edges", []))}
                payload_edges.discard(())
                if edges and payload_edges.intersection(edges):
                    return text
            for key, payload in cache.items():
                text = str(key)
                if not text.startswith("boundary_condition:item:"):
                    continue
                payload_nodes = {str(node) for node in self._ensure_list(payload.get("nodes", []))}
                payload_edges = {self._edge_tuple_key(edge) for edge in self._ensure_list(payload.get("edges", []))}
                payload_edges.discard(())
                if (nodes and payload_nodes.intersection(nodes)) or (edges and payload_edges.intersection(edges)):
                    return text
            return ""

        def _tree_key_for_load_scene_selection(self, data_items: list[Mapping[str, Any]]) -> str:
            nodes = {str(data.get("id")) for data in data_items if data.get("kind") == "node" and data.get("id") not in (None, "")}
            elements = {
                str(data.get("element", data.get("id")))
                for data in data_items
                if data.get("kind") in {"element", "mesh_quality_violation", "edge"} and data.get("element", data.get("id")) not in (None, "")
            }
            edges = {
                self._edge_tuple_key(data.get("nodes", []))
                for data in data_items
                if data.get("kind") == "edge"
            }
            edges.discard(())
            cache = getattr(self, "_load_navigation_specs_cache", {})
            for key, payload in cache.items():
                text = str(key)
                if not text.startswith("load_condition:item:") or ":node:" not in text:
                    continue
                payload_nodes = {str(node) for node in self._ensure_list(payload.get("nodes", []))}
                if nodes and payload_nodes.intersection(nodes):
                    return text
            for key, payload in cache.items():
                text = str(key)
                if not text.startswith("load_condition:item:") or ":edge:" not in text:
                    continue
                payload_edges = {self._edge_tuple_key(edge) for edge in self._ensure_list(payload.get("edges", []))}
                payload_edges.discard(())
                if edges and payload_edges.intersection(edges):
                    return text
            for key, payload in cache.items():
                text = str(key)
                if not text.startswith("load_condition:item:"):
                    continue
                payload_nodes = {str(node) for node in self._ensure_list(payload.get("nodes", []))}
                payload_elements = {str(element) for element in self._ensure_list(payload.get("elements", []))}
                payload_edges = {self._edge_tuple_key(edge) for edge in self._ensure_list(payload.get("edges", []))}
                payload_edges.discard(())
                if (
                    (nodes and payload_nodes.intersection(nodes))
                    or (edges and payload_edges.intersection(edges))
                    or (elements and payload_elements.intersection(elements))
                ):
                    return text
            return ""

        def _tree_key_for_material_scene_selection(self, data_items: list[Mapping[str, Any]]) -> str:
            cache = getattr(self, "_material_navigation_specs_cache", {})
            for data in data_items:
                kind = str(data.get("kind", ""))
                if kind == "geometry_region" and data.get("id") not in (None, ""):
                    key = f"material_assignment:region:{data.get('id')}"
                    if key in cache:
                        return key
                if kind in {"element", "edge", "mesh_quality_violation"}:
                    element_id = str(data.get("element", data.get("id", "")) or "")
                    key = f"material_assignment:element:{element_id}"
                    if element_id and key in cache:
                        return key
            for data in data_items:
                material = str(data.get("material", "") or "").strip()
                key = self._material_group_navigation_key(material)
                if key in cache:
                    return key
            if any(str(data.get("kind", "")) in {"geometry_region", "element"} for data in data_items):
                key = self._material_group_navigation_key("")
                if key in cache:
                    return key
            return ""

        def _tree_key_for_mesh_quality_scene_selection(self, data_items: list[Mapping[str, Any]]) -> str:
            cache = getattr(self, "_mesh_quality_navigation_specs_cache", {})
            for data in data_items:
                kind = str(data.get("kind", ""))
                if kind in {"mesh_quality_violation", "element", "edge"}:
                    element_id = str(data.get("element", data.get("id", "")) or "")
                    key = f"mesh_quality:element:{element_id}"
                    if element_id and key in cache:
                        return key
            selected_nodes = {str(data.get("id")) for data in data_items if data.get("kind") == "node" and data.get("id") not in (None, "")}
            if selected_nodes:
                for key, payload in cache.items():
                    if not str(key).startswith("mesh_quality:element:"):
                        continue
                    payload_nodes = {str(node) for node in self._ensure_list(payload.get("nodes", []))}
                    if payload_nodes.intersection(selected_nodes):
                        return str(key)
            return ""

        def _sync_left_tree_from_scene_selection(self, items: list[Any]) -> None:
            if getattr(self, "_syncing_scene_from_tree_selection", False):
                return
            data_items = [item.data(0) for item in items if isinstance(item.data(0), Mapping) and item.data(0).get("kind") != "selection_highlight"]
            if not data_items:
                return
            panel_key = self._panel_key_from_tree_key(str(getattr(self, "current_panel_key", "")))
            matchers: list[Callable[[list[Mapping[str, Any]]], str]] = []
            if panel_key == "boundary_conditions":
                matchers.append(self._tree_key_for_boundary_scene_selection)
            elif panel_key == "loads":
                matchers.append(self._tree_key_for_load_scene_selection)
            elif panel_key == "materials":
                matchers.append(self._tree_key_for_material_scene_selection)
            elif panel_key == "mesh":
                matchers.append(self._tree_key_for_mesh_quality_scene_selection)
            for matcher in matchers:
                key = matcher(data_items)
                if key:
                    self._select_left_tree_item_from_palette(key)
                    return

        def _scene_selection_changed(self) -> None:
            items = self.scene.selectedItems()
            self._refresh_selection_highlight_overlays()
            if not items:
                for attr in ("stage_selection_summary", "boundary_selection_summary", "load_selection_summary"):
                    summary = getattr(self, attr, None)
                    if summary is not None:
                        summary.setText("モデルビューで節点・辺・要素を複数選択してから操作します。")
                self._refresh_auxiliary_selection_context()
                self._refresh_cad_tool_button_state()
                self._refresh_mesh_tool_button_state()
                return
            self._sync_model_geometry_editor_from_selection()
            entities = self._selected_preview_entities()
            text = f"選択: 節点 {len(entities['nodes'])} / 辺 {len(entities['edges'])} / 要素 {len(entities['elements'])}"
            for attr in ("stage_selection_summary", "boundary_selection_summary", "load_selection_summary"):
                summary = getattr(self, attr, None)
                if summary is not None:
                    summary.setText(text)
            data = items[0].data(0)
            if isinstance(data, dict):
                self.statusBar().showMessage(f"{text} / {data.get('kind')} {data.get('id')} ({data.get('type', '')})")
            self._sync_left_tree_from_scene_selection(items)
            self._refresh_auxiliary_selection_context()
            self._refresh_cad_tool_button_state()
            self._refresh_mesh_tool_button_state()

        def _check_selection_changed(self) -> None:
            self._navigate_from_issue_table_selection(self.check_table)

        def _model_check_issue_selection_changed(self) -> None:
            table = getattr(self, "model_check_issue_table", None)
            if table is not None:
                self._navigate_from_issue_table_selection(table)

        def _issue_row_data(self, table: QTableWidget) -> tuple[str, str, str, dict[str, Any], int] | None:
            row = table.currentRow()
            if row < 0:
                indexes = table.selectedIndexes()
                row = indexes[0].row() if indexes else -1
            if row < 0 or row >= table.rowCount():
                return None
            values: list[str] = []
            for col in range(min(3, table.columnCount())):
                item = table.item(row, col)
                values.append(str(item.text() if item is not None else ""))
            while len(values) < 3:
                values.append("")
            item = table.item(row, 0)
            payload = item.data(Qt.ItemDataRole.UserRole) if item is not None else None
            return values[0], values[1], values[2], dict(payload) if isinstance(payload, Mapping) else {}, row

        @staticmethod
        def _strip_issue_prefix(path: str) -> str:
            text = str(path or "").strip()
            for prefix in ("入力補助.", "input_assistance."):
                if text.startswith(prefix):
                    return text[len(prefix) :]
            return text

        def _issue_path_text(self, target: str, payload: Mapping[str, Any]) -> str:
            for key in ("path", "target_path", "yaml_path", "_raw_target"):
                value = str(payload.get(key, "") or "").strip()
                if value:
                    return self._strip_issue_prefix(value)
            return self._strip_issue_prefix(target)

        def _panel_for_issue_target(self, target: str, payload: Mapping[str, Any]) -> str:
            path = self._issue_path_text(target, payload)
            text = f"{path} {target}".lower()
            if path.startswith("stages") or text.startswith("stage") or ".stages" in text:
                return "stages"
            if path.startswith(("materials", "material")) or "materials." in text or "material" in text:
                return "materials"
            if path.startswith(("boundary_conditions", "bc", "mpc_constraints", "mpc")) or "boundary_conditions" in text or "axisymmetric.boundary" in text:
                return "boundary_conditions"
            if path.startswith("loads") or "loads[" in text or "axisymmetric.loads" in text:
                return "loads"
            if path.startswith("mesh") or "mesh." in text or payload.get("elements"):
                return "mesh"
            if path.startswith(("geometry", "near_points")) or "geometry" in text or "near_points" in text:
                return "geometry"
            if path.startswith("analysis") or "axisymmetric" in text:
                return "analysis"
            return "model_check"

        @staticmethod
        def _path_index(path: str, key: str) -> int | None:
            match = re.search(rf"(?:^|\.){re.escape(key)}\[(\d+)\]", str(path or ""))
            if not match:
                return None
            try:
                return max(0, int(match.group(1)) - 1)
            except ValueError:
                return None

        def _select_table_cell_if_possible(self, table: QTableWidget | None, row: int | None, col: int | None = 0) -> bool:
            if table is None or row is None or row < 0 or row >= table.rowCount():
                return False
            target_col = max(0, min(int(col or 0), max(0, table.columnCount() - 1)))
            table.selectRow(row)
            table.setCurrentCell(row, target_col)
            item = table.item(row, target_col) or table.item(row, 0)
            if item is not None:
                table.scrollToItem(item)
            return True

        def _material_issue_column(self, field: str) -> int:
            key = str(field or "").lower().strip()
            aliases = {
                "name": 0,
                "model": 1,
                "type": 1,
                "e": 2,
                "young": 2,
                "nu": 3,
                "poisson": 3,
                "gamma": 4,
                "unit_weight": 4,
                "cohesion": 5,
                "c": 5,
                "phi": 6,
                "friction_angle": 6,
                "psi": 7,
                "dilation_angle": 7,
                "yield": 8,
                "yield_stress": 8,
                "hardening": 9,
                "k0": 10,
                "tension": 11,
                "tension_cutoff": 11,
                "ft": 12,
                "tensile_strength": 12,
                "extra": 13,
            }
            return aliases.get(key, 0)

        def _focus_material_issue_cell(self, path: str, payload: Mapping[str, Any]) -> bool:
            table = getattr(self, "material_table", None)
            if table is None:
                return False
            material = ""
            field = ""
            match = re.match(r"materials(?:\.|\[['\"]?)([^.\]'\"]+)(?:['\"]?\])?(?:\.(.+))?", path)
            if match:
                material = str(match.group(1) or "")
                field = str(match.group(2) or "")
            if not material:
                values = self._ensure_list(payload.get("materials", payload.get("material", [])))
                material = str(values[0]) if values else ""
            row = None
            if material:
                for index in range(table.rowCount()):
                    if self._table_text(table, index, 0).strip() == material:
                        row = index
                        break
            if row is None and table.rowCount():
                row = 0
            return self._select_table_cell_if_possible(table, row, self._material_issue_column(field))

        def _focus_stage_issue_cell(self, path: str) -> bool:
            stage_index = self._path_index(path, "stages")
            if self._select_table_cell_if_possible(getattr(self, "stage_table", None), stage_index, 0):
                self.populate_stage_detail_tables()
            focused = False
            if "boundary_conditions[" in path or ".bc[" in path:
                focused = self._select_table_cell_if_possible(getattr(self, "stage_boundary_table", None), self._path_index(path, "boundary_conditions"), 0)
            elif "loads[" in path:
                focused = self._select_table_cell_if_possible(getattr(self, "stage_load_table", None), self._path_index(path, "loads"), 0)
            elif "element_properties[" in path:
                focused = self._select_table_cell_if_possible(getattr(self, "stage_material_table", None), self._path_index(path, "element_properties"), 0)
            elif ".hydro." in path:
                focused = self._select_table_cell_if_possible(getattr(self, "stage_hydro_table", None), 0, 0)
            elif ".mpc[" in path or "mpc_constraints[" in path:
                focused = self._select_table_cell_if_possible(getattr(self, "stage_mpc_table", None), self._path_index(path, "mpc"), 0)
            return focused or stage_index is not None

        def _focus_issue_input_cell(self, panel: str, target: str, payload: Mapping[str, Any]) -> bool:
            path = self._issue_path_text(target, payload)
            if panel == "materials":
                return self._focus_material_issue_cell(path, payload)
            if panel == "boundary_conditions":
                row = self._path_index(path, "boundary_conditions")
                if row is None:
                    row = self._path_index(path, "bc")
                return self._select_table_cell_if_possible(getattr(self, "boundary_table", None), row, 0)
            if panel == "loads":
                return self._select_table_cell_if_possible(getattr(self, "load_table", None), self._path_index(path, "loads"), 0)
            if panel == "stages":
                return self._focus_stage_issue_cell(path)
            return False

        def _tree_key_for_issue(self, panel: str, target: str, payload: Mapping[str, Any]) -> str:
            path = self._issue_path_text(target, payload)
            stage_index = self._path_index(path, "stages")
            if panel == "stages" and stage_index is not None:
                return f"stage:item:{stage_index + 1}"
            if panel == "boundary_conditions":
                row = self._path_index(path, "boundary_conditions")
                if row is not None:
                    return f"boundary_condition:item:global:{row + 1}"
                row = self._path_index(path, "mpc_constraints")
                if row is not None:
                    return f"boundary_condition:item:global_mpc:{row + 1}"
            if panel == "loads":
                row = self._path_index(path, "loads")
                if row is not None:
                    return f"load_condition:item:global:{row + 1}"
            if panel == "materials":
                elements = [str(value) for value in self._ensure_list(payload.get("elements", [])) if str(value)]
                geometry = [str(value) for value in self._ensure_list(payload.get("geometry", [])) if str(value)]
                materials = [str(value) for value in self._ensure_list(payload.get("materials", payload.get("material", []))) if str(value)]
                if elements:
                    return f"material_assignment:element:{elements[0]}"
                if geometry:
                    return f"material_assignment:region:{geometry[0]}"
                if materials:
                    return self._material_group_navigation_key(materials[0])
            if panel == "mesh":
                elements = [str(value) for value in self._ensure_list(payload.get("elements", [])) if str(value)]
                if elements:
                    return f"mesh_quality:element:{elements[0]}"
            return panel

        def _navigate_from_issue_table_selection(self, table: QTableWidget) -> None:
            if getattr(self, "_navigating_model_issue", False):
                return
            row_data = self._issue_row_data(table)
            if row_data is None:
                return
            severity, target, detail, payload, _row = row_data
            if not target and not payload:
                return
            self._navigating_model_issue = True
            try:
                panel = self._panel_for_issue_target(target, payload)
                if panel != "model_check":
                    self._activate_panel(panel)
                tree_key = self._tree_key_for_issue(panel, target, payload)
                if tree_key:
                    self._select_tree_panel(tree_key)
                cell_focused = self._focus_issue_input_cell(panel, target, payload)
                if any(payload.get(key) for key in ("nodes", "node", "edges", "edge", "elements", "element", "geometry")):
                    self._select_preview_payload(payload)
                suffix = " / 入力セルを選択" if cell_focused else ""
                self.statusBar().showMessage(f"{severity} {target}: 修正候補へ移動しました{suffix}")
            finally:
                self._navigating_model_issue = False

        def _legacy_select_preview_from_issue_payload(self) -> None:
            indexes = self.check_table.selectedIndexes()
            if not indexes:
                return
            row = indexes[0].row()
            item = self.check_table.item(row, 0)
            payload = item.data(Qt.ItemDataRole.UserRole) if item is not None else None
            if not isinstance(payload, Mapping) or not payload:
                return
            self._select_preview_payload(payload)

        def _select_preview_payload(self, payload: Mapping[str, Any]) -> None:
            kinds = set(str(kind) for kind in self._ensure_list(payload.get("kinds", payload.get("kind", []))) if kind)
            node_ids = {str(value) for value in self._ensure_list(payload.get("nodes", payload.get("node", []))) if value is not None}
            element_ids = {str(value) for value in self._ensure_list(payload.get("elements", payload.get("element", []))) if value is not None}
            geometry_ids = {str(value) for value in self._ensure_list(payload.get("geometry", [])) if value is not None}
            edge_keys: set[tuple[str, str]] = set()
            for raw_edge in self._ensure_list(payload.get("edges", payload.get("edge", []))):
                edge_nodes = [str(value) for value in self._ensure_list(raw_edge)]
                if len(edge_nodes) >= 2:
                    edge_keys.add(tuple(sorted((edge_nodes[0], edge_nodes[1]), key=self._natural_sort_key)))
            self.scene.clearSelection()
            selected_items = []
            for item in self.scene.items():
                data = item.data(0)
                if not isinstance(data, dict):
                    continue
                kind = str(data.get("kind", ""))
                ident = str(data.get("id", ""))
                match = (
                    (kind == "node" and ident in node_ids)
                    or (kind == "element" and ident in element_ids)
                    or (kind == "mesh_quality_violation" and str(data.get("element", ident)) in element_ids)
                    or (
                        kind == "edge"
                        and tuple(sorted([str(value) for value in self._ensure_list(data.get("nodes", []))[:2]], key=self._natural_sort_key))
                        in edge_keys
                    )
                    or (kind.startswith("geometry") and ident in geometry_ids)
                    or (kind in kinds and not (node_ids or element_ids or geometry_ids or edge_keys))
                )
                if match:
                    item.setSelected(True)
                    selected_items.append(item)
            if not selected_items and (node_ids or element_ids or edge_keys):
                try:
                    mesh = getattr(self, "_preview_mesh_cache_value", None) or self._preview_mesh_from_config()
                except Exception:
                    mesh = None
                if mesh is not None:
                    added_proxy = False
                    for element_id in sorted(element_ids, key=self._natural_sort_key):
                        if self._add_mesh_lod_selection_proxy(mesh, kind="element", identifier=element_id, additive=added_proxy):
                            added_proxy = True
                    for node_id in sorted(node_ids, key=self._natural_sort_key):
                        if self._add_mesh_lod_selection_proxy(mesh, kind="node", identifier=node_id, additive=added_proxy):
                            added_proxy = True
                    for edge in sorted(edge_keys, key=lambda item: [self._natural_sort_key(value) for value in item]):
                        edge_id = f"{edge[0]}-{edge[1]}"
                        if self._add_mesh_lod_selection_proxy(mesh, kind="edge", identifier=edge_id, nodes=list(edge), additive=added_proxy):
                            added_proxy = True
                    if added_proxy:
                        selected_items = list(self.scene.selectedItems())
            if selected_items:
                rect = selected_items[0].sceneBoundingRect()
                for item in selected_items[1:]:
                    rect = rect.united(item.sceneBoundingRect())
                self.view.fitInView(rect.adjusted(-25.0, -25.0, 25.0, 25.0), Qt.AspectRatioMode.KeepAspectRatio)
                self.tabs.setCurrentIndex(0)
                self.statusBar().showMessage(f"チェック箇所を選択しました: {len(selected_items)}件")

        def new_sample(self) -> None:
            if self._guard_input_mutation("新規入力"):
                return
            self.current_input = None
            self.result_view.clear()
            self._load_cfg(plane_strain_quad4_sample(), keep_yaml=False)
            self.append_log(self.ui_message("log.sample.created"))

        def open_input(self) -> None:
            if self._guard_input_mutation("入力を開く"):
                return
            path, _ = QFileDialog.getOpenFileName(self, "入力YAML/JSONを開く", str(self.project_root), "YAML/JSON (*.yaml *.yml *.json)")
            if not path:
                return
            self.current_input = Path(path)
            self.project_root = self.current_input.parent
            self._reset_autosave_failure_backoff()
            try:
                data, preview = read_mapping_file_guarded(self.current_input)
            except Exception as exc:
                QMessageBox.warning(self, "GeoFEM", f"入力を開けません: {exc}")
                return
            self._syncing_yaml = True
            self.yaml_editor.setPlainText(preview.text)
            self._syncing_yaml = False
            self._load_cfg(data, keep_yaml=True)
            self.record_recent_project(self.current_input)
            self.append_log(f"[GUI] 入力を開きました: {path}")
            self._prompt_skip_analysis_conditions_after_yaml_load(source_label=str(path))

        def _prompt_skip_analysis_conditions_after_yaml_load(self, *, source_label: str = "") -> None:
            if self.input_execution_blockers():
                return
            try:
                if str(QApplication.platformName()).lower() == "offscreen":
                    return
            except Exception:
                pass
            reply = QMessageBox.question(
                self,
                "YAML Loaded" if self.gui_locale == "en" else "YAML読込完了",
                (
                    "The input is valid. Continue to the analysis run screen with these settings?"
                    if self.gui_locale == "en"
                    else "入力内容は正常です。読み込んだ解析条件で、解析実行画面へ進みますか？"
                ),
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.Yes,
            )
            self._apply_yaml_load_navigation_choice(reply, source_label=source_label)

        def _apply_yaml_load_navigation_choice(self, reply: Any, *, source_label: str = "") -> None:
            if reply == QMessageBox.StandardButton.Yes:
                self._skip_to_solver_wizard_after_yaml_load(source_label=source_label)
            else:
                self._activate_panel("analysis")
                detail = f": {source_label}" if source_label else ""
                self.statusBar().showMessage(f"YAMLを読み込みました。解析条件を確認できます{detail}")
                self.append_log(f"[GUI] YAML読込後に解析条件の確認画面へ移動しました{detail}")

        def _skip_to_solver_wizard_after_yaml_load(self, *, source_label: str = "") -> None:
            self._activate_panel("solver")
            detail = f": {source_label}" if source_label else ""
            self.statusBar().showMessage(f"YAMLを読み込みました。解析実行へ移動しました{detail}")
            self.append_log(f"[GUI] YAML読込後に解析実行画面へ移動しました{detail}")

        def _input_template_default_dir(self) -> Path:
            repo_root = Path(__file__).resolve().parents[2]
            for candidate in (self.project_root / "templates", repo_root / "examples", self.project_root):
                if candidate.exists():
                    return candidate
            return self.project_root

        def _input_template_candidate_paths(self) -> list[Path]:
            repo_root = Path(__file__).resolve().parents[2]
            bases = [repo_root / "examples", self.project_root / "templates"]
            paths: list[Path] = []
            seen: set[str] = set()
            for base in bases:
                if not base.exists():
                    continue
                for path in sorted(base.rglob("*")):
                    if not path.is_file() or path.suffix.lower() not in {".yaml", ".yml", ".json"}:
                        continue
                    resolved = str(path.resolve())
                    if resolved in seen:
                        continue
                    seen.add(resolved)
                    paths.append(path)
            return paths

        @staticmethod
        def _looks_like_input_template(data: Mapping[str, Any]) -> bool:
            if not isinstance(data, Mapping):
                return False
            template_keys = {"analysis", "mesh", "geometry", "materials", "boundary_conditions", "loads", "stages", "steps"}
            return any(key in data for key in template_keys)

        def _input_template_label(self, data: Mapping[str, Any], path: Path | None = None) -> str:
            if path is None:
                return "標準2Dサンプル"
            analysis = self._mapping(data.get("analysis", {}))
            mesh = self._mapping(data.get("mesh", {}))
            analysis_type = str(analysis.get("type", "")).strip()
            element_type = str(mesh.get("element_type", mesh.get("type", ""))).strip()
            integration = str(mesh.get("integration", "")).strip()
            suffix = " / ".join(value for value in (analysis_type, element_type, integration) if value)
            return f"{path.stem} ({suffix})" if suffix else path.stem

        def _input_template_integration_variants(self, data: Mapping[str, Any]) -> list[str]:
            variants = self._mapping(data.get("template_variants", {}))
            raw = variants.get("integrations", variants.get("integration", []))
            integrations = [str(value).strip() for value in self._ensure_list(raw) if str(value).strip()]
            return list(dict.fromkeys(integrations))

        @staticmethod
        def _input_template_variant_id(path: Path, *, integration: str) -> str:
            return f"{path.resolve()}::integration={integration}"

        @staticmethod
        def _split_input_template_variant_id(value: str | Path) -> tuple[Path, dict[str, str]]:
            text = str(value)
            marker = "::integration="
            if marker not in text:
                return Path(text), {}
            path_text, integration = text.split(marker, 1)
            return Path(path_text), {"integration": integration.strip()}

        def _apply_input_template_variant(self, data: Mapping[str, Any], variant: Mapping[str, str]) -> dict[str, Any]:
            cfg = copy.deepcopy(dict(data))
            integration = str(variant.get("integration", "")).strip()
            if integration:
                mesh = dict(self._mapping(cfg.get("mesh", {})))
                mesh["integration"] = integration
                cfg["mesh"] = mesh
                metadata = dict(self._mapping(cfg.get("metadata", {})))
                metadata["selected_integration"] = integration
                cfg["metadata"] = metadata
            return cfg

        def input_template_catalog(self) -> list[dict[str, str]]:
            catalog = [{"id": "builtin:plane_strain_quad4_sample", "label": self._input_template_label(plane_strain_quad4_sample()), "path": ""}]
            for path in self._input_template_candidate_paths():
                try:
                    metadata = read_input_template_metadata(path)
                except Exception:
                    continue
                data = metadata.as_mapping()
                if not self._looks_like_input_template(data):
                    continue
                integrations = self._input_template_integration_variants(data)
                if integrations:
                    for integration in integrations:
                        variant_data = self._apply_input_template_variant(data, {"integration": integration})
                        catalog.append(
                            {
                                "id": self._input_template_variant_id(path, integration=integration),
                                "label": self._input_template_label(variant_data, path),
                                "path": str(path.resolve()),
                            }
                        )
                    continue
                catalog.append({"id": str(path.resolve()), "label": self._input_template_label(data, path), "path": str(path.resolve())})
            return catalog

        def refresh_input_template_combo(self, *_args: Any) -> None:
            combo = getattr(self, "input_template_combo", None)
            if combo is None:
                return
            current = str(combo.currentData() or "")
            entries = self.input_template_catalog()
            combo.blockSignals(True)
            combo.clear()
            for entry in entries:
                combo.addItem(entry["label"], entry["id"])
                index = combo.count() - 1
                tooltip = entry["path"] or "GeoFEM標準サンプル"
                combo.setItemData(index, tooltip, Qt.ItemDataRole.ToolTipRole)
            if current:
                index = combo.findData(current)
                if index >= 0:
                    combo.setCurrentIndex(index)
            combo.blockSignals(False)

        def _load_input_template_mapping(self, data: Mapping[str, Any], source_label: str, *, prompt_skip_review: bool = False) -> bool:
            if not self._looks_like_input_template(data):
                QMessageBox.warning(self, "GeoFEM", "選択したファイルは入力テンプレートではありません。analysis、mesh、materials等を含むYAML/JSONを選択してください。")
                return False
            self.current_input = None
            self._load_cfg(self._template_with_display_geometry(data), keep_yaml=False)
            self.refresh_input_template_combo()
            self.statusBar().showMessage(f"入力テンプレートを読込みました: {source_label}")
            self.append_log(f"[GUI] 入力テンプレートを読込みました: {source_label}")
            if prompt_skip_review:
                self._prompt_skip_analysis_conditions_after_yaml_load(source_label=source_label)
            return True

        def load_selected_input_template(self, *_args: Any) -> None:
            combo = getattr(self, "input_template_combo", None)
            template_id = str(combo.currentData() or "") if combo is not None else "builtin:plane_strain_quad4_sample"
            if template_id == "builtin:plane_strain_quad4_sample":
                self._load_input_template_mapping(plane_strain_quad4_sample(), "標準2Dサンプル")
                return
            if not template_id:
                self.statusBar().showMessage("入力テンプレート候補がありません。")
                return
            self.load_project_template_input(template_id)

        def load_project_template_input(self, path: str | Path | bool | None = None, *_args: Any) -> None:
            if self._guard_input_mutation("入力テンプレート読込"):
                return
            if isinstance(path, bool):
                path = None
            if path is None:
                selected, _ = QFileDialog.getOpenFileName(
                    self,
                    "入力テンプレートを読込",
                    str(self._input_template_default_dir()),
                    "YAML/JSON (*.yaml *.yml *.json)",
                )
                if not selected:
                    return
                path = selected
            template_path, variant = self._split_input_template_variant_id(path)
            try:
                data, preview = read_mapping_file_guarded(template_path)
            except Exception as exc:
                QMessageBox.warning(self, "GeoFEM", f"入力テンプレートを読込めません: {exc}")
                return
            if variant:
                data = self._apply_input_template_variant(data, variant)
            if not self._load_input_template_mapping(data, str(template_path), prompt_skip_review=True):
                return
            if preview.truncated:
                self.yaml_editor.setPlainText(preview.text)

        def save_input(self) -> None:
            if self._guard_input_mutation("入力を保存"):
                return
            if self._project_locked_by_other():
                QMessageBox.warning(self, "GeoFEM", f"他の利用者がロック中のため保存できません: {self._read_project_lock()}")
                return
            if self.current_input is None:
                path, _ = QFileDialog.getSaveFileName(self, "入力YAMLを保存", str(self.project_root / "input" / "model.yaml"), "YAML (*.yaml)")
                if not path:
                    return
                self.current_input = Path(path)
            self.current_input.parent.mkdir(parents=True, exist_ok=True)
            self.current_input.write_text(self.yaml_editor.toPlainText(), encoding="utf-8")
            self.record_recent_project(self.current_input)
            self.append_log(f"[GUI] 入力を保存しました: {self.current_input}")

        def save_input_as(self) -> None:
            if self._guard_input_mutation("名前を付けて保存"):
                return
            if self._project_locked_by_other():
                QMessageBox.warning(self, "GeoFEM", f"他の利用者がロック中のため保存できません: {self._read_project_lock()}")
                return
            default_path = self.current_input if self.current_input is not None else self.project_root / "input" / "model.yaml"
            path, _ = QFileDialog.getSaveFileName(self, "名前を付けて入力YAMLを保存", str(default_path), "YAML (*.yaml)")
            if not path:
                return
            self.current_input = Path(path)
            self.save_input()

        def _analysis_output_config_from_widgets(self) -> dict[str, Any]:
            policy_widget = getattr(self, "analysis_output_policy", None)
            policy = str(policy_widget.currentData() or "same_as_input") if policy_widget is not None else "same_as_input"
            formats: list[str] = []
            if getattr(self, "analysis_output_csv", None) is None or self.analysis_output_csv.isChecked():
                formats.append("csv")
            if getattr(self, "analysis_output_vtk", None) is None or self.analysis_output_vtk.isChecked():
                formats.append("vtk")
            output: dict[str, Any] = {
                "root_policy": policy,
                "run_folder": "{input_stem}_run_{timestamp}",
                "formats": formats or ["csv"],
                "write_log": bool(getattr(self, "analysis_output_log", None) is None or self.analysis_output_log.isChecked()),
                "lazy_reports": True,
            }
            custom = getattr(self, "analysis_output_custom_dir", None)
            if policy == "custom" and custom is not None and custom.text().strip():
                output["directory"] = custom.text().strip()
            return output

        def update_analysis_output_path_preview(self) -> None:
            preview = getattr(self, "analysis_output_preview", None)
            if preview is None:
                return
            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            input_path = self.current_input or (self.project_root / "input" / f"analysis_{timestamp}.yaml")
            try:
                run_dir = resolve_analysis_output_dir(
                    input_path,
                    self._analysis_output_config_from_widgets(),
                    self.project_root,
                    timestamp=timestamp,
                    default_root_policy="same_as_input",
                )
                preview.setText(str(run_dir / "results"))
            except Exception as exc:
                if self.gui_locale == "en":
                    preview.setText(f"Could not resolve output location: {exc}")
                else:
                    preview.setText(f"出力先を解決できません: {exc}")

        def browse_analysis_output_directory(self) -> None:
            current = getattr(self, "analysis_output_custom_dir", None)
            start = current.text().strip() if current is not None and current.text().strip() else str(self.project_root)
            selected = QFileDialog.getExistingDirectory(self, "出力フォルダーを選択", start)
            if not selected:
                return
            if current is not None:
                current.setText(selected)
            policy = getattr(self, "analysis_output_policy", None)
            if policy is not None:
                for index in range(policy.count()):
                    if str(policy.itemData(index) or "") == "custom":
                        policy.setCurrentIndex(index)
                        break
            self.update_analysis_output_path_preview()

        def _ensure_current_input_saved_for_solver(self, timestamp: str) -> Path:
            if self.current_input is None:
                path = self.project_root / "input" / f"analysis_{timestamp}.yaml"
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(self.yaml_editor.toPlainText(), encoding="utf-8")
                self.current_input = path
                self.record_recent_project(path)
                self.append_log(f"[GUI] 解析用入力YAMLを保存しました: {path}")
            return self.current_input

        def run_solver(self) -> None:
            if self._project_locked_by_other():
                QMessageBox.warning(self, "GeoFEM", f"他の利用者がロック中のため解析できません: {self._read_project_lock()}")
                return
            if self.process is not None and self.process.state() != QProcess.ProcessState.NotRunning:
                QMessageBox.warning(self, "GeoFEM", "解析ジョブが実行中です。")
                return
            if self._solver_preflight_job_id:
                self.statusBar().showMessage(self.ui_message("status.preflight.running"))
                return
            try:
                synced = self.sync_from_yaml()
            except Exception as exc:
                QMessageBox.warning(self, "GeoFEM", f"YAML反映に失敗しました: {exc}")
                return
            if not synced:
                return
            if self.input_execution_blockers():
                self.show_input_execution_blockers("解析実行", warn_dialog=True)
                return
            self.run_solver_preflight_async()

        def run_solver_preflight_async(self) -> None:
            if self.model_check_timer.isActive():
                self.model_check_timer.stop()
            signature = self._model_check_cache_signature()
            cached = self._cached_model_check_issues(signature)
            if cached is not None:
                self._solver_preflight_snapshot = signature
                self.check_summary.setText("Pre-run model check reused cached diagnostics.")
                self.statusBar().showMessage(self.check_summary.text())
                self.refresh_solver_panel()
                self._finish_solver_preflight_issues(cached, source="cache")
                return
            cfg_snapshot = copy.deepcopy(self.cfg)
            target = str(self.current_input) if self.current_input is not None else "current-config"
            job_id = self.gui_jobs.start_job("model_check", target=target, metadata={"mode": "solver_preflight"})
            self._solver_preflight_job_id = job_id
            self._solver_preflight_snapshot = signature
            self.check_summary.setText(
                "Pre-run model check is running in the background..."
                if self.gui_locale == "en"
                else "解析直前モデルチェックをバックグラウンド実行中..."
            )
            self.statusBar().showMessage(self.check_summary.text())
            self.refresh_solver_panel()
            runner = QtCallableRunner(job_id, lambda: collect_model_issues_snapshot(type(self), cfg_snapshot))
            self._gui_task_runners[job_id] = runner
            runner.signals.finished.connect(self._solver_preflight_finished)
            runner.signals.failed.connect(self._solver_preflight_failed)
            self.gui_thread_pool.start(runner)

        def _finish_solver_preflight_issues(self, issues: list[tuple[str, str, str, dict[str, Any]]], *, source: str = "worker") -> None:
            self._apply_model_check_issues(issues)
            self._model_check_dirty = False
            self.append_log(f"[GUI] solver preflight {source}: {len(issues)} issues")
            if self._solver_preflight_snapshot and self._solver_preflight_snapshot != self._model_check_cache_signature():
                QMessageBox.warning(self, "GeoFEM", "Model input changed after the pre-run check. Please run analysis again.")
                self._solver_preflight_snapshot = ""
                return
            self._solver_preflight_snapshot = ""
            if any(issue[0] == "ERROR" for issue in issues):
                QMessageBox.warning(self, "GeoFEM", "Model check has ERROR items. Fix them before running analysis.")
                self.panel_stack.setCurrentWidget(self.panel_pages["model_check"])
                return
            self._start_solver_process_after_preflight()

        def _solver_preflight_finished(self, job_id: str, issues_obj: Any) -> None:
            if job_id != self._solver_preflight_job_id:
                self._gui_task_runners.pop(job_id, None)
                return
            issues = list(issues_obj or [])
            self._complete_gui_worker_job(job_id, status="finished", message=f"{len(issues)} issues")
            self._solver_preflight_job_id = ""
            self._store_model_check_cache(getattr(self, "_solver_preflight_snapshot", ""), issues)
            self._finish_solver_preflight_issues(self._copy_model_check_issues(issues), source="worker")
            self.refresh_solver_panel()

        def _solver_preflight_failed(self, job_id: str, message: str) -> None:
            if job_id != self._solver_preflight_job_id:
                self._gui_task_runners.pop(job_id, None)
                return
            manifest = self._write_gui_worker_failure_manifest(job_id, message)
            self._complete_gui_worker_job(job_id, status="failed", message=message)
            self._solver_preflight_job_id = ""
            self._solver_preflight_snapshot = ""
            self._apply_model_check_issues([("ERROR", "solver_preflight", message, {})])
            suffix = f" manifest={manifest}" if manifest is not None else ""
            self.append_log(f"[GUI] 解析直前モデルチェック失敗: {message}{suffix}")
            self.refresh_solver_panel()

        def _start_solver_process_after_preflight(self) -> None:
            if self.process is not None and self.process.state() != QProcess.ProcessState.NotRunning:
                QMessageBox.warning(self, "GeoFEM", "解析ジョブが実行中です。")
                return
            ensure_project_dirs(self.project_root)
            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            source_input = self._ensure_current_input_saved_for_solver(timestamp)
            solver_input_text = self._solver_input_text_with_gui_defaults()
            try:
                solver_cfg = yaml.safe_load(solver_input_text) if solver_input_text.strip() else {}
            except Exception:
                solver_cfg = {}
            output_cfg = solver_cfg.get("output", {}) if isinstance(solver_cfg, Mapping) else {}
            run_dir = resolve_analysis_output_dir(
                source_input,
                output_cfg if isinstance(output_cfg, Mapping) else {},
                self.project_root,
                timestamp=timestamp,
                default_root_policy="same_as_input",
            )
            run_dir.mkdir(parents=True, exist_ok=True)
            input_path = run_dir / "input.yaml"
            input_path.write_text(solver_input_text, encoding="utf-8")
            self.last_run_dir = run_dir
            self._solver_cancel_requested_local = False
            cancel_file = run_dir / ".solver_cancel"
            try:
                cancel_file.unlink(missing_ok=True)
            except OSError:
                pass
            self._solver_cancel_file = cancel_file
            self._refresh_tree(select_panel="solver")
            self.process = QProcess(self)
            self._solver_job_id = self.gui_jobs.start_job("solver", target=str(input_path), metadata={"run_dir": str(run_dir)})
            frozen = bool(getattr(sys, "frozen", False))
            if frozen:
                app_root = Path(sys.executable).resolve().parent
                cli_exe = app_root / "GeoFEM-CLI.exe"
                program = str(cli_exe if cli_exe.exists() else Path(sys.executable).resolve())
                args = ["solve", str(input_path), "--out", str(run_dir / "results"), "--cancel-file", str(cancel_file)]
                self.process.setWorkingDirectory(str(app_root))
            else:
                repo_root = Path(__file__).resolve().parents[2]
                program = sys.executable
                args = ["-m", "geofem_app.cli", "solve", str(input_path), "--out", str(run_dir / "results"), "--cancel-file", str(cancel_file)]
                self.process.setWorkingDirectory(str(repo_root))
            self.process.readyReadStandardOutput.connect(self._read_stdout)
            self.process.readyReadStandardError.connect(self._read_stderr)
            self.process.stateChanged.connect(lambda _state: self.refresh_solver_panel())
            self.process.finished.connect(lambda code, _status: self._finished(code, run_dir))
            self._solver_started_perf = time.perf_counter()
            self.last_solver_elapsed_seconds = None
            self._set_solver_navigation_suppressed(True)
            self.append_log(f"[GUI] 解析開始: {Path(program).name} {' '.join(args)}")
            self.process.start(program, args)
            self.refresh_solver_panel()

        def _solver_input_text_with_gui_defaults(self) -> str:
            text = apply_gui_solver_output_defaults(self.yaml_editor.toPlainText())
            try:
                loaded = yaml.safe_load(text) if text.strip() else {}
            except Exception:
                return text
            if not isinstance(loaded, Mapping):
                return text
            cfg = copy.deepcopy(dict(loaded))
            output = cfg.get("output", cfg.get("outputs", {}))
            output_map = dict(output) if isinstance(output, Mapping) else {}
            output_map.update(self._analysis_output_config_from_widgets())
            cfg["output"] = output_map
            mesh = cfg.get("mesh")
            if isinstance(mesh, Mapping) and str(mesh.get("source", "")).strip().lower() in {"external", "file"} and self.current_input is not None:
                updated_mesh = dict(mesh)
                updated_mesh.setdefault("base_dir", str(self.current_input.resolve().parent))
                cfg["mesh"] = updated_mesh
            return yaml.safe_dump(cfg, allow_unicode=True, sort_keys=False)

        def _request_solver_cancel_file(self) -> None:
            cancel_file = getattr(self, "_solver_cancel_file", None)
            if cancel_file is None:
                return
            try:
                cancel_file.parent.mkdir(parents=True, exist_ok=True)
                cancel_file.write_text(
                    json.dumps({"cancel_requested": True, "requested_at": datetime.now().isoformat(timespec="seconds")}, ensure_ascii=False),
                    encoding="utf-8",
                )
                self.append_log(f"[GUI] cooperative solver cancel requested: {cancel_file}")
            except OSError as exc:
                self.append_log(f"[GUI] failed to write solver cancel file: {exc}")

        def _kill_solver_if_still_running(self) -> None:
            if self.process is not None and self.process.state() != QProcess.ProcessState.NotRunning:
                self.process.kill()
                self.append_log("[GUI] solver process killed after cooperative cancel grace period")

        def stop_solver(self) -> None:
            if not self._solver_process_running():
                self.statusBar().showMessage("解析は実行されていません。")
                self.refresh_solver_panel()
                return
            if self._solver_cancel_requested():
                self.statusBar().showMessage("解析の中断要求は送信済みです。")
                self.refresh_solver_panel()
                return
            if self._solver_job_id:
                self.gui_jobs.request_cancel(self._solver_job_id)
            self._solver_cancel_requested_local = True
            self._request_solver_cancel_file()
            QTimer.singleShot(2000, self._kill_solver_if_still_running)
            self.append_log("[GUI] 解析中断を要求しました")
            self.statusBar().showMessage("解析の中断を要求しました。停止処理を待っています。")
            self.refresh_solver_panel()

        def reset_analysis_results(self) -> None:
            if self._solver_process_running() or self._solver_preflight_job_id:
                QMessageBox.warning(self, "GeoFEM", "解析の開始処理または実行中は結果リセットできません。停止後に実行してください。")
                self.refresh_solver_panel()
                return
            if not self._analysis_results_available():
                self.statusBar().showMessage("リセットする解析結果がありません。")
                self.refresh_solver_panel()
                return
            self.last_run_dir = None
            self._loaded_result_summary_path = None
            self.result_stage_dir = None
            self.result_stage_dirs = []
            self.current_result_kind = ""
            self.post_mode = "none"
            self.post_component = "q"
            self.result_displacements = {}
            self.result_element_values = {}
            self.result_node_values = {}
            self.compare_element_values = {}
            self.result_distribution = []
            self.result_rows = []
            self.result_headers = []
            self.result_table_page_index = 0
            self.result_table_csv_path = None
            self.result_table_csv_summary = None
            self._post_element_display_values = {}
            self._last_auto_result_visual_signature = ""
            for combo_name in ("result_stage_selector", "aux_result_stage_combo"):
                combo = getattr(self, combo_name, None)
                if combo is not None:
                    combo.blockSignals(True)
                    combo.clear()
                    combo.blockSignals(False)
            result_component_combo = getattr(self, "result_component", None)
            if result_component_combo is not None:
                result_component_combo.blockSignals(True)
                self._set_combo(result_component_combo, "q")
                result_component_combo.blockSignals(False)
            for combo_name, default_text in (
                ("result_table_component", "value"),
                ("aux_result_component_combo", "q"),
            ):
                combo = getattr(self, combo_name, None)
                if combo is not None:
                    combo.blockSignals(True)
                    combo.clear()
                    combo.addItem(default_text, default_text)
                    combo.setCurrentIndex(0)
                    combo.blockSignals(False)
            if getattr(self, "result_table", None) is not None:
                self.result_table.clearContents()
                self.result_table.setRowCount(0)
            if getattr(self, "result_view", None) is not None:
                self.result_view.clear()
            if getattr(self, "results_summary", None) is not None:
                self.results_summary.setText("解析結果をリセットしました。入力データは維持されています。")
            if getattr(self, "report_summary", None) is not None:
                self.report_summary.setText("解析結果リセット後は、必要に応じて解析を再実行してください。")
            if getattr(self, "aux_result_control_group", None) is not None:
                self.aux_result_control_group.setVisible(False)
            self._refresh_result_action_states()
            self._refresh_tree(select_panel=getattr(self, "current_panel_key", "analysis"))
            self.update_preview()
            self.refresh_workflow_guidance()
            self.refresh_solver_panel()
            self.append_log("[GUI] 解析結果の表示状態をリセットしました。入力データは維持しています。")

        def _read_stdout(self) -> None:
            if self.process:
                self.append_log(bytes(self.process.readAllStandardOutput()).decode("utf-8", errors="replace"))

        def _read_stderr(self) -> None:
            if self.process:
                self.append_log(bytes(self.process.readAllStandardError()).decode("utf-8", errors="replace"))

        def _solver_elapsed_seconds(self) -> float:
            started = float(getattr(self, "_solver_started_perf", 0.0) or 0.0)
            if started <= 0.0:
                return 0.0
            return max(time.perf_counter() - started, 0.0)

        def _format_solver_elapsed(self, elapsed_seconds: float) -> str:
            total_seconds = max(0, int(round(float(elapsed_seconds))))
            hours, remainder = divmod(total_seconds, 3600)
            minutes, seconds = divmod(remainder, 60)
            if self.gui_locale == "en":
                if hours:
                    return f"{hours} h {minutes:02d} min {seconds:02d} sec"
                return f"{minutes} min {seconds:02d} sec"
            if hours:
                return f"{hours}時間{minutes:02d}分{seconds:02d}秒"
            return f"{minutes}分{seconds:02d}秒"

        def _solver_completion_srm_text(self, summary_path: Path) -> str:
            try:
                data = json.loads(summary_path.read_text(encoding="utf-8"))
            except Exception:
                return ""
            stages = data.get("stages", []) if isinstance(data, Mapping) else []
            if not isinstance(stages, list):
                return ""
            rows: list[str] = []
            for stage in stages:
                if not isinstance(stage, Mapping):
                    continue
                solver = stage.get("solver", {})
                if not isinstance(solver, Mapping):
                    continue
                srm = solver.get("srm")
                if not isinstance(srm, Mapping):
                    continue
                trials = srm.get("trials", [])
                trial_count = len(trials) if isinstance(trials, list) else 0
                rows.append(
                    f"{stage.get('name', '')}: {srm_fos_display(srm, locale=self.gui_locale)}, "
                    f"stable={srm.get('stable_factor', '')}, failed={srm.get('failed_factor', '')}, trials={trial_count}"
                )
            return "" if not rows else "SRM FOS: " + " / ".join(rows)

        def _solver_completion_message(self, code: int, elapsed_seconds: float, run_dir: Path) -> str:
            elapsed_text = self._format_solver_elapsed(elapsed_seconds)
            results_dir = run_dir / "results"
            srm_text = self._solver_completion_srm_text(results_dir / "summary.json")
            srm_line = f"\n{srm_text}" if srm_text else ""
            if self.gui_locale == "en":
                status = "Analysis completed." if code == 0 else f"Analysis finished with exit code {code}."
                return f"{status}\nElapsed time: {elapsed_text}{srm_line}\nOutput: {results_dir}"
            status = "解析が終了しました。" if code == 0 else f"解析が終了しました。終了コード: {code}"
            return f"{status}\n経過時間: {elapsed_text}\n出力先: {results_dir}"

        def _show_solver_completion_dialog(self, code: int, elapsed_seconds: float, run_dir: Path) -> None:
            title = "Analysis Finished" if self.gui_locale == "en" else "解析終了"
            message = self._solver_completion_message(code, elapsed_seconds, run_dir)
            srm_text = self._solver_completion_srm_text(run_dir / "results" / "summary.json")
            if srm_text and srm_text not in message:
                message = f"{message}\n{srm_text}"
            if code == 0:
                QMessageBox.information(self, title, message)
            else:
                QMessageBox.warning(self, title, message)

        def _srm_log_lines_from_summary_path(self, summary_path: Path) -> list[str]:
            try:
                data = json.loads(summary_path.read_text(encoding="utf-8"))
            except Exception:
                return []
            if not isinstance(data, Mapping):
                return []
            return self._srm_log_lines_from_summary(data)

        def _srm_log_lines_from_summary(self, summary_data: Mapping[str, Any]) -> list[str]:
            stages = summary_data.get("stages", [])
            if not isinstance(stages, list):
                return []
            lines: list[str] = []
            for stage in stages:
                if not isinstance(stage, Mapping):
                    continue
                solver = stage.get("solver", {})
                if not isinstance(solver, Mapping):
                    continue
                srm = solver.get("srm")
                if not isinstance(srm, Mapping):
                    continue
                stage_name = str(stage.get("name", ""))
                trials = srm.get("trials", [])
                trial_count = len(trials) if isinstance(trials, list) else 0
                lines.append(
                    f"[GUI][SRM] {stage_name}: {srm_fos_display(srm, locale=self.gui_locale)}, "
                    f"stable_factor={srm.get('stable_factor', '')}, failed_factor={srm.get('failed_factor', '')}, "
                    f"trials={trial_count}, search_mode={srm.get('search_mode', '')}, "
                    f"fos_status={srm_result_status(srm)}, fos_confidence={srm_result_confidence(srm)}"
                )
                if not isinstance(trials, list):
                    continue
                for index, trial in enumerate(trials, start=1):
                    if not isinstance(trial, Mapping):
                        continue
                    lines.append(
                        f"[GUI][SRM trial] {stage_name} #{index}: factor={trial.get('factor', '')}, "
                        f"ok={trial.get('ok', '')}, converged={trial.get('converged', '')}, "
                        f"plastic_ratio={trial.get('plastic_ratio', '')}, "
                        f"reason={trial.get('failure_reason') or trial.get('error') or ''}"
                    )
            return lines

        def _finished(self, code: int, run_dir: Path) -> None:
            elapsed_seconds = self._solver_elapsed_seconds()
            self.last_solver_elapsed_seconds = elapsed_seconds
            self._set_solver_navigation_suppressed(False)
            self._solver_cancel_file = None
            if self._solver_job_id:
                if code == 0 and not self.gui_jobs.is_cancel_requested(self._solver_job_id):
                    self.gui_jobs.finish_job(self._solver_job_id, message=f"exit code {code}, elapsed {elapsed_seconds:.3f}s")
                elif self.gui_jobs.is_cancel_requested(self._solver_job_id):
                    self.gui_jobs.cancel_job(self._solver_job_id, message=f"exit code {code}, elapsed {elapsed_seconds:.3f}s")
                else:
                    self.gui_jobs.fail_job(self._solver_job_id, message=f"exit code {code}, elapsed {elapsed_seconds:.3f}s")
                self._solver_job_id = ""
            self._solver_cancel_requested_local = False
            self.refresh_solver_panel()
            self.append_log(f"[GUI] 解析終了 code={code} elapsed={self._format_solver_elapsed(elapsed_seconds)}")
            self._flush_log_buffer()
            self._write_gui_log_artifact(run_dir)
            summary = run_dir / "results" / "summary.json"
            if summary.exists():
                self._set_result_view_file(summary)
                self.results_summary.setText(f"最新結果: {summary}")
                self._load_result_summary(summary)
                srm_log_lines = self._srm_log_lines_from_summary_path(summary)
                for line in srm_log_lines:
                    self.append_log(line)
                if srm_log_lines:
                    self._flush_log_buffer()
                    self._write_gui_log_artifact(run_dir)
            else:
                failure = run_dir / "results" / "failure_report.json"
                if failure.exists():
                    try:
                        data = json.loads(failure.read_text(encoding="utf-8"))
                    except Exception:
                        data = {}
                    analysis = data.get("failure_analysis", {}) if isinstance(data.get("failure_analysis", {}), Mapping) else {}
                    recovery = data.get("failure_recovery", {}) if isinstance(data.get("failure_recovery", {}), Mapping) else {}
                    actions = recovery.get("actions", []) if isinstance(recovery.get("actions", []), list) else []
                    first_action = actions[0] if actions and isinstance(actions[0], Mapping) else {}
                    message = "\n".join(
                        [
                            f"解析に失敗しました: {failure}",
                            f"主原因: {analysis.get('primary_cause', '')}",
                            f"対象画面: {analysis.get('primary_gui_panel', '')}",
                            f"入力箇所: {analysis.get('primary_input_path', '')}",
                            f"推奨修正: {analysis.get('primary_recommended_fix', '')}",
                            f"復旧候補: {first_action.get('title', '')} - {first_action.get('action', '')}",
                            f"再実行条件: {analysis.get('primary_rerun_condition', '')}",
                        ]
                    )
                    self.result_view.setPlainText(message)
                    self.results_summary.setText(message.replace("\n", " / "))
                    panel = str(analysis.get("primary_gui_panel", "model_check"))
                    if panel in self.panel_pages and self.result_navigation_target_allowed(panel):
                        self._activate_panel(panel)
                    else:
                        self._activate_panel("results")
                else:
                    self.result_view.setPlainText(f"summary.json が見つかりません: {summary}")
            self._refresh_result_action_states()
            self.refresh_workflow_guidance()
            self.refresh_solver_panel()
            self._show_solver_completion_dialog(code, elapsed_seconds, run_dir)

