        def _distribution_from_csv(self, path: Path, component: str) -> list[tuple[float, float]]:
            out: list[tuple[float, float]] = []
            try:
                with path.open("r", encoding="utf-8", newline="") as f:
                    reader = csv.DictReader(f)
                    headers = list(reader.fieldnames or [])
                    if component not in headers:
                        return []
                    if "x" in headers:
                        x_field = "x"
                    elif "step" in headers:
                        x_field = "step"
                    elif "lambda" in headers and component != "lambda":
                        x_field = "lambda"
                    elif "arc_length" in headers and component != "arc_length":
                        x_field = "arc_length"
                    else:
                        x_field = ""
                    for index, row in enumerate(reader):
                        try:
                            xval = float(row.get(x_field, index) if x_field else index)
                            yval = float(row.get(component, 0.0) or 0.0)
                        except (TypeError, ValueError):
                            continue
                        if math.isfinite(xval) and math.isfinite(yval):
                            out.append((xval, yval))
            except OSError:
                return []
            out.sort(key=lambda item: item[0])
            return out

        def refresh_distribution_plot(self) -> None:
            component = self.result_table_component.currentText()
            if not component:
                return
            if self.result_rows:
                self.result_distribution = self._distribution_from_rows(self.result_rows, preferred=(component,))
            elif self.result_table_csv_path is not None:
                self.result_distribution = self._distribution_from_csv(self.result_table_csv_path, component)
            else:
                return
            self.post_component = component
            if self.result_distribution:
                self.post_mode = "distribution"
