        def _populate_case_compare_table(self, comparison: Mapping[str, Any]) -> None:
            table = getattr(self, "case_compare_table", None)
            if table is None:
                return
            rows = [row for row in comparison.get("rows", []) if isinstance(row, Mapping)]
            table.setRowCount(min(len(rows), 200))
            fields = ["category", "artifact", "metric", "status", "current", "baseline", "abs_difference", "rel_difference", "detail"]
            for row_index, row in enumerate(rows[:200]):
                for col, field in enumerate(fields):
                    table.setItem(row_index, col, QTableWidgetItem(str(row.get(field, ""))))
            table.resizeRowsToContents()

