        def _parse_model_xy_text(self, text: str, label: str) -> tuple[float, float]:
            parts = [part.strip() for part in text.replace(";", ",").split(",") if part.strip()]
            if len(parts) != 2:
                raise ValueError(f"{label}は x,y 形式で入力してください。")
            return float(parts[0]), float(parts[1])

        def create_measurement_distribution(self) -> None:
            try:
                p0 = self._parse_model_xy_text(self.measure_line_start.text(), "測線始点")
                p1 = self._parse_model_xy_text(self.measure_line_end.text(), "測線終点")
            except ValueError as exc:
                QMessageBox.warning(self, "GeoFEM", str(exc))
                return
            dx = p1[0] - p0[0]
            dy = p1[1] - p0[1]
            length = math.hypot(dx, dy)
            if length <= 1.0e-12:
                QMessageBox.warning(self, "GeoFEM", "測線長が0です。")
                return
            try:
                from geofem_app.fem2d import mesh_from_config

                mesh = mesh_from_config(self.cfg)
            except Exception as exc:
                QMessageBox.warning(self, "GeoFEM", f"測線分布を作成できません: {exc}")
                return
            samples: list[tuple[float, float, float]] = []
            if self.result_element_values:
                values = self._display_element_values(mesh)
                node_index = mesh.node_index
                for element in mesh.elements:
                    if element.id not in values:
                        continue
                    corner_count = 3 if element.type.startswith("TRI") else 4
                    pts = [mesh.coords[node_index[nid]] for nid in element.nodes[:corner_count]]
                    cx = float(sum(float(point[0]) for point in pts) / len(pts))
                    cy = float(sum(float(point[1]) for point in pts) / len(pts))
                    tx = ((cx - p0[0]) * dx + (cy - p0[1]) * dy) / (length * length)
                    dist = abs((cx - p0[0]) * dy - (cy - p0[1]) * dx) / length
                    if 0.0 <= tx <= 1.0:
                        samples.append((tx * length, dist, values[element.id]))
            elif self.result_node_values:
                node_index = mesh.node_index
                for nid, value in self.result_node_values.items():
                    if nid not in node_index:
                        continue
                    idx = node_index[nid]
                    x = float(mesh.coords[idx, 0])
                    y = float(mesh.coords[idx, 1])
                    tx = ((x - p0[0]) * dx + (y - p0[1]) * dy) / (length * length)
                    dist = abs((x - p0[0]) * dy - (y - p0[1]) * dx) / length
                    if 0.0 <= tx <= 1.0:
                        samples.append((tx * length, dist, float(value)))
            if not samples:
                QMessageBox.information(self, "GeoFEM", "測線上に表示中のPost値がありません。")
                return
            band = max(length * 0.08, 1.0e-9)
            close = [sample for sample in samples if sample[1] <= band]
            if close:
                samples = close
            samples.sort(key=lambda item: item[0])
            self.result_distribution = [(station, value) for station, _dist, value in samples]
            component = self.post_component or self._combo_value(self.result_component, "value") or "value"
            rows = [{"station": f"{station:.6g}", component: f"{value:.6g}"} for station, value in self.result_distribution]
            self.result_rows = rows
            self.result_headers = ["station", component]
            self._populate_result_table(rows)
            self.post_component = component
            self.post_mode = "distribution"
            self.tabs.setCurrentIndex(0)
            self.update_preview()
            self.results_summary.setText(f"任意測線分布を作成しました: {len(self.result_distribution)}点")

        def _scene_image_with_layout(self, *, max_side: float = 2400.0) -> QImage | None:
            rect = self.scene.itemsBoundingRect()
            if not rect.isValid() or rect.width() <= 0.0 or rect.height() <= 0.0:
                return None
            source = rect.adjusted(-28.0, -28.0, 28.0, 28.0)
            title_height = 96.0
            ratio = min(1.0, max_side / max(source.width(), source.height() + title_height, 1.0))
            width = max(1, int(math.ceil(source.width() * ratio)))
            drawing_height = max(1, int(math.ceil(source.height() * ratio)))
            title_px = max(72, int(math.ceil(title_height * ratio)))
            image = QImage(width, drawing_height + title_px, QImage.Format.Format_ARGB32)
            image.fill(QColor("#ffffff"))
            painter = QPainter(image)
            painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
            self.scene.render(painter, QRectF(0.0, 0.0, float(width), float(drawing_height)), source)
            y0 = drawing_height + 8
            painter.setPen(QPen(QColor("#111111")))
            template = self.drawing_template.currentText() if getattr(self, "drawing_template", None) is not None else "GeoFEAS風A4"
            if "GeoFEAS" in template:
                painter.fillRect(0, drawing_height, width, title_px, QColor("#f8f9fa"))
                painter.drawRect(0, drawing_height, width - 1, title_px - 1)
                painter.drawLine(max(12, width // 2) - 12, drawing_height, max(12, width // 2) - 12, drawing_height + title_px)
                painter.drawLine(0, drawing_height + title_px // 2, width - 1, drawing_height + title_px // 2)
            elif "標準" in template:
                painter.drawRect(0, drawing_height, width - 1, title_px - 1)
                painter.drawLine(0, drawing_height + title_px // 2, width - 1, drawing_height + title_px // 2)
            else:
                painter.drawRect(0, drawing_height, width - 1, title_px - 1)
            title = self.drawing_title_edit.text().strip() if getattr(self, "drawing_title_edit", None) is not None else "GeoFEM 2D Post"
            scale = self.drawing_scale_edit.text().strip() if getattr(self, "drawing_scale_edit", None) is not None else ""
            stage = self.result_stage_selector.currentText() if getattr(self, "result_stage_selector", None) is not None else ""
            component = self.post_component or (self._combo_value(self.result_component) if getattr(self, "result_component", None) is not None else "")
            painter.drawText(12, y0 + 16, f"Title: {title}")
            painter.drawText(12, y0 + 38, f"Stage: {stage}")
            painter.drawText(max(12, width // 2), y0 + 16, f"Component: {component}")
            painter.drawText(max(12, width // 2), y0 + 38, f"Scale: {scale}")
            painter.drawText(12, y0 + 60, f"Generated: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
            painter.end()
            return image

