        def export_scene_image_async(self) -> None:
            default = self.project_root / "post_view.png"
            if self.result_stage_dir is not None:
                default = self.result_stage_dir / "post_view.png"
            path, _ = QFileDialog.getSaveFileName(self, "Post image export", str(default), "PNG (*.png)")
            if not path:
                return
            image = self._scene_image_with_layout()
            if image is None:
                QMessageBox.information(self, "GeoFEM", "No Post scene is available for export.")
                return
            out = Path(path)
            self._start_post_export_job(
                "save_image",
                out,
                lambda image=image.copy(), out=out: save_post_image_snapshot(image, out, role="post_image"),
            )

        def export_scene_image(self) -> None:
            default = self.project_root / "post_view.png"
            if self.result_stage_dir is not None:
                default = self.result_stage_dir / "post_view.png"
            path, _ = QFileDialog.getSaveFileName(self, "図面出力", str(default), "PNG (*.png)")
            if not path:
                return
            out = Path(path)
            if out.suffix.lower() != ".png":
                out = out.with_suffix(".png")
            image = self._scene_image_with_layout()
            if image is None:
                QMessageBox.information(self, "GeoFEM", "出力する図面がありません。")
                return
            if not image.save(str(out)):
                QMessageBox.warning(self, "GeoFEM", f"図面を保存できませんでした: {out}")
                return
            self.results_summary.setText(f"図面を保存しました: {out}")

        def add_current_view_to_drawing_layout_async(self) -> None:
            image = self._scene_image_with_layout(max_side=1800.0)
            if image is None:
                QMessageBox.information(self, "GeoFEM", "No Post scene is available for layout.")
                return
            out_dir = (self.result_stage_dir or self.project_root) / "post_snapshots"
            out_dir.mkdir(parents=True, exist_ok=True)
            self.post_snapshot_count += 1
            out = out_dir / f"layout_view_{self.post_snapshot_count:03d}.png"
            self._start_post_export_job(
                "save_image",
                out,
                lambda image=image.copy(), out=out: save_post_image_snapshot(image, out, role="layout_image"),
            )

        def add_current_view_to_drawing_layout(self) -> Path | None:
            image = self._scene_image_with_layout(max_side=1800.0)
            if image is None:
                QMessageBox.information(self, "GeoFEM", "配置するPostビューがありません。")
                return None
            out_dir = (self.result_stage_dir or self.project_root) / "post_snapshots"
            out_dir.mkdir(parents=True, exist_ok=True)
            self.post_snapshot_count += 1
            out = out_dir / f"layout_view_{self.post_snapshot_count:03d}.png"
            if not image.save(str(out)):
                QMessageBox.warning(self, "GeoFEM", f"図面配置画像を保存できませんでした: {out}")
