        def _add_drawing_layout_row(self, image_path: Path) -> None:
            table = getattr(self, "drawing_layout_table", None)
            if table is None:
                return
            row = table.rowCount()
            table.insertRow(row)
            title = self.drawing_title_edit.text().strip() if getattr(self, "drawing_title_edit", None) is not None else image_path.stem
            scale = self.drawing_scale_edit.text().strip() if getattr(self, "drawing_scale_edit", None) is not None else ""
            columns = [str(image_path), title, scale, "0.08", f"{0.08 + 0.44 * (row % 2):.2f}", "0.84", "0.38"]
            for col, value in enumerate(columns):
                table.setItem(row, col, QTableWidgetItem(value))

        def _drawing_layout_specs(self) -> list[dict[str, Any]]:
            table = getattr(self, "drawing_layout_table", None)
            if table is None:
                return []
            specs = []
            for row in range(table.rowCount()):
                path = Path(self._table_text(table, row, 0).strip())
                if not path.exists():
                    continue
                try:
                    x = float(self._table_text(table, row, 3) or 0.05)
                    y = float(self._table_text(table, row, 4) or 0.05)
                    w = float(self._table_text(table, row, 5) or 0.9)
                    h = float(self._table_text(table, row, 6) or 0.4)
                except ValueError:
                    continue
                specs.append(
                    {
                        "path": path,
                        "title": self._table_text(table, row, 1).strip() or path.stem,
                        "scale": self._table_text(table, row, 2).strip(),
                        "rect": (max(0.0, min(1.0, x)), max(0.0, min(1.0, y)), max(0.05, min(1.0, w)), max(0.05, min(1.0, h))),
                    }
                )
            return specs

        def _drawing_template_library(self) -> dict[str, dict[str, Any]]:
            library: dict[str, dict[str, Any]] = {
                "GeoFEAS風A4": {"title_height": 96, "frame": "geo_feas", "company": "GeoFEM"},
                "標準A4": {"title_height": 96, "frame": "standard", "company": ""},
                "簡易タイトル欄": {"title_height": 72, "frame": "simple", "company": ""},
                "企業様式:社内標準": {"title_height": 110, "frame": "corporate", "company": "Company", "approval": True},
                "企業様式:照査付き": {"title_height": 128, "frame": "review", "company": "Company", "approval": True, "review_table": True},
            }
            bundled = Path(__file__).resolve().parent.parent / "templates" / "drawing_templates.yaml"
            if bundled.exists():
                try:
                    data = yaml.safe_load(bundled.read_text(encoding="utf-8")) or {}
                    bundled_library = data.get("drawing_template_library", data)
                    if isinstance(bundled_library, Mapping):
                        for name, spec in bundled_library.items():
                            if isinstance(spec, Mapping):
                                library[str(name)] = dict(spec)
                except Exception:
                    pass
            project_templates = self.project_root / "templates" / "drawing_templates.yaml"
            if project_templates.exists():
                try:
                    data = yaml.safe_load(project_templates.read_text(encoding="utf-8")) or {}
                    project_library = data.get("drawing_template_library", data)
                    if isinstance(project_library, Mapping):
                        for name, spec in project_library.items():
                            if isinstance(spec, Mapping):
                                library[str(name)] = dict(spec)
                except Exception:
                    pass
            custom = self._mapping(self.cfg.get("drawing_template_library", {}))
            for name, spec in custom.items():
                if isinstance(spec, Mapping):
                    library[str(name)] = dict(spec)
            return library

        def _refresh_drawing_template_combo(self) -> None:
            combo = getattr(self, "drawing_template", None)
            if combo is None:
                return
            current = combo.currentText()
            combo.blockSignals(True)
            combo.clear()
            combo.addItems(sorted(self._drawing_template_library()))
            if current:
                self._set_combo(combo, current)
            combo.blockSignals(False)

        def _drawing_template_data(self) -> dict[str, Any]:
            rows = []
            table = getattr(self, "drawing_layout_table", None)
            if table is not None:
                for row in range(table.rowCount()):
                    rows.append(
                        {
                            "image": self._table_text(table, row, 0),
                            "title": self._table_text(table, row, 1),
                            "scale": self._table_text(table, row, 2),
                            "x": self._table_text(table, row, 3),
                            "y": self._table_text(table, row, 4),
                            "w": self._table_text(table, row, 5),
                            "h": self._table_text(table, row, 6),
                        }
                    )
            return {
                "title": self.drawing_title_edit.text().strip() if getattr(self, "drawing_title_edit", None) is not None else "",
                "scale": self.drawing_scale_edit.text().strip() if getattr(self, "drawing_scale_edit", None) is not None else "",
                "template": self.drawing_template.currentText() if getattr(self, "drawing_template", None) is not None else "",
                "layout": rows,
            }

        def install_project_drawing_templates(self, destination: str | Path | None = None) -> Path:
            bundled = Path(__file__).resolve().parent.parent / "templates" / "drawing_templates.yaml"
            if destination is None:
                destination = self.project_root / "templates" / "drawing_templates.yaml"
            out = Path(destination)
            out.parent.mkdir(parents=True, exist_ok=True)
            if bundled.exists():
                shutil.copyfile(bundled, out)
            else:
                out.write_text(yaml.safe_dump({"drawing_template_library": self._drawing_template_library()}, allow_unicode=True, sort_keys=False), encoding="utf-8")
            self._refresh_drawing_template_combo()
            self.write_audit_event("drawing_templates_installed", str(out), {"source": str(bundled)})
            if getattr(self, "results_summary", None) is not None:
                self.results_summary.setText(f"企業様式テンプレートを配置しました: {out}")
            return out

        def save_drawing_template(self, path: str | Path | None = None) -> Path | None:
            if path is None:
                default = self.project_root / "post_drawing_template.yaml"
                selected, _ = QFileDialog.getSaveFileName(self, "図面枠テンプレート保存", str(default), "YAML (*.yaml *.yml)")
                if not selected:
                    return None
                path = selected
            out = Path(path)
            out.write_text(
                yaml.safe_dump(
                    {
                        "drawing_template": self._drawing_template_data(),
                        "drawing_template_library": self._drawing_template_library(),
                    },
                    allow_unicode=True,
                    sort_keys=False,
                ),
                encoding="utf-8",
            )
            self.results_summary.setText(f"図面枠テンプレートを保存しました: {out}")
            return out

        def load_drawing_template(self, path: str | Path | None = None) -> None:
            if path is None:
                selected, _ = QFileDialog.getOpenFileName(self, "図面枠テンプレート読込", str(self.project_root), "YAML (*.yaml *.yml)")
                if not selected:
                    return
                path = selected
            data = yaml.safe_load(Path(path).read_text(encoding="utf-8")) or {}
            if isinstance(data.get("drawing_template_library"), Mapping):
                self.cfg["drawing_template_library"] = {str(key): dict(value) for key, value in data["drawing_template_library"].items() if isinstance(value, Mapping)}
                self._refresh_drawing_template_combo()
            template = self._mapping(data.get("drawing_template", data))
            self.drawing_title_edit.setText(str(template.get("title", self.drawing_title_edit.text())))
            self.drawing_scale_edit.setText(str(template.get("scale", self.drawing_scale_edit.text())))
            if template.get("template"):
                self._set_combo(self.drawing_template, str(template["template"]))
            table = getattr(self, "drawing_layout_table", None)
            if table is not None:
                rows = self._ensure_list(template.get("layout", []))
                table.setRowCount(len(rows))
                for row, raw in enumerate(rows):
                    raw_map = self._mapping(raw)
                    values = [raw_map.get(key, "") for key in ("image", "title", "scale", "x", "y", "w", "h")]
                    for col, value in enumerate(values):
                        table.setItem(row, col, QTableWidgetItem(str(value)))
            self.results_summary.setText(f"図面枠テンプレートを読込みました: {path}")

        def _draw_layout_pdf_page(self, painter: QPainter, specs: list[dict[str, Any]]) -> None:
            viewport = painter.viewport()
            painter.fillRect(viewport, QColor("#ffffff"))
            painter.setPen(QPen(QColor("#111111")))
            painter.drawRect(viewport.adjusted(8, 8, -8, -8))
            title = self.drawing_title_edit.text().strip() if getattr(self, "drawing_title_edit", None) is not None else "GeoFEM 2D Post"
            painter.drawText(24, 32, title)
            for spec in specs:
                x, y, w, h = spec["rect"]
                target = QRectF(
                    viewport.left() + viewport.width() * x,
                    viewport.top() + viewport.height() * y,
                    viewport.width() * w,
                    viewport.height() * h,
                )
                image = QImage(str(spec["path"]))
                if image.isNull():
                    continue
                painter.drawImage(target, image)
                painter.drawRect(target)
                painter.drawText(int(target.left()), int(target.bottom()) + 16, f"{spec['title']}  {spec['scale']}")

