        @staticmethod
        def _element_rows_to_values(rows: list[dict[str, str]], field: str) -> dict[str, float]:
            values: dict[str, float] = {}
            for row in rows:
                eid = row.get("element_id")
                if not eid:
                    continue
                try:
                    values[str(eid)] = float(row.get(field, row.get("q", row.get("sigma_1", 0.0))) or 0.0)
                except ValueError:
                    values[str(eid)] = 0.0
            return values

        @staticmethod
        def _node_rows_to_values(rows: list[dict[str, str]], field: str) -> dict[str, float]:
            values: dict[str, float] = {}
            for row in rows:
                nid = row.get("node_id")
                if not nid:
                    continue
                try:
                    values[str(nid)] = float(row.get(field, 0.0) or 0.0)
                except ValueError:
                    values[str(nid)] = 0.0
            return values

        def _distribution_from_rows(self, rows: list[dict[str, str]], *, preferred: tuple[str, ...]) -> list[tuple[float, float]]:
            if not rows:
                return []
            y_field = next((field for field in preferred if field in rows[0]), "")
            if not y_field:
                y_field = self.result_table_component.currentText()
            if not y_field or y_field not in rows[0]:
                return []
            x_field = "x" if "x" in rows[0] else ("step" if "step" in rows[0] else ("lambda" if "lambda" in rows[0] and y_field != "lambda" else ""))
            if not x_field:
                x_field = "arc_length" if "arc_length" in rows[0] and y_field != "arc_length" else ""
            out: list[tuple[float, float]] = []
            for index, row in enumerate(rows):
                try:
                    xval = float(row.get(x_field, index) if x_field else index)
                    yval = float(row.get(y_field, 0.0) or 0.0)
                except ValueError:
                    continue
                out.append((xval, yval))
            out.sort(key=lambda item: item[0])
            return out

        def _parse_yaml_editor(self) -> dict[str, Any]:
            data = yaml.safe_load(self.yaml_editor.toPlainText())
            if not isinstance(data, Mapping):
                raise ValueError("input root must be a mapping")
            return dict(data)

        def _geometry_cfg(self) -> dict[str, Any]:
            geometry = self.cfg.get("geometry", {})
            if "geometry" not in self.cfg or not isinstance(geometry, dict):
                geometry = {}
                self.cfg["geometry"] = geometry
            return geometry

        def _mesh_cfg(self) -> dict[str, Any]:
            mesh = self.cfg.get("mesh", {})
            if "mesh" not in self.cfg or not isinstance(mesh, dict):
                mesh = {}
                self.cfg["mesh"] = mesh
            return mesh

        def _stages(self) -> list[dict[str, Any]]:
            raw = self.cfg.get("stages", self.cfg.get("steps", []))
            if not isinstance(raw, list):
                raw = []
            stages: list[dict[str, Any]] = []
            for idx, stage in enumerate(raw, start=1):
                stages.append(dict(stage) if isinstance(stage, Mapping) else {"name": f"Stage-{idx}", "type": "static"})
            self.cfg["stages"] = stages
            return stages

        def _last_stage(self) -> dict[str, Any]:
            stages = self._stages()
            if not stages:
                stages.append({"name": "Stage-1", "type": "static"})
            return stages[-1]

        def _selected_stage_row(self) -> int | None:
            table = getattr(self, "stage_table", None)
            if table is None:
                return None
            indexes = table.selectedIndexes()
            if not indexes:
                return None
            return indexes[0].row()

        def _selected_stage_context(self) -> tuple[list[dict[str, Any]], int, dict[str, Any]]:
            stages = self._stages()
            if not stages:
                stages.append({"name": "Stage-1", "type": "static"})
                self.cfg["stages"] = stages
            row = self._selected_stage_row()
            if row is None or row < 0 or row >= len(stages):
                row = len(stages) - 1
            return stages, row, stages[row]

        def _selected_preview_entities(self) -> dict[str, Any]:
            nodes: set[str] = set()
            elements: set[str] = set()
            edge_seen: set[tuple[str, str]] = set()
            edges: list[tuple[str, str]] = []
            for item in self.scene.selectedItems():
                data = item.data(0)
                if not isinstance(data, Mapping):
                    continue
                kind = str(data.get("kind", ""))
                if kind == "node" and data.get("id") is not None:
                    nodes.add(str(data.get("id")))
                elif kind == "element" and data.get("id") is not None:
                    elements.add(str(data.get("id")))
                elif kind == "edge":
                    raw_nodes = [str(value) for value in self._ensure_list(data.get("nodes", []))]
                    if len(raw_nodes) >= 2:
                        edge = (raw_nodes[0], raw_nodes[1])
                        key = tuple(sorted(edge, key=self._natural_sort_key))
                        if key not in edge_seen:
                            edge_seen.add(key)
                            edges.append(edge)
            if not nodes and not elements and not edges:
                current = getattr(getattr(self, "tree", None), "currentItem", lambda: None)()
                key = str(current.data(0, Qt.ItemDataRole.UserRole) or "") if current is not None else ""
                if key.startswith("mesh_quality:"):
                    payload = getattr(self, "_mesh_quality_navigation_specs_cache", {}).get(key, {})
                    for value in self._ensure_list(payload.get("nodes", [])):
                        if value is not None:
                            nodes.add(str(value))
                    for value in self._ensure_list(payload.get("elements", [])):
                        if value is not None:
                            elements.add(str(value))
            return {"nodes": nodes, "elements": elements, "edges": edges}

        def _selected_nodes_for_stage_action(self, *, include_elements: bool = True) -> list[str]:
            entities = self._selected_preview_entities()
            nodes = set(entities["nodes"])
            for a, b in entities["edges"]:
                nodes.add(a)
                nodes.add(b)
            if include_elements and not nodes and entities["elements"]:
                try:
                    from geofem_app.fem2d import mesh_from_config

                    mesh = mesh_from_config(self.cfg)
                    selected = set(entities["elements"])
                    for element in mesh.elements:
                        if element.id in selected:
                            nodes.update(str(nid) for nid in element.nodes)
                except Exception:
                    pass
            return sorted(nodes, key=self._natural_sort_key)

        def _selected_edges_for_stage_action(self) -> list[tuple[str, str]]:
            entities = self._selected_preview_entities()
            if entities["edges"]:
                return list(entities["edges"])
            if not entities["elements"]:
                return []
            try:
                from geofem_app.fem2d import mesh_from_config

                mesh = mesh_from_config(self.cfg)
            except Exception:
                return []
            edge_map = {
                "TRI3": [(0, 1), (1, 2), (2, 0)],
                "TRI6": [(0, 3), (3, 1), (1, 4), (4, 2), (2, 5), (5, 0)],
                "QUAD4": [(0, 1), (1, 2), (2, 3), (3, 0)],
                "QUAD8": [(0, 4), (4, 1), (1, 5), (5, 2), (2, 6), (6, 3), (3, 7), (7, 0)],
            }
            counts: dict[tuple[str, str], tuple[int, tuple[str, str]]] = {}
            selected = set(entities["elements"])
            for element in mesh.elements:
                if element.id not in selected:
                    continue
                for a, b in edge_map.get(element.type, []):
                    edge = (str(element.nodes[a]), str(element.nodes[b]))
                    key = tuple(sorted(edge, key=self._natural_sort_key))
                    count, first_edge = counts.get(key, (0, edge))
                    counts[key] = (count + 1, first_edge)
            boundary_edges = [edge for count, edge in counts.values() if count == 1]
            return sorted(boundary_edges, key=lambda edge: (self._natural_sort_key(edge[0]), self._natural_sort_key(edge[1])))

        def _active_elements_after_stage_index(self, mesh: Any, index: int) -> set[str]:
            active = {element.id for element in mesh.elements if element.active}
            if index < 0:
                return active
            for stage in self._stages()[: index + 1]:
                stype = str(stage.get("type", "")).lower().strip()
                if stype in {"excavation", "death", "deactivate"}:
                    active.difference_update(self._stage_element_targets(mesh, stage))
            return active

        @staticmethod
        def _natural_sort_key(value: Any) -> tuple[int, Any]:
            text = str(value)
            try:
                return 0, int(text)
            except ValueError:
                return 1, text

        @staticmethod
        def _stable_json(value: Any) -> str:
            return json.dumps(value, ensure_ascii=False, sort_keys=True, default=str)

        def _short_json(self, value: Any, limit: int = 160) -> str:
            text = self._stable_json(value)
            return text if len(text) <= limit else text[: limit - 3] + "..."

        def _stage_visual_state(self, mesh: Any) -> tuple[set[str], str]:
            active = {element.id for element in mesh.elements if element.active}
            stages = self._stages()
            row = self._selected_stage_row()
            if row is None:
                return active, ""
            row = min(row, len(stages) - 1)
            if row < 0:
                return active, ""
            for stage in stages[: row + 1]:
                stype = str(stage.get("type", "")).lower().strip()
                if stype not in {"excavation", "death", "deactivate"}:
                    continue
                targets = self._stage_element_targets(mesh, stage)
                active.difference_update(targets)
            return active, str(stages[row].get("name", f"Stage-{row + 1}"))

        def _stage_element_targets(self, mesh: Any, stage: Mapping[str, Any]) -> set[str]:
            if bool(stage.get("all", False)):
                return {element.id for element in mesh.elements}
            if "element" in stage:
                return {str(stage["element"])}
            if "elements" in stage:
                raw = stage["elements"]
                if isinstance(raw, str) and raw in mesh.element_sets:
                    return set(mesh.element_sets[raw])
                return {str(value) for value in self._ensure_list(raw)}
            for key in ("set", "element_set", "elementSet"):
                if key in stage:
                    name = str(stage[key])
                    return set(mesh.element_sets.get(name, []))
            return set()

        def _element_targets_for_spec(self, mesh: Any, spec: Mapping[str, Any]) -> set[str]:
            return self._stage_element_targets(mesh, spec)

        def _node_targets_for_spec(self, mesh: Any, spec: Mapping[str, Any]) -> list[str]:
            if "node" in spec:
                nid = str(spec["node"])
                return [nid] if nid in mesh.node_index else []
            if "nodes" in spec:
                raw = spec["nodes"]
                if isinstance(raw, str) and raw in mesh.node_sets:
                    return list(mesh.node_sets[raw])
                return [str(value) for value in self._ensure_list(raw) if str(value) in mesh.node_index]
            if "set" in spec:
                return list(mesh.node_sets.get(str(spec["set"]), []))
            if bool(spec.get("all", False)):
                return list(mesh.node_ids)
            return []

        def _edge_targets_for_spec(self, mesh: Any, spec: Mapping[str, Any]) -> list[tuple[str, str]]:
            raw_edges = spec.get("edges", spec.get("edge"))
            if raw_edges is not None:
                if isinstance(raw_edges, str):
                    ids = mesh.node_sets.get(raw_edges, [])
                    return [(ids[i], ids[i + 1]) for i in range(len(ids) - 1)]
                raw_list = self._ensure_list(raw_edges)
                if len(raw_list) == 2 and not isinstance(raw_list[0], (list, tuple, Mapping)):
                    a, b = str(raw_list[0]), str(raw_list[1])
                    return [(a, b)] if a in mesh.node_index and b in mesh.node_index else []
                edges = []
                for edge in raw_list:
                    nodes = [str(value) for value in self._ensure_list(edge)]
                    if len(nodes) >= 2 and nodes[0] in mesh.node_index and nodes[1] in mesh.node_index:
                        edges.append((nodes[0], nodes[1]))
                return edges
            if "nodes" in spec:
                nodes = [str(value) for value in self._ensure_list(spec["nodes"])]
                if len(nodes) == 2 and nodes[0] in mesh.node_index and nodes[1] in mesh.node_index:
                    return [(nodes[0], nodes[1])]
            if "set" in spec:
                ids = mesh.node_sets.get(str(spec["set"]), [])
                return [(ids[i], ids[i + 1]) for i in range(len(ids) - 1)]
            return []

        def _check_node_target(self, mesh: Any, spec: Any, label: str, add_issue: Any) -> None:
            if not isinstance(spec, Mapping):
                add_issue("ERROR", label, "節点対象はマッピングで指定してください。")
                return
            targets = self._node_targets_for_spec(mesh, spec)
            if not targets:
                add_issue("ERROR", label, "節点/節点セット参照が空または不正です。", {})
                return
            add_issue("INFO", label, f"節点対象 {len(targets)} 件", {"nodes": targets[:80]})

        def _check_load_target(self, mesh: Any, spec: Any, label: str, add_issue: Any) -> None:
            if not isinstance(spec, Mapping):
                add_issue("ERROR", label, "荷重はマッピングで指定してください。")
                return
            ltype = str(spec.get("type", "")).lower().strip()
            if ltype in {"gravity", "self_weight", "body"} or bool(spec.get("self_weight", False)):
                requested = []
                if "material" in spec:
                    requested = [str(spec["material"])]
                elif "materials" in spec:
                    requested = [str(value) for value in self._ensure_list(spec["materials"])]
                if requested:
                    available = {str(getattr(element, "material", "")) for element in getattr(mesh, "elements", [])}
                    missing = [name for name in requested if name not in available]
                    if missing:
                        add_issue("ERROR", label, f"体積力の材料参照が見つかりません: {', '.join(missing)}")
                        return
                    add_issue("INFO", label, f"材料体積力 {len(requested)} 件", {"materials": requested})
                    return
                element_targets = self._element_targets_for_spec(mesh, spec)
                if any(key in spec for key in ("element", "elements", "element_set", "set")) and not element_targets:
                    add_issue("ERROR", label, "体積力の要素/要素セット参照が空または不正です。")
                    return
                if element_targets:
                    elements = sorted(element_targets, key=self._natural_sort_key)
                    add_issue("INFO", label, f"要素体積力 {len(element_targets)} 件", {"elements": elements[:80]})
                    return
                add_issue("INFO", label, "自重/体積力")
                return
            if "edge" in spec or "edges" in spec:
                edges = self._edge_targets_for_spec(mesh, spec)
                if not edges:
                    add_issue("ERROR", label, "辺/辺セット参照が空または不正です。")
                    return
                add_issue("INFO", label, f"辺対象 {len(edges)} 件", {"nodes": list(dict.fromkeys([nid for edge in edges for nid in edge]))[:80]})
                return
            targets = self._node_targets_for_spec(mesh, spec)
            if not targets:
                add_issue("ERROR", label, "荷重の節点/節点セット参照が空または不正です。")
                return
            add_issue("INFO", label, f"節点荷重対象 {len(targets)} 件", {"nodes": targets[:80]})

        def _check_pore_target(self, mesh: Any, spec: Any, label: str, add_issue: Any) -> None:
            if not isinstance(spec, Mapping):
                add_issue("ERROR", label, "水理境界はマッピングで指定してください。")
                return
            edges = self._edge_targets_for_spec(mesh, spec)
            nodes = self._node_targets_for_spec(mesh, spec)
            if not edges and not nodes:
                add_issue("ERROR", label, "水理境界の節点/辺参照が空または不正です。")
                return
            payload_nodes = list(dict.fromkeys([nid for edge in edges for nid in edge] + nodes))[:80]
            add_issue("INFO", label, f"水理境界対象 edge={len(edges)} / node={len(nodes)}", {"nodes": payload_nodes})

        def _check_axisymmetric_gui_model(self, mesh: Any, constraints: Mapping[int, float], loads: list[Any], stages: list[dict[str, Any]], add_issue: Any) -> None:
            sets = self._axisymmetric_reference_sets_from_mesh(mesh)
            axis_nodes = sets.get("axisymmetric_axis", [])
            outer_nodes = sets.get("axisymmetric_outer_radius", [])
            xs = [float(mesh.coords[i, 0]) for i in range(len(mesh.node_ids))]
            xmin = min(xs) if xs else 0.0
            xmax = max(xs) if xs else 0.0
            span = max(xmax - xmin, 1.0)
            tol = max(span * 1.0e-8, 1.0e-10)
            add_issue(
                "INFO",
                "axisymmetric.gui",
                f"r-z display ready: axis nodes={len(axis_nodes)}, outer radius nodes={len(outer_nodes)}, r=[{xmin:g}, {xmax:g}]",
                {"nodes": axis_nodes[:80]},
            )
            if xmin > tol:
                add_issue("WARN", "axisymmetric.radius", "r=0 symmetry axis is outside the mesh; confirm this is a hollow/annular axisymmetric model.", {"min_radius": xmin})
            missing_ux = []
            for nid in axis_nodes:
                idx = mesh.node_index.get(str(nid))
                if idx is None:
                    continue
                if 2 * idx not in constraints:
                    missing_ux.append(str(nid))
            if missing_ux and xmin <= tol:
                add_issue("WARN", "axisymmetric.boundary", f"symmetry-axis nodes without ux=0: {', '.join(missing_ux[:10])}", {"nodes": missing_ux[:80]})
            elif axis_nodes:
                add_issue("INFO", "axisymmetric.boundary", "symmetry-axis radial constraint check passed", {"nodes": axis_nodes[:80]})

            all_loads = list(loads)
            for stage in stages:
                all_loads.extend(self._ensure_list(stage.get("loads", [])))
            for index, load in enumerate(all_loads, start=1):
                if not isinstance(load, Mapping):
                    continue
                ltype = str(load.get("type", "")).lower().strip()
                if ltype in {"gravity", "self_weight", "body"} or bool(load.get("self_weight", False)):
                    continue
                if ("node" in load or "nodes" in load or "set" in load) and any(abs(float(load.get(key, 0.0) or 0.0)) > 0.0 for key in ("fx", "fy", "px", "py")):
                    if not (load.get("axisymmetric_total_ring_force") or load.get("axisymmetric_measure") or load.get("coordinate_system") == "axisymmetric_rz"):
                        add_issue("WARN", f"axisymmetric.loads[{index}]", "nodal force has no axisymmetric ring/per-radian metadata; confirm intended ring resultant.", {})
                for edge in self._edge_targets_for_spec(mesh, load):
                    radius = self._edge_average_radius(mesh, edge)
                    if radius <= tol and any(abs(float(load.get(key, 0.0) or 0.0)) > 0.0 for key in ("tx", "ty", "qx", "qy")):
                        add_issue("WARN", f"axisymmetric.loads[{index}]", "edge load on r=0 axis has zero ring surface measure.", {"nodes": list(edge)})

            all_hydro: list[Mapping[str, Any]] = []
            for stage in stages:
                hydro = self._mapping(stage.get("hydro", stage.get("consolidation", {})))
                if hydro:
                    all_hydro.append(hydro)
            for hindex, hydro in enumerate(all_hydro, start=1):
                for key in ("pore_flux_bcs", "flux_bcs", "pore_robin_bcs", "robin_bcs"):
                    for spec in self._ensure_list(hydro.get(key, [])):
                        if not isinstance(spec, Mapping):
                            continue
                        for edge in self._edge_targets_for_spec(mesh, spec):
                            radius = self._edge_average_radius(mesh, edge)
                            if radius <= tol:
                                add_issue("INFO", f"axisymmetric.hydro[{hindex}]", f"{key} on r=0 axis uses zero ring measure; suitable for no-flow symmetry.", {"nodes": list(edge)})

        def _edge_average_radius(self, mesh: Any, edge: tuple[str, str]) -> float:
            try:
                a, b = edge
                ia = mesh.node_index[str(a)]
                ib = mesh.node_index[str(b)]
                return 0.5 * (float(mesh.coords[ia, 0]) + float(mesh.coords[ib, 0]))
            except Exception:
                return 0.0

        def _check_duplicate_elements(self, mesh: Any, add_issue: Any) -> None:
            by_nodes: dict[tuple[str, tuple[str, ...]], list[str]] = {}
            by_geometry: dict[tuple[str, tuple[tuple[float, float], ...]], list[str]] = {}
            for element in mesh.elements:
                corner_count = 3 if element.type.startswith("TRI") else 4
                corner_nodes = tuple(str(nid) for nid in element.nodes[:corner_count])
                by_nodes.setdefault((element.type, tuple(sorted(corner_nodes, key=self._natural_sort_key))), []).append(element.id)
                points = []
                for nid in corner_nodes:
                    idx = mesh.node_index[nid]
                    points.append((round(float(mesh.coords[idx, 0]), 10), round(float(mesh.coords[idx, 1]), 10)))
                by_geometry.setdefault((element.type, tuple(sorted(points))), []).append(element.id)
            duplicate_connectivity = [ids for ids in by_nodes.values() if len(ids) > 1]
            duplicate_geometry = [ids for ids in by_geometry.values() if len(ids) > 1]
            for ids in duplicate_connectivity[:10]:
                add_issue("ERROR", "mesh.duplicate_elements", f"重複要素接続: {', '.join(ids)}", {"elements": ids[:80]})
            for ids in duplicate_geometry[:10]:
                if any(set(ids) == set(existing) for existing in duplicate_connectivity):
                    continue
                add_issue("WARN", "mesh.duplicate_geometry", f"同一形状の重複要素候補: {', '.join(ids)}", {"elements": ids[:80]})

        def _check_mesh_quality_thresholds(self, mesh: Any, add_issue: Any) -> None:
            checks = self._mapping(self.cfg.get("checks", {}))
            quality_cfg = self._mapping(checks.get("mesh_quality", {}))

            def threshold(name: str, default: float, *aliases: str) -> float:
                for key in (name, *aliases):
                    if key not in quality_cfg:
                        continue
                    try:
                        value = float(quality_cfg[key])
                    except (TypeError, ValueError) as exc:
                        raise ValueError(f"{key} は数値で指定してください") from exc
                    if not math.isfinite(value):
                        raise ValueError(f"{key} は有限値で指定してください")
                    return value
                return default

            try:
                min_area = threshold("min_area", 1.0e-12)
                min_angle = threshold("min_angle_deg", 10.0, "min_angle")
                max_aspect = threshold("max_aspect_ratio", 20.0)
                max_skew = threshold("max_skew", 0.85)
            except ValueError as exc:
                add_issue("ERROR", "mesh.quality.thresholds", str(exc))
                return
            if min_area <= 0.0 or min_angle <= 0.0 or max_aspect <= 0.0 or max_skew < 0.0:
                add_issue("ERROR", "mesh.quality.thresholds", "min_area/min_angle/max_aspect_ratio は正値、max_skew は0以上で指定してください")
                return
            small_area: list[str] = []
            low_angle: list[str] = []
            high_aspect: list[str] = []
            high_skew: list[str] = []
            worst_angle = math.inf
            worst_aspect = 0.0
            worst_skew = 0.0
            for element in mesh.elements:
                corner_count = 3 if element.type.startswith("TRI") else 4
                points = [(float(mesh.coords[mesh.node_index[nid], 0]), float(mesh.coords[mesh.node_index[nid], 1])) for nid in element.nodes[:corner_count]]
                metrics = self._element_quality_metrics(points)
                worst_angle = min(worst_angle, metrics["min_angle"])
                worst_aspect = max(worst_aspect, metrics["aspect"])
                worst_skew = max(worst_skew, metrics["skew"])
                if metrics["area"] < min_area:
                    small_area.append(element.id)
                if metrics["min_angle"] < min_angle:
                    low_angle.append(element.id)
                if metrics["aspect"] > max_aspect:
                    high_aspect.append(element.id)
                if corner_count == 4 and metrics["skew"] > max_skew:
                    high_skew.append(element.id)
            if small_area:
                add_issue("ERROR", "mesh.quality.area", f"面積しきい値未満の要素 {len(small_area)} 件 (min_area={min_area:g})", {"elements": small_area[:80]})
            if low_angle:
                add_issue("WARN", "mesh.quality.angle", f"最小角しきい値未満の要素 {len(low_angle)} 件 (min_angle={min_angle:g} deg, worst={worst_angle:.4g})", {"elements": low_angle[:80]})
            if high_aspect:
                add_issue("WARN", "mesh.quality.aspect", f"アスペクト比しきい値超過の要素 {len(high_aspect)} 件 (max={max_aspect:g}, worst={worst_aspect:.4g})", {"elements": high_aspect[:80]})
            if high_skew:
                add_issue("WARN", "mesh.quality.skew", f"スキューしきい値超過の四角形 {len(high_skew)} 件 (max={max_skew:g}, worst={worst_skew:.4g})", {"elements": high_skew[:80]})
            add_issue("INFO", "mesh.quality.thresholds", f"min_area={min_area:g}, min_angle={min_angle:g}deg, max_aspect={max_aspect:g}, max_skew={max_skew:g}")

        def _check_boundary_conflicts(self, mesh: Any, bcs: list[Any], label: str, add_issue: Any) -> None:
            assignments: dict[tuple[str, str], list[tuple[float, int]]] = {}
            for index, bc in enumerate(bcs, start=1):
                if not isinstance(bc, Mapping):
                    continue
                try:
                    nodes = self._node_targets_for_spec(mesh, bc)
                    values = self._boundary_dof_values(bc)
                except Exception as exc:
                    add_issue("ERROR", f"{label}[{index}]", f"境界条件の解釈に失敗しました: {exc}")
                    continue
                if not values:
                    add_issue("WARN", f"{label}[{index}]", "拘束DOFが指定されていません。")
                for nid in nodes:
                    for dof, value in values.items():
                        assignments.setdefault((nid, dof), []).append((value, index))
            for (nid, dof), values in assignments.items():
                unique: list[tuple[float, int]] = []
                for value, index in values:
                    if not any(abs(value - existing) <= 1.0e-10 for existing, _idx in unique):
                        unique.append((value, index))
                if len(unique) > 1:
                    detail = ", ".join(f"{value:g}@{idx}" for value, idx in unique[:6])
                    add_issue("ERROR", label, f"節点 {nid} の {dof} に矛盾する拘束値があります: {detail}", {"nodes": [nid]})

        def _check_load_boundary_inconsistency(self, mesh: Any, constraints: Mapping[int, float], loads: list[Any], label: str, add_issue: Any) -> None:
            if not constraints:
                return
            for index, load in enumerate(loads, start=1):
                if not isinstance(load, Mapping):
                    continue
                ltype = str(load.get("type", "")).lower().strip()
                if ltype in {"gravity", "self_weight", "body"} or bool(load.get("self_weight", False)):
                    continue
                if "edge" in load or "edges" in load:
                    values = self._edge_load_dof_values(load)
                    constrained_hits: list[str] = []
                    for edge in self._edge_targets_for_spec(mesh, load):
                        for dof, value in values.items():
                            if value is None or abs(value) <= 1.0e-30:
                                continue
                            offset = 0 if dof == "ux" else 1
                            if all(2 * mesh.node_index[nid] + offset in constraints for nid in edge):
                                constrained_hits.append(f"{edge[0]}-{edge[1]}.{dof}")
                    if constrained_hits:
                        add_issue("WARN", f"{label}[{index}]", f"拘束済み境界DOFへ分布荷重が作用しています: {', '.join(constrained_hits[:10])}", {"edges": constrained_hits[:80]})
                    continue
                try:
                    nodes = self._node_targets_for_spec(mesh, load)
                except Exception:
                    continue
                values = self._load_dof_values(load)
                constrained_hits: list[str] = []
                for nid in nodes:
                    base = 2 * mesh.node_index[nid]
                    for dof, value in values.items():
                        if value is None or abs(value) <= 1.0e-30:
                            continue
                        dof_index = base + (0 if dof == "ux" else 1)
                        if dof_index in constraints:
                            constrained_hits.append(f"{nid}.{dof}")
                if constrained_hits:
                    add_issue("WARN", f"{label}[{index}]", f"拘束済みDOFへ荷重が作用しています: {', '.join(constrained_hits[:10])}", {"nodes": [item.split('.')[0] for item in constrained_hits[:80]]})

        def _check_rigid_body_modes(self, mesh: Any, constraints: Mapping[int, float], label: str, add_issue: Any, *, active_elements: set[str] | None = None) -> None:
            components = self._mesh_connected_components(mesh, active_elements=active_elements)
            for comp_index, nodes in enumerate(components, start=1):
                rank = self._rigid_mode_constraint_rank(mesh, nodes, constraints)
                if rank < 3:
                    add_issue("WARN", f"{label}.rigid_modes[{comp_index}]", f"未拘束剛体モードの可能性があります。拘束ランク={rank}/3, component_nodes={len(nodes)}", {"nodes": sorted(nodes, key=self._natural_sort_key)[:80]})

        def _check_duplicate_stage_names(self, stages: list[Mapping[str, Any]], add_issue: Any) -> None:
            seen: dict[str, int] = {}
            for index, stage in enumerate(stages, start=1):
                name = str(stage.get("name", f"Stage-{index}"))
                if name in seen:
                    add_issue("WARN", "stages", f"ステージ名が重複しています: '{name}' ({seen[name]} と {index})")
                else:
                    seen[name] = index

        def _check_stage_scalar_consistency(self, stage: Mapping[str, Any], label: str, analysis_fields: set[str], add_issue: Any) -> None:
            stype = str(stage.get("type", "")).lower().strip()
            if "stress_release" in stage:
                try:
                    release = float(stage.get("stress_release"))
                    if not 0.0 <= release <= 1.0:
                        add_issue("ERROR", label, f"stress_release は 0..1 の範囲で指定してください: {release:g}")
                except (TypeError, ValueError):
                    add_issue("ERROR", label, "stress_release が数値ではありません。")
            hydro = stage.get("hydro", stage.get("consolidation", {}))
            has_hydro = isinstance(hydro, Mapping) and any(hydro.get(key) for key in ("pressure_bcs", "pore_pressure_bcs", "pore_flux_bcs", "pore_robin_bcs"))
            if has_hydro and "p" not in analysis_fields:
                add_issue("WARN", label, "水理境界がありますが analysis.fields に p がありません。u-p/圧密設定を確認してください。")
            if stype in {"consolidation", "up", "u-p", "u_p", "coupled_consolidation"} and "p" not in analysis_fields:
                add_issue("WARN", label, "圧密/u-pステージですが analysis.fields に p がありません。")
            if has_hydro and stype not in {"consolidation", "up", "u-p", "u_p", "coupled_consolidation", "riks", "arc_length", "arclength"}:
                add_issue("WARN", label, f"{stage.get('type', 'static')} ステージに水理境界があります。意図した連成ステージか確認してください。")
            if stype in {"geostatic", "initial", "k0"} and not bool(stage.get("apply_gravity", True)) and not self._ensure_list(stage.get("loads", [])):
                add_issue("WARN", label, "geostatic/K0ステージで自重も荷重も無効です。初期応力が生成されない可能性があります。")

        @staticmethod
        def _boundary_dof_values(bc: Mapping[str, Any]) -> dict[str, float]:
            values: dict[str, float] = {}
            if "dof" in bc:
                values[str(bc["dof"]).lower()] = float(bc.get("value", 0.0))
            for dof in ("ux", "uy"):
                if dof in bc and bc[dof] is not None:
                    values[dof] = float(bc[dof])
            if "dofs" in bc:
                value = float(bc.get("value", 0.0))
                raw = bc["dofs"]
                dofs = raw if isinstance(raw, (list, tuple)) else [raw]
                for dof in dofs:
                    values[str(dof).lower()] = value
            if bool(bc.get("fixed", False)):
                values.setdefault("ux", 0.0)
                values.setdefault("uy", 0.0)
            return values

        def _load_dof_values(self, load: Mapping[str, Any]) -> dict[str, float | None]:
            return {
                "ux": self._optional_float(str(load.get("fx", load.get("px", load.get("ux", ""))))),
                "uy": self._optional_float(str(load.get("fy", load.get("py", load.get("uy", ""))))),
            }

        def _edge_load_dof_values(self, load: Mapping[str, Any]) -> dict[str, float | None]:
            def first_float(*keys: str) -> float | None:
                parsed: list[float] = []
                for key in keys:
                    value = self._optional_float(str(load.get(key, "")))
                    if value is not None:
                        parsed.append(value)
                for value in parsed:
                    if abs(value) > 1.0e-30:
                        return value
                return parsed[0] if parsed else None

            return {
                "ux": first_float("tx", "qx", "tx1", "qx1", "tx2", "qx2", "tx_start", "tx_end"),
                "uy": first_float("ty", "qy", "ty1", "qy1", "ty2", "qy2", "ty_start", "ty_end"),
            }

        @staticmethod
        def _element_quality_metrics(points: list[tuple[float, float]]) -> dict[str, float]:
            area2 = 0.0
            for a, b in zip(points, points[1:] + points[:1]):
                area2 += a[0] * b[1] - b[0] * a[1]
            area = abs(area2) * 0.5
            lengths = [math.hypot(b[0] - a[0], b[1] - a[1]) for a, b in zip(points, points[1:] + points[:1])]
            positive = [length for length in lengths if length > 1.0e-30]
            aspect = max(positive) / min(positive) if positive else math.inf
            angles = []
            for i, p in enumerate(points):
                prev = points[i - 1]
                nxt = points[(i + 1) % len(points)]
                v1 = (prev[0] - p[0], prev[1] - p[1])
                v2 = (nxt[0] - p[0], nxt[1] - p[1])
                n1 = math.hypot(*v1)
                n2 = math.hypot(*v2)
                if n1 <= 1.0e-30 or n2 <= 1.0e-30:
                    angles.append(0.0)
                    continue
                cosv = max(-1.0, min(1.0, (v1[0] * v2[0] + v1[1] * v2[1]) / (n1 * n2)))
                angles.append(math.degrees(math.acos(cosv)))
            min_angle = min(angles) if angles else 0.0
            skew = max((abs(angle - 90.0) / 90.0 for angle in angles), default=0.0) if len(points) == 4 else 0.0
            return {"area": area, "aspect": aspect, "min_angle": min_angle, "skew": skew}

        def _mesh_quality_threshold_values(self) -> tuple[float, float, float, float]:
            checks = self._mapping(self.cfg.get("checks", {}))
            quality_cfg = self._mapping(checks.get("mesh_quality", {}))

            def threshold(name: str, default: float, *aliases: str) -> float:
                for key in (name, *aliases):
                    if key not in quality_cfg:
                        continue
                    try:
                        value = float(quality_cfg[key])
                    except (TypeError, ValueError):
                        return default
                    if math.isfinite(value):
                        return value
                return default

            return (
                threshold("min_area", 1.0e-12),
                threshold("min_angle_deg", 10.0, "min_angle"),
                threshold("max_aspect_ratio", 20.0),
                threshold("max_skew", 0.85),
            )

        def _mesh_quality_violations(self, mesh: Any) -> list[dict[str, Any]]:
            try:
                from geofem_app.mesh_quality import evaluate_mesh_quality

                return list(evaluate_mesh_quality(mesh, self.cfg).get("violations", []))
            except Exception:
                return []

        def _mesh_connected_components(self, mesh: Any, *, active_elements: set[str] | None = None) -> list[set[str]]:
            adjacency: dict[str, set[str]] = {str(nid): set() for nid in mesh.node_ids}
            active = active_elements if active_elements is not None else {element.id for element in mesh.elements if element.active}
            used: set[str] = set()
            for element in mesh.elements:
                if element.id not in active:
                    continue
                nodes = [str(nid) for nid in element.nodes]
                used.update(nodes)
                for nid in nodes:
                    adjacency.setdefault(nid, set()).update(other for other in nodes if other != nid)
            for raw in self._ensure_list(self.cfg.get("interfaces", self.cfg.get("interface_elements", []))):
                if not isinstance(raw, Mapping) or not self._bool_text(str(raw.get("active", True)), True):
                    continue
                nodes = [str(nid) for nid in self._ensure_list(raw.get("nodes", []))]
                nodes.extend(str(nid) for nid in self._ensure_list(raw.get("minus_nodes", raw.get("nodes_minus", []))))
                nodes.extend(str(nid) for nid in self._ensure_list(raw.get("plus_nodes", raw.get("nodes_plus", []))))
                nodes = [nid for nid in nodes if nid in adjacency]
                used.update(nodes)
                for nid in nodes:
                    adjacency.setdefault(nid, set()).update(other for other in nodes if other != nid)
            components: list[set[str]] = []
            remaining = set(used)
            while remaining:
                start = remaining.pop()
                comp = {start}
                stack = [start]
                while stack:
                    nid = stack.pop()
                    for other in adjacency.get(nid, set()):
                        if other in remaining:
                            remaining.remove(other)
                            comp.add(other)
                            stack.append(other)
                components.append(comp)
            return components

        def _rigid_mode_constraint_rank(self, mesh: Any, nodes: set[str], constraints: Mapping[int, float]) -> int:
            import numpy as np

            constrained_rows: list[list[float]] = []
            coords = [(float(mesh.coords[mesh.node_index[nid], 0]), float(mesh.coords[mesh.node_index[nid], 1])) for nid in nodes if nid in mesh.node_index]
            if not coords:
                return 0
            cx = sum(x for x, _y in coords) / len(coords)
            cy = sum(y for _x, y in coords) / len(coords)
            for nid in nodes:
                if nid not in mesh.node_index:
                    continue
                idx = mesh.node_index[nid]
                x = float(mesh.coords[idx, 0]) - cx
                y = float(mesh.coords[idx, 1]) - cy
                if 2 * idx in constraints:
                    constrained_rows.append([1.0, 0.0, -y])
                if 2 * idx + 1 in constraints:
                    constrained_rows.append([0.0, 1.0, x])
            if not constrained_rows:
                return 0
            matrix = np.asarray(constrained_rows, dtype=float)
            return int(np.linalg.matrix_rank(matrix, tol=1.0e-10))

        def _scene_to_model(self, *args: Any, **kwargs: Any) -> Any:
            return selection_controller._scene_to_model(self, self._selection_controller_qt(), *args, **kwargs)
        def _snap_tolerance_model(self, *args: Any, **kwargs: Any) -> Any:
            return selection_controller._snap_tolerance_model(self, self._selection_controller_qt(), *args, **kwargs)
        def _snap_model_point(self, *args: Any, **kwargs: Any) -> Any:
            return selection_controller._snap_model_point(self, self._selection_controller_qt(), *args, **kwargs)
        def _snap_candidates(self, *args: Any, **kwargs: Any) -> Any:
            return selection_controller._snap_candidates(self, self._selection_controller_qt(), *args, **kwargs)
        def _geometry_bbox(self, geometry: Mapping[str, Any]) -> tuple[float, float, float, float] | None:
            xs: list[float] = []
            ys: list[float] = []
            for region in self._geometry_regions(geometry):
                for x, y in region:
                    xs.append(x)
                    ys.append(y)
            raw_lines = geometry.get("lines", [])
            if isinstance(raw_lines, list):
                for raw in raw_lines:
                    if not isinstance(raw, Mapping):
                        continue
                    try:
                        for value in (raw.get("start", raw.get("p1", [0.0, 0.0])), raw.get("end", raw.get("p2", [0.0, 0.0]))):
                            x, y = self._xy_pair(value)
                            xs.append(x)
                            ys.append(y)
                    except ValueError:
                        continue
            raw_annotations = geometry.get("annotations", [])
            if isinstance(raw_annotations, list):
                for raw in raw_annotations:
                    if not isinstance(raw, Mapping):
                        continue
                    try:
                        x, y = self._xy_pair(raw.get("point", raw.get("position", [0.0, 0.0])))
                    except ValueError:
                        continue
                    xs.append(x)
                    ys.append(y)
            raw_dimensions = geometry.get("dimensions", [])
            if isinstance(raw_dimensions, list):
                for raw in raw_dimensions:
                    if not isinstance(raw, Mapping):
                        continue
                    try:
                        for value in (raw.get("start", raw.get("p1", [0.0, 0.0])), raw.get("end", raw.get("p2", [0.0, 0.0]))):
                            x, y = self._xy_pair(value)
                            xs.append(x)
                            ys.append(y)
                    except ValueError:
                        continue
            raw_hatches = geometry.get("hatches", [])
            if isinstance(raw_hatches, list):
                for raw in raw_hatches:
                    if not isinstance(raw, Mapping):
                        continue
                    for ring in self._hatch_rings(raw):
                        for x, y in ring:
                            xs.append(x)
                            ys.append(y)
            for cx, cy, radius in self._geometry_tunnels(geometry):
                xs.extend([cx - radius, cx + radius])
                ys.extend([cy - radius, cy + radius])
            if not xs or not ys:
                mesh = self._mapping(self.cfg.get("mesh", {}))
                xr = mesh.get("x_range")
                yr = mesh.get("y_range")
                if isinstance(xr, list) and len(xr) >= 2 and isinstance(yr, list) and len(yr) >= 2:
                    return float(xr[0]), float(xr[1]), float(yr[0]), float(yr[1])
                return None
            pad = max(max(xs) - min(xs), max(ys) - min(ys), 1.0) * 1.0e-6
            return min(xs) - pad, max(xs) + pad, min(ys) - pad, max(ys) + pad

        def _geometry_regions(self, geometry: Mapping[str, Any]) -> list[list[tuple[float, float]]]:
            regions: list[list[tuple[float, float]]] = []
            raw_regions = geometry.get("regions", [])
            if isinstance(raw_regions, list):
                for raw in raw_regions:
                    if not isinstance(raw, Mapping):
                        continue
                    points_raw = raw.get("points", [])
                    if not isinstance(points_raw, list):
                        continue
                    points: list[tuple[float, float]] = []
                    for value in points_raw:
                        try:
                            points.append(self._xy_pair(value))
                        except ValueError:
                            points = []
                            break
                    if len(points) >= 3:
                        regions.append(points)
            return regions

        def _geometry_polygon_holes(self, geometry: Mapping[str, Any]) -> list[list[tuple[float, float]]]:
            holes: list[list[tuple[float, float]]] = []
            raw_regions = geometry.get("regions", [])
            if isinstance(raw_regions, list):
                for raw in raw_regions:
                    if not isinstance(raw, Mapping):
                        continue
                    rings = self._hatch_rings(raw)
                    if len(rings) > 1:
                        holes.extend(rings[1:])
            return holes

        def _geometry_tunnels(self, geometry: Mapping[str, Any]) -> list[tuple[float, float, float]]:
            tunnels: list[tuple[float, float, float]] = []
            raw_tunnels = geometry.get("tunnels", [])
            if isinstance(raw_tunnels, list):
                for raw in raw_tunnels:
                    if not isinstance(raw, Mapping):
                        continue
                    try:
                        cx, cy = self._xy_pair(raw.get("center", [0.0, 0.0]))
                        radius = float(raw.get("radius", 0.0))
                    except (TypeError, ValueError):
                        continue
                    if radius > 0.0:
                        tunnels.append((cx, cy, radius))
            return tunnels

        def _mesh_refinements(self, mesh: Mapping[str, Any]) -> list[tuple[float, float, float, float]]:
            out: list[tuple[float, float, float, float]] = []
            for raw in self._mesh_refinement_specs(mesh):
                if not isinstance(raw, Mapping):
                    continue
                if str(raw.get("type", raw.get("kind", ""))).lower() in {"split_line", "constraint_line", "division_line", "block_split"}:
                    continue
                try:
                    cx, cy = self._xy_pair(raw.get("center", raw.get("point", [raw.get("cx", 0.0), raw.get("cy", 0.0)])))
                    radius = float(raw.get("radius", raw.get("r", 0.0)))
                    factor = float(raw.get("factor", raw.get("refinement", 2.0)))
                except (TypeError, ValueError):
                    continue
                if radius > 0.0 and factor > 1.0:
                    out.append((cx, cy, radius, factor))
            return out

        def _mesh_refinement_specs(self, mesh: Mapping[str, Any]) -> list[dict[str, Any]]:
            specs: list[dict[str, Any]] = []
            raw_refinements = mesh.get("refinements", mesh.get("local_refinements", []))
            if isinstance(raw_refinements, list):
                for raw in raw_refinements:
                    if isinstance(raw, Mapping):
                        specs.append(dict(raw))
            base = self._mesh_base_target(mesh)
            raw_size_map = mesh.get("size_map", mesh.get("local_size_map", []))
            if isinstance(raw_size_map, list):
                for index, raw in enumerate(raw_size_map, start=1):
                    if not isinstance(raw, Mapping):
                        continue
                    try:
                        center = raw.get("center", raw.get("point", [raw.get("x", 0.0), raw.get("y", 0.0)]))
                        cx, cy = self._xy_pair(center)
                        radius = float(raw.get("radius", raw.get("r", base)))
                        target_size = float(raw.get("target_size", raw.get("size", base)))
                    except (TypeError, ValueError):
                        continue
                    if radius <= 0.0 or target_size <= 0.0:
                        continue
                    factor = max(base / target_size, 1.05)
                    specs.append({"id": str(raw.get("id", f"size_{index}")), "center": [cx, cy], "radius": radius, "factor": factor, "source": "size_map"})
            raw_points = mesh.get("control_points", mesh.get("mesh_control_points", []))
            if isinstance(raw_points, list):
                for index, raw in enumerate(raw_points, start=1):
                    if not isinstance(raw, Mapping):
                        continue
                    try:
                        cx, cy = self._xy_pair(raw.get("point", raw.get("position", [raw.get("x", 0.0), raw.get("y", 0.0)])))
                        target_size = float(raw.get("target_size", raw.get("size", base)))
                    except (TypeError, ValueError):
                        continue
                    if target_size <= 0.0:
                        continue
                    radius = float(raw.get("radius", max(base, target_size) * 2.0))
                    factor = max(base / target_size, 1.05)
                    specs.append({"id": str(raw.get("id", f"cp_{index}")), "center": [cx, cy], "radius": radius, "factor": factor, "source": "control_point"})
            for index, (start, end, target_size) in enumerate(self._mesh_split_lines(mesh), start=1):
                spec: dict[str, Any] = {"id": f"split_{index}", "type": "split_line", "start": list(start), "end": list(end), "locked": True}
                if target_size is not None:
                    spec["target_size"] = target_size
                specs.append(spec)
            return specs

        def _mesh_split_lines(self, mesh: Mapping[str, Any]) -> list[tuple[tuple[float, float], tuple[float, float], float | None]]:
            out: list[tuple[tuple[float, float], tuple[float, float], float | None]] = []
            raw_split_lines = mesh.get("split_lines", mesh.get("split_line_constraints", []))
            if not isinstance(raw_split_lines, list):
                return out
            for raw in raw_split_lines:
                if not isinstance(raw, Mapping):
                    continue
                try:
                    start = raw.get("start", raw.get("p1", [raw.get("x1", 0.0), raw.get("y1", 0.0)]))
                    end = raw.get("end", raw.get("p2", [raw.get("x2", 0.0), raw.get("y2", 0.0)]))
                    x1, y1 = self._xy_pair(start)
                    x2, y2 = self._xy_pair(end)
                except ValueError:
                    continue
                if math.hypot(x2 - x1, y2 - y1) <= 1.0e-12:
                    continue
                target_size = None
                if raw.get("target_size", raw.get("size", None)) not in (None, ""):
                    try:
                        target_size = float(raw.get("target_size", raw.get("size")))
                    except (TypeError, ValueError):
                        target_size = None
                out.append(((x1, y1), (x2, y2), target_size))
            return out

        def _mesh_base_target(self, mesh: Mapping[str, Any]) -> float:
            for key in ("target_size", "division_width"):
                try:
                    value = float(mesh.get(key, 0.0))
                except (TypeError, ValueError):
                    value = 0.0
                if value > 0.0:
                    return value
            try:
                x_range = mesh.get("x_range", [0.0, 1.0])
                nx = max(int(float(mesh.get("nx", 1))), 1)
                if isinstance(x_range, list) and len(x_range) >= 2:
                    return max(abs(float(x_range[1]) - float(x_range[0])) / nx, 1.0e-6)
            except (TypeError, ValueError):
                pass
            return 1.0

        def _triangle_crosses_boundary(
            self,
            triangle: list[tuple[float, float]],
            boundary_segments: list[tuple[tuple[float, float], tuple[float, float]]],
        ) -> bool:
            tri_edges = list(zip(triangle, triangle[1:] + triangle[:1]))
            for a, b in tri_edges:
                for c, d in boundary_segments:
                    hit = self._segment_intersection(a, b, c, d)
                    if hit is None:
                        continue
                    _ta, _tb, x, y = hit
                    point = (x, y)
                    if self._point_matches_any(point, (a, b, c, d)):
                        continue
                    return True
            return False

        @staticmethod
        def _point_matches_any(point: tuple[float, float], candidates: tuple[tuple[float, float], ...], tol: float = 1.0e-8) -> bool:
            return any(math.hypot(point[0] - candidate[0], point[1] - candidate[1]) <= tol for candidate in candidates)

        def _smooth_delaunay_points(
            self,
            points: Any,
            triangles: list[tuple[int, int, int, float, float]],
            boundary_segments: list[tuple[tuple[float, float], tuple[float, float]]],
            regions: list[list[tuple[float, float]]],
            tunnels: list[tuple[float, float, float]],
            *,
            iterations: int,
        ) -> Any:
            import numpy as np

            if iterations <= 0:
                return points
            smoothed = np.asarray(points, dtype=float).copy()
            adjacency: dict[int, set[int]] = {}
            used = {idx for tri in triangles for idx in tri[:3]}
            for i, j, k, _cx, _cy in triangles:
                adjacency.setdefault(i, set()).update([j, k])
                adjacency.setdefault(j, set()).update([i, k])
                adjacency.setdefault(k, set()).update([i, j])
            fixed: set[int] = set()
            tol = max(float(np.ptp(smoothed[:, 0]) + np.ptp(smoothed[:, 1])) * 1.0e-8, 1.0e-8)
            for idx in used:
                p = (float(smoothed[idx, 0]), float(smoothed[idx, 1]))
                if any(self._point_to_segment_distance(p, a, b) <= tol for a, b in boundary_segments):
                    fixed.add(idx)
            for _ in range(iterations):
                trial = smoothed.copy()
                for idx in used:
                    if idx in fixed:
                        continue
                    neighbors = sorted(adjacency.get(idx, []))
                    if not neighbors:
                        continue
                    candidate = np.mean(smoothed[neighbors, :], axis=0)
                    x = float(candidate[0])
                    y = float(candidate[1])
                    inside_region = True if not regions else any(self._point_in_polygon(x, y, region) for region in regions)
                    inside_tunnel = any(math.hypot(x - tx, y - ty) <= tr for tx, ty, tr in tunnels)
                    if inside_region and not inside_tunnel:
                        trial[idx, :] = candidate
                smoothed = trial
            return smoothed

        @staticmethod
        def _point_to_segment_distance(point: tuple[float, float], a: tuple[float, float], b: tuple[float, float]) -> float:
            ax, ay = a
            bx, by = b
            px, py = point
            dx = bx - ax
            dy = by - ay
            length2 = dx * dx + dy * dy
            if length2 <= 1.0e-30:
                return math.hypot(px - ax, py - ay)
            t = max(0.0, min(1.0, ((px - ax) * dx + (py - ay) * dy) / length2))
            qx = ax + t * dx
            qy = ay + t * dy
            return math.hypot(px - qx, py - qy)

        @staticmethod
        def _point_in_polygon(x: float, y: float, polygon: list[tuple[float, float]]) -> bool:
            inside = False
            j = len(polygon) - 1
            for i, (xi, yi) in enumerate(polygon):
                xj, yj = polygon[j]
                intersects = (yi > y) != (yj > y) and x < (xj - xi) * (y - yi) / ((yj - yi) or 1.0e-30) + xi
                if intersects:
                    inside = not inside
                j = i
            return inside

        @staticmethod
        def _list_value(parent: dict[str, Any], key: str) -> list[Any]:
            value = parent.get(key)
            if not isinstance(value, list):
                value = []
                parent[key] = value
            return value

        @staticmethod
        def _ensure_list(value: Any) -> list[Any]:
            if value is None:
                return []
            return list(value) if isinstance(value, (list, tuple)) else [value]

        @staticmethod
        def _next_id(prefix: str, values: list[Any]) -> str:
            used = {str(item.get("id")) for item in values if isinstance(item, Mapping) and item.get("id") is not None}
            index = len(values) + 1
            while f"{prefix}_{index}" in used:
                index += 1
            return f"{prefix}_{index}"

        @staticmethod
        def _parse_float_csv(text: str, count: int, label: str) -> list[float]:
            parts = [part.strip() for part in text.replace(";", ",").replace(" ", ",").split(",") if part.strip()]
            if len(parts) != count:
                raise ValueError(f"{label}は{count}個の数値で入力してください。")
            try:
                return [float(part) for part in parts]
            except ValueError as exc:
                raise ValueError(f"{label}の座標は数値で入力してください。") from exc

        @staticmethod
        def _parse_node_force(text: str) -> tuple[str, float, float]:
            parts = [part.strip() for part in text.split(",")]
            if len(parts) != 3 or not parts[0]:
                raise ValueError("node,fx,fy の形式で入力してください。")
            try:
                return parts[0], float(parts[1]), float(parts[2])
            except ValueError as exc:
                raise ValueError("fx,fyは数値で入力してください。") from exc

        @staticmethod
        def _xy_pair(value: Any) -> tuple[float, float]:
            if isinstance(value, Mapping):
                return float(value.get("x", 0.0)), float(value.get("y", 0.0))
            if isinstance(value, (list, tuple)) and len(value) >= 2:
                return float(value[0]), float(value[1])
            raise ValueError("xy pair is required")

