        @staticmethod
        def _segment_intersection(
            p: tuple[float, float],
            p2: tuple[float, float],
            q: tuple[float, float],
            q2: tuple[float, float],
        ) -> tuple[float, float, float, float] | None:
            rx = p2[0] - p[0]
            ry = p2[1] - p[1]
            sx = q2[0] - q[0]
            sy = q2[1] - q[1]
            denom = rx * sy - ry * sx
            if abs(denom) < 1.0e-12:
                return None
            qpx = q[0] - p[0]
            qpy = q[1] - p[1]
            t = (qpx * sy - qpy * sx) / denom
            u = (qpx * ry - qpy * rx) / denom
            if -1.0e-9 <= t <= 1.0 + 1.0e-9 and -1.0e-9 <= u <= 1.0 + 1.0e-9:
                return t, u, p[0] + t * rx, p[1] + t * ry
            return None

        def _clip_line_to_box(self, line: Mapping[str, Any], xmin: float, ymin: float, xmax: float, ymax: float) -> tuple[float, float, float, float] | None:
            if xmax < xmin:
                xmin, xmax = xmax, xmin
            if ymax < ymin:
                ymin, ymax = ymax, ymin
            x1, y1 = self._xy_pair(line.get("start", [0.0, 0.0]))
            x2, y2 = self._xy_pair(line.get("end", [0.0, 0.0]))
            dx = x2 - x1
            dy = y2 - y1
            t0 = 0.0
            t1 = 1.0
            for p, q in [(-dx, x1 - xmin), (dx, xmax - x1), (-dy, y1 - ymin), (dy, ymax - y1)]:
                if abs(p) < 1.0e-30:
                    if q < 0.0:
                        return None
                    continue
                r = q / p
                if p < 0.0:
                    if r > t1:
                        return None
                    t0 = max(t0, r)
                else:
                    if r < t0:
                        return None
                    t1 = min(t1, r)
            return x1 + t0 * dx, y1 + t0 * dy, x1 + t1 * dx, y1 + t1 * dy

