        @staticmethod
        def _segments_from_points(points: list[tuple[float, float]], *, closed: bool) -> list[tuple[float, float, float, float]]:
            if len(points) < 2:
                return []
            segments = [(a[0], a[1], b[0], b[1]) for a, b in zip(points, points[1:])]
            if closed and len(points) > 2:
                a = points[-1]
                b = points[0]
                segments.append((a[0], a[1], b[0], b[1]))
            return segments

        @staticmethod
        def _arc_segments(cx: float, cy: float, radius: float, start_deg: float, end_deg: float, *, full_circle: bool) -> list[tuple[float, float, float, float]]:
            if radius <= 0.0:
                return []
            if full_circle:
                start_deg = 0.0
                end_deg = 360.0
            while end_deg <= start_deg:
                end_deg += 360.0
            sweep = end_deg - start_deg
            count = max(8, int(math.ceil(abs(sweep) / 12.0)))
            points = []
            for i in range(count + 1):
                angle = math.radians(start_deg + sweep * i / count)
                points.append((cx + radius * math.cos(angle), cy + radius * math.sin(angle)))
            return MainWindow._segments_from_points(points, closed=full_circle)

