        def _refresh_set_display_options(self) -> None:
            combo = getattr(self, "set_display", None)
            if combo is None:
                return
            current = combo.currentData()
            current_key = json.dumps(current, sort_keys=True) if isinstance(current, Mapping) else ""
            combo.blockSignals(True)
            combo.clear()
            en = str(getattr(self, "gui_locale", DEFAULT_GUI_LOCALE)).startswith("en")
            hidden_label = "Hide Sets" if en else "セット非表示"
            node_prefix = "Node" if en else "節点"
            element_prefix = "Element" if en else "要素"
            combo.addItem(hidden_label, None)
            try:
                from geofem_app.fem2d import mesh_from_config

                mesh = mesh_from_config(self.cfg)
                for name in sorted(mesh.node_sets):
                    combo.addItem(f"{node_prefix}: {name}", {"kind": "node", "name": name})
                for name in sorted(mesh.element_sets):
                    combo.addItem(f"{element_prefix}: {name}", {"kind": "element", "name": name})
            except Exception:
                mesh_cfg = self._mapping(self.cfg.get("mesh", {}))
                for name in sorted(self._mapping(mesh_cfg.get("node_sets", {}))):
                    combo.addItem(f"{node_prefix}: {name}", {"kind": "node", "name": name})
                for name in sorted(self._mapping(mesh_cfg.get("element_sets", {}))):
                    combo.addItem(f"{element_prefix}: {name}", {"kind": "element", "name": name})
            if current_key:
                for index in range(combo.count()):
                    data = combo.itemData(index)
                    if isinstance(data, Mapping) and json.dumps(dict(data), sort_keys=True) == current_key:
                        combo.setCurrentIndex(index)
                        break
            combo.blockSignals(False)
            self._set_display_options_dirty = False

        def _refresh_set_display_options_if_dirty(self) -> None:
            if bool(getattr(self, "_set_display_options_dirty", False)):
                self._refresh_set_display_options()

        def _selected_set_targets(self, mesh: Any) -> tuple[set[str], set[str], str]:
            combo = getattr(self, "set_display", None)
            data = combo.currentData() if combo is not None else None
            if not isinstance(data, Mapping):
                return set(), set(), ""
            kind = str(data.get("kind", ""))
            name = str(data.get("name", ""))
            if not name:
                return set(), set(), ""
            if kind == "node":
                return set(str(nid) for nid in mesh.node_sets.get(name, [])), set(), f"節点:{name}"
            if kind == "element":
                return set(), set(str(eid) for eid in mesh.element_sets.get(name, [])), f"要素:{name}"
            return set(), set(), ""

